window.KG_XC = [{"set": 1, "date": "2026-10-09", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 1 批）", "items": [{"type": "sci", "level": "中等", "stem": "用弹簧测力计水平拉木块，使木块在水平桌面上做匀速直线运动，此时弹簧测力计的示数为 2N。若保持接触面粗糙程度不变，把木块上的砝码取走，再次水平拉动木块使其做匀速直线运动，则弹簧测力计的示数将（　　）", "options": ["仍然为 2N", "大于 2N", "小于 2N 但大于 0", "无法判断"], "answer": ["C"], "explain": "木块做匀速直线运动时，水平方向受力平衡，拉力等于滑动摩擦力。取走砝码后，木块对桌面的压力减小；在接触面粗糙程度不变的情况下，滑动摩擦力随压力减小而减小，因此为维持匀速运动所需的拉力也变小，示数小于 2N 但仍大于 0。", "tip": "匀速直线运动 → 拉力 = 滑动摩擦力；滑动摩擦力大小只由「压力」和「接触面粗糙程度」决定。取走砝码改变了压力，摩擦力随之变小。", "method": "受力分析：先判断平衡（匀速 → 二力平衡），再判断摩擦力如何随压力变化。"}, {"type": "sci", "level": "容易", "stem": "把一根筷子斜插入水中，从水面上方看去，筷子好像在水面处「折断」了。对这一现象，正确的解释是（　　）", "options": ["光沿直线传播", "光发生了反射", "光发生了折射", "光发生了色散"], "answer": ["C"], "explain": "光从水中斜射入空气时，在水面处传播方向发生偏折，这就是光的折射。筷子反射的光经水面折射后进入人眼，人眼逆着折射光线看到的是筷子的虚像，位置比实际偏上，因此看起来像「折断」了。", "tip": "折射发生在「光斜射入另一种介质」时；反射是光在同一介质（表面）返回。关键是介质是否改变、是否斜射。", "method": "看到「水中的物体位置偏移/折断」→ 先想折射。"}, {"type": "sci", "level": "中等", "stem": "生活中，要降低水的硬度，下列做法有效的是（　　）", "options": ["静置沉淀", "过滤", "煮沸", "加入食盐"], "answer": ["C"], "explain": "水的硬度主要由水中可溶性的钙、镁化合物（如碳酸氢钙）引起。煮沸时，碳酸氢钙等受热分解生成难溶的碳酸钙沉淀，从而降低水中钙、镁离子的浓度，达到软化水的目的。静置沉淀和过滤只能除去不溶性杂质，不能除去可溶性钙镁化合物。", "tip": "区分「除不溶性杂质」（沉淀、过滤）和「降低硬度」（煮沸、蒸馏）。硬度是『可溶性』钙镁造成的。", "method": "硬水软化：生活中用煮沸，实验室用蒸馏。"}, {"type": "sci", "level": "容易", "stem": "把一粒种子萌发后长成的幼苗放在黑暗处培养一段时间，幼苗逐渐变黄。这一现象最能说明（　　）", "options": ["叶绿素的形成需要光", "种子的萌发需要光", "暗处植物不能进行呼吸作用", "幼苗体内的水分被不断消耗"], "answer": ["A"], "explain": "植物叶片呈绿色是因为含有叶绿素，而叶绿素只有在有光的条件下才能形成。幼苗在黑暗处不能合成叶绿素，叶片因此变黄。种子萌发本身不需要光，呼吸作用在暗处也照常进行。", "tip": "「光是叶绿素形成的条件」——缺光→叶黄，这是经典考点，别和「光合作用需要光」混淆。", "method": "看到「暗处变黄」→ 指向叶绿素合成需要光。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做需要 10 天完成，乙单独做需要 15 天完成。若两人合作，完成这项工程需要（　　）天。", "options": ["5", "6", "7", "8"], "answer": ["B"], "explain": "设工程总量为 10 与 15 的最小公倍数 30，则甲的效率为 30÷10＝3，乙的效率为 30÷15＝2，两人合作效率为 3＋2＝5。所需时间＝30÷5＝6（天）。", "method": "赋值法：工程问题把总量设为完工天数的公倍数，各人效率即为整数，运算最简。", "tip": "时间之比 10∶15＝2∶3，则效率之比为 3∶2（反比）；合作时间一定小于甲单干，别错选 5。"}, {"type": "logic", "level": "中等", "stem": "行政诉讼是指公民、法人或其他组织认为行政机关及其工作人员的具体行政行为侵犯其合法权益，依法向人民法院提起诉讼、由人民法院审理的活动。根据上述定义，下列属于行政诉讼的是（　　）", "options": ["李某因不服所在单位对其作出的降职处分，向法院起诉单位", "王某对交警大队对其作出的罚款处罚不服，向人民法院提起诉讼", "张某因邻居侵占其宅基地，向人民法院提起民事诉讼", "某公司因合同纠纷，向人民法院起诉另一家公司"], "answer": ["B"], "explain": "行政诉讼有三个要件：①被告须是行政机关；②针对的是具体行政行为；③向人民法院起诉。B 中被告是交警大队（行政机关），争议是罚款（具体行政行为），完全符合。A 的被告是单位（非行政机关），是内部人事争议；C、D 都是平等民事主体之间的纠纷。", "method": "定义判断：把定义的要素逐条列出（主体/对象/行为），拿选项逐一比对，缺一即排除。", "tip": "记住行政诉讼的内核是「民告官」——被告必须是行政机关，争的是具体行政行为；内部处分、平等主体纠纷都不算。"}]}, {"set": 2, "date": "2026-10-10", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 2 批）", "difficulty": "基础+中等", "items": [{"type": "sci", "level": "中等", "stem": "把一只鸡蛋放入盛水的烧杯中，鸡蛋沉底；向水中逐渐加盐并搅拌，鸡蛋恰好悬浮；继续加盐后鸡蛋最终漂浮在水面。下列说法正确的是（　）", "options": ["鸡蛋悬浮时所受的浮力小于沉底时所受的浮力", "鸡蛋漂浮时所受的浮力等于它所受的重力", "从沉底到漂浮的整个过程中，鸡蛋受到的浮力始终不变", "鸡蛋漂浮时排开盐水的体积比悬浮时排开盐水的体积大"], "answer": ["B"], "explain": "沉底时浮力小于重力；悬浮和漂浮时浮力都等于重力，故 B 正确。加盐后液体密度增大，同一只鸡蛋排开液体的体积不变（仍浸没）时浮力变大，所以悬浮浮力大于沉底浮力，A 错；整个过程浮力并不恒定，C 错；漂浮时浮力仍等于重力，而盐水密度更大，由 F浮＝ρ液gV排 可知排开体积反而变小，D 错。", "tip": "“悬浮”与“漂浮”都满足 F浮＝G物；区别在 V排：悬浮时 V排＝V物，漂浮时 V排＜V物。", "method": "先受力分析定浮力大小（沉底 F浮＜G，悬浮/漂浮 F浮＝G），再据 F浮＝ρ液gV排 判断排开体积。"}, {"type": "sci", "level": "容易", "stem": "下列关于金属与金属材料的说法，正确的是（　）", "options": ["钢和生铁都是铁碳合金，其中钢的含碳量比生铁高", "铁在潮湿的空气中容易生锈，表面镀锌可有效防锈", "铜的导电性比银强，因此常用铜制作电线", "铝合金的硬度比纯铝小"], "answer": ["B"], "explain": "铁在潮湿空气中与氧气、水共同作用容易生锈，镀锌能隔绝空气和水并起电化学保护作用，故 B 正确。生铁含碳量（2%～4.3%）高于钢（0.03%～2%），A 错；导电性银最强、铜次之，C 错；合金的硬度一般大于其成分纯金属，铝合金硬度比纯铝大，D 错。", "tip": "记三组对比：生铁含碳＞钢；合金硬度＞成分纯金属；导电性银＞铜＞铝。", "method": "逐项对照金属材料的基本性质与合金规律，排除法定位。"}, {"type": "sci", "level": "中等", "stem": "关于绿色植物的光合作用与呼吸作用，下列说法正确的是（　）", "options": ["光合作用只在白天进行，呼吸作用只在夜间进行", "光合作用在叶绿体中进行，呼吸作用在活细胞内进行", "光合作用消耗氧气、释放二氧化碳", "呼吸作用储存能量并释放氧气"], "answer": ["B"], "explain": "光合作用在叶绿体中进行，呼吸作用在活细胞（主要在细胞的线粒体）内昼夜不停地进行，故 B 正确。呼吸作用昼夜都有，A 错；光合作用吸收二氧化碳、释放氧气，C 说反了；呼吸作用分解有机物、释放能量并放出二氧化碳，D 错。", "tip": "一句话记：光合“吸碳放氧、储能量”，呼吸“吸氧放碳、释能量”；呼吸昼夜不停，光合需要光照。", "method": "先分清两个过程的场所、原料产物与能量变化，再逐项对照。"}, {"type": "sci", "level": "容易", "stem": "关于声现象，下列说法正确的是（　）", "options": ["声音在真空中传播得最快", "“闻其声知其人”主要依据的是音调", "高速公路旁的隔音墙是在传播过程中减弱噪声", "超声波不能在水中传播"], "answer": ["C"], "explain": "声音的传播需要介质，真空不能传声，A 错；“闻其声知其人”主要依据音色而非音调，B 错；隔音墙是在声音的传播过程中减弱噪声，C 对；超声波可以在水、固体等介质中传播，声呐就是利用超声波在水中定位，D 错。", "tip": "记三句：真空不传声；辨人靠音色；隔音墙属“传播过程中”减弱噪声。", "method": "对照声音的产生、传播条件与三特性逐项判断。"}, {"type": "math", "level": "容易", "stem": "将质量分数 20% 的盐水 200 克与质量分数 5% 的盐水 300 克混合，混合后盐水的质量分数为（　）", "options": ["10%", "11%", "12.5%", "15%"], "answer": ["B"], "explain": "盐的总量＝200×20%＋300×5%＝40＋15＝55（克），溶液总质量＝200＋300＝500（克），质量分数＝55÷500＝11%，故选 B。", "tip": "浓度混合题算“溶质之和÷溶液之和”，切忌把两个百分数直接平均（直接平均会得到 12.5%）。", "method": "先分别求溶质，相加后再除以溶液总质量。"}, {"type": "math", "level": "中等", "stem": "甲、乙两人分别从相距 36 千米的两地同时出发相向而行，甲每小时走 5 千米，乙每小时走 4 千米。甲带的一条狗以每小时 8 千米的速度在两人之间往返奔跑，直到两人相遇时狗才停下。狗一共跑了多少千米？（　）", "options": ["24 千米", "28 千米", "32 千米", "36 千米"], "answer": ["C"], "explain": "狗奔跑的总时间＝两人从出发到相遇的时间。相遇时间＝36÷(5＋4)＝4（小时），故狗跑的路程＝8×4＝32（千米），选 C。", "tip": "“往返跑”类题不用逐段累加，抓“时间相同”即可：狗跑的时间＝两人相遇所需时间。", "method": "先求相遇时间（路程÷速度和），再乘狗的速度。"}, {"type": "math", "level": "中等", "stem": "某商品按获利 20% 定价，后来按定价打八折出售，结果亏了 40 元。该商品的进价是多少元？（　）", "options": ["800 元", "1000 元", "1200 元", "1500 元"], "answer": ["B"], "explain": "设进价为 x 元。定价＝1.2x，打八折后售价＝1.2x×0.8＝0.96x。由“亏 40 元”得 x－0.96x＝0.04x＝40，解得 x＝1000（元），选 B。", "tip": "利润率的单位“1”是进价；先算出实际售价比进价少百分之几（本题少 4%），再对应亏损额。", "method": "设进价为 x，写出定价→折后售价，用亏损额列一元一次方程。"}, {"type": "logic", "level": "中等", "stem": "沉没成本是指由于过去的决策已经发生、而不能由现在或将来的任何决策改变的成本。根据上述定义，下列属于沉没成本的是（　）", "options": ["小王为看一场电影已购买的、不可退换的电影票", "某公司为新增生产线向银行申请的贷款利息", "小李为了将来出国留学而报名的英语培训班费用", "企业为扩大生产而计划投入的设备购置预算"], "answer": ["A"], "explain": "沉没成本有两个要件：过去已发生、且不可改变。A 中电影票已购买且不可退换，符合定义。B 贷款利息是针对未来的支出；C 培训费用指向将来收益；D 设备购置属尚未发生的计划投入，均可改变，故排除。", "tip": "定义判断抓“关键要件”：本题要件是“已发生＋不可改变”，逐项比对即可。", "method": "提取定义的两个要件，逐项检验选项是否同时满足。"}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀，与下列哪组词的逻辑关系最为相似？（　）", "options": ["画家∶画笔", "农民∶土地", "学生∶课本", "工人∶工资"], "answer": ["A"], "explain": "题干是“职业与其所使用的工具”的对应关系：医生使用手术刀。A 中画家使用画笔，关系一致。B 土地是农民的劳动对象（场所）而非工具；C 课本是学生使用的学习材料，但学生不是职业、且重点在“学习用品”而非“操作工具”；D 工资是工人的报酬，与题干关系不符。", "tip": "类比先定关系大类（工具/对象/原料/产物…），再比“是否同为职业与操作工具”。", "method": "先判题干关系类型，再逐项验证是否为同一种关系。"}, {"type": "logic", "level": "中等", "stem": "某单位要选派人员参加比赛。已知条件：（1）如果派甲去，则必须派乙去；（2）只有派丙去，才派丁去；（3）甲和丙两人中至少派一人；（4）不派乙去。据此可以推出（　）", "options": ["一定派甲去", "一定派丙去", "一定派丁去", "甲和丁都被派去"], "answer": ["B"], "explain": "（4）不派乙。（1）甲→乙，结合“不派乙”逆否可得不派甲。（3）甲和丙至少一人，既然不派甲，则必派丙。（2）丁→丙，丙被派并不能反推丁，故丁是否派去无法确定。唯一能确定的是“一定派丙去”，选 B。", "tip": "“只有…才…”表示后者是前者的必要条件（前→后）；“如果…则…”表示前者是充分条件（前→后）。善用逆否命题。", "method": "把条件符号化（甲→乙、丁→丙、甲∨丙、¬乙），从头逆推链条。"}, {"type": "fig", "imgs": ["data/figs/figq_001_1.png", "data/figs/figq_001_2.png"], "src": "", "cat": "", "fmt": "", "stem": "选择最合适的完成图形推理：", "options": ["", "", "", "", ""], "answer": ["C"], "explain": "前三个图形，图一图二都有圆，图三是圆。图一图二是两个图形，图三是一个图形。后三个图形应该也是一样的道理，图一图二都有三角形，所以图三是三角形，图一图二是两个图形，图三是一个图形。只有选项C符合，所以选C。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_002_1.png"], "src": "", "cat": "", "fmt": "", "stem": "根据以上图形的规律，下一个图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "看小黑点和竖线，第二列，小黑点在竖线的左侧，竖线每次旋转45°；第三列竖线每次旋转45°，每转一次小黑点位置就变一次，右，左，右，左。", "trap": ""}]}, {"set": 3, "date": "2026-10-10", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 3 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入盛水的玻璃杯中，从侧面看，筷子好像在水面处“折断”了。这一现象说明：", "options": ["光在水中不沿直线传播", "光从水斜射入空气时发生了折射", "光总是沿曲线传播", "水面把筷子切断了"], "answer": ["B"], "explain": "光从水斜射入空气时，传播方向在两介质交界处发生偏折，这就是光的折射；人眼仍沿折射光线的反向看去，便产生了“折断”的错觉。光在同种均匀介质中沿直线传播，A、C 错；D 显然错误。故选 B。", "method": "判断光学现象先分类：同种均匀介质→沿直线传播（影子、小孔成像）；斜射到界面、进入另一介质→折射（筷子折断、水变浅）；遇到反射面→反射（倒影、平面镜）。", "tip": "别把“折射”当成“反射”——看有没有“界面”并“进入另一种介质”。", "hard": "“光的反射”与“光的折射”最易混。"}, {"type": "sci", "level": "容易", "stem": "一个物体在水平面上做匀速直线运动，则它受到的力：", "options": ["一定不受任何力的作用", "一定是平衡力", "一定是非平衡力", "以上都不对"], "answer": ["B"], "explain": "物体做匀速直线运动，速度的大小和方向都不变，处于平衡状态，所受的力一定是平衡力（合力为零）。物体受重力、支持力等，并非不受力，A 错；既然匀速，就不是非平衡力，C 错。故选 B。", "method": "记“平衡状态”：静止或做匀速直线运动⇒受力平衡，合力为零。", "tip": "“匀速”不等于“不受力”，而是“受平衡力”。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "一个木块漂浮在水面上，则它受到的浮力与物体重力的大小关系是：", "options": ["浮力大于重力", "浮力小于重力", "浮力等于重力", "无法比较"], "answer": ["C"], "explain": "木块漂浮时处于静止（平衡）状态，竖直方向只受浮力和重力两个力，二力平衡，故浮力等于重力。故选 C。", "method": "漂浮、悬浮均为平衡状态，F浮＝G；下沉时 F浮＜G；从水底上浮过程中 F浮＞G。", "tip": "漂浮和悬浮都是平衡状态、浮力都等于重力，区别在于物体密度与液体密度的大小关系。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "把一盆绿色植物放到黑暗处一昼夜后，用黑纸片把一片叶的一部分遮住，再光照几小时，摘下后经酒精脱色、滴加碘液处理。观察到的现象是：", "options": ["遮光部分变蓝，见光部分不变蓝", "见光部分变蓝，遮光部分不变蓝", "整片叶都变蓝", "整片叶都不变蓝"], "answer": ["B"], "explain": "见光部分进行了光合作用，产生了淀粉，遇碘变蓝；遮光部分见不到光，不能进行光合作用、没有淀粉，故不变蓝。故选 B。", "method": "验证“光合作用需要光”：黑暗处理→部分遮光→光照→酒精脱色→滴碘。见光部分变蓝，说明有淀粉生成。", "tip": "“黑暗处一昼夜”是为了耗尽叶片中原有的淀粉，否则结果不可靠，别漏这一步。", "hard": "容易忽略“先暗处理”的作用。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做需要 10 天完成，乙单独做需要 15 天完成。两人合作，需要多少天完成？", "options": ["5 天", "6 天", "8 天", "12 天"], "answer": ["B"], "explain": "把工程总量设为 1，甲每天做 1/10，乙每天做 1/15，合作每天做 1/10＋1/15＝3/30＋2/30＝5/30＝1/6，故需要 6 天。故选 B。", "method": "赋值法：取工作时间的最小公倍数作总量。10、15 的最小公倍数是 30，甲 3、乙 2，合计 5，则 30÷5＝6 天。", "tip": "别把天数直接相加（10＋15＝25 是常见错解）；效率才能相加，时间不能。", "hard": ""}, {"type": "math", "level": "中等", "stem": "浓度为 20% 的盐水 200 克，要使其浓度变为 25%，需要蒸发掉多少克水？", "options": ["30 克", "40 克", "50 克", "60 克"], "answer": ["B"], "explain": "盐的质量＝200×20%＝40 克，蒸发水时盐的质量不变。设蒸发 x 克水，则 40/(200−x)＝25%，解得 200−x＝160，x＝40 克。故选 B。", "method": "浓度问题抓“不变量”：加水时盐不变，蒸发水时盐也不变，用溶质质量列方程。", "tip": "先算溶质（盐）质量，再按新浓度反推溶液总量，别拿 200 直接乘 5%。", "hard": ""}, {"type": "math", "level": "中等", "stem": "甲、乙两人从相距 36 千米的两地同时出发，相向而行，甲每小时走 5 千米，乙每小时走 4 千米。经过几小时两人相遇？", "options": ["3 小时", "4 小时", "4.5 小时", "5 小时"], "answer": ["B"], "explain": "相向而行时，两人的速度和＝5＋4＝9（千米/时），相遇时间＝总路程÷速度和＝36÷9＝4 小时。故选 B。", "method": "相遇问题：时间＝总路程÷速度和；追及问题：时间＝路程差÷速度差。", "tip": "先分清“相向（求和）”还是“同向（求差）”，别把速度和、速度差用反。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "光环效应，是指人们对他人的认知判断首先根据个人的好恶得出，然后再从这个判断推论出认知对象的其他品质的现象。根据上述定义，下列属于光环效应的是：", "options": ["因为小李待人热情，大家便认为他工作也一定认真负责", "小李工作认真，同事们都愿意与他合作", "小李因为个子高，被选进了学校篮球队", "小李因为成绩优异，获得了奖学金"], "answer": ["A"], "explain": "光环效应的关键要件是“由对某一特点的好印象，推及其他并不相关的品质”。A 由“待人热情”推出“工作认真负责”，正是以点带面的推论，符合定义。B 是正常因果；C、D 都是某一条件导致的相关结果，不存在“推及其他品质”。故选 A。", "method": "定义判断：先圈出定义的关键要件（主体、方式、结果），再逐项比对，缺件即排除。", "tip": "抓住“由已知的某一特征推及其他无关品质”这一核心要件。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀（　）", "options": ["画家∶画笔", "病人∶医院", "老师∶学生", "农民∶土地"], "answer": ["A"], "explain": "医生使用手术刀作为职业工具，二者是“职业—工具”关系。A 画家使用画笔，同样是职业—工具关系；B 是“人—场所”，C 是“人—对象”，D 是“人—劳动对象（场所）”。故选 A。", "method": "类比推理先定题干关系（工具/场所/对象/因果/并列……），再到选项里找同一种关系的。", "tip": "分清“工具”与“对象”：手术刀是工具，土地是被作用的对象。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "只有努力学习，才能考上理想的大学。小李没有考上理想的大学。由此可以推出：", "options": ["小李一定没有努力学习", "小李一定努力学习了", "小李可能没有努力学习", "小李学习很努力，只是发挥失常"], "answer": ["C"], "explain": "“只有努力，才能考上”表示“考上→努力”（努力是考上的必要条件）。小李没考上，是否定了后件，不能必然推出他是否努力，只能说“可能没有努力”。A 把“可能”误当成“必然”；B、D 更无从推出。故选 C。", "method": "必要条件命题“只有 A 才 B”可写成“B→A”：肯定后件必肯定前件；否定后件推不出确定结论，只能得到“可能”。", "tip": "“只有……才……”是必要条件，切忌由“没考上”直接推成“没努力”。", "hard": "充分条件与必要条件容易记反。"}, {"type": "fig", "imgs": ["data/figs/figq_003_1.png", "data/figs/figq_003_2.png"], "src": "", "cat": "", "fmt": "", "stem": "空缺处的图形应当是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "一行看过去，前两个合并叠加，等于第三个。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_004_1.png"], "src": "", "cat": "", "fmt": "", "stem": "根据以上图形规律，下一个图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "把线条分为上下方向移动和左右方向移动，横线从下往上移动一个单位（移到最顶部再移动就回到最底部），竖线从左往右移动一个单位（移到最右边再移动就回到最左边）。", "trap": ""}]}, {"set": 4, "date": "2026-10-11", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 4 批）", "items": [{"type": "sci", "level": "容易", "stem": "在水平地面上，用水平推力推一个静止的木箱，木箱未被推动。下列说法正确的是：", "options": ["木箱受到的推力小于摩擦力", "木箱受到的静摩擦力与推力大小相等、方向相反", "木箱受到的静摩擦力大于推力", "木箱不受摩擦力"], "answer": ["B"], "explain": "木箱保持静止，处于平衡状态，水平方向上推力与静摩擦力是一对平衡力，二者大小相等、方向相反，故选 B。A、C 把大小关系说反了，只要木箱没被推动，静摩擦力就始终等于推力；D 错误，木箱虽静止但有相对地面滑动的趋势，必然受到静摩擦力。", "method": "受力平衡法：先判断物体处于什么运动状态，再对水平方向作二力平衡分析。", "tip": "静摩擦力的大小随外力变化而变化，不能直接套用滑动摩擦力的公式 f＝μN。", "hard": "把“静摩擦力”当成“滑动摩擦力”去套公式。"}, {"type": "sci", "level": "中等", "stem": "下列关于生活中常见现象的解释，错误的是：", "options": ["铁在潮湿的空气中容易生锈，是因为铁与氧气和水共同作用", "用食醋可以除去水壶中的水垢，是因为醋酸能与水垢中的碳酸钙反应", "新装修的房间有刺鼻气味，主要是甲醛等物质挥发造成的", "冬天用煤炉取暖要开窗通风，是因为煤不完全燃烧会产生二氧化碳"], "answer": ["D"], "explain": "D 的解释错误：煤在氧气不足时不充分燃烧，产生的有毒气体主要是一氧化碳（CO），而不是二氧化碳，所以必须开窗通风以防中毒，故选 D。A、B、C 的解释均符合化学原理：铁生锈需氧气和水，醋酸可与碳酸钙反应，新装修的刺激性气味多由甲醛等挥发造成。", "method": "逐一判断法：把每个选项当作一个独立的化学小结论去核对，选出明显违背生活化学常识的一项。", "tip": "一定要区分一氧化碳和二氧化碳：前者有毒、可致人中毒，后者本身无毒，这是常见误区。", "hard": "“一氧化碳”与“二氧化碳”混淆。"}, {"type": "sci", "level": "中等", "stem": "关于人体消化系统，下列说法正确的是：", "options": ["胃是消化和吸收营养物质的主要器官", "小肠内表面有许多皱襞和小肠绒毛，有利于营养物质的吸收", "胆汁中含有消化脂肪的酶", "食物中的淀粉在口腔中开始被消化为葡萄糖"], "answer": ["B"], "explain": "小肠内壁有大量皱襞和小肠绒毛，极大增加了消化和吸收的面积，使小肠成为消化吸收的主要器官，故选 B。A 错在把主要器官说成了胃；C 错在胆汁并不含消化酶，它只是把脂肪乳化成小颗粒；D 错在口腔中淀粉被分解为麦芽糖，而不是葡萄糖。", "method": "抓结构与功能相适应：看哪个选项把器官的结构与它的生理功能对应得最合理。", "tip": "牢记两点：胆汁不含消化酶；淀粉在口腔只被消化成麦芽糖，最终在小肠才变成葡萄糖。", "hard": "误以为胆汁中含有消化脂肪的酶。"}, {"type": "sci", "level": "容易", "stem": "夏天从冰箱中取出一瓶冰镇饮料，放置一会儿后，瓶外壁出现许多小水珠。对该现象的分析，正确的是：", "options": ["是瓶内的饮料渗漏到瓶外形成的", "是瓶外空气遇冷凝固形成的", "是空气中的水蒸气遇冷液化形成的", "小水珠形成的过程中要吸收热量"], "answer": ["C"], "explain": "瓶壁温度很低，空气中的水蒸气接触到冷瓶壁后放热液化成小水珠附着在瓶外，故选 C。A 属无中生有，瓶内液体并未渗漏；B 错在把液化说成凝固，凝固是液态变固态；D 错在液化过程要放热，而不是吸热。", "method": "物态变化判断题：先判断物质变化前后各是什么状态，再对应相应物态变化的名称与吸放热情况。", "tip": "液化的关键是“气态→液态”，且液化放热，别与凝固、汽化混淆。", "hard": "把“液化”与“凝固”弄混，或记错吸放热。"}, {"type": "math", "level": "中等", "stem": "一项工程，甲单独做需要 10 天完成，乙单独做需要 15 天完成。若甲先单独做 2 天后，再由甲、乙两人合作完成剩余工程，则完成这项工程共需要多少天？", "options": ["6 天", "6.5 天", "6.8 天", "7 天"], "answer": ["C"], "explain": "设工作总量为 30（10 和 15 的最小公倍数），则甲效率为 3、乙效率为 2。甲先做 2 天完成 3×2＝6，剩余 30－6＝24；两人合作效率为 3＋2＝5，需 24÷5＝4.8 天。总时间为 2＋4.8＝6.8 天，故选 C。A、B、D 多为只算合作时间或取整出错。", "method": "赋值法：把工作总量赋为两人单独完成天数的公倍数，便于快速算出各自效率。", "tip": "题目问的是“完成这项工程总共需要多少天”，要把甲先单独做的 2 天加上，别只算合作天数。", "hard": "漏掉甲先单独做的 2 天，只算合作时间。"}, {"type": "math", "level": "容易", "stem": "甲、乙两数之和为 60，甲数比乙数的 2 倍少 6，则甲、乙两数分别是：", "options": ["36 和 24", "38 和 22", "40 和 20", "34 和 26"], "answer": ["B"], "explain": "设乙数为 x，则甲数为 2x－6，由题意得 (2x－6)＋x＝60，即 3x－6＝60，解得 x＝22，甲数为 2×22－6＝38，故选 B。其余选项代入都不能同时满足“和为 60”且“甲比乙的 2 倍少 6”两个条件。", "method": "方程法：设较小的数为未知数，把另一个数用含未知数的式子表示，再根据数量关系列方程求解。", "tip": "“比乙数的 2 倍少 6”是 2x－6，不要写成 2(x－6)，少 6 是在整体 2x 上减去 6。", "hard": "把“2x－6”错写成“2(x－6)”。"}, {"type": "math", "level": "中等", "stem": "某商品按成本加价 50% 标价，后因促销按标价打八折出售，则每件商品的利润率是多少？", "options": ["15%", "25%", "30%", "20%"], "answer": ["D"], "explain": "设成本为 100，则标价为 100×(1＋50%)＝150，八折售价为 150×0.8＝120，利润为 120－100＝20，利润率＝20÷100×100%＝20%，故选 D。A、B、C 多因把折扣或加价率算错，或把利润除以售价而得到。", "method": "赋值法：直接设成本为 100，按顺序算出标价、售价、利润，最后套利润率公式。", "tip": "利润率＝利润÷成本×100%，分母是“成本”而不是“售价”，两者相差较大，是最常见的失分点。", "hard": "把利润率的分母错用成“售价”。"}, {"type": "logic", "level": "中等", "stem": "破窗效应是指：环境中的不良现象如果被放任存在，会诱使人们仿效，甚至变本加厉。根据上述定义，下列不属于破窗效应的是：", "options": ["一面墙上出现一些涂鸦没有被及时清洗掉，很快墙上就布满了乱七八糟的东西", "某广场干净整洁时没人乱扔垃圾，一旦有人扔了垃圾而无人制止，不久地上就到处是垃圾", "一栋房子的窗户破了没人修补，过不了多久，其他窗户也会被人打破", "小明坚持每天早起晨跑，受他影响，同学们也纷纷开始早起晨跑"], "answer": ["D"], "explain": "题干定义强调“不良现象被放任→诱使他人仿效并变本加厉”，而 D 中“早起晨跑”是良好的行为习惯，同学们仿效的是正面行为，与定义中“不良现象”这一要件不符，故选 D。A、B、C 都符合“不良现象被放任后被纷纷效仿”的特征。", "method": "定义判断抓要件：把定义拆成“不良现象＋被放任＋被仿效并加重”几个关键要件，逐一对照选项。", "tip": "务必抓住“不良现象”这个核心前提，正面行为的带动再像也不属于破窗效应。", "hard": "只看“被仿效”就选，忽略“不良现象”这一前提。"}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀 相当于：", "options": ["画家∶画笔", "农民∶土地", "学生∶书本", "司机∶乘客"], "answer": ["A"], "explain": "医生工作时要使用手术刀，二者是“职业与其使用的工具”的对应关系，画家工作时使用画笔，同样是职业与工具的对应，故选 A。B 中土地是农民劳作的场所；C 中书本是学生学习的对象或资料，工具色彩不如 A 直接；D 中乘客是司机的服务对象。", "method": "类比推理先定关系：准确概括出题干两词的关系类型，再找与之关系最贴近、最一致的一项。", "tip": "要比较关系的“同一性”，不能只看是否相关；场所、对象、工具三种关系要分辨清楚。", "hard": "把“场所关系”“对象关系”误当成“工具关系”。"}, {"type": "logic", "level": "较难", "stem": "某研究表明，经常喝咖啡的人患某种疾病的概率明显低于不喝咖啡的人。因此，研究人员认为喝咖啡能降低患该疾病的风险。以下哪项如果为真，最能削弱上述结论？", "options": ["这项研究的样本量相对较小，结论的可靠性有待进一步验证", "经常喝咖啡的人往往也更注重锻炼身体和饮食健康，而这些习惯本身就能降低患病风险", "咖啡中含有一些对人体有益的抗氧化物质", "不喝咖啡的人群中，也有很多人身体十分健康"], "answer": ["B"], "explain": "题干由“喝咖啡者患病少”直接推出“喝咖啡能降低患病风险”。若 B 成立，说明患病少可能是锻炼和饮食健康等“其他因素”造成的，而非咖啡本身，属于典型的“另有他因”削弱，削弱力度最强，故选 B。A 只是说样本量小，削弱力度较弱；C 反而支持结论；D 与结论无直接关系。", "method": "削弱题抓“因果链”：题干由相关关系推因果关系，削弱应优先找“另有他因”或“因果倒置”。", "tip": "削弱力度要比较：直接斩断因果（另有他因）强于笼统质疑研究的可靠性，别被“样本小”这类弱选项带走。", "hard": "被“样本量小”这类弱削弱项迷惑，忽略“另有他因”的强削弱。"}, {"type": "fig", "imgs": ["data/figs/figq_005_1.png", "data/figs/figq_005_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "每一行都是两个黑球两个白球。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_006_1.png", "data/figs/figq_006_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "第一个图中，左边到中间规律是：第一个移到最后，全体箭头换方向中间到后边同理。", "trap": ""}]}, {"set": 5, "date": "2026-10-11", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 5 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入水中，从水面上方看，筷子在水中的部分好像“折断”了。这是因为（　）", "options": ["光从水中斜射入空气时发生了折射", "光在水中发生了反射", "光沿直线传播被水挡住了", "水面发生了漫反射"], "answer": ["A"], "explain": "筷子反射的光从水中斜射入空气时，在水面处改变传播方向，人眼逆着光线看去，就觉得筷子在水中“变折”了，这是光的折射，选 A。B、D 是反射现象，C 与现象不符。", "method": "看到水中的物体“位置变了/折断/变浅”，都是折射（光从一种介质斜射入另一种介质）；看到水中倒影才是反射。", "tip": "折射的关键词是“斜射入另一种介质”，垂直入射时不偏折。", "hard": "注意区分：看水中的鱼“变浅”、筷子“折断”是折射；看水面的倒影是反射。"}, {"type": "sci", "level": "容易", "stem": "关于惯性，下列说法正确的是（　）", "options": ["物体只有在静止时才有惯性", "惯性的大小只与物体的质量有关，与速度无关", "运动越快的物体惯性越大", "物体受到的力越大，惯性越大"], "answer": ["B"], "explain": "惯性是物体保持原有运动状态的性质，是一切物体固有的属性，大小只由质量决定，与速度、受力都无关，B 正确。A、C、D 都把惯性与状态、速度或力混为一谈。", "method": "判惯性题只认“质量”一个量：质量越大惯性越大，其余条件一律不影响。", "tip": "“惯性”与“惯性定律（牛顿第一定律）”不是一回事，惯性是属性，不能被“产生”。", "hard": "常见陷阱：说“速度大惯性大”“受力大惯性大”——都是把惯性和运动状态、力混了。"}, {"type": "sci", "level": "中等", "stem": "某溶液的 pH＝3，向其中滴入紫色石蕊试液，溶液呈现的颜色是（　）", "options": ["红色", "蓝色", "紫色", "无色"], "answer": ["A"], "explain": "pH＝3＜7，溶液显酸性，紫色石蕊试液遇酸变红，故选 A。B 是石蕊遇碱的颜色，C 是中性时不变色，D 不符合石蕊变色的规律。", "method": "记石蕊口诀：遇酸变红、遇碱变蓝，中性紫色不变。先由 pH 判酸碱性，再看颜色。", "tip": "酚酞遇酸不变色（仍无色），石蕊遇酸变红——两种指示剂别记混。", "hard": "pH 越小酸性越强，但要看清题问的是“石蕊”还是“酚酞”。"}, {"type": "sci", "level": "中等", "stem": "一对夫妇均为 AB 型血，他们的子女可能的血型是（　）", "options": ["只能是 AB 型", "A 型或 B 型", "A 型、B 型或 AB 型", "A 型、B 型、AB 型或 O 型"], "answer": ["C"], "explain": "AB 型血的基因型为 I^A I^B，双亲各提供一个基因：可组合成 I^A I^A（A 型）、I^A I^B（AB 型）、I^B I^B（B 型），因此子女可能是 A、B、AB 型，选 C。O 型（ii）需要两个 i 基因，双亲均无 i，故不可能，排除 D。", "method": "血型遗传用“各取一个基因再两两组合”，列组合表即可；注意 O 型必须同时拿到两个 i。", "tip": "AB 型父母不可能生出 O 型孩子，这是最常见的干扰项。", "hard": "别忘了 A 型可能来自 I^A I^A 也可能 I^A i，但本题父母无 i，所以只出现 A、B、AB 三种。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做 10 天完成，乙单独做 15 天完成。两人合作，需要多少天完成？", "options": ["5 天", "6 天", "7 天", "8 天"], "answer": ["B"], "explain": "把工程总量设为“1”。甲每天做 1/10，乙每天做 1/15，合作每天做 1/10＋1/15＝3/30＋2/30＝5/30＝1/6，所以需要 6 天，选 B。", "method": "工程问题赋值法：总量设为 1（或设为两人效率的最小公倍数），合作时间＝1÷效率和。", "tip": "总量设 1 后，效率就是“每天完成几分之几”，别把 10 和 15 直接相加。", "hard": "若设总量为 30，则甲效率 3、乙效率 2，合作 30÷5＝6 天，结果一致，赋值更省事。"}, {"type": "math", "level": "中等", "stem": "某商品进价 80 元，标价 120 元。若按标价打八折出售，则利润率是（　）", "options": ["20%", "25%", "30%", "40%"], "answer": ["A"], "explain": "售价＝120×0.8＝96 元，利润＝96－80＝16 元，利润率＝利润÷进价＝16÷80＝20%，选 A。", "method": "利润率的分母永远是“进价（成本）”，不是标价、也不是售价。先算实际售价，再套公式。", "tip": "16÷120≈13.3% 是把分母用错（用了标价）的典型错法，正好对应干扰项附近。", "hard": "“打八折”是乘以 0.8；利润率＝(售价－进价)÷进价，两个易错点叠在一起。"}, {"type": "math", "level": "中等", "stem": "从 1、2、3、4、5 中任取两个不同的数字，组成一个两位数，一共能得到多少个不同的两位数？", "options": ["10 个", "15 个", "20 个", "25 个"], "answer": ["C"], "explain": "两位数有十位和个位，顺序不同算不同的数。十位有 5 种选法，个位在剩下的 4 个数字中选，共 5×4＝20 个，选 C。", "method": "“取两个不同数字组两位数”是有序排列：先定十位（5 种），再定个位（4 种），相乘。", "tip": "若问“任取两个数字组成一个集合/组合”才是 5×4÷2＝10 种，注意“两位数”隐含有序。", "hard": "选项里的 10 就是漏掉顺序（当成组合）的结果，要看清“组两位数”是否讲究顺序。"}, {"type": "logic", "level": "容易", "stem": "搭便车效应：指在集体行动中，个别人不付出成本却坐享集体收益的现象。根据上述定义，下列属于搭便车效应的是（　）", "options": ["小区业主共同出资修路，其中某户未出钱却照常通行", "顾客趁商场打折时低价购入心仪商品", "员工加班完成项目后获得了公司奖金", "农民在自家承包地里辛勤耕种，获得丰收"], "answer": ["A"], "explain": "A 中该户未出资（不付成本）却照常享用大家修的路（坐享集体收益），符合定义。B 是正常消费；C 付出了加班劳动并得到对等奖励；D 自己劳动自己收获，均不符合“不付成本却享集体收益”。", "method": "定义判断抓“要件”：①集体行动 ②不付成本 ③享受集体收益，三者同时满足才可入选，缺一个就排除。", "tip": "“搭便车”的关键是“不付出却受益”，不要被“打折”“奖励”这类无关词带偏。", "hard": "易错项是那些“看似占了便宜”的日常行为（如打折购物），其实并不涉及“集体行动”。"}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀。下列选项中，与这一组关系最为相似的是（　）", "options": ["厨师∶菜刀", "教师∶钢笔", "农民∶土地", "作家∶小说"], "answer": ["A"], "explain": "“医生”是职业，“手术刀”是该职业工作时使用的专门工具，二者是“职业—工具”关系。A“厨师∶菜刀”同样是职业与其专用工具，故选 A。B 钢笔只是书写工具、并非教师专有；C 土地是劳动对象（场所），不是工具；D 小说是作家创作的产品。", "method": "类比题先给题干关系“定性”（职业与工具/对象/产品），再逐项对照，找关系最贴合的。", "tip": "区分“工具”与“对象”“产品”：手术刀是工具，土地是对象，小说是产品。", "hard": "B 迷惑性在于“教师也用笔”，但钢笔不是教师职业的专属工具（医生与手术刀则有强对应）。"}, {"type": "logic", "level": "较难", "stem": "甲、乙、丙三人中只有一人说真话。甲说：“乙在说谎。”乙说：“丙在说谎。”丙说：“甲和乙都在说谎。”由此可以推出（　）", "options": ["甲说真话", "乙说真话", "丙说真话", "三人都说真话"], "answer": ["B"], "explain": "设甲、乙、丙的话分别为 A、B、C。A＝“乙在说谎”＝非 B；B＝“丙在说谎”＝非 C；C＝“甲和乙都在说谎”＝非 A 且非 B。若 C 真，则 A、B 都假，但 A＝非 B 就为真，矛盾，故 C 假。C 假说明“A 假且 B 假”不成立，即 A、B 至少一真；又 A＝非 B，故 A、B 恰一真一假。若 A 真则 B 假，而 B＝非 C，由 C 假得 B 真，矛盾；故只能是 A 假、B 真。此时 C 假也成立。所以只有乙说真话，选 B。", "method": "真假话题用“假设法＋矛盾排除”：先假设某句为真，推出矛盾就否定它，剩下的唯一自洽情形即答案。", "tip": "把每句话写成“非某某”的等价式再推理，比空想更不容易乱。", "hard": "“只有一人说真话”是硬约束，推出的情形必须与之一致；本题“乙真、甲丙假”正好满足。"}, {"type": "fig", "imgs": ["data/figs/figq_007_1.png", "data/figs/figq_007_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", "", ""], "answer": ["E"], "explain": "最底层相邻两个两两相加，得到上一层，相同消去，相异叠加。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_008_1.png"], "src": "", "cat": "", "fmt": "", "stem": "下列图形中不同于其他图形的一项是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "其他图形都是两个元素组成，只有A是三个图形元素。", "trap": ""}]}, {"set": 6, "date": "2026-10-12", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 6 批）", "items": [{"type": "sci", "level": "容易", "stem": "小明用弹簧测力计沿水平方向拉一个放在水平桌面上的木块，木块保持静止。此时弹簧测力计的示数为 3N。下列说法正确的是：", "options": ["木块不受摩擦力", "木块受到的合力为 3N", "木块受到的摩擦力大于 3N", "木块受到的摩擦力大小为 3N，方向与拉力相反"], "answer": ["D"], "explain": "木块静止，水平方向受拉力和摩擦力，二力平衡，故摩擦力与拉力大小相等、方向相反，为 3N，合力为 0，D 对。A 忽略了摩擦力的存在；B、C 都违背了二力平衡条件。", "method": "先判断运动状态（静止/匀速 → 合力为零），再对水平方向做受力分析，列出平衡方程。", "tip": "“静止就是受力平衡”，不要看到“有拉力”就以为摩擦力一定存在方向问题。", "hard": "容易漏掉竖直方向的判断（重力与支持力也平衡）。"}, {"type": "sci", "level": "容易", "stem": "某溶液能使紫色石蕊试液变蓝，则该溶液：", "options": ["一定呈中性", "一定呈碱性", "一定是氢氧化钠溶液", "一定能使无色酚酞试液变蓝"], "answer": ["B"], "explain": "石蕊遇碱变蓝，故该溶液一定呈碱性，B 对。A 与变色规律矛盾。C 过于绝对，碳酸钠溶液等也呈碱性。D 错在酚酞遇碱变红而非变蓝，与石蕊变色规律不同。", "method": "记住指示剂变色规律：石蕊遇酸变红、遇碱变蓝；酚酞遇碱变红、遇酸不变色。", "tip": "“碱性溶液”不等于“某一种具体的碱”，别把结论收紧成某个具体物质。", "hard": "多个选项看似都对，要抓住题目问的“一定”与“直接对应”。"}, {"type": "sci", "level": "中等", "stem": "把一盆绿色植物放在黑暗处一昼夜后，用黑纸片把其中一片叶的一部分上下两面都遮盖起来，然后移到阳光下照射几小时，再取下该叶片脱色、漂洗、滴加碘液。结果是：", "options": ["遮盖部分不变蓝，未遮盖部分变蓝", "遮盖部分变蓝，未遮盖部分不变蓝", "整片叶都变蓝", "整片叶都不变蓝"], "answer": ["A"], "explain": "暗处理耗尽淀粉后，只有见光部分能进行光合作用制造淀粉，遇碘变蓝；遮光部分无光不能光合作用，无淀粉，不变蓝。故 A 对。", "method": "抓住实验变量是“光”，见光处才有光合作用产物（淀粉），淀粉遇碘变蓝。", "tip": "暗处理一昼夜是为了耗尽原有淀粉，这一步忘掉会误判。", "hard": "区分“光合作用产物淀粉”与“呼吸作用消耗有机物”。"}, {"type": "sci", "level": "中等", "stem": "把一根筷子斜插入盛水的碗中，从水面上方看去，水下部分好像“折断”并向上弯折。下列现象成因与之相同的是：", "options": ["用平面镜看到自己的像", "岸边看到水中的鱼比实际位置浅", "日食的形成", "手影游戏"], "answer": ["B"], "explain": "筷子“折断”是光从水射入空气时发生折射造成的。看到水中的鱼比实际浅同样是由光的折射引起，B 对。A 是平面镜反射（成像）；C、D 都属于光的直线传播形成影/食。", "method": "先判断现象类属：反射（镜面/成像）、折射（跨介质看物体）、直线传播（影/食/小孔成像）。", "tip": "“插入水中变弯”“池水变浅”“鱼的实际位置”都是折射。", "hard": "“看水中的鱼”是看物体（折射），而“水面映出天空”是反射，勿混。"}, {"type": "math", "level": "中等", "stem": "一项工程，甲单独做需 12 天，乙单独做需 18 天。两人合作完成这项工程，中途甲休息了 3 天，乙一直没有休息。问完成这项工程共用多少天？", "options": ["8 天", "9 天", "10 天", "11 天"], "answer": ["B"], "explain": "设工程总量为 36（12 与 18 的最小公倍数），则甲每天做 3，乙每天做 2。设共用了 T 天，乙工作 T 天，甲工作 T−3 天，有 3(T−3)+2T=36，即 5T−9=36，T=9。故选 B。", "method": "赋值法：把总量赋成两人单独完成时间的最小公倍数，求出各自效率，再按“谁休了几天”列方程。", "tip": "别把总量当 1 直接算效率，赋整数值更快且不易错。", "hard": "甲休息时乙仍在做功，这部分工作量容易算漏。"}, {"type": "math", "level": "容易", "stem": "甲、乙两地相距 300 千米。一辆汽车从甲地开往乙地，去时速度为 60 千米/小时，返回时速度为 50 千米/小时，则汽车往返的平均速度为：", "options": ["55 千米/小时", "53 千米/小时", "54.5 千米/小时", "60 千米/小时"], "answer": ["C"], "explain": "去时耗时 300÷60=5 小时，返回耗时 300÷50=6 小时，总路程 600 千米、总时间 11 小时，平均速度=600÷11≈54.5 千米/小时，C 对。注意平均速度不是速度的简单平均（那是 55，对应 A）。", "method": "往返平均速度 = 总路程 ÷ 总时间 = 2v₁v₂/(v₁+v₂)，切忌直接把两个速度相加除以 2。", "tip": "“平均速度”永远是总路程÷总时间；“速度的算术平均”是常见陷阱。", "hard": "若把 600÷11 粗算成 55，就会误选 A。"}, {"type": "math", "level": "容易", "stem": "把 200 克质量分数为 20% 的盐水与 300 克质量分数为 5% 的盐水混合，混合后盐水的质量分数约为：", "options": ["10%", "12.5%", "15%", "11%"], "answer": ["D"], "explain": "溶质总量=200×20%+300×5%=40+15=55 克，溶液总量=200+300=500 克，质量分数=55÷500=11%，D 对。", "method": "抓住“溶质守恒、质量相加”：分别算出各部分溶质，除以总质量。", "tip": "不要用 20% 和 5% 直接取中间值（12.5%），那是等质量混合才成立。", "hard": "两杯质量不同，混合后偏向质量大的那一杯的浓度。"}, {"type": "logic", "level": "中等", "stem": "晕轮效应是指在人际知觉中形成的以点概面、以偏概全的主观印象，即根据对象某一方面的突出特征而推断其其他方面。根据上述定义，下列属于晕轮效应的是：", "options": ["小张因为同事小李平时总是面带笑容，就觉得小李的工作能力也一定很强", "老师根据平时的多次观察和成绩记录，综合评定学生的学期等级", "公司按照统一的绩效考核指标，逐项给每位员工打分", "医生根据化验单上多项检查指标，综合判断患者的病情"], "answer": ["A"], "explain": "A 中仅凭“爱笑”这一突出特征，就推断出“工作能力强”，属于以点概面，符合定义。B、C、D 都是依据多个方面的信息做综合判断，不是以偏概全。故选 A。", "method": "定义判断抓“要件”：①基于某一突出特征 ②据此推断其他无关方面。两要件同时满足才符合。", "tip": "凡出现“综合评定／多项指标／逐项打分”等字眼的，一般是有依据的多维判断，不属于以偏概全。", "hard": "容易把“凭单一证据下结论”与“以某一特征推断其他方面”混为一谈。"}, {"type": "logic", "level": "中等", "stem": "厨师∶菜谱∶烹饪。下列选项中，与这组词在逻辑关系上最为贴近、相似或匹配的是：", "options": ["演员∶剧本∶表演", "观众∶电影∶影院", "学生∶课本∶考试", "病人∶药品∶医院"], "answer": ["A"], "explain": "题干关系：厨师依据菜谱这一“依据”来进行烹饪这一“活动”。A 中演员依据剧本来进行表演，关系一致。B 观众看电影的场所是影院，不符合；C 学生用课本但不是为了“考试”这一活动；D 病人用药品但“医院”是场所。故选 A。", "method": "类比先定“造句式”关系：把三词连成一句话，再拿同样句式去套选项。", "tip": "注意区分“依据（工具）关系”和“场所关系”，不要被表面词性带偏。", "hard": "多个选项都含“人+物+活动”字样，必须逐句核对关系是否一致。"}, {"type": "logic", "level": "容易", "stem": "所有优秀的运动员都经过刻苦训练。小刘经过了刻苦训练。由此可以推出：", "options": ["小刘一定是优秀运动员", "小刘一定不是优秀运动员", "小刘可能是优秀运动员", "优秀运动员都不需要刻苦训练"], "answer": ["C"], "explain": "“优秀运动员 → 刻苦训练”成立，但反过来“刻苦训练 → 优秀运动员”不一定成立。小刘满足后件（刻苦训练），只能推出他“可能”是优秀运动员，不能确定。故选 C。", "method": "记住充分条件推理规则：肯前必肯后，否后必否前；肯后、否前都不能推出确定结论。", "tip": "“所有 A 都 B”只能推出“非 B 非 A”，不能推出“B 则 A”。", "hard": "看到“经过了刻苦训练”就顺着条件倒推，是这类题最常见的错法。"}, {"type": "fig", "imgs": ["data/figs/figq_009_1.png", "data/figs/figq_009_2.png"], "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["C"], "explain": "竖排依次顺时针旋转90°。"}, {"type": "fig", "imgs": ["data/figs/figq_010_1.png"], "stem": "问号处应当是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "前面三个图，图一加图二是图三（图一平移到图二中间的位置）。后三个图也是一样的道理，图一加图二是图三。只有选项D符合，所以答案选D。"}]}, {"set": 7, "date": "2026-10-13", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 7 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入盛水的玻璃杯中，从侧面看，筷子好像在水面处“折断”了，且水下部分看起来变浅。关于这一现象，下列说法正确的是：", "options": ["光从水中斜射入空气时发生了反射", "光从水中斜射入空气发生折射，折射角小于入射角", "光从水中斜射入空气发生折射，折射角大于入射角", "这是光的直线传播造成的"], "answer": ["C"], "explain": "我们看到水下部分，是水中物体反射的光从水斜射入空气后进入眼睛；在界面处发生折射，因空气的折射率小于水，光从光密介质进入光疏介质，折射光线偏离法线，折射角大于入射角，人眼逆着折射光线看过去，物体像的位置比实际位置偏高，故“变浅”。A 说的是反射，与“变浅”无关；B 把折射角与入射角的大小关系说反了；D 属于光的直线传播（如影子、小孔成像），不是折射现象。", "method": "记住“光疏/光密介质”判断法：光从光密（水）入光疏（空气），折射角＞入射角，像偏高（变浅）；反过来从空气入水则折射角＜入射角。", "tip": "别把“反射”和“折射”混为一谈，也要注意方向：水中看空气与空气看水中，折射角大小关系正好相反。"}, {"type": "sci", "level": "容易", "stem": "一个物体在水平地面上做匀速直线运动，下列说法正确的是：", "options": ["物体不受任何力的作用", "物体所受的牵引力大于摩擦力", "物体所受的牵引力等于摩擦力，合力为零", "物体受到的合力方向一定与运动方向相同"], "answer": ["C"], "explain": "匀速直线运动属于平衡状态，物体所受合外力为零。水平方向上牵引力与摩擦力是一对平衡力，大小相等、方向相反，故 C 正确。A 错，不受力只是理想化情形，实际存在牵引力与摩擦力；B 错，若牵引力大于摩擦力物体将加速而不再匀速；D 错，合力为零时没有确定的合力方向。", "method": "看到“静止或匀速直线运动”立刻判定为平衡状态，合外力为零，方向相反的两个力必然等大。", "tip": "关键在“匀速”二字，很多人只盯着力的大小而忘了合力为零这个本质。"}, {"type": "sci", "level": "中等", "stem": "某同学用 pH 试纸测某溶液的 pH，测得结果为 3。下列说法正确的是：", "options": ["该溶液一定是盐酸", "该溶液显酸性，且 pH 越小酸性越强", "该溶液能使酚酞试液变红", "该溶液加水稀释后，pH 会增大到 7 以上"], "answer": ["B"], "explain": "pH＜7 显酸性，且 pH 越小酸性越强，B 正确。pH=3 只能说明溶液显酸性，酸有很多种（硫酸、醋酸等），无法断定就是盐酸，A 错。酚酞遇酸不变色、遇碱变红，C 错。酸性溶液加水稀释时 pH 会向 7 靠近，但无论怎样稀释都不会超过 7，D 错。", "method": "牢记 pH 判据：＜7 酸性、=7 中性、＞7 碱性，数值越远离 7 酸碱性越强。", "tip": "“稀释后 pH 一定升到 7 以上”是典型错项，无限稀释也只是无限接近 7。"}, {"type": "sci", "level": "中等", "stem": "下列关于植物光合作用和呼吸作用的说法，正确的是：", "options": ["光合作用只在白天进行，呼吸作用只在夜间进行", "光合作用消耗氧气，产生二氧化碳", "光合作用在叶绿体中进行，呼吸作用在活细胞内均可进行", "植物白天不进行呼吸作用"], "answer": ["C"], "explain": "光合作用在叶绿体中进行、需要光照；呼吸作用在活细胞的线粒体（细胞质）中进行，昼夜不停，故 C 正确。A 错在“呼吸作用只在夜间进行”；B 把两者物质变化弄反了，光合作用吸收二氧化碳、放出氧气；D 错，白天植物既进行光合作用也进行呼吸作用。", "method": "用两句话记：光合作用“吃”二氧化碳、“吐”氧气，只在有光时进行；呼吸作用“吃”氧气、“吐”二氧化碳，昼夜不停。", "tip": "常见坑是把“呼吸作用只在夜间”“白天只进行光合作用”当成正确说法。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做 10 天完成，乙单独做 15 天完成。两人合作，几天可以完成？", "options": ["5 天", "6 天", "7 天", "8 天"], "answer": ["B"], "method": "赋值法。设总工程量为 10 和 15 的最小公倍数 30，则甲效率为 30÷10=3，乙效率为 30÷15=2，合作效率为 5，时间＝30÷5=6 天。", "explain": "设总工程量为 30，甲每天完成 30/10=3，乙每天完成 30/15=2，两人合作每天完成 3+2=5，故需要 30÷5=6 天，选 B。", "tip": "不要直接把 10 与 15 相加再除以 2；工程问题优先把总量赋值为各时间的最小公倍数。"}, {"type": "math", "level": "中等", "stem": "甲、乙两车分别从 A、B 两地同时出发相向而行，甲车速度 60 千米/时，乙车速度 40 千米/时，两地相距 200 千米。两车相遇时，甲车行驶了多少千米？", "options": ["80 千米", "100 千米", "120 千米", "130 千米"], "answer": ["C"], "method": "相遇问题：相遇时间＝路程和÷速度和，再由各自速度×时间求各自路程。也可用比例法：路程比＝速度比＝60∶40＝3∶2，全程 5 份，甲占 3 份。", "explain": "速度和为 60+40=100（千米/时），相遇时间＝200÷100=2 小时，甲车行 60×2=120 千米。用比例法验证：甲∶乙＝3∶2，甲占全程的 3/5，200×3/5=120 千米，选 C。", "tip": "比例法最快，但要注意甲占的是 3/5 而不是 2/5，别把快慢车的份额弄反。"}, {"type": "math", "level": "中等", "stem": "有浓度为 20% 的酒精溶液 300 克，要使其浓度变为 15%，需要加水多少克？", "options": ["60 克", "80 克", "100 克", "120 克"], "answer": ["C"], "method": "抓住“溶质不变”：先求原溶质，再用水后浓度反推溶液总量，两者之差即为加水量。", "explain": "原溶液中酒精＝300×20%=60 克。加水后溶质仍为 60 克，占总量的 15%，则加水后溶液总量＝60÷15%=400 克，故需加水 400−300=100 克，选 C。", "tip": "浓度＝溶质÷溶液（不是÷水）；加水时溶质不变、溶液变多，别把分母写错。"}, {"type": "logic", "level": "容易", "stem": "律师∶法庭。下列各组词中与题干逻辑关系最为相似的是：", "options": ["医生∶医院", "教师∶学生", "农民∶土地", "司机∶汽车"], "answer": ["A"], "explain": "题干中律师的职业活动场所是法庭，二者是“职业与工作场所”的关系。医生的工作场所是医院，A 与题干关系一致。B 教师与学生是教育者与教育对象的关系；C 农民对土地更接近劳动对象/依托；D 司机使用汽车是工具与操作者的关系。关系类型最贴切的只有 A。", "method": "类比推理先定关系类型（场所、工具、对象、种属、并列……），再逐项比对，选关系类型完全一致的那一项。", "tip": "“职业∶场所”要盯住“工作场所”，别被 C 的“土地”带偏成劳动对象。"}, {"type": "logic", "level": "中等", "stem": "破窗效应：如果有人打坏了一幢建筑物的窗户玻璃，而这扇窗户又得不到及时的维修，别人就可能受到某些暗示性的纵容，去打烂更多的窗户。也就是说，环境中的不良现象如果被放任存在，会诱使人们仿效，甚至变本加厉。根据上述定义，下列属于破窗效应的是：", "options": ["小区里有一处垃圾长期无人清理，很快角落里堆满了居民乱扔的垃圾", "老师批评了迟到的学生，此后班里的迟到现象明显减少", "商场开展打折促销活动，顾客纷纷前来购买商品", "天气转凉，患感冒的人逐渐增多"], "answer": ["A"], "explain": "A 中“垃圾长期无人清理”正是被放任的不良现象，随后诱使更多人乱扔垃圾，符合“放任→仿效→加剧”，属于破窗效应。B 是及时纠正后情况变好，与“放任”方向相反；C 是促销吸引顾客，与不良现象无关；D 属自然现象，没有仿效效应。", "method": "定义判断抓关键点：①不良现象被放任存在 ②他人仿效、加剧。逐项核对关键点是否齐全。", "tip": "干扰项常给“及时处理使情况变好”，与定义方向正好相反，注意别选。"}, {"type": "logic", "level": "中等", "stem": "已知“如果今天下雨，那么运动会取消”。今天运动会没有取消。由此可以推出：", "options": ["今天下雨了", "今天没下雨", "今天可能下雨", "无法确定今天是否下雨"], "answer": ["B"], "explain": "原命题“下雨→取消”的逆否命题是“不取消→不下雨”，两者等价。现在“没有取消”成立，根据逆否命题可必然推出“今天没下雨”，选 B。A 与结论矛盾；C、D 认为结论不确定，但由逆否推理可唯一确定，故排除。", "method": "充分条件假言命题“A→B”等价于“¬B→¬A”。见到后件的否定，就直接用逆否推理得前件的否定。", "tip": "不要用“否定前件”或“肯定后件”去乱推，这两种方式都得不出必然结论。"}, {"type": "fig", "imgs": ["data/figs/figq_013_1.png", "data/figs/figq_013_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处应当是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "第一图中，图一减去图二的一半等于图三；第二图中图一减去图二的一半等于D。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_014_1.png"], "src": "", "cat": "", "fmt": "", "stem": "下列哪一个图形是特殊的？", "options": ["", "", "", ""], "answer": ["C"], "explain": "相邻两个图形大小不一，其它选项都有相同的相邻情况。", "trap": ""}]}, {"set": 8, "date": "2026-10-14", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 8 批）", "items": [{"type": "sci", "level": "容易", "stem": "一辆汽车在平直公路上匀速行驶，下列说法正确的是：", "options": ["汽车受到的牵引力与阻力是一对平衡力", "汽车不受任何力的作用", "汽车受到的牵引力大于阻力", "汽车受到的重力与牵引力是一对平衡力"], "answer": ["A"], "explain": "汽车匀速直线行驶，处于平衡状态，受到的合力为零。水平方向上牵引力与阻力大小相等、方向相反、作用在同一直线上，是一对平衡力，A 正确。B 错，汽车一定受力；C 若牵引力大于阻力则汽车会加速；D 重力与支持力才是一对平衡力，牵引力与之方向垂直，不成对。", "method": "看到“匀速直线运动”或“静止”，先判定物体受平衡力（合力为零），再找同一直线上大小相等、方向相反的一对力。", "tip": "运动不需要合外力维持；匀速、静止都对应平衡力。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "用扇子扇燃着的蜡烛，火焰会熄灭；而扇炉火时却越扇越旺。蜡烛熄灭的原因是：", "options": ["隔绝了氧气", "移走了可燃物", "使温度降到了着火点以下", "增大了氧气的浓度"], "answer": ["C"], "explain": "扇蜡烛时，气流带走大量热量，使石蜡温度降到着火点以下，燃烧停止，C 正确。扇炉火时气流带走的少量热量被炉火自身补充，同时补充了氧气，所以越烧越旺。A、B 均与事实不符，D 只会助燃不会灭火。", "method": "燃烧需同时满足三个条件：可燃物、氧气、温度达到着火点；灭火只需破坏其中任意一个。", "tip": "判断灭火原理要对号入座：浇水降温、盖沙隔绝氧气、清走柴草移除可燃物。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于绿色植物的光合作用与呼吸作用，下列说法正确的是：", "options": ["光合作用只在白天进行，呼吸作用只在夜晚进行", "光合作用制造有机物并释放氧气", "呼吸作用消耗氧气，但不产生任何能量", "光合作用和呼吸作用都在叶绿体中进行"], "answer": ["B"], "explain": "光合作用利用光能把二氧化碳和水合成有机物并释放氧气，B 正确。A 错，呼吸作用昼夜都进行；C 错，呼吸作用分解有机物、释放能量；D 错，呼吸作用主要在细胞质和线粒体中进行，叶绿体是光合作用的场所。", "method": "记两条线：光合作用“吸二氧化碳、放氧气、造有机物、需光”；呼吸作用“吸氧气、放二氧化碳、耗有机物、昼夜不停”。", "tip": "呼吸作用昼夜不停，别误以为只在夜晚进行。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于声音的传播，下列说法正确的是：", "options": ["声音在真空中传播得最快", "声音在固体中传播一般比在空气中快", "只要物体振动，人耳就一定能听到声音", "声音在空气中的传播速度是 340 米/秒，且与温度无关"], "answer": ["B"], "explain": "声音的传播需要介质，一般在固体中最快、气体中最慢，B 正确。A 错，真空不能传声；C 错，能否听到还与振动频率是否在听觉范围（约 20~20000 赫兹）、响度大小有关；D 错，声速随温度升高而增大，340 米/秒是 15℃ 空气时的近似值。", "method": "声速比较：固体 > 液体 > 气体；真空不能传声。", "tip": "“振动就一定听得到”是常见陷阱——还要看频率和响度。", "hard": ""}, {"type": "math", "level": "容易", "stem": "一项工作，甲单独做需 10 天完成，乙单独做需 15 天完成。两人合作，需要多少天完成？", "options": ["5 天", "6 天", "6.5 天", "7.5 天"], "answer": ["B"], "explain": "赋值法：设工作总量为 10 和 15 的最小公倍数 30，则甲效率为 30÷10=3，乙效率为 30÷15=2，合作效率为 5，所需时间为 30÷5=6（天），选 B。", "method": "工程问题首选赋值法：把总量设为工期的公倍数，效率=总量÷时间；合作时间=总量÷效率之和。", "tip": "别把两人的时间直接相加（10+15=25）或取平均，那是常见错算。", "hard": ""}, {"type": "math", "level": "中等", "stem": "一件商品成本 80 元，标价 120 元，商家按标价打八折出售，则利润率是多少？", "options": ["16%", "20%", "25%", "33.3%"], "answer": ["B"], "explain": "售价=120×0.8=96 元，利润=96−80=16 元，利润率=利润÷成本=16÷80=20%，选 B。", "method": "利润率=（售价−成本）÷成本；先算实际售价（标价×折扣），再套公式。", "tip": "注意利润率的分母是“成本”不是“售价”，用 16÷96≈16.7% 是典型错算。", "hard": ""}, {"type": "math", "level": "中等", "stem": "从 5 名同学中选出 3 名，并让他们排成一排照相，共有多少种不同的排法？", "options": ["10 种", "20 种", "60 种", "120 种"], "answer": ["C"], "explain": "“选出 3 名并排队”与顺序有关，是排列问题：A(5,3)=5×4×3=60（种），选 C。若只选不排则是组合 C(5,3)=10 种。", "method": "先判断“与顺序有关吗”：有关→排列 A(n,m)；无关→组合 C(n,m)。", "tip": "“照相、排队、派岗位”都算排列，别误用组合。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "晕轮效应：指人们对他人的认知判断首先根据个人的好恶得出，然后再从这个判断推论出认知对象的其他品质的现象。根据上述定义，下列属于晕轮效应的是：", "options": ["因为小李长得帅气，同事们就认为他的工作能力也一定很强", "老师根据小明平时作业和考试的表现，判断他这次能考好", "消费者因为某品牌广告投放多，觉得它的产品质量更好", "小王因为一次工作失误受到上司批评"], "answer": ["A"], "explain": "A 中同事由“长得帅气”这一好恶印象，推出“能力也强”，符合“先凭好恶下判断，再由该判断推论其他品质”，属于晕轮效应。B 是基于实际表现的合理推断；C 是受广告影响，不属于对“人”的认知；D 是对具体行为的评价，均不符合定义。", "method": "定义判断抓“要件”：①对象是“人”②先凭个人好恶形成印象③再据此推出其他品质。逐项比对要件。", "tip": "“因为外表好而推断能力强/人品好”是晕轮效应的典型表述。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "蜜蜂：蜂蜜。请从选项中选出与这对关系最为相似的一项：", "options": ["树叶：树木", "蚕：蚕丝", "茧：蛾", "花朵：花蜜"], "answer": ["B"], "explain": "蜜蜂产出蜂蜜，是“生物与其所产之物”的对应关系；蚕产出蚕丝，关系与之最相似，选 B。A 是部分与整体，C 是发育阶段（茧化蛾），D 是采食（花朵提供花蜜），均不相同。", "method": "类比推理先确定题干两词的逻辑关系（这里是“产出关系”），再找关系一致的一项。", "tip": "“蜜蜂产蜜”对“蚕产丝”，是常见的产出关系类比。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "已知：所有喜欢阅读的人都善于思考；小李善于思考。由此可以推出：", "options": ["小李喜欢阅读", "小李不喜欢阅读", "小李很可能喜欢阅读", "无法确定小李是否喜欢阅读"], "answer": ["D"], "explain": "“所有喜欢阅读的人都善于思考”表示：喜欢阅读 → 善于思考。小李“善于思考”是肯定了后件，而肯定后件不能肯定前件，所以不能推出小李是否喜欢阅读，选 D。", "method": "记住推理规则：肯前必肯后、否后必否前；肯后、否前都得不出确定结论。", "tip": "“所有 A 都是 B，某人是 B”推不出“某人是 A”——这是必要条件被误当成充分条件。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_019_1.png", "data/figs/figq_019_2.png"], "stem": "根据以上图形的规律，下一个图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "箭头依次顺时针旋转 90°。"}, {"type": "fig", "imgs": ["data/figs/figq_020_1.png"], "stem": "找出下列图形中不同于其他图形的一项：", "options": ["", "", "", ""], "answer": ["A"], "explain": "图 234 中黑球数量均为 7。"}]}, {"set": 9, "date": "2026-10-14", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 9 批）", "items": [{"type": "sci", "level": "容易", "stem": "关于液体内部的压强，下列说法正确的是：", "options": ["液体压强随深度的增加而增大", "液体压强与液体的密度无关", "液体内部同一深度，各方向的压强不相等", "液体压强只与容器的形状有关"], "answer": ["A"], "explain": "由 p=ρgh 可知，液体压强随深度 h 增加而增大，A 正确。B 错，密度 ρ 越大压强越大；C 错，同一深度各方向压强相等；D 错，液体压强与容器形状无关，只与液体密度和深度有关。", "method": "液体压强公式 p=ρgh：只看“密度”和“深度”两个变量，与容器形状、液体总量无关。", "tip": "大坝下宽上窄、潜水服抗压，都是“深度越深压强越大”的体现。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于溶液的 pH，下列说法正确的是：", "options": ["常温下 pH<7 的溶液一定显酸性", "pH 越小，溶液的酸性越弱", "pH=7 的溶液一定是纯水", "用 pH 试纸可以准确测得某溶液 pH=5.6"], "answer": ["A"], "explain": "常温下 pH<7 显酸性，A 正确。B 错，pH 越小酸性越强；C 错，pH=7 只表示中性，还可能是氯化钠等中性盐溶液；D 错，pH 试纸只能读到整数，不能读出 5.6。", "method": "pH<7 酸性、=7 中性、>7 碱性（常温）；试纸读数取整，精密测量用 pH 计。", "tip": "“pH=7 就是纯水”是常见陷阱，中性盐溶液的 pH 也为 7。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于遗传与变异，下列说法正确的是：", "options": ["人的性别由常染色体决定", "基因是控制生物性状的基本单位", "只有显性基因才能遗传给后代", "环境不会影响生物的性状"], "answer": ["B"], "explain": "基因是控制生物性状的基本单位，B 正确。A 错，人的性别由性染色体决定；C 错，隐性基因同样能遗传，只是不一定表现出来；D 错，生物性状是基因与环境共同作用的结果。", "method": "抓住“基因—性状”这一主线：基因控制性状，但性状表现还受环境影响。", "tip": "“性别由常染色体决定”是典型错项，人的性别由 X、Y 性染色体决定。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于热传递，下列说法正确的是：", "options": ["热量总是自发地从低温物体传给高温物体", "热传递的三种方式是传导、对流和辐射", "热传递能改变物体的内能，而做功不能", "只要两物体内能不同，就一定会发生热传递"], "answer": ["B"], "explain": "热传递的三种方式是传导、对流和辐射，B 正确。A 错，热量自发地从高温物体传到低温物体；C 错，做功和热传递都能改变内能；D 错，发生热传递的条件是两物体存在温度差，而非内能不同。", "method": "热传递的条件是“温度差”，方向是“高温→低温”，方式是“传导、对流、辐射”。", "tip": "“内能不同就热传递”是陷阱，关键看“温度”是否有差别。", "hard": ""}, {"type": "math", "level": "中等", "stem": "现有含盐 20% 的盐水 200 克，要使其含盐量降为 10%，需要加水多少克？", "options": ["100 克", "150 克", "200 克", "400 克"], "answer": ["C"], "explain": "加水前后盐的质量不变：200×20%=40 克。要使含盐量为 10%，则盐水总质量应为 40÷10%=400 克，故需加水 400−200=200 克，选 C。", "method": "稀释问题抓“溶质不变”：先算溶质质量，再由目标浓度反推溶液总质量，差额即为加水量。", "tip": "别按“浓度降一半、水加一倍”直接猜 200——只有原溶液刚好 200 克时才好巧，稳妥用溶质守恒。", "hard": ""}, {"type": "math", "level": "中等", "stem": "甲以每小时 5 公里的速度步行，出发 2 小时后，乙骑车以每小时 15 公里的速度沿同一路线追赶。乙追上甲需要多少小时？", "options": ["0.5 小时", "1 小时", "1.5 小时", "2 小时"], "answer": ["B"], "explain": "乙出发时，甲已领先 5×2=10 公里；两人速度差为 15−5=10 公里/小时。追及时间=追及距离÷速度差=10÷10=1（小时），选 B。", "method": "追及问题公式：追及时间=追及距离（领先路程）÷速度差。", "tip": "别忘了先算“出发时已拉开的距离”，直接用 10÷15 是典型错算。", "hard": ""}, {"type": "math", "level": "容易", "stem": "5 个数的平均数是 12，去掉其中一个数后，剩下 4 个数的平均数是 11。去掉的那个数是多少？", "options": ["8", "11", "16", "20"], "answer": ["C"], "explain": "5 个数总和为 12×5=60，剩下 4 个数总和为 11×4=44，去掉的数为 60−44=16，选 C。", "method": "平均数问题用“总和=平均数×个数”：分别算整体和部分的总和，作差即可。", "tip": "去掉的数通常大于原平均数（因为剩下的平均数变小了），可用此快速排除偏小的选项。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "沉没成本：指已经付出且无论如何都无法收回的支出。根据上述定义，下列属于沉没成本的是：", "options": ["小张已买好、无法退票的电影票钱", "小李计划明年买车的一笔预算", "小王这个月还没交的房租", "小赵打算周末去旅游的交通费"], "answer": ["A"], "explain": "电影票钱已经付出且无法退票收回，属于沉没成本，A 正确。B、C、D 都尚未实际支出，可以决定是否花，均不属于“已经付出且无法收回”。", "method": "定义判断抓要件：①已经付出 ②无法收回。逐项比对，只要“还没花”或“能收回”就排除。", "tip": "判断沉没成本的关键是“已经付出 + 收不回”，未发生的支出不算。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "医生：手术刀。请从选项中选出与这对关系最为相似的一项：", "options": ["读者：图书馆", "作家：钢笔", "出版社：图书", "灵感：作家"], "answer": ["B"], "explain": "手术刀是医生使用的工具，是“职业与其工具”的对应关系；钢笔是作家写作的工具，关系最相似，选 B。A 是人物与场所，C 是机构与产品，D 是抽象物与人物，均不相同。", "method": "类比推理先定关系（这里为“工具关系”），再看选项中哪个关系一致。", "tip": "看到“职业：工具”的类比，优先找“某职业 + 该职业所用工具”的选项。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "已知：如果下雨，那么地面会湿。现在观察到地面湿了，由此可以推出：", "options": ["一定下过雨", "一定没有下雨", "可能下过雨，也可能因其他原因而湿", "下雨与地面湿没有关系"], "answer": ["C"], "explain": "“如果下雨，那么地面湿”表示：下雨 → 地面湿。现在“地面湿”是肯定了后件，而肯定后件不能肯定前件——地面湿也可能由洒水、漏水等原因造成，因此只能推出“可能下过雨”，选 C。", "method": "牢记“肯前必肯后、否后必否前；肯后、否前都不确定”，遇到“后件成立”要警惕陷阱。", "tip": "由“地面湿”不能断定“下过雨”，这是把充分条件当成了必要条件。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_021_1.png", "data/figs/figq_021_2.png"], "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "图一二三四均为封闭图形排除 B 项，且大图形与小图形紧邻排除 A、C 项。"}, {"type": "fig", "imgs": ["data/figs/figq_022_1.png", "data/figs/figq_022_2.png"], "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "间隔的黑块白块组成完整图形，如 1 和 2 组成完整图形。"}]}, {"set": 10, "date": "2026-10-15", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 10 批）", "items": [{"type": "sci", "level": "容易", "stem": "关于串联电路和并联电路，下列说法正确的是：", "options": ["串联电路中各处的电流都相等", "并联电路中各支路的电压之和等于电源电压", "串联电路中各用电器两端的电压一定相等", "并联电路中干路电流一定小于任一支路的电流"], "answer": ["A"], "explain": "串联电路中电流处处相等，A 正确。B 错，并联各支路电压都等于电源电压（不是相加）；C 错，串联时各用电器电压与电阻成正比，不一定相等；D 错，干路电流等于各支路电流之和，大于任一支路电流。", "method": "记两个口诀：串联“电流相等、电压按电阻分配”，并联“电压相等、干路电流等于各支路之和”。", "tip": "“串流并压”——串联看电流相同，并联看电压相同，判断时先分清电路连接方式。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于凸透镜成像规律，下列说法正确的是：", "options": ["物体放在焦点以内时，成倒立、放大的实像", "照相机成像时，物体应位于二倍焦距以外", "投影仪成像时，物体应位于焦点以内", "凸透镜成实像时，物距越小，成的像越小"], "answer": ["B"], "explain": "照相机物距 u>2f，成倒立、缩小的实像，B 正确。A 错，物在焦点以内成正立、放大的虚像；C 错，投影仪 f<u<2f，成倒立、放大的实像；D 错，成实像时物距越小、像距越大、像越大。", "method": "“一倍焦距分虚实、二倍焦距分大小”：u>2f 缩小实像（照相机）、f<u<2f 放大实像（投影仪）、u<f 放大虚像（放大镜）。", "tip": "“物近像远像变大”只适用于成实像的情形，别套到虚像上。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于增大或减小压强，下列说法正确的是：", "options": ["书包背带做得较宽，是为了增大压强", "刀刃磨得很薄，是为了减小压强", "载重汽车的轮胎又多又宽，是为了减小对地面的压强", "图钉尖做得很尖，是为了减小对墙面的压强"], "answer": ["C"], "explain": "由 p=F/S 可知，受力面积越大压强越小。轮胎又多又宽增大了受力面积，减小对地面的压强，C 正确。A 错，背带宽是减小压强；B、D 错，刀薄、钉尖都是减小受力面积、增大压强。", "method": "压强 p=F/S：判断压强大小就看压力 F 和受力面积 S，面积大→压强小，面积小→压强大。", "tip": "“尖、薄、窄”一般是为了增大压强；“宽、大、多”一般是为了减小压强。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于生态系统的组成和能量流动，下列说法正确的是：", "options": ["生态系统只由生产者、消费者和分解者组成", "生态系统中能量沿食物链逐级递减", "食物链通常从消费者开始", "分解者能把无机物合成有机物供植物利用"], "answer": ["B"], "explain": "能量在食物链中单向流动、逐级递减，B 正确。A 错，生态系统还包括阳光、空气、水等非生物的物质和能量；C 错，食物链从生产者（绿色植物）开始；D 错，分解者把动植物遗体中的有机物分解为无机物，合成有机物的是生产者。", "method": "生态题抓三句：食物链从生产者起；能量单向流动、逐级递减；分解者把有机物分解为无机物。", "tip": "生态系统=生物部分（生产者/消费者/分解者）+ 非生物部分，别漏了阳光、水、空气等。", "hard": ""}, {"type": "math", "level": "容易", "stem": "在一条长 100 米的路的一侧栽树，每隔 5 米栽一棵（两端都要栽），一共要栽多少棵？", "options": ["19 棵", "20 棵", "21 棵", "22 棵"], "answer": ["C"], "explain": "两端都栽时棵数=间隔数+1。间隔数=100÷5=20，故要栽 20+1=21 棵，选 C。", "method": "植树问题：两端都栽→棵数=段数+1；只栽一端→棵数=段数；两端都不栽→棵数=段数−1。", "tip": "先分清“两端栽不栽”再套公式；100÷5=20 只是间隔数，别直接当成棵数。", "hard": ""}, {"type": "math", "level": "容易", "stem": "袋中有 3 个红球和 2 个白球，除颜色外完全相同。从中任意摸出一个球，摸到红球的概率是多少？", "options": ["1/2", "2/5", "3/5", "3/2"], "answer": ["C"], "explain": "共有 3+2=5 个球，其中红球 3 个，摸到红球的概率=3/5，选 C。", "method": "古典概型：概率=符合条件的结果数 ÷ 全部等可能的结果数。", "tip": "概率一定在 0 和 1 之间，“3/2”大于 1 必错，可直接排除。", "hard": ""}, {"type": "math", "level": "中等", "stem": "笼子里有鸡和兔共 20 只，它们共有 56 条腿。兔子有多少只？", "options": ["6 只", "8 只", "10 只", "12 只"], "answer": ["B"], "explain": "假设全是鸡，则腿数为 2×20=40 条，实际多出 56−40=16 条；每把一只鸡换成兔多 2 条腿，故兔=16÷2=8 只，选 B。（方程法：4x+2(20−x)=56，解得 x=8。）", "method": "鸡兔同笼用“假设法”：假设全是鸡，求出比实际少的腿数，再除以“每换一只的差值”（鸡兔差 2 条腿）。", "tip": "假设法关键是“每换一只相差几条腿”，鸡换兔相差 2 条，别误算成 4 条。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "羊群效应是指个体的行为容易受到多数人行为的影响，从而盲目跟从大众、放弃独立判断的现象。根据上述定义，下列属于羊群效应的是：", "options": ["小张学习了理财知识后，根据自己的风险承受能力选择了基金", "看到周围人都在抢购某款商品，小李原本不需要也跟风买了一件", "小王经过比较后选定了一家性价比更高的旅行社", "小赵坚持每天早起锻炼，不受他人影响"], "answer": ["B"], "explain": "B 中因他人抢购而盲目跟风，买了自己本不需要的东西，符合“受多数人影响、放弃独立判断”，正确。A、C 都是经过独立判断的自主选择；D 是坚持自我、不受他人影响，均不符合。", "method": "定义判断抓要件：①受多数人行为影响 ②盲目跟从而非独立判断。逐项核对，凡“自己思考过”的直接排除。", "tip": "“羊群效应”的核心是“盲目从众”，有独立判断的不算。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "汽车：轮胎。请从选项中选出与这对关系最为相似的一项：", "options": ["学校：老师", "书本：封面", "农民：庄稼", "铅笔：作业"], "answer": ["B"], "explain": "轮胎是汽车的组成部分，属于“整体与部分”关系；封面是书本的组成部分，关系一致，选 B。A 是整体与其人员，C 是职业与劳动对象，D 是工具与用途，均不同。", "method": "类比先定关系：“整体—部分”“职业—工具”“种属”“因果”等，再找关系一致的选项。", "tip": "遇到“整体:部分”的题，注意排除“整体:人/单位”这类看似相关的关系。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "已知：甲或者乙参加了昨天的会议（至少有一人参加）。经确认，甲没有参加。由此可以推出：", "options": ["乙一定参加了会议", "乙一定没有参加会议", "甲、乙都没有参加会议", "无法确定乙是否参加了会议"], "answer": ["A"], "explain": "“甲或乙参加”表示至少一人参加（相容选言命题）。现在甲没参加，否定其中一支，则另一支必真，即乙一定参加，选 A。", "method": "相容选言推理规则：“否定一部分，就要肯定另一部分”（否一推一）；由“肯定一支”不能推出另一支的真假。", "tip": "“或”表示至少一个，排除一支后剩下的必然成立，别把它当成“都可能不确定”。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_023_1.png", "data/figs/figq_023_2.png"], "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "三个图上都有＋号，×号，黑圆，白圆但是位置不相同。先来看＋号的位置，图一到图二＋号顺时针走了3个格，图二到图三顺时针＋号走了4个格，所以图四应该是在图三的基础上顺时针走5个格。再来看×号的位置，图一到图二×顺时针走了1个格，图二到图三×顺时针走了1个格，所以图四应该是在图三的基础上顺时针走1个格。看黑圆的位置，图一到图二顺时针走了6个格，图二到图三顺时针走了5个格，所以图四应该是在图三的基础上顺时针走了4个格。看白圆的位置，图一到图二顺时针走了2个格，图二到图三顺时针走了2个格，所以图四应该是在图三的基础上顺时针走2个格。只有选项A符合，所以选A。"}, {"type": "fig", "imgs": ["data/figs/figq_024_1.png", "data/figs/figq_024_2.png"], "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "每一行横着看，白+白=白，白+灰=灰，黑+白=灰，黑+黑=白，黑+灰=黑。"}]}, {"set": 11, "date": "2026-10-15", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 11 批）", "items": [{"type": "sci", "level": "中等", "stem": "关于电压、电流和电阻，下列说法正确的是：", "options": ["导体两端的电压为零时，它的电阻也为零", "导体电阻的大小由它两端的电压和通过的电流共同决定", "同一导体两端的电压增大，通过它的电流也随之增大", "导体的电阻随通过它的电流增大而减小"], "answer": ["C"], "explain": "电阻一定时，电流与电压成正比，电压增大电流随之增大，C 正确。A 错，电阻是导体本身的性质，与有无电压无关；B 错，电阻由材料、长度、横截面积和温度决定，与电压、电流无关；D 错，电阻不随电流变化。", "method": "欧姆定律 I=U/R。牢记“电阻是导体本身的性质”，R=U/I 只是计算式，不是决定式。", "tip": "“电压为零电阻为零”是典型陷阱，电阻与导体两端有没有电压无关。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于大气压强，下列说法正确的是：", "options": ["大气压强随海拔高度的升高而增大", "用吸管吸饮料，是利用大气压强把饮料压入嘴里", "马德堡半球实验第一次测出了大气压强的数值", "大气压强的大小与海拔高度、天气都没有关系"], "answer": ["B"], "explain": "吸饮料时先把吸管中的空气吸走，管内气压减小，外界大气压就把饮料压入口中，B 正确。A 错，海拔越高空气越稀薄，大气压越小；C 错，马德堡半球实验证明大气压的存在，首次测出大气压数值的是托里拆利实验；D 错，大气压随海拔和天气变化。", "method": "大气压题抓两点：“海拔越高气压越低”；“证明存在（马德堡半球）≠ 测出数值（托里拆利）”。", "tip": "高压锅、吸盘、吸管都利用大气压，但“托里拆利实验”才是测量大气压值的实验。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于氧气和二氧化碳的性质与检验，下列说法正确的是：", "options": ["氧气能支持燃烧，可用带火星的木条来检验", "二氧化碳能使干燥的紫色石蕊纸花变红", "二氧化碳能使澄清石灰水变浑浊，说明二氧化碳显酸性", "氧气不易溶于水，所以水中几乎不含氧气"], "answer": ["A"], "explain": "氧气能支持燃烧，使带火星的木条复燃，这是检验氧气的常用方法，A 正确。B 错，二氧化碳本身不能使干燥石蕊纸花变红，只有与水反应生成碳酸后才显酸性；C 错，石灰水变浑浊是因为生成难溶的碳酸钙，不能说明二氧化碳本身显酸性；D 错，氧气虽不易溶于水，但水中仍溶有少量氧气，水生生物靠它呼吸。", "method": "气体检验口诀：氧气——带火星木条复燃；二氧化碳——使澄清石灰水变浑浊。", "tip": "“二氧化碳使石蕊变红”的前提是石蕊纸花“湿润”，干燥的纸花不会变红。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于人体的呼吸，下列说法正确的是：", "options": ["肺泡是气体交换的主要场所", "人体呼出的气体中不含有氧气", "呼吸道能使吸入的空气变得温暖、湿润、清洁，是气体交换的场所", "吸气时，肋间肌和膈肌舒张，胸廓容积缩小"], "answer": ["A"], "explain": "肺泡壁很薄、外面缠绕着丰富的毛细血管，是气体交换的主要场所，A 正确。B 错，呼出的气体中仍含少量氧气，只是比吸入时少；C 错，呼吸道只是气体进出的通道，不能进行气体交换；D 错，吸气时肋间肌和膈肌收缩，胸廓容积扩大。", "method": "呼吸题抓两句：“吸气=收缩、胸腔变大；呼气=舒张、胸腔变小”；气体交换只在肺泡等处发生。", "tip": "“呼出的气体不含氧气”是错误说法，只是氧气含量比吸入的气体少。", "hard": ""}, {"type": "math", "level": "容易", "stem": "一组数 2、5、8、11、14……按此规律排列，第 20 项是多少？", "options": ["57", "59", "60", "62"], "answer": ["B"], "explain": "这是首项为 2、公差为 3 的等差数列。第 n 项=首项+(n−1)×公差=2+(20−1)×3=2+57=59，选 B。", "method": "等差数列通项公式 aₙ=a₁+(n−1)d：先定首项和公差，再代入公式。", "tip": "求“第 n 项”要乘(n−1)次公差，别误乘 n 次。", "hard": ""}, {"type": "math", "level": "中等", "stem": "今年父亲比儿子大 28 岁，5 年后父亲的年龄是儿子年龄的 3 倍。今年儿子多少岁？", "options": ["7 岁", "9 岁", "11 岁", "14 岁"], "answer": ["B"], "explain": "年龄差始终不变，5 年后父亲仍比儿子大 28 岁。设 5 年后儿子 x 岁，则父为 x+28，由 x+28=3x 解得 x=14，即 5 年后儿子 14 岁，今年为 14−5=9 岁，选 B。", "method": "年龄问题抓“年龄差不变”，设未知数列方程；注意题目问的是“今年”，算完要再减去年数。", "tip": "解出的是“5 年后”的年龄，别忘了减去 5 年，这是本题最常见的失分点。", "hard": ""}, {"type": "math", "level": "中等", "stem": "一个不透明的盒子里有红、黄、蓝三种颜色的球各若干个（每种颜色都有足够多）。至少摸出多少个球，才能保证一定有 2 个球颜色相同？", "options": ["2 个", "3 个", "4 个", "6 个"], "answer": ["C"], "explain": "最不利的情况是每种颜色各摸出 1 个，共 3 个，再多摸 1 个必与其中一种颜色相同，故至少摸 3+1=4 个，选 C。", "method": "抽屉原理（最不利原则）：要保证有 m 个同色，先让每种颜色各取 m−1 个，再加 1。本题 m=2，即 3×1+1=4。", "tip": "“保证”二字是关键——要按最坏情况算，不能按运气好的情况算。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "刻板印象是指对某一类人或事物形成的概括而固定的看法，这种看法往往忽视个体差异。根据上述定义，下列属于刻板印象的是：", "options": ["小李根据面试表现决定是否录用应聘者", "小王认为“北方人一定都很豪爽”，见到北方同事先入为主", "小张通过考试成绩评估学生本学期的学习情况", "小赵根据医生的建议按时服药"], "answer": ["B"], "explain": "B 中“北方人都豪爽”是对一类人的固定概括、忽视了每个人的个体差异，符合定义。A、C 都是依据具体表现作判断，D 是遵医嘱，均不符合。", "method": "定义判断抓要件：①针对某一类人或事物 ②概括而成、固定不变 ③忽视个体差异。三个要件须同时满足。", "tip": "刻板印象的对象是“一类人/事物”，针对具体个人的评价不算。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "水果：苹果。请从选项中选出与这对关系最为相似的一项：", "options": ["汽车：火车", "蔬菜：白菜", "树木：森林", "钢笔：写字"], "answer": ["B"], "explain": "苹果是水果的一种，二者为种属（包含于）关系；白菜是蔬菜的一种，关系一致，选 B。A 是并列关系，C 是个体与集合，D 是工具与用途，均不同。", "method": "类比先定关系：种属（一个属于另一个）还是并列（同层级并列）。种属可用“A 是 B 的一种”检验。", "tip": "用“……是……的一种”检验种属关系，成立即种属，不成立多半是并列或组成。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "某研究称：常喝绿茶的人患某疾病的概率明显低于不喝绿茶的人，因此喝绿茶能预防这种疾病。以下哪项如果为真，最能削弱上述结论？", "options": ["绿茶中含有多种对人体有益的成分", "调查对象中常喝绿茶的人大多也有规律运动、作息健康的习惯", "该疾病在我国的发病率本来就不高", "少量饮用绿茶不会对身体造成伤害"], "answer": ["B"], "explain": "B 指出常喝绿茶的人同时还具备规律运动、作息健康等习惯，他们患病率低可能源于这些习惯而非绿茶，提出“另有他因”，削弱了“喝绿茶能预防疾病”的因果结论，选 B。A 支持结论；C 与该疾病因果无关；D 只说不伤害身体，不能削弱其预防作用。", "method": "削弱因果论证：寻找“另有他因”——把结果归因于别的因素，即可动摇“正是该因素起作用”。", "tip": "看到“相关性 → 因果”的论证，优先找“其他原因”或“因果倒置”的选项。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_025_1.png", "data/figs/figq_025_2.png"], "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "左边与右边的对应顺序是:曲线变直线，直线变曲线。"}, {"type": "fig", "imgs": ["data/figs/figq_026_1.png"], "stem": "找出下列图形中不同于其他图形的一项：", "options": ["", "", "", ""], "answer": ["A"], "explain": "图234中大正方形内侧小正方形数量与外侧相同。"}]}, {"set": 12, "date": "2026-10-16", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 12 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入盛水的玻璃杯中，从侧面看，筷子好像在水面处“折断”了。这是因为：", "options": ["光的直线传播", "光的反射", "光的折射", "光的色散"], "answer": ["C"], "explain": "光从水斜射入空气时传播方向发生偏折，筷子水下部分的像上移，看起来像折断了，这是光的折射，故选 C。A 是影子成因，B 是平面镜成像，D 是棱镜分光。", "method": "记住“水中物体看起来变浅/折断”＝折射；“水中有倒影”＝反射。", "tip": "折射看“水中之物”，反射看“水面倒影”，别混。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "下列家庭常见物质的水溶液，pH 大于 7 的是：", "options": ["食醋", "柠檬汁", "小苏打水", "汽水"], "answer": ["C"], "explain": "小苏打（碳酸氢钠）水溶液显碱性，pH 大于 7；食醋、柠檬汁、汽水都含酸显酸性，pH 小于 7。故选 C。", "method": "记常见酸：醋、柠檬、汽水（碳酸）；常见碱：小苏打、肥皂水、纯碱。", "tip": "“汽水”因含碳酸而显酸性，别当碱性。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于人的性别决定，下列说法正确的是：", "options": ["性别由母亲决定", "男性的性染色体为 XY", "生男生女概率由女方决定", "女性可产生两种卵细胞"], "answer": ["B"], "explain": "男性性染色体为 XY，女性为 XX，故 B 正确。受精时含 X 或 Y 的精子与卵结合决定性别，故生男生女由父方精子类型决定，A、C 错；女性只产生一种卵细胞（含 X），D 错。", "method": "性别决定看“父方的精子是 X 还是 Y”。", "tip": "女性只产生一种卵细胞（X），不要把性别归结为女方。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "两个小灯泡串联在同一电路中，若其中一个灯丝断了，另一个灯泡将：", "options": ["更亮", "变暗", "不亮", "亮度不变"], "answer": ["C"], "explain": "串联电路中电流只有一条路径，一处断路则整个电路断开，另一个灯泡也不亮，故选 C。", "method": "串联“一断全灭”，并联“互不影响”。", "tip": "串联与并联的故障表现正好相反，别记反。", "hard": ""}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做需 10 天完成，乙单独做需 15 天完成。两人合作，需要多少天完成？", "options": ["5", "6", "8", "12"], "answer": ["B"], "explain": "设工程量为 1，甲效率 1/10、乙效率 1/15，合作效率 = 1/10+1/15 = 1/6，故需 6 天。", "method": "赋值法：设工作总量为 1，用效率和求时间。", "tip": "别把效率直接相加成“天数”，时间要取效率和 1/6 的倒数。", "hard": ""}, {"type": "math", "level": "中等", "stem": "某商品进价 80 元，按标价的 8 折出售，仍可获利 20%。该商品的标价是多少元？", "options": ["100", "120", "150", "160"], "answer": ["B"], "explain": "获利 20% 的售价 = 80×(1+20%) = 96 元；8 折＝标价×0.8，故标价 = 96÷0.8 = 120 元。", "method": "先求实际售价（进价×(1+利润率)），再除以折扣反推标价。", "tip": "利润率的基数是“进价”，不是标价。", "hard": ""}, {"type": "math", "level": "容易", "stem": "从 5 名同学中选出 2 人参加比赛，共有多少种不同的选法？", "options": ["10", "20", "25", "5"], "answer": ["A"], "explain": "从 5 人中选 2 人，与顺序无关，是组合：C(5,2)=5×4÷2=10 种。", "method": "“选出/任选”用组合 C(n,m)；“排队/安排职务”才用排列 A(n,m)。", "tip": "别再乘 2（那是把组合当成排列算了）。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "首因效应：指人们最初接触到的信息所形成的印象，对以后的行为活动和评价的影响。下列属于首因效应的是：", "options": ["小李第一次面试表现出色，此后同事一直认为他能力强", "小王每天坚持跑步锻炼身体", "小张因为朋友推荐而买了某品牌产品", "小赵看到消息后立刻回复了对方"], "answer": ["A"], "explain": "A 中“第一次面试”形成的印象持续影响同事后续评价，符合首因效应定义。B 是习惯行为，C 是他人推荐影响购买，D 是即时回应，均不含“最初印象影响后续评价”这一要件。", "method": "定义判断抓要件：“最初信息”“影响后续评价”，两者缺一不可。", "tip": "别与“近因效应（最近印象影响大）”混，题眼在“最初”。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "医生：手术刀 相当于：", "options": ["农民：田地", "裁缝：剪刀", "学生：课本", "司机：乘客"], "answer": ["B"], "explain": "医生使用手术刀作为职业工具，裁缝使用剪刀作为职业工具，二者关系一致，故选 B。A 是场所关系，C 是学习用具但非职业工具关系，D 是服务对象。", "method": "类比先定关系（此处为“职业—工具”），再逐项比对。", "tip": "“职业＋使用工具”要两边都是工具，别被“课本”这类近似搭子骗到。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "“所有金属都导电，铜是金属，所以铜导电。”以下推理方式与其相同的是：", "options": ["所有鸟都会飞，企鹅是鸟，所以企鹅会飞", "所有学生都要参加考试，小明是学生，所以小明参加考试", "有些花是红色的，玫瑰是花，所以玫瑰是红色的", "所有猫都喜欢鱼，这只动物喜欢鱼，所以它是猫"], "answer": ["B"], "explain": "题干是“所有 M 都是 P，S 是 M，所以 S 是 P”的演绎推理，B 结构相同。A 前提本身有误（企鹅不会飞）；C 是大前提为“有些”，不能必然推出；D 是“肯定后件”的错误推理。", "method": "先抽象出题干的形式结构，再逐项对照是否同构。", "tip": "注意区分“所有…是…”与“有些…是…”，后者推不出确定结论。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_027_1.png", "data/figs/figq_027_2.png"], "stem": "问号处应当是？", "options": ["", "", "", ""], "answer": ["D"], "explain": "后面的图比前面的图增加一个图形，增加的图形的边数是一样的。"}, {"type": "fig", "imgs": ["data/figs/figq_028_1.png", "data/figs/figq_028_2.png"], "stem": "问号处的图形应该是？", "options": ["", "", "", ""], "answer": ["A"], "explain": "每隔3个图形，出现一次黑圆，三角形顺序是两正一倒。"}]}, {"set": 13, "date": "2026-10-16", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 13 批）", "items": [{"type": "sci", "level": "容易", "stem": "夜间（无光照）绿色植物主要进行的生理活动是：", "options": ["光合作用", "呼吸作用", "蒸腾作用", "受精作用"], "answer": ["B"], "explain": "光合作用需要光，夜间无光不能进行；呼吸作用昼夜不停，故夜间植物主要进行呼吸作用，故选 B。", "method": "记“光合需光、呼吸不停”；夜晚植物也在消耗氧气、放出二氧化碳。", "tip": "别以为植物在夜里“只放氧”，卧室不宜摆放过密绿植。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "用吸管吸饮料时，饮料能进入口中，主要原因是：", "options": ["嘴的吸力直接把饮料拉上来", "大气压把饮料压入口中", "饮料所受的重力作用", "液体分子间的引力"], "answer": ["B"], "explain": "吸管吸气使管内气压减小，外界大气压大于管内气压，把饮料压入口中，故选 B。A 的说法不准确（“吸”并不是靠“拉力”）。", "method": "一切“吸”的现象（吸盘、吸管、注射器吸水）本质都是大气压把物体压上/压入。", "tip": "题眼是“大气压”，别用“吸力”这种模糊表述作答。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "用锅盖盖住着火的油锅可以灭火，其主要灭火原理是：", "options": ["降低油的温度到着火点以下", "隔绝氧气（空气）", "移走可燃物", "降低油的着火点"], "answer": ["B"], "explain": "盖上锅盖后锅内氧气被隔绝，燃烧因缺少助燃物而停止，故选 B。盖盖也能减少热量散失，但主因是隔绝氧气；着火点是物质固有属性，不能“降低”，D 错。", "method": "灭火三途径：清除可燃物、隔绝氧气、降温到着火点以下——看题对号。", "tip": "“着火点”不可改变，凡是说“降低着火点”的选项必错。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于人体消化，下列说法正确的是：", "options": ["胆汁中含有消化脂肪的酶", "肝脏是人体最大的消化腺", "胃是吸收养分的主要器官", "淀粉在口腔中不会被初步消化"], "answer": ["B"], "explain": "肝脏是人体最大的消化腺，故 B 正确。胆汁不含消化酶，只起乳化脂肪的作用，A 错；小肠是吸收养分的主要器官，C 错；唾液淀粉酶可在口腔初步消化淀粉，D 错。", "method": "记“最大消化腺＝肝脏”“主要吸收器官＝小肠”“胆汁无酶”。", "tip": "“胆汁不含酶”是高频陷阱，别想当然。", "hard": ""}, {"type": "math", "level": "容易", "stem": "甲、乙两地相距 300 千米，两车同时从两地相向而行，速度分别为 40 千米/时和 60 千米/时。两车几小时后相遇？", "options": ["2", "3", "4", "5"], "answer": ["B"], "explain": "相向而行，相遇时间 = 路程 ÷ 速度和 = 300 ÷ (40+60) = 3 小时。", "method": "相遇问题用“路程÷速度和”；追及问题用“路程差÷速度差”。", "tip": "相向用“速度和”，同向追及用“速度差”，别搞反。", "hard": ""}, {"type": "math", "level": "容易", "stem": "把 20 克盐完全溶解在 180 克水中，所得溶液的浓度（质量分数）是多少？", "options": ["8%", "10%", "11.1%", "20%"], "answer": ["B"], "explain": "溶液质量 = 20+180 = 200 克，浓度 = 20÷200×100% = 10%，故选 B。", "method": "浓度＝溶质÷（溶质＋溶剂），分母是溶液总量。", "tip": "别用 20÷180 得到 11.1% 的干扰项，分母要加溶质。", "hard": ""}, {"type": "math", "level": "中等", "stem": "父亲今年 40 岁，儿子今年 10 岁。多少年后，父亲的年龄是儿子的 2 倍？", "options": ["10", "15", "20", "30"], "answer": ["C"], "explain": "设 x 年后，40+x = 2(10+x)，解得 x = 20，即 20 年后父亲 60 岁、儿子 30 岁，故选 C。", "method": "年龄问题列方程：抓住“年龄差不变”，设未知数解方程。", "tip": "两人年龄同步增长，别只给一方加年份。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "从众心理：指个人受到群体的影响，在知觉、判断、行为上表现出与群体多数一致的现象。下列属于从众心理的是：", "options": ["小王原本不想买，但看到大家都在买，也跟着买了", "小李坚持自己的判断，拒绝了朋友的建议", "小张因为下雨而带了雨伞出门", "小赵看见红灯后停下车来"], "answer": ["A"], "explain": "A 中“原本不想买，因多数人购买而改变行为”，符合从众心理。B 是坚持己见（恰好相反），C 是应对天气，D 是遵守规则，均不因群体多数而改变。", "method": "定义判断抓要件：“受群体影响”＋“与多数一致”，两者缺一不可。", "tip": "B 项“拒绝建议”是反例，正是用来考查是否抓准要件。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "蜜蜂：蜂蜜 相当于：", "options": ["牛：青草", "蜘蛛：蛛网", "鸟：天空", "马：草原"], "answer": ["B"], "explain": "蜜蜂产出蜂蜜，蜘蛛产出蛛网，都是“动物与其产出物”的关系，故选 B。A 是食物关系，C、D 是活动场所关系。", "method": "类比先定关系（此处为“动物—产出物”），再逐项比对。", "tip": "“牛：青草”是吃与被吃，别当成产出关系。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "“只有努力，才能成功。”由此可以推出：", "options": ["努力了就一定能成功", "成功了一定努力过", "不成功就不努力", "不努力也可能成功"], "answer": ["B"], "explain": "“只有 A 才 B”表示 A 是 B 的必要条件，即 B→A：成功→努力，故选 B。A 把必要条件当成充分条件；C 是逆否命题的反向错误（应为“不努力→不成功”）；D 与必要条件含义相反。", "method": "“只有 A 才 B”＝A 必要，B→A；“只要 A 就 B”＝A 充分，A→B。", "tip": "必要与充分方向相反，翻译时务必先定箭头指向。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_029_1.png"], "stem": "找出不同的一项：", "options": ["", "", "", ""], "answer": ["A"], "explain": "轴对称图形。"}, {"type": "fig", "imgs": ["data/figs/figq_030_1.png", "data/figs/figq_030_2.png"], "stem": "问号处的图形应该是？", "options": ["", "", "", ""], "answer": ["D"], "explain": "观察图像可知，一个大的带两个小的相同的图形，只有D符号。"}]}, {"set": 14, "date": "2026-10-17", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第14批）", "items": [{"type": "sci", "level": "容易", "stem": "下列工具中，属于省力杠杆的是：", "options": ["镊子", "筷子", "羊角锤（拔钉子）", "钓鱼竿"], "answer": ["C"], "explain": "省力杠杆的动力臂大于阻力臂。用羊角锤拔钉子时动力臂大、阻力臂小，省力，C正确。镊子、筷子、钓鱼竿的动力臂都小于阻力臂，属于费力杠杆（但省距离）。", "method": "判断杠杆类型：比较动力臂与阻力臂。动力臂>阻力臂=省力；< =费力；= =等臂（如天平）。", "tip": "费力杠杆并非没用——它能省距离、便于操作，别误以为费力就该淘汰。", "hard": "常见工具归类要熟：省力—羊角锤、开瓶器、独轮车；费力—镊子、筷子、钓鱼竿。"}, {"type": "sci", "level": "中等", "stem": "把同一实心铁球分别放入盛水和盛酒精的烧杯中，铁球都沉到底部。则它在两种液体中受到的浮力：", "options": ["在水中较大", "在酒精中较大", "一样大", "无法确定"], "answer": ["A"], "explain": "铁球都沉底，则排开液体的体积 V排 都等于铁球体积，相同；而水的密度大于酒精，由 F浮=ρ液gV排 知，在水中受到的浮力较大，A正确。", "method": "先看是否浸没（决定 V排），再用 F浮=ρ液gV排 比较。", "tip": "沉底时 V排=V物；只有漂浮或悬浮时才由物体密度决定 V排。"}, {"type": "sci", "level": "容易", "stem": "'未见其人，先闻其声'，就能判断出说话的是谁，依据的是声音的：", "options": ["音调", "响度", "音色", "频率"], "answer": ["C"], "explain": "不同人发声体的材料和结构不同，音色不同，因此能凭音色辨人，C正确。音调由频率决定，响度由振幅决定，都不能用来辨别人。", "method": "三要素对应：音调—频率；响度—振幅；音色—发声体材料结构。", "tip": "辨人、辨乐器靠音色，不是音调或响度。"}, {"type": "sci", "level": "中等", "stem": "近视眼的成像落在视网膜前方，其矫正应佩戴：", "options": ["凸透镜", "凹透镜", "平面镜", "三棱镜"], "answer": ["B"], "explain": "近视是晶状体过凸或眼轴过长，会聚能力过强，像成在视网膜前，需用凹透镜先发散光线，B正确。远视则用凸透镜。", "method": "记'近视凹、远视凸'：凹透镜发散、凸透镜会聚。", "tip": "别记反：近视配凹透镜，远视配凸透镜。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做需 12 天，乙单独做需 24 天。两人合作，需几天完成？", "options": ["6", "8", "9", "10"], "answer": ["B"], "explain": "赋值工作总量为24（12与24的最小公倍数），甲效率2、乙效率1，合作效率3，24÷3=8（天），选B。", "method": "赋值法：总量取两时间的最小公倍数，求出各自效率再相加。", "tip": "总量赋值取最小公倍数最省事；直接 1/12+1/24 也行，但要小心约分。"}, {"type": "math", "level": "中等", "stem": "某商品进价 80 元，按标价的 8 折出售，仍可获利 20%。该商品的标价为：", "options": ["100 元", "110 元", "120 元", "125 元"], "answer": ["C"], "explain": "实际售价=进价×(1+20%)=80×1.2=96（元）；打8折后为标价的0.8倍，故标价=96÷0.8=120（元），选C。", "method": "先由利润率求出实际售价，再由折扣反推标价。", "tip": "'8折'指售价=标价×0.8，千万不要乘 1.8 或除以 8。"}, {"type": "math", "level": "较难", "stem": "从 5 名男生、4 名女生中任选 3 人，要求至少有 1 名女生。共有多少种选法？", "options": ["74", "80", "84", "90"], "answer": ["A"], "explain": "正难则反：全部选法 C(9,3)=84 种，减去全为男生的 C(5,3)=10 种，得 84−10=74 种，选A。", "method": "遇到'至少一个'，常用'总数−反面（一个都没有）'。", "tip": "组合数计算要准：C(9,3)=84、C(5,3)=10。"}, {"type": "logic", "level": "中等", "stem": "沉没成本是指已经发生且无法收回的支出，理性决策不应受其影响。根据该定义，下列体现'沉没成本谬误'的是：", "options": ["小张买了电影票，看了半小时发现是烂片，仍忍着看完", "小李放弃已过期的健身卡，重新办了一张", "小王把用不上的旧手机送给朋友", "小赵退掉了不合适的课程并获得部分退款"], "answer": ["A"], "explain": "A中电影票的钱已花且无法收回（沉没成本），小张却因'已经花了钱'而继续看烂片，属典型的沉没成本谬误。B、C、D都及时处置、止损，没有受沉没成本左右。", "method": "定义判断抓关键词：'已发生、不可收回'＋'仍据此做决策'。", "tip": "题干若无'已花费/无法收回'的提示，就不能算沉没成本谬误。"}, {"type": "logic", "level": "容易", "stem": "医生：手术刀 相当于：", "options": ["农民：土地", "作家：钢笔", "学生：学校", "厨师：顾客"], "answer": ["B"], "explain": "医生用手术刀作为工作工具，作家用钢笔作为工作工具，二者都是'职业—使用工具'的关系，选B。A是职业—场所/对象，C是身份—场所，D是服务者—服务对象。", "method": "类比先定关系类型（职业：工具），再逐一验证其他选项的关系。", "tip": "别被'都与工作有关'迷惑，要精确到关系类型。"}, {"type": "logic", "level": "中等", "stem": "某班学生中，所有喜欢篮球的同学都喜欢跑步；小明不喜欢跑步。由此可以推出：", "options": ["小明喜欢篮球", "小明不喜欢篮球", "有些喜欢跑步的同学不喜欢篮球", "喜欢跑步的同学都喜欢篮球"], "answer": ["B"], "explain": "由'喜欢篮球→喜欢跑步'，其逆否命题为'不喜欢跑步→不喜欢篮球'，题干又给出'小明不喜欢跑步'，故可推出'小明不喜欢篮球'，B正确。A与题干矛盾；C、D均无法推出。", "method": "'所有A都是B'等价于'非B则非A'（逆否），但不能反推'B都是A'。", "tip": "充分条件命题要会用逆否，切忌把'所有A是B'当成'所有B是A'。"}, {"type": "fig", "imgs": ["data/figs/figq_031_1.png"], "src": "", "cat": "", "fmt": "", "stem": "找出下列图形中不同于其他图形的一项：", "options": ["", "", "", "", ""], "answer": ["E"], "explain": "A和D都是面积相等的，只有E是黑白色块个数不一样。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_032_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处应当是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "数横线与图形的接点数。左边规律，交点数从左到右-2/2。", "trap": ""}]}, {"set": 15, "date": "2026-10-17", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第15批）", "items": [{"type": "sci", "level": "容易", "stem": "夏天从冰箱里取出的饮料瓶，外壁很快出现'水珠'。这是因为空气中的水蒸气发生了：", "options": ["汽化", "液化", "凝固", "凝华"], "answer": ["B"], "explain": "空气中水蒸气遇到温度较低的瓶壁，放热由气态变为液态的小水珠，属于液化，B正确。汽化是液→气（吸热），凝固是液→固，凝华是气→固，均不符。", "method": "先判断初末状态：'气→液'即液化，液化放热。", "tip": "雾、露、冬天窗内壁水珠都是液化，不是汽化（汽化要吸热且由液变气）。"}, {"type": "sci", "level": "容易", "stem": "下列做法中，为了减小压强的是：", "options": ["菜刀磨得很锋利", "篆刻刀刃口很薄", "书包背带做得较宽", "图钉的尖端很尖"], "answer": ["C"], "explain": "压强 p=F/S，压力一定时增大受力面积可减小压强。书包背带做宽，增大了肩膀受力面积，从而减小压强，C正确。A、B、D都是减小受力面积、增大压强。", "method": "看目的是'增大'还是'减小'压强，再对应'减小/增大'受力面积。", "tip": "'锋利、尖细'=增大压强；'宽带、履带、雪橇、螺丝垫片'=减小压强。"}, {"type": "sci", "level": "中等", "stem": "关于平面镜成像，下列说法正确的是：", "options": ["像比物体小", "像是实像", "像与物到镜面的距离相等", "物体靠近平面镜时，像会变小"], "answer": ["C"], "explain": "平面镜成等大、正立的虚像，像与物到镜面的距离相等、连线与镜面垂直，C正确。像与物等大（A错）、是虚像（B错）、靠近时像大小不变（D错，感觉变大是错觉）。", "method": "平面镜成像口诀：等大、正立、虚像、左右相反、关于镜面对称。", "tip": "'人靠近镜子像变大'是视觉错觉，像的大小始终与物相等。"}, {"type": "sci", "level": "中等", "stem": "在'草→兔→狼'这条食物链中，狼属于：", "options": ["生产者", "初级消费者", "次级消费者", "分解者"], "answer": ["C"], "explain": "草是生产者；兔直接吃草，是初级消费者；狼吃兔，是次级消费者（第二级消费者），C正确。分解者指细菌、真菌等。", "method": "食物链从生产者开始，按顺序数消费者级别：吃生产者为初级，吃初级消费者为次级。", "tip": "食物链必须以生产者开头，不要把分解者算进食物链。"}, {"type": "math", "level": "容易", "stem": "甲、乙两地相距 240 千米，两车同时从两地相对开出，速度分别为 50 千米/时和 70 千米/时。两车几小时后相遇？", "options": ["1.5", "2", "2.5", "3"], "answer": ["B"], "explain": "相遇时间=总路程÷速度和=240÷(50+70)=240÷120=2（小时），选B。", "method": "相遇问题用'速度和'，追及问题用'速度差'。", "tip": "算出 120 后别忘再除一次，240÷120=2，易粗心写成 4。"}, {"type": "math", "level": "中等", "stem": "将 20 克盐完全溶解在 180 克水中，所得盐水的浓度约为：", "options": ["9%", "10%", "11.1%", "12.5%"], "answer": ["B"], "explain": "浓度=溶质÷溶液=20÷(20+180)=20÷200=10%，选B。C选项 11.1% 是错用'溶质÷溶剂'=20÷180 得出的结果。", "method": "记住：溶液=溶质+溶剂，浓度分母是溶液总量。", "tip": "最典型的坑就是把分母写成'水'的克数。"}, {"type": "math", "level": "中等", "stem": "一条长 100 米的路，从头到尾每隔 5 米栽一棵树（两端都栽）。共需栽多少棵？", "options": ["19", "20", "21", "22"], "answer": ["C"], "explain": "100÷5=20 段，两端都栽时棵数=段数+1=21（棵），选C。", "method": "植树问题：两端都栽+1；只栽一端不加不减；两端都不栽−1；封闭线路棵数=段数。", "tip": "先分清'两端是否都要栽'，再决定加不加 1。"}, {"type": "logic", "level": "中等", "stem": "破窗效应是指环境中的不良现象若被放任存在，就会诱使人们仿效，甚至变本加厉。根据该定义，下列最符合'破窗效应'的是：", "options": ["教室墙面一处涂鸦无人清理，很快整面墙被人画满", "小李坚持每天早起背单词", "公司实行严格考核，员工效率很高", "公园增设垃圾桶后，乱扔垃圾的现象减少了"], "answer": ["A"], "explain": "A中一处涂鸦（不良现象）未被处置，引发更多人仿效涂画，符合'放任不良→诱使仿效'的定义。B、C、D分别是个体自律、严格管理、积极干预，都与'放任导致蔓延'相反。", "method": "定义判断抓核心链条：不良现象被放任→被仿效→变本加厉。", "tip": "'严格管理''及时干预'通常是破窗效应的反面（治标/纠偏），别选。"}, {"type": "logic", "level": "容易", "stem": "书籍：知识 相当于：", "options": ["农民：庄稼", "医生：病人", "望远镜：远方", "教师：知识"], "answer": ["C"], "explain": "书籍是获取知识的工具，望远镜是观察远方的工具，二者都是'工具—所指向的对象'，选C。A是生产者—产品，B是服务者—服务对象，D是传播者—内容，关系不同。", "method": "类比先抽象出关系（工具：对象），再横向验证。", "tip": "'教师：知识'看似贴近，但关系是'传授'而非'工具承载'。"}, {"type": "logic", "level": "中等", "stem": "所有金属都导电，铜是金属。由此可以推出：", "options": ["铜导电", "导电的都是金属", "不导电的可能是金属", "铜是导电性最好的金属"], "answer": ["A"], "explain": "由'所有金属都导电'和'铜是金属'，可推出'铜导电'（典型的三段论），A正确。B把条件倒置（导电→金属不成立，如石墨导电但不是金属）；C与题干矛盾；D中'最好'题干未提。", "method": "全称肯定命题可正向推理，但当它作为'所有A是B'时不能倒推'所有B是A'。", "tip": "注意'最好、唯一'这类绝对化表述，题干没给就不能选。"}, {"type": "fig", "imgs": ["data/figs/figq_033_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "图形的边数依次递增。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_034_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "图形的方向依次顺时针旋转。", "trap": ""}]}, {"set": 16, "date": "2026-10-18", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 16 批）", "items": [{"type": "sci", "level": "容易", "stem": "透过一块纯绿色的玻璃窗观察白墙上写的纯红色大字，最有可能看到：", "options": ["绿墙无字", "绿墙黑字", "绿墙橙字", "黑墙无字"], "answer": ["B"], "explain": "思路：绿色玻璃只让绿光透过，吸收红光等其他色光；详解：白墙反射白光，其中绿光透过玻璃呈绿色墙面；红字只反射红光，红光被绿色玻璃吸收，没有光透过，字看起来就是黑色。故看到绿墙黑字。答案为B。", "method": "绿色玻璃只让绿光透过，吸收红光等其他色光", "tip": "有色透明体只透过自身颜色的光；被吸收的色光看起来变黑；不透明物体颜色由它反射的色光决定", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第73题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "下列关于我国家庭用电的说法正确的是：", "options": ["我国家庭使用的是220V的直流电", "带金属外壳的用电器一般使用两孔插座", "要使用电器之间互不影响，用电器应串联接入电路", "家庭用电的保险丝可以由电阻率大、熔点低的合金制成"], "answer": ["D"], "explain": "思路：家庭用电基本常识逐项判断；详解：A是交流电不是直流；B金属外壳用三孔插座接地防触电；C并联才能互不影响，串联会分压；D保险丝用电阻率大、熔点低的铅锑合金，电流过大时自动熔断。故答案为D。", "method": "家庭用电基本常识逐项判断", "tip": "家庭电路：220V/50Hz交流电，用电器并联；金属外壳必须接地线（三孔）；保险丝/空气开关在电流过大时切断电路", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第81题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "容易", "stem": "以下现象属于化学变化的是：", "options": ["将木纤维打碎后摊薄晒干制成土纸", "石墨在高温高压作用下变成金刚石", "打开易拉罐，一股气体喷涌而出", "在室外放了一段时间的干冰消失了"], "answer": ["B"], "explain": "思路：化学变化必有新物质生成，物理变化只改形态状态；详解：A打碎晒干只改形状；C开罐CO2逸出是物理解压；D干冰升华是状态变化；B石墨和金刚石是不同单质，转化生成新物质，属化学变化。故答案为B。", "method": "化学变化必有新物质生成，物理变化只改形态状态", "tip": "有新物质生成才是化学变化；升华、凝华、熔化、溶解、扩散都是物理变化；同素异形体互变（石墨↔金刚石）是化学变化", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第72题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "困难", "stem": "水平地面上有甲、乙两块由不同材质构成、质地分布均匀的长方体金属块。已知甲的体积>乙的体积，甲的底面积<乙的底面积，甲的质量>乙的质量。则以下判断一定正确的有：\n①甲的高度>乙的高度\n②甲的高度<乙的高度\n③甲的密度>乙的密度\n④甲的密度<乙的密度", "options": ["①", "③", "①③", "②④"], "answer": ["A"], "explain": "思路：长方体V=S·h，密度ρ=m/V；详解：高度h=V/S，甲V更大、S更小，则h甲必大于h乙，①正确②错误；密度ρ=m/V，甲m更大但V也更大，两因素方向相反，密度大小无法确定，③④都不一定成立。故答案为A。", "method": "长方体V=S·h，密度ρ=m/V", "tip": "h=V/S，分子大分母小→高度一定更大；ρ=m/V，m和V同时大时密度不确定；“一定正确”要找必然成立的，排除可能性判断", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第67题", "kind": "real", "year": "2023"}, {"type": "math", "level": "中等", "stem": "某单位办事大厅有3个相同的办事窗口，2天最多可以办理600笔业务，每个窗口办理单笔业务的用时均相同。现对该办事大厅进行流程优化，增设2个与以前相同的办事窗口，且每个办事窗口办理每笔业务的用时缩短到以前的2/3。问优化后的办事大厅办理6000笔业务最少需要多少天？", "options": ["8", "10", "12", "15"], "answer": ["A"], "explain": "思路：工程问题（效率×窗口数×时间=总量）；详解：1个窗口1天办理600÷(3×2)=100笔。优化后增设2个共5个窗口；单笔用时缩短到原来的2/3，效率变为原来的3/2，即1个窗口1天办100×3/2=150笔。设需t天：6000=150×5×t，解得t=8。故答案为A。", "method": "工程问题（效率×窗口数×时间=总量）", "tip": "工程问题注意“时间缩短到1/n”则效率变为n倍；窗口数=原有3个+新增2个=5个，别漏加", "src": "2022年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 1 题", "kind": "real", "year": "2022"}, {"type": "math", "level": "中等", "stem": "一个A型4G基站的地面覆盖半径为1~3千米，一个B型5G基站的地面覆盖半径为100~200米。按此计算，一个A型4G基站的地面覆盖面积为B型5G基站的（    ）。", "options": ["100~225倍", "100~900倍", "25~225倍", "25~900倍"], "answer": ["D"], "explain": "思路：圆面积比=半径比平方；详解：A半径1~3km=1000~3000米，B半径100~200米。最小倍数=(1000/200)²=25，最大倍数=(3000/100)²=900。故为25~900倍，答案为D。", "method": "圆面积比=半径比平方", "tip": "面积比=半径比平方；求倍数范围时注意谁除以谁：A最小/B最大=25，A最大/B最小=900", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 7 题", "kind": "real", "year": "2023"}, {"type": "math", "level": "困难", "stem": "某线上店铺将进货单价为8元的商品按每件10元出售，每天可销售100件。该店铺计划提高售价增加利润，若每件商品售价每提高1元，每天销售量就要减少10件，为保证每天至少获利350元，问该商品售价应为多少？", "options": ["不到13元", "13~15元之间", "15~17元之间", "17元以上"], "answer": ["B"], "explain": "思路：代入法/二次函数。详解：设提价x元，每件利润=(10+x-8)=(2+x)元，销量=(100-10x)件，总利润y=(2+x)(100-10x)。要求y≥350。代入A：x=2（售价12元），y=4×80=320<350，排除；代入B：x=4（售价14元），y=6×60=360>350，满足。解不等式：(2+x)(100-10x)≥350，化简得x²-8x+15≤0，即(x-3)(x-5)≤0，得3≤x≤5，售价=10+x在13~15元之间。故答案为B。", "method": "代入法/二次函数", "tip": "经济利润最值用二次函数；不等式解集是区间，边界要代入验证；选项为范围时用代入法最快", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 8 题", "kind": "real", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "析数是指在一定的语境中，利用数学上相加或相乘等关系，把一个数有目的地进行拆分的一种修辞手法。\n根据上述定义，下列没有使用析数的是（ ）。", "options": ["故国三千里，深宫二十年。一声何满子，双泪落君前", "蛾眉蔽珠栊，玉钩隔琐窗。三五二八时，千里与君同", "读尽文书一百担，老来方得一青衫。媒人却问余年纪，四十年前三十三", "江陵去扬州，三千三百里。已行一千三，所有二千在"], "answer": ["A"], "explain": "划关键词：①利用数学相加或相乘关系；②把一个数有目的地拆分。逐项比对：A“三千里”“二十年”是独立数量，未把某数拆成两数之和/积，不符合，当选；B“三五”=3×5=15、“二八”=2×8=16，用相乘拆分十五、十六，符合；C“四十”+“三十三”=73，用相加拆分年纪，符合；D“一千三”+“二千”=三千三百，用相加拆分总路程，符合。本题为选非题，故答案为A。", "method": "定义法：先划关键要件（数学加减/相乘、把一个数拆分），再逐项比对，选“没有拆分”的。", "tip": "定义题先划关键要件，选项必须全部满足才算符合；析数核心是“一个数拆成两个数”，独立数量不构成拆分", "src": "2021年国家公务员录用考试《行测》题（地市级网友回忆版） 第 16 题", "kind": "real", "year": "2021"}, {"type": "logic", "level": "容易", "stem": "塑料：容器", "options": ["石灰：水泥", "陶瓷：餐具", "桥墩：桥梁", "木材：木头"], "answer": ["B"], "explain": "先定一级关系：塑料是制作容器的原材料，为原材料与成品对应。二级辨析：A石灰和水泥都是胶凝材料，并列关系；B陶瓷是制作餐具的原材料，原材料与成品对应，与题干一致；C桥墩是桥梁的组成部分，组成关系；D木头是木材的统称，种属关系。故正确答案为B。", "method": "类比：先定一级关系（原材料→成品），再做二级辨析排除组成/并列/种属。", "tip": "先看词性结构再定关系：原材料→成品（塑料做容器）vs组成部分（桥墩是桥梁一部分）vs并列（石灰和水泥）；二级辨析注意原材料是否可独立加工成成品", "src": "2021年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 11 题", "kind": "real", "year": "2021"}, {"type": "logic", "level": "中等", "stem": "并非所有人都能够去当人民教师，除非有教师资格证。 如果这个假设为真，则以下哪项一定为假？", "options": ["所有没有教师资格证的人都不能去当人民教师", "即使有教师资格证也不一定能去当人民教师", "没有人能够没有教师资格证就去当人民教师", "有的人能去当人民教师，他们并没有教师资格证"], "answer": ["D"], "explain": "第一步：翻译题干。题干可等价替换为“除非有教师资格证，否则有的人不能去当人民教师”。这里有无教师资格证和是否当人民教师都是同一部分人。主体一致，则可翻译为：当人民教师有教师资格证。第二步：逐一分析选项。A项：翻译为“有教师资格证当人民教师”，否后推否前，根据逆否等价原则可以推出，该项和题干都为真，排除；B项：“有教师资格证”是肯定了题干的后件，肯后无法推出确定结论，该项真假不确定，排除；C项：即所有人都需要有教师资格证才能当人民教师。翻译为“当人民教师有教师资格证”，肯前必肯后，该项和题干都为真，排除；D项：翻译为有的人“当人民教师 且 有教师资格证”，与题干是矛盾关系，则该项为假，当选。本题为选非题，⇒ 正确答案为D。", "method": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」", "src": "2021年重庆市选调优秀大学生到基层工作考试《行测》题 第19 题", "kind": "real", "year": "2021"}, {"type": "fig", "imgs": ["data/figs/figq_001_1.png", "data/figs/figq_001_2.png"], "src": "", "cat": "", "fmt": "", "stem": "选择最合适的完成图形推理：", "options": ["", "", "", ""], "answer": ["C"], "explain": "前三个图形，图一图二都有圆，图三是圆。图一图二是两个图形，图三是一个图形。后三个图形应该也是一样的道理，图一图二都有三角形，所以图三是三角形，图一图二是两个图形，图三是一个图形。只有选项C符合，所以选C。", "trap": "", "desc": "题干（左列）：①圆形与三角形部分重叠，②正方形内嵌小圆，③单独的圆形；右列：①五边形内嵌小三角形，②三角形内嵌小圆，③问号。选项（竖排从上到下）：A正五边形、B倒三角形内嵌小三角形、C实心三角形、D正方形。规律：左列图①＋图②叠加去重合部分得图③；右列同理，问号应为单独的三角形。", "kind": "real"}, {"type": "fig", "imgs": ["data/figs/figq_009_1.png", "data/figs/figq_009_2.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["C"], "explain": "竖排依次顺时针旋转90°。", "trap": "", "desc": "题干为3×3九宫格：每格为圆形被横竖线分割成四等分扇形，部分扇形涂黑；第三行第三格为问号。选项为三个圆形被三条辐射线分割为三等分扇形的图案。规律：按列看，圆形分割图案依次顺时针旋转90°（扇形涂黑位置随之旋转）。需对照选项选择。", "kind": "real"}]}, {"set": 17, "date": "2026-10-18", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 17 批）", "items": [{"type": "sci", "level": "中等", "stem": "胰岛素是一种蛋白质，可以用于治疗糖尿病。以下有关胰岛素的说法，正确的是（ ）。", "options": ["胰岛素能够抑制血糖分解", "人体中的胰岛素由肝脏分泌", "一般通过口服胰岛素治疗糖尿病", "血液中的胰岛素浓度过高会导致低血糖"], "answer": ["D"], "explain": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "method": "结合胰岛素的化学本质、分泌部位和作用判断", "tip": "胰岛素=蛋白质，只能注射不能口服；由胰岛分泌，作用是降低血糖；血糖过低会引发低血糖症状", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "kind": "real", "year": "2024"}, {"type": "sci", "level": "容易", "stem": "在生活中，我们可以用紫色的蝴蝶兰花溶液作为酸碱指示剂，其遇酸性溶液显红色，遇碱性溶液则显黄色。下列说法正确的是（ ）。", "options": ["在盐水中滴入蝴蝶兰花溶液，溶液呈红色", "在纯净水中滴入蝴蝶兰花溶液，溶液呈无色", "在苏打水中滴入蝴蝶兰花溶液，溶液呈黄色", "在酸或碱性溶液滴入蝴蝶兰花溶液后，变色的过程属于物理变化"], "answer": ["C"], "explain": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "method": "指示剂酸性显红、碱性显黄，中性保持紫色", "tip": "先判断溶液酸碱性，再套指示剂颜色规则；苏打水、肥皂水、草木灰水均为碱性；指示剂变色=化学变化，不是颜色简单混合", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "kind": "real", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "小李驾驶卡丁车驶过一个半圆形弯道时，滑离了原定赛道，撞到了安全护栏。为了避免卡丁车转弯时滑离赛道，下列做法最可能有效的是：", "options": ["增加卡丁车的质量", "减少卡丁车的质量", "使用更加粗糙的轮胎", "减小半圆形弯道的半径"], "answer": ["C"], "explain": "思路：转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r；详解：质量m在两边约掉，增减质量无效；减小半径r会让临界速度更低、更易滑；换更粗糙轮胎增大μ，可提高临界速度。故答案为C。", "method": "转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r", "tip": "向心力问题中质量常被约掉，先写公式再判断；增大摩擦系数、降低车速、增大弯道半径都更安全；v临=√(μgr)，μ越大r越大越稳", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第69题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "一般来说，海水会从密度大的地方向密度小的地方流动，而海水的密度主要受到温度和盐度的影响。则以下判断正确的是（ ）。", "options": ["越热越咸的海水，密度越大", "越冷越咸的海水，密度越大", "越冷越淡的海水，密度越大", "越热越淡的海水，密度越大"], "answer": ["B"], "explain": "思路：ρ随温度降低而增大、随盐度升高而增大；详解：要密度最大，就要温度最低且盐度最高，即“越冷越咸”。故答案为B。", "method": "ρ随温度降低而增大、随盐度升高而增大", "tip": "先记两个变量各自的影响方向再组合；冷而咸密度最大，热而淡密度最小；密度流从高密度流向低密度", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第68题", "kind": "real", "year": "2020"}, {"type": "math", "level": "容易", "stem": "某家政公司承诺以低于市场价20％的价格为小区业主提供服务。如果有业主向该公司支付了服务费4000元，则与市场价相比优惠了（   ）元。", "options": ["400", "600", "800", "1000"], "answer": ["D"], "explain": "思路：折扣方程。详解：设市场价为x元，低于市场价20%即实付为原价的80%，列方程(1-20%)x=4000，解得x=5000元。优惠金额=5000-4000=1000元。故答案为D。", "method": "折扣方程", "tip": "折扣题先分清“折后价”和“原价”：80%对应折后价4000，必须先反求原价再算优惠；优惠=原价-折后价", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第 6 题", "kind": "real", "year": "2024"}, {"type": "math", "level": "中等", "stem": "父子两人在百米赛道上匀速跑步，两人从赛道起点同时出发，父亲跑到终点时，儿子距离终点还有40米，若父亲立即折返跑向赛道起点，则两人相遇时，儿子距离终点还有（    ）米。", "options": ["35", "30", "25", "15"], "answer": ["C"], "explain": "思路：比例法（时间相同路程比=速度比）；详解：父到终点跑100米时子跑60米，速度比v父:v子=100:60=5:3；父折返后两人相向而行，相距40米（子距终点40米），相遇时两人共跑40米，按5:3分配，父亲跑40×5/8=25米；即相遇点距终点25米。故答案为C。", "method": "比例法（时间相同路程比=速度比）", "tip": "行程问题先求速度比；相遇问题路程和=总距离，按速度比分配；注意问的是“儿子距离终点”，即折返父亲跑的距离（从终点往回跑）", "src": "2025年广东省公务员录用考试《行测》题（网友回忆版） 第 5 题", "kind": "real", "year": "2025"}, {"type": "math", "level": "困难", "stem": "甲、乙、丙三个工程队共同承担一项市政工程。甲队独立完成需要30天，乙队效率比甲队高20%。丙队仅提供技术支持，即能够为其他队伍提高效率，其与甲队或乙队合作时效率可提高120%，三个队伍合作时效率可提高200%。甲、乙两队合作3天后，丙队加入，最后两天乙队休息。问该工程耗时约多少天？", "options": ["7", "8", "9", "10"], "answer": ["B"], "explain": "思路：赋值法。详解：赋值甲效率=5，乙=5×(1+20%)=6，工程总量=5×30=150。甲乙合作3天完成(5+6)×3=33。最后两天乙休息，甲丙合作效率提高120%即变为原来的2.2倍，甲效率=5×2.2=11，两天完成22。剩余150-33-22=95，三队合作效率提高200%即变为原来的3倍，甲乙效率和=11×3=33，需95÷33≈2.9天，向上取整3天。总耗时=3+3+2=8天。故答案为B。", "method": "赋值法", "tip": "工程问题“效率提高120%”=变为原来的2.2倍，不是1.2倍；完成工程天数有小数一律向上取整", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 4 题", "kind": "real", "year": "2024"}, {"type": "logic", "level": "容易", "stem": "架构创新是指组成产品的基本元件不变，但是整体结构布局改变，即将相同元件进行整体结构的重新调整，进而产生新功能的创新。\n根据上述定义，下列属于架构创新的是：", "options": ["陶瓷底板电熨斗与传统不锈钢底板电熨斗相比，其底板的耐磨性更强，具有更高的光滑度，使用起来更顺畅", "某款手机聊天软件增加了拜年红包功能，用户可以在给亲朋好友发送红包时，编辑拜年吉祥语、自定义红包图片，满足个性化需求", "可拆卸手柄锅将原手柄设计成可从锅具上拆卸下来，并提供多个手柄可安装在锅具边缘的任意位置上，满足烹饪需要", "某板材厂改良制作工艺，将原来的轧制工序分成两步进行，同时增加砂光工序，生产出满足市场需要的薄板"], "answer": ["C"], "explain": "划关键词：①基本元件不变；②重新调整相同元件整体结构布局；③产生新功能。逐项：A陶瓷底板vs不锈钢底板基本元件不同；B新增拜年红包功能是新开发不是结构调整；C锅和手柄基本元件不变，手柄可拆可装多个位置=整体结构布局重新调整，产生炒/煮/蒸等新功能，全满足；D轧制工序分两步+增加砂光=制作工艺改变不是产品结构调整。故C。", "method": "定义法：要件=基本元件不变＋重调整体布局＋产生新功能，三项全满足才选。", "tip": "架构创新=元件不变只改布局；发明创新=元件变了/全新功能；工艺创新=生产工序变。先划关键要件，选项必须全部满足才算符合", "src": "2023年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 17 题", "kind": "real", "year": "2023"}, {"type": "logic", "level": "容易", "stem": "耳塞：噪音", "options": ["书籍：知识", "蜡烛：光明", "肥皂：污渍", "风扇：低温"], "answer": ["C"], "explain": "先定一级关系：耳塞的功能是减少噪音，为“工具—减少某对象”的功能对应。再做二级辨析：A书籍是知识的载体，不是减少知识；B蜡烛用来增加光明，方向相反；C肥皂用来减少污渍，与题干“工具减少对象”完全一致，当选；D风扇用来降低温度，不是减少低温。", "method": "类比：一级关系是“工具—减少/消除某对象”，注意方向是“减少”而非“增加”。", "tip": "先看词性结构再定关系，二级辨析往往是区分项：功能对应要分清是“减少/消除”还是“增加/产生”，方向相反的选项即排除", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 11 题", "kind": "real", "year": "2022"}, {"type": "logic", "level": "中等", "stem": "在某公司中，李明帮助了王刚，而王刚帮助了赵贤。李明纳税比赵贤多。 由此可以推出：", "options": ["王刚纳税比赵贤多", "李明纳税和王刚一样多", "有人帮助了一个纳税比他多的人", "有人帮助了一个纳税比他少的人"], "answer": ["D"], "explain": "第一步：抓住题干主要信息。李明帮助了王刚，而王刚帮助了赵贤。李明纳税比赵贤多（李赵）。第二步：逐一分析选项。A项：题干只说了李明比赵贤纳税多，没有提到王刚的纳税情况，无法与赵贤作比较，排除；B项：王刚的纳税情况题干并没有提到，因此无法得知是否与李明一样多，排除；C项：由题干得知李明比赵贤纳税多，但是并不知道赵贤是否帮助了李明，无法得出，排除；D项：由题干得知李赵，而李明帮助了王刚，王刚帮助了赵贤，那么王的纳税可能有以下三种情况：（1）当李王时，不论王与赵的纳税谁多谁少，都可以确定李一定帮助了一个纳税比他少的人（王），则D选项结论一定成立。（2）当李王时，只可能王赵，否则不满足题干条件李赵。由王赵可知，王帮助了一个纳税比他少的人（赵），则D选项结论一定成立。（3）当李王时，只可能王赵（且李赵时），否则不满足题干条件李赵。由王赵可知，王帮助了一个纳税比他少的人（赵），则D选项结论一定成立。因此，结论“有人帮助了一个纳税比他少的人”一定成立。⇒ 正确答案为D。", "method": "分析推理：抓住已知“李纳税＞赵”，用代入排除，分情况讨论王的纳税位置。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多", "src": "2017年国家公务员录用考试《行测》题（副省级） 第39 题", "kind": "real", "year": "2017"}, {"type": "fig", "imgs": ["data/figs/figq_012_1.png", "data/figs/figq_012_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应当是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "前三个图，图一加图二，重复的地方不显示，留下不重复的部分，就是图三。后三个图也是一样的道理。图一加图二，重复的地方不显示，留下不重复的部分。图一图二两个阴影部分未重复，都留下来。图一图二六边形和六边形中的两条线都重复了，不显示。最后只剩下两个阴影组成的图形。只有选项D符合，所以答案选D。", "trap": "", "desc": "题干：左侧三图：五角星轮廓、五边形内接三角形、五边形内接复杂多边形；右侧两图为带阴影填充的六边形分割图形，末位问号。选项（竖排从上到下）：A正六边形轮廓、B六边形内三角形四边形立体组合、C六边形内嵌五边形立体结构、D实心直角梯形。规律：叠加去重合：图①＋图②留下不重合部分得图③；右列同理。需对照选项选择。", "kind": "real"}, {"type": "fig", "imgs": ["data/figs/figq_047_1.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。", "options": ["", "", "", ""], "answer": ["A"], "explain": "第一行都是一笔写成的线条，第二行都是两笔写成的线条，第三行都是三笔写成的线条，选择选项中是三笔写成的选项，只要A 是三笔写成的，所以答案选A。", "trap": "", "desc": "题干为图形序列，选项 A~D 为候选图形（本题需配合图片作答）。规律提示：第一行都是一笔写成的线条，第二行都是两笔写成的线条，第三行都是三笔写成的线条，选择选项中是三笔写成的选项，只要A 是三笔写成的，所以答案选A。 若图片无法显示，可先跳过本题，不影响其他题目。", "kind": "real"}]}, {"set": 18, "date": "2026-10-19", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 18 批）", "items": [{"type": "sci", "level": "容易", "stem": "农技站为了贮存种子，拟采用以下做法，其中最可行的是", "options": ["将种子浸泡在含水的容器中", "将种子置放在含氧量低于1%的干燥地窖中", "将种子置于15摄氏度左右的低温环境中", "将种子封闭在完全避光的黑暗环境中"], "answer": ["B"], "explain": "思路：种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度；详解：A浸泡在水中会让种子萌发甚至霉烂；C仅15℃远达不到储存要求；D避光并非关键；B干燥地窖既控制水分又把含氧量压到1%以下，呼吸作用被显著抑制，最可行。故答案为B。", "method": "种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度", "tip": "种子储存三要素：干燥、低温、低氧，缺一不可；；高温高湿环境会加速呼吸和霉变；；密闭≠真空，关键是含水与氧气含量。", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第66题", "kind": "real", "year": "2020"}, {"type": "sci", "level": "容易", "stem": "援藏干部小吴发现，夏天在藏区的高山上能看到一条横在半山腰的线，这条线之上冰雪璀璨闪耀，线下则只有裸露岩坡或草丛树林。当地人告诉他，这就是“雪线”。如果气候稳定，雪线每年大致在同一个高度上，如果气候或降雪量发生变化，雪线就会发生变化。则小吴最不可能观察到的现象是", "options": ["气候变暖，降雪量增加，雪线上移", "气候变暖，降雪量减少，雪线上移", "气候变冷，降雪量减少，雪线下移", "气候变冷，降雪量增加，雪线上移"], "answer": ["D"], "explain": "思路：雪线是常年积雪的下界，气温升高消融增强会使雪线上移，气温降低消融减弱会使雪线下移；降雪量增加补给增多会使雪线下移，降雪量减少会使雪线上移；详解：D项气候变冷（消融减弱，雪线应下移）叠加降雪量增加（补给增多，雪线也应下移），两个因素都指向雪线下移，不可能出现雪线上移。故答案为D。", "method": "雪线是常年积雪的下界，气温升高消融增强会使雪线上移，气温降低消融减弱会使雪线下移", "tip": "雪线=消融量与补给量平衡的高度，两个反向因素要分开判断；；气候变暖→雪线上移，气候变冷→雪线下移；；降雪增多→雪线下移，降雪减少→雪线上移。", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第67题", "kind": "real", "year": "2020"}, {"type": "sci", "level": "容易", "stem": "下列物质与其用途搭配正确的是（ ）。\n①臭氧——用作氧化剂\n②二氧化碳——用作干燥剂\n③氦气——用作燃料\n④液氮——用作制冷剂", "options": ["①④", "②③", "①②", "③④"], "answer": ["A"], "explain": "思路：逐项判断物质性质与用途是否匹配；详解：①臭氧具有强氧化性，可作氧化剂正确；②CO2不能干燥气体；③氦气化学性质稳定、不可燃，不能作燃料；④液氮汽化吸热，可作制冷剂正确。故①④组合。答案为A。", "method": "逐项判断物质性质与用途是否匹配", "tip": "干燥剂要选浓硫酸、碱石灰、氯化钙等能吸水的；；氦气、稀有气体稳定不燃，作保护气或填充气；；液氮干冰靠汽化升华吸热做制冷剂。", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第70题", "kind": "real", "year": "2020"}, {"type": "sci", "level": "容易", "stem": "对下列生活中的现象或做法解释不合理的是（ ）。", "options": ["物体的热胀冷缩——分子随温度升高而变大", "油锅着火用锅盖盖灭——使可燃物与空气隔绝", "在铁制品表面刷油漆——避免铁制品氧化生锈", "利用真空袋包装食品——破坏需氧菌类的生存环境"], "answer": ["A"], "explain": "思路：用微观和化学原理逐一核对；详解：A热胀冷缩是分子间间隔随温度升高而增大，分子本身体积不变，解释错误；B盖锅盖隔绝氧气灭火正确；C刷油漆隔绝水和氧气防锈正确；D真空缺氧气抑制需氧菌正确。故答案为A。", "method": "用微观和化学原理逐一核对", "tip": "分子大小不会随温度改变，变的是分子间距离；；燃烧三要素：可燃物、氧气、温度，盖锅盖断氧气；；生锈需要水和氧气同时存在，真空包装抑菌。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第76题", "kind": "real", "year": "2022"}, {"type": "math", "level": "中等", "stem": "甲、乙、丙三人的年龄之比为3：4：5。8年之后，甲、乙的年龄之和是丙的1.5倍，且这一年甲、乙、丙、丁四人的平均年龄为43岁。问再过15年，甲、乙、丙、丁中有几人将超过60岁?", "options": ["4", "3", "2", "1"], "answer": ["C"], "explain": "思路：方程+比例。设甲乙丙现在为3x、4x、5x岁。8年后甲乙和是丙的1.5倍：(3x+8)+(4x+8)=1.5(5x+8)，即7x+16=7.5x+12，解得x=8，现在甲乙丙=24、32、40岁。8年后四人平均43，和=172，此时甲乙丙=32、40、48，丁=172-32-40-48=52岁。“再过15年”即8年后再加15年：甲=32+15=47，乙=40+15=55，丙=48+15=63，丁=52+15=67。超60岁的是丙、丁，共2人。故答案为C。", "method": "方程+比例", "tip": "年龄问题每人每年长1岁，注意“8年后”“再过15年”的时间基准；未知的丁先用平均年龄反推。", "src": "2024年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 1 题", "kind": "real", "year": "2024"}, {"type": "math", "level": "中等", "stem": "92.46，84.42，76.38，68.34，（    ）", "options": ["50.25", "53.26", "55.17", "56.30"], "answer": ["A"], "explain": "思路：机械划分（小数数列）；详解：观察各项92=46×2，84=42×2，76=38×2，68=34×2，规律为整数部分=小数部分×2。验证选项：A 50=25×2满足；B 53≠26×2；C 55≠17×2；D 56≠30×2。故答案为A。", "method": "机械划分（小数数列）", "tip": "小数数列优先机械划分，先看整数与小数部分的和差倍比；若分开等差无选项，立即转内部关系。", "src": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 1 题", "kind": "real", "year": "2023"}, {"type": "math", "level": "中等", "stem": "某地10户贫困农户共申请扶贫小额信贷25万元。已知每人申请金额都是1000元的整数倍，申请金额最高的农户申请金额不超过申请金额最低农户的2倍，且任意2户农户的申请金额都不相同。问申请金额最低的农户最少可能申请多少万元信贷？", "options": ["1.5", "1.6", "1.7", "1.8"], "answer": ["B"], "explain": "思路：最值构造。详解：设最低户申请x万元，要让x最小，则其余9户尽可能多，但最高≤2x且各户金额互不相同、均为0.1的整数倍。令其余9户分别取2x、2x-0.1、2x-0.2、…、2x-0.8（递减0.1），则总和=x+(2x+2x-0.1+…+2x-0.8)=x+18x-(0+0.1+…+0.8)=19x-3.6。令19x-3.6=25，得19x=28.6，x≈1.505万元。由于x必须是0.1的整数倍，向上取整为1.6万元（验证：1.6+3.2+3.1+3.0+2.9+2.8+2.7+2.6+2.5+2.4=26.8>25，需再调小其他户使总和=25，可行）。故答案为B（1.6万元）。", "method": "最值构造", "tip": "①最值问题求最小→其他量取最大；②“互不相同”要构造连续差；③算出小数后按“0.1万元整数倍”向上取整。", "src": "2021年国家公务员录用考试《行测》题（地市级网友回忆版） 第 2 题", "kind": "real", "year": "2021"}, {"type": "logic", "level": "中等", "stem": "人民是创作的源头活水，只有扎根人民，创作才能获得取之不尽、用之不竭的源泉。文化文艺工作者要走进实践深处，观照人民生活，表达人民心声，用心用情用功抒写人民、描绘人民、歌唱人民。哲学社会科学工作者要多到实地调查研究，了解百姓生活状况，把握群众思想脉搏，着眼群众需要解疑释惑、阐明道理，把学问写进群众心坎儿里。 由此可以推出：", "options": ["文化文艺工作者只有走进实践深处，才能观照人民生活", "如果不扎根人民，创作就不能获得取之不尽、用之不竭的源泉", "哲学社会科学工作者只有到实地调查研究，才能了解百姓生活状况，把握群众思想脉搏", "如果哲学社会科学工作者没有着眼群众需要解疑释惑、阐明道理，就说明他们没有进行实地调查研究"], "answer": ["B"], "explain": "第一步：翻译题干。创作获得取之不尽、用之不竭的源泉扎根人民。第二步：逐一分析选项。A项：翻译为“观照人民生活文化文艺工作者走进实践深处”，但是题干二者之间没有推出关系，无法推出，排除；B项：翻译为“扎根人民创作获得取之不尽、用之不竭的源泉”，是对题干“创作获得取之不尽、用之不竭的源泉扎根人民”的否后，否后必否前，可以推出，当选；C项：翻译为“了解百姓生活状况，把握群众思想脉搏哲学社会科学工作者到实地调查研究”，但是题干二者之间没有推出关系，无法推出，排除；D项：翻译为“哲学社会科学工作者着眼群众需要解疑释惑、阐明道理他们进行实地调查研究”，但是题干二者之间没有推出关系，无法推出，排除。⇒ 正确答案为B。", "method": "第一步：翻译题干。创作获得取之不尽、用之不竭的源泉扎根人民。第二步：逐一分析选项", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。", "src": "2024年国家公务员录用考试《行测》题（副省级网友回忆版） 第31 题", "kind": "real", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "“城归”，有学者解释为，从农村出去打工、经商的农民，或从农村走出的读书人、退役士兵等，经过多年在城市打拼，累积了经验，获得技术和资金。如今又重回乡村生产生活。据国务院公布的数据，目前“城归”已超过450万人。在新农村建设中，需要大量人才和资金支持，而“城归”群体的迅速壮大是提供人才和资金的必要条件。 据此可以推出：", "options": ["如果没有“城归”群体的发展壮大，那么就不能实现新农村建设目标", "只要有人才和资金支持，就能实现新农村建设目标", "一旦有人才就会有资金", "倘若有资金支持，就能实现新农村建设目标"], "answer": ["A"], "explain": "第一步：翻译题干。①新农村建设人才和资金；②人才和资金“城归”群体壮大；将①和②串联得出：③新农村建设人才和资金“城归”群体壮大。第二步：逐一分析选项。A项：翻译为“城归”群体壮大新农村建设，是对③的否后推否前，可以推出，当选；B项：翻译为人才和资金新农村建设，是对①的肯后，肯后无必然结论，无法推出，排除；C项：翻译为人才资金，题干未提及人才和资金之间的关系，无关项，无法推出，排除；D项：翻译为资金新农村建设，新农村建设不仅需要资金还需要人才，无法推出，排除。⇒ 正确答案为A。", "method": "第一步：翻译题干。①新农村建设人才和资金；②人才和资金“城归”群体壮大；将①和②", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。", "src": "2017年湖北省选调生行测题（精选） 第17 题", "kind": "real", "year": "2017"}, {"type": "logic", "level": "中等", "stem": "某次足球比赛前，甲、乙、丙、丁四位运动员猜测他们的上场情况。 甲：我们四人都不会上场； 乙：我们中有人会上场； 丙：乙和丁至少有一人上场； 丁：我会上场。 四人中有两人猜测为真两人猜测为假，则以下哪项断定成立？", "options": ["猜测为真的是乙和丙", "猜测为真的是甲和丁", "猜测为真的是甲和丙", "猜测为真的是乙和丁"], "answer": ["A"], "explain": "本题属于真假推理题。 第一步：找出题干矛盾命题。 甲：我们四人都不会上场； 乙：我们中有人会上场； 丙：乙或丁； 丁：丁。 甲说“我们四人都不会上场”和乙说“我们中有人会上场”是矛盾关系，则必有一真必有一假。已知四人中有两人猜测为真两人猜测为假，说明丙和丁的猜测也必然是一真一假。 第二步：看其余。 假设丁的猜测为真，则丁会上场，而“丁”为“乙或丁”的其中一项，此时丙的猜测也一定为真，那么丙、丁的猜测均为真，与题干要求的一真一假矛盾，故丁的猜测一定为假，即丁不会上场，则丙的猜测为真，说明乙或丁会上场，既然丁不会上场，那么上场的为乙，也就是说四个人中有人会上场，则乙的猜测为真，甲的猜测为假，即猜测为真的是乙和丙。 ⇒ 正确答案为A。", "method": "本题属于真假推理题。 第一步：找出题干矛盾命题。 甲：我们四人都不会上场； 乙：", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。", "src": "2019年北京市公务员录用考试《行测》题（网友回忆版） 第14 题", "kind": "real", "year": "2019"}, {"type": "fig", "imgs": ["data/figs/figq_037_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "图形的形状依次变化。", "trap": "", "desc": "题干为图形序列，选项 A~D 为候选图形（本题需配合图片作答）。规律提示：图形的形状依次变化。 若图片无法显示，可先跳过本题，不影响其他题目。", "kind": "real"}, {"type": "fig", "imgs": ["data/figs/figq_038_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "图形的边数依次递增。", "trap": "", "desc": "题干为图形序列，选项 A~D 为候选图形（本题需配合图片作答）。规律提示：图形的边数依次递增。 若图片无法显示，可先跳过本题，不影响其他题目。", "kind": "real"}]}, {"set": 19, "date": "2026-10-19", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 19 批）", "items": [{"type": "sci", "level": "容易", "stem": "食物链主要反映了生产者与消费者之间的联系，下列关系中最能准确表示食物链的是（ ）。", "options": ["草→兔→狐→鹰", "阳光→草→鸡→狼", "虫→鸟→蛇", "草→羊→虎→微生物"], "answer": ["A"], "explain": "思路：食物链起点必须是生产者（绿色植物），终点是最高级消费者，不含非生物部分和分解者；详解：B起点阳光是非生物；C起点虫是消费者不是生产者；D末尾微生物是分解者；A草为生产者，经兔、狐到鹰，完整准确。故答案为A。", "method": "食物链起点必须是生产者（绿色植物），终点是最高级消费者，不含非生物部分和分解者", "tip": "食物链起点=生产者，不能是阳光或动物；；食物链不出现分解者（细菌真菌微生物）；；箭头方向=被吃→吃，代表能量流动方向。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第79题", "kind": "real", "year": "2022"}, {"type": "sci", "level": "容易", "stem": "如图，甲、乙两个相同的容器中盛着不同的液体，当相同的小球漂浮在容器中并保持静止时，容器中液面的高度相同，则下列说法准确的是（ ）。", "options": ["小球在甲容器中受到浮力比在乙容器中的小", "小球在甲容器中受到浮力比在乙容器中的大", "甲容器中液体的密度比乙容器中液体的小", "甲容器中液体的密度比乙容器中液体的大"], "answer": ["C"], "explain": "思路：漂浮条件F浮=G球，两容器小球相同故浮力相等；再由阿基米德原理F浮=ρ液gV排；详解：浮力相等则ρ液甲·V排甲=ρ液乙·V排乙；图中甲中小球排开液体体积更大，故甲液体密度更小。故答案为C。", "method": "漂浮条件F浮=G球，两容器小球相同故浮力相等", "tip": "先定漂浮=浮力等于重力，两容器浮力相等；；F浮=ρ液gV排，V排大则ρ液小；；液面高度相同不代表液体密度相同。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第80题", "kind": "real", "year": "2022"}, {"type": "sci", "level": "容易", "stem": "如图是某种固态物质在加热过程中，温度随时间变化的图像。下列说法最不准确的是（ ）。", "options": ["该固态物质有固定的熔点", "该固态物质在熔化过程中，比热容增大", "温度为0℃时，该物质可能处于固液共存状态", "该固态物质在熔化时不断吸收热量，温度不断升高"], "answer": ["D"], "explain": "思路：有固定熔点的物质是晶体，熔化时吸热温度不变；详解：A有水平熔化段说明有固定熔点；B熔化过程物态变化比热容会改变；C熔点附近可能固液共存；D晶体熔化吸热但温度不变，“温度不断升高”错误。故答案为D。", "method": "有固定熔点的物质是晶体，熔化时吸热温度不变", "tip": "晶体熔化吸热不升温，图像有水平段；；非晶体没有固定熔点，温度持续上升；；水平段对应固液共存状态。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第85题", "kind": "real", "year": "2022"}, {"type": "sci", "level": "容易", "stem": "以下延长粮食存放时间的措施，最不合理的是：", "options": ["粮库的粮食存放区保持较低温度", "将其真空包装，以避免接触氧气", "适当在粮库中洒水，保持空气湿度", "给粮库的粮食存放区充入二氧化碳"], "answer": ["C"], "explain": "思路：粮食呼吸和霉变都需要水分、氧气、适宜温度；详解：A低温、B真空隔氧、D充CO2降氧都能抑制呼吸；C洒水增大湿度，会加速粮食呼吸、发芽和霉菌繁殖，最不合理。故答案为C。", "method": "粮食呼吸和霉变都需要水分、氧气、适宜温度", "tip": "粮食储存关键词：干燥、低温、低氧；；高湿高温是粮食霉变的元凶；；充氮充二氧化碳都是气调储存。", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第71题", "kind": "real", "year": "2023"}, {"type": "math", "level": "中等", "stem": "一项工作甲独立完成需要3小时，乙独立完成的用时比其与甲合作完成多4小时，且乙和丙合作完成需要4小时。问丙独立完成需要多少小时？", "options": ["10", "12", "6", "8"], "answer": ["B"], "explain": "思路：赋值+方程法。详解：赋值工作总量为12，则甲效率=12/3=4，乙丙合作效率=12/4=3。设乙效率为x，乙独立用时12/x，甲乙合作效率4+x、合作用时12/(4+x)。由题意12/x - 12/(4+x) = 4，解得x=2（乙效率2），丙效率=3-2=1，丙独立完成需12/1=12小时。故答案为B。", "method": "赋值+方程法", "tip": "工程问题设工作总量为各时间的公倍数；注意\"乙比合作多4小时\"指完成时间差，要换算成时间列方程。", "src": "2023年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 1 题", "kind": "real", "year": "2023"}, {"type": "math", "level": "中等", "stem": "某辆货车载有20吨货物，上午卸了货物总重的20%，下午卸了剩余货物的30%,则下午卸货后,货车上的货物还剩（    ）吨。", "options": ["10", "10.4", "11.2", "12.6"], "answer": ["C"], "explain": "思路：连续百分比（基数变化）；详解：上午卸20%后剩20×(1-20%)=16吨；下午卸剩余的30%后剩16×(1-30%)=16×0.7=11.2吨。故答案为C。", "method": "连续百分比（基数变化）", "tip": "连续百分比题注意每次的基数：上午基数=总量，下午基数=上午剩余；不能直接相减百分比。", "src": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 5 题", "kind": "real", "year": "2023"}, {"type": "math", "level": "中等", "stem": "-3，-1，2，7，14，（    ）", "options": ["22", "23", "25", "26"], "answer": ["C"], "explain": "思路：多级数列作差；详解：后项减前项得新数列2，3，5，7，（），为连续质数数列，下一项为11，故所求项=14+11=25。故答案为C。", "method": "多级数列作差", "tip": "多级数列先作差，差数列常见质数/合数/等差规律；质数数列2,3,5,7,11要熟记。", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 1 题", "kind": "real", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "只有确立竞争政策的基础性地位，才能推动供给侧结构性改革。在这种新形势下，必须加强顶层设计，才能确立竞争政策的基础性地位，加强顶层设计必须围绕创造公平竞争的制度环境展开，确立竞争政策的基础性地位也是实现创新驱动的必然要求。 由此可以推出：", "options": ["不加强顶层设计就不能推动供给侧结构性改革", "推动供给侧结构性改革才能实现创新驱动", "围绕创造公平竞争的制度环境展开是加强顶层设计的充分条件", "只有推动供给侧结构性改革才能加强顶层设计"], "answer": ["A"], "explain": "第一步：翻译题干。 推动供给侧结构性改革确立竞争政策的基础性地位； 确立竞争性政策的基础性地位加强顶层设计； 加强顶层设计围绕创造公平竞争的制度环境； 实现创新驱动确立竞争政策的基础性地位。将串联得：推动供给侧结构性改革确立竞争政策的基础性地位加强顶层设计围绕创造公平竞争的制度环境。第二步：逐一分析选项。A项：翻译为推动供给侧结构性改革加强顶层设计，是对的肯前，肯前必肯后，可以推出，当选；B项：翻译为实现创新驱动推动供给侧结构性改革，根据题干，没有在二者之间建立联系，无法推出，排除；C项：翻译为围绕创造公平竞争的制度环境加强顶层设计，是对的肯后，肯后得不到确定性结论，无法推出，排除；D项：翻译为加强顶层设计推动供给侧结构性改革，是对的肯后，肯后得不到确定性结论，无法推出，排除。⇒ 正确答案为A。", "method": "第一步：翻译题干。 推动供给侧结构性改革确立竞争政策的基础性地位； 确立竞争性政", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。", "src": "2019年山东省选调应届优秀高校毕业生到基层工作考试《行测》试卷（网友回忆版） 第34 题", "kind": "real", "year": "2019"}, {"type": "logic", "level": "中等", "stem": "研究表明，锻炼对人类大脑有积极作用，如果坚持锻炼，阿尔茨海默病等神经退行性疾病的发病风险就会降低。 由此可以推出：", "options": ["人类大脑如果不进行锻炼，阿尔茨海默病等神经退行性疾病的发病风险就会进一步提高", "如果没有降低阿尔茨海默病等神经退行性疾病的发病风险，那一定是没有坚持锻炼", "如果阿尔茨海默病等神经退行性疾病的发病风险降低了，那么就一定是坚持锻炼的结果", "是否坚持锻炼，直接决定了阿尔茨海默病等神经退行性疾病的发病风险能否得到降低"], "answer": ["B"], "explain": "第一步：翻译题干。坚持锻炼发病风险降低第二步：逐一分析选项。A项：翻译为锻炼发病风险提高，是对题干的否前，否前推不出确定性结论，排除；B项：翻译为发病风险降低坚持锻炼，是对题干的否后，否后必否前，可以推出，当选；C项：翻译为发病风险降低坚持锻炼，是对题干的肯后，肯后推不出确定性结论，排除；D项：“是否坚持锻炼”是同时对题干的肯前和否前，否前是推不出确定性结论，排除。⇒ 正确答案为B。", "method": "第一步：翻译题干。坚持锻炼发病风险降低第二步：逐一分析选项。A项：翻译为锻炼发病", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。", "src": "2020年湖南公务员考试《行测》试题（网友回忆版） 第33 题", "kind": "real", "year": "2020"}, {"type": "logic", "level": "中等", "stem": "四位球迷在某球赛的晋级赛开始之前对几个队伍的赛况进行预测，他们比较关注其中的两支球队，分别作了如下预测： 方某说：如果甲队不能晋级，那么乙队也不能晋级。 白某说：不管甲队能不能晋级，乙队都不能晋级。 夏某说：乙队能晋级，但甲队不能晋级。 邓某说：我看这几支球队都不能晋级。 比赛结果证明，四位球迷中只有一位的预测是正确的。 根据上述情况，以下哪项一定为真？", "options": ["白某预测是正确的", "邓某预测是正确的", "如果甲队能够晋级，那么方某的预测是正确的", "如果甲队不能晋级，那么方某的预测是正确的"], "answer": ["C"], "explain": "第一步：翻译题干。方：甲队晋级乙队晋级；白：乙队晋级；夏：乙队晋级 且 甲队晋级；邓：乙队晋级 且 甲队晋级。第二步：找关系。方某和夏某是矛盾关系，必有一真一假。第三步：看其余。四位球迷只有一位预测为真，可知白某、邓某一定为假，排除A、B两项。由白某为假，可知乙队晋级了，此时无法直接判断方某、夏某的真假，代入C、D两项验证。代入C项：假设甲队晋级，即甲和乙都晋级了，此时，夏某为假，方某为真，该项正确，当选；代入D项：假设甲队没有晋级，即甲没晋级，乙晋级了，此时，夏某为真，方某为假，该项错误，排除。⇒ 正确答案为C。", "method": "第一步：翻译题干。方：甲队晋级乙队晋级；白：乙队晋级；夏：乙队晋级 且 甲队晋级", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。", "src": "2018年421联考《行测》题（青海卷）（网友回忆版） 第35 题", "kind": "real", "year": "2018"}, {"type": "fig", "imgs": ["data/figs/figq_039_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "图形的方向依次顺时针旋转。", "trap": "", "desc": "题干为图形序列，选项 A~D 为候选图形（本题需配合图片作答）。规律提示：图形的方向依次顺时针旋转。 若图片无法显示，可先跳过本题，不影响其他题目。", "kind": "real"}, {"type": "fig", "imgs": ["data/figs/figq_040_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "图形的颜色依次变化。", "trap": "", "desc": "题干为图形序列，选项 A~D 为候选图形（本题需配合图片作答）。规律提示：图形的颜色依次变化。 若图片无法显示，可先跳过本题，不影响其他题目。", "kind": "real"}]}, {"set": 20, "date": "2026-10-20", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 20 批）", "items": [{"type": "sci", "level": "容易", "stem": "如图，物体M在恒力F的作用下沿粗糙的斜面匀速向上移动。下列说法不准确的是：", "options": ["恒力F对物体M做正功", "物体M的重力势能逐渐增大", "物体所受的摩擦力与运动方向相反", "斜面对物体M的支持力和M受到的重力是一对平衡力"], "answer": ["D"], "explain": "思路：匀速=合力为零，但各力要按方向分解判断；详解：A力沿运动方向做正功正确；B上升高度增加势能增大正确；C沿粗糙面向上，摩擦力沿斜面向下与运动方向相反正确；D支持力垂直斜面，重力竖直向下，不在同一直线上，不是平衡力。故答案为D。", "method": "匀速=合力为零，但各力要按方向分解判断", "tip": "平衡力必须同一直线、等大反向；；斜面上重力要分解为沿斜面向下和垂直压面两个分量；；摩擦力方向与相对运动方向相反。", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第68题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "目前，我国许多城市已经实现5G网络全覆盖，由于5G基站覆盖范围比4G基站的覆盖范围要小，这就意味着想要覆盖同样的区域，5G网络基站数量要比4G基站多。由此可知，与4G信号相比，5G信号：", "options": ["频率较低，波长较短", "频率较低，波长较长", "频率较高，波长较短", "频率较高，波长较长"], "answer": ["C"], "explain": "思路：电磁波在空气中波速近似光速不变，c=λf；详解：5G覆盖范围小说明绕射能力弱、波长短，由c=λf可知波长短则频率高。故答案为C。", "method": "电磁波在空气中波速近似光速不变，c=λf", "tip": "c=λf，波速一定，频率与波长成反比；；波长短→绕射差→覆盖范围小；；频率高、带宽大、穿墙差。", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第75题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "图示为海陆风示意图，昼夜交替过程中海洋与陆地间的气温差，造成了近地面大气的密度和气压差，推动气流由高压（低温）区域向低压（高温）区域运动，从而形成了海陆风，下列关于海陆风的说法正确的是：", "options": ["日间海面上气温低于陆地，而夜间则高于陆地", "日间，近地面气流由陆地向海面移动", "海面上的昼夜温差较陆地大", "图1是夜间海陆风示意图"], "answer": ["A"], "explain": "思路：陆地砂石比热容小，白天比海洋热、夜晚比海洋冷；详解：A白天海面气温低于陆地、夜间高于陆地，正确；B白天近地面风应由海面吹向陆地；C海洋昼夜温差比陆地小；D需看图，仅凭文字可确定A正确。故答案为A。", "method": "陆地砂石比热容小，白天比海洋热、夜晚比海洋冷", "tip": "陆地比热小→昼夜温差大；海洋比热大→温差小；；白天海风（海→陆），夜晚陆风（陆→海）；；风由高压低温区吹向低压高温区。", "src": "2025年广东省公务员录用考试《行测》题（考生回忆版） 第68题", "kind": "real", "year": "2025"}, {"type": "sci", "level": "容易", "stem": "有一种传统的制墨工艺：把冷碟子放在蜡烛火焰的上方，蜡烛燃烧一段时间后，冷碟子底部会有黑色物质生成，黑色物质经过进一步加工可以变成墨，则以下说法有误的是（ ）。", "options": ["所使用的蜡烛由该黑色物质和其他材料混合制成", "该黑色物质具有还原性", "冷碟子会影响蜡烛燃烧过程中氧气的补充，导致蜡烛不完全燃烧", "冷碟子能冷却底部的黑色物质，使其无法燃烧"], "answer": ["A"], "explain": "思路：冷碟压在火焰上方使氧气供应不足，蜡烛不完全燃烧析出炭黑；详解：A错误，蜡烛是石蜡制成，炭黑是燃烧产物不是原料；B炭黑（碳单质）具有还原性；C冷碟隔绝氧气造成不完全燃烧；D冷碟降温使生成的炭黑不能继续燃烧。故答案为A。", "method": "冷碟压在火焰上方使氧气供应不足，蜡烛不完全燃烧析出炭黑", "tip": "含碳物质不完全燃烧生成炭黑（黑烟）；；碳单质具有可燃性和还原性；；蜡烛主要成分是石蜡烃类。", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第65题", "kind": "real", "year": "2024"}, {"type": "math", "level": "中等", "stem": "2024年张和李年龄的平均值是刘的2倍；2028年张的年龄是李的1.5倍，比刘年龄的2倍大4岁。问张哪一年60岁？", "options": ["2036年", "2038年", "2040年", "2042年"], "answer": ["C"], "explain": "思路：方程法。详解：设2028年张、李年龄为3x、2x（张是李1.5倍），刘y岁。由张比刘2倍大4：3x=2y+4①。2024年张=3x-4、李=2x-4、刘=y-4，张李平均是刘2倍：(3x-4+2x-4)/2=2(y-4)，即(5x-8)/2=2y-8，化简5x-8=4y-16，5x=4y-8②。由①得y=(3x-4)/2，代入②：5x=2(3x-4)-8=6x-16，得x=16。2028年张=3×16=48岁，到60岁还需12年，即2028+12=2040年。故答案为C。", "method": "方程法。详解：设2028年张、李年龄为3x、2x（张是李1.5倍），刘y岁。由张比刘2倍大4：3x=2y+4①。2024年张=3x-4、李=2x-4、刘=y-4，张李平均是刘2倍：(3x-4+2x-4)/2=2(y-4)，即(5x-8)/2=2y-8，化简5x-8=4y-16，5x=4y-8②。由①得y=(3x-4)/2，代入②：5x=2(3x-4)-8=6x-16，得x=16。2028年张=3×16=48岁，到60岁还需12年，即2028+12=2040年。故答案为C。", "tip": "年龄问题每个人同增同减；整除秒杀：2028年张年龄是3的倍数，60也是3的倍数，故所求年份减2028能被3整除，只有2040满足。", "src": "2026年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 4 题", "kind": "real", "year": "2026"}, {"type": "math", "level": "中等", "stem": "某单位从所有职工中随机选3人参加某个会议，张立和李磊2人中只有1人被选中的概率是2人均被选中概率的30倍。问该单位有职工多少人？", "options": ["15", "17", "29", "33"], "answer": ["D"], "explain": "思路：组合计数。详解：设单位n人。张李只有1人被选中：先从2人选1人C(2,1)=2，再从其余n-2人选2人，情况数=2×C(n-2,2)=(n-2)(n-3)。张李都被选中：再从其余n-2人选1人，情况数=C(n-2,1)=n-2。前者是后者30倍：(n-2)(n-3)=30(n-2)，n>2约去(n-2)：n-3=30，n=33人。故答案为D。", "method": "组合计数。详解：设单位n人。张李只有1人被选中：先从2人选1人C(2,1)=2，再从其余n-2人选2人，情况数=2×C(n-2,2)=(n-2)(n-3)。张李都被选中：再从其余n-2人选1人，情况数=C(n-2,1)=n-2。前者是后者30倍：(n-2)(n-3)=30(n-2)，n>2约去(n-2)：n-3=30，n=33人。故答案为D。", "tip": "组合题'恰有1人'=选1人乘其余选2人；倍数关系方程列出后大胆约分化简，比逐一代入快。", "src": "2026年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 6 题", "kind": "real", "year": "2026"}, {"type": "math", "level": "容易", "stem": "已知食用西红柿、猪大排、油炸土豆片、牛奶各100克吸收的热量分别为20大卡、388大卡、612大卡、54大卡，快走每30分钟可以消耗热量132大卡。若小红午餐享用了西红柿84克、猪大排120克、油炸土豆片40克和牛奶120克，则她通过快走消耗掉午餐吸收的热量所需的时间是（    ）。", "options": ["1.5小时", "3小时", "4.5小时", "6小时"], "answer": ["B"], "explain": "思路：归一化计算总热量；详解：每克热量分别为0.2、3.88、6.12、0.54大卡。总热量=84×0.2+120×3.88+40×6.12+120×0.54=16.8+465.6+244.8+64.8=792大卡。快走每30分钟消耗132大卡，所需时间=792÷132×30=180分钟=3小时。故答案为B。", "method": "归一化计算总热量", "tip": "先归一到每克/每单位再计算；注意30分钟消耗132大卡，换算成小时要乘2。", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 5 题", "kind": "real", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "三维反求是测量技术、数据处理技术、图形处理技术和加工技术相结合的综合性技术，是指用一定的测量方法对实物进行测量，根据测量数据通过三维几何建模方法重构实物的数字化模型的过程。\n根据上述定义，下列关于三维反求工程的步骤，排序正确的是：\n①通过制造样品来验证模型是否满足精度和其他性能指标\n②通过一定的算法，从测量数据中提取零件的设计与加工特征\n③使用高精度的三维测量技术获取零件表面各点的空间坐标\n④使用计算机辅助设计软件将数据与特征重构为三维模型", "options": ["①③④②", "①④③②", "③①②④", "③②④①"], "answer": ["D"], "explain": "划关键词：先用测量方法对实物测量→再根据测量数据通过三维建模重构数字化模型。据此排序：③用三维测量获取表面坐标是第一步，排除A、B；再看②提取特征与④重构模型、①验证模型的顺序，应先④用软件重构模型、最后①制造样品验证模型精度，故③②④①。当选D。", "method": "过程排序题先定首末：首必是“测量/获取数据”，末必是“验证/制造样品”；再按“测量→提取特征→建模→验证”的技术逻辑串中间。", "tip": "过程排序题先定首末：首必是“测量/获取数据”，末必是“验证/制造样品”；再按“测量→提取特征→建模→验证”的技术逻辑串中间。", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 19 题", "kind": "real", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "世界科技强国必须能够在全球范围内吸引人才、留住人才、用好人才。我国要建设世界科技强国。因此，我国必须注重对国际人才的吸引与使用。\n下列选项的逻辑结构与题干最相似的是（    ）。", "options": ["人才的培养培育离不开良好的环境。因此，构筑集聚全球优秀人才的科研创新高地，完善配套制度，就能面向世界汇聚一流人才", "国家科技创新力的根本源泉在于人才，国家、民族长远发展离不开科技创新力。因此，培养创新型人才是国家、民族的长远发展之计", "科技创新离不开科技人员持久的时间和精力投入。因此，要建立让科研人员把主要精力放在科研上的保障机制", "榜样的力量对科技工作者来说是无穷的。两院院士是科技成果的主要贡献者，更应做好表率，激励广大科技工作者不断攻坚克难、勇攀高峰"], "answer": ["B"], "explain": "先抽象题干结构：世界科技强国(1)→吸引用好人才(2)；我国(3)要建设世界科技强国(即3属于1/3→1)；因此我国(3)→注重吸引使用国际人才(2)，即结构为1→2，3→1，故3→2（连锁三段论）。逐项：A只有一个前提1→2，直接推2→3，缺第二个前提，结构不同；B科技创新力(1)→人才(2)，国家长远发展(3)→科技创新力(1)，因此长远发展(3)→人才(2)，即1→2，3→1，故3→2，完全一致，当选；C只有一个前提1→2，结论3（保障机制）是新提的概念；D科技工作者→榜样，院士→主要贡献者，两概念不等同无法串联。", "method": "平行结构先数前提个数、再套字母公式；题干是两个前提连锁推出结论，单前提或引入新概念的选项直接排除。", "tip": "平行结构先数前提个数、再套字母公式；题干是两个前提连锁推出结论，单前提或引入新概念的选项直接排除。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 30 题", "kind": "real", "year": "2022"}, {"type": "logic", "level": "容易", "stem": "某科研机构今年拟举办甲、乙、丙、丁、戊、己、庚、辛8次学术会议，其中第二季度（4—6月）的会议安排需满足以下条件：（1）4月只安排1次会议；（2）丙会议必须安排在5月；（3）甲会议要安排在乙会议之前（不一定在同一月），且甲、乙两次会议安排在连续的月份；（4）丁、戊两次会议安排在同一月；（5）己会议安排在庚会议之后（不一定在同一月）；（6）辛会议安排在戊会议之后（不一定在同一月）。\n如果丙会议和乙会议安排在同一月，且己会议安排在5月，则以下会议安排不可能在6月的是：", "options": ["辛", "戊", "乙", "甲"], "answer": ["D"], "explain": "先定硬约束：由（2）丙在5月，丙与乙同月，故乙也在5月；由（3）甲在乙之前且连续月份，乙在5月则甲必在4月；由（5）己在5月。因此甲已锁定在4月，不可能在6月。辛、戊在满足（4）（6）下可排6月，乙在5月。当选D。", "method": "连续月份+甲在乙之前是关键：乙在5月则甲只能在4月，直接锁定甲不可能在6月。", "tip": "连续月份+甲在乙之前是关键：乙在5月则甲只能在4月，直接锁定甲不可能在6月。", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 4 题", "kind": "real", "year": "2025"}, {"type": "fig", "imgs": ["data/figs/figq_041_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "图形的大小依次递减。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_042_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "图形的形状依次变化。", "trap": ""}]}, {"set": 21, "date": "2026-10-20", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 21 批）", "items": [{"type": "sci", "level": "容易", "stem": "下图是动物养殖场自动喂水装置的简要示意图。当动物通过饮水口饮水后，水箱内的水位下降，水瓶中的水将自动流入水箱，使水位回到一定的高度。关于这一装置，下列说法正确的是：", "options": ["水瓶最终会处于真空状态", "水瓶内的气压始终等于水箱内的气压", "装置达到平衡时，水瓶内的气压高于大气压", "该装置是利用水瓶、水箱之间的气压差实现的"], "answer": ["D"], "explain": "思路：这是大气压支撑水柱的装置，类似倒置水杯；详解：水位下降瓶口露出时空气进入水瓶，在重力和气压差作用下水补入水箱，正是利用瓶内外气压差；A不会真空；B气压并不始终相等；C平衡时瓶内气压+水柱压=大气压，瓶内气压低于大气压。故答案为D。", "method": "这是大气压支撑水柱的装置，类似倒置水杯", "tip": "瓶内气压+水柱压强=外界大气压；；水位控制靠空气进入与气压差；；不要把瓶内气压判断成高于外界。", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第77题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "如图，小球在细绳的牵引下从A点自由摆动到C点，B点是最低点。若忽略空气阻力，则下列说法不准确的是（ ）。", "options": ["从A点到B点小球的动能增加", "从B点到C点小球的势能增加", "在B点小球的动能最大", "从A点到C点小球的机械能增加"], "answer": ["D"], "explain": "思路：单摆摆动中机械能守恒，高度决定势能、速度决定动能；详解：A到B高度下降势能转动能，动能增大；B到C上升动能转势能，势能增大；B点最低速度最大动能最大；D机械能守恒不增加。故答案为D。", "method": "单摆摆动中机械能守恒，高度决定势能、速度决定动能", "tip": "不计空气阻力=机械能守恒；；最低点动能最大势能最小；；上升过程动能转势能，下降过程势能转动能。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第83题", "kind": "real", "year": "2022"}, {"type": "sci", "level": "中等", "stem": "无性繁殖是一种不涉及生殖细胞，不需要经过受精过程，由母体的一部分直接形成新个体的繁殖方式。以下繁殖过程不属于无性繁殖的是：", "options": ["西瓜的花被授粉后结出了果实", "一个草履虫经过细胞分裂变成两个", "水螅母体的体壁上形成与母体相似的芽体", "马铃薯的块茎发芽生长后，形成新的个体"], "answer": ["A"], "explain": "思路：判断关键是否经过受精作用；详解：A西瓜花授粉即精子与卵细胞结合，经过受精，属有性繁殖；B分裂生殖、C出芽生殖、D营养繁殖都没有受精，属无性繁殖。故答案为A。", "method": "判断关键是否经过受精作用", "tip": "有性繁殖=经过两性生殖细胞结合；；分裂、出芽、扦插嫁接、块茎繁殖都是无性；；种子繁殖一般是有性繁殖。", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第82题", "kind": "real", "year": "2023"}, {"type": "sci", "level": "容易", "stem": "夏日，小王调制了一杯28℃的蔗糖水，尝了一口后感觉不够甜，又加入了一些蔗糖，搅拌后蔗糖完全溶解。之后他把蔗糖水放入冰箱，一段时间后取出时发现杯子底部有少许晶体析出，则下列说法正确的有：\n①刚放入冰箱的蔗糖溶液一定不是饱和溶液\n②从冰箱中取出的蔗糖溶液一定是饱和溶液\n③放入冰箱前后，蔗糖溶液中溶质的质量相等\n④用加热蒸发溶剂的方法能够得到与析出晶体相同的物质", "options": ["①②", "①④", "②③", "②④"], "answer": ["D"], "explain": "思路：根据是否有未溶晶体判断饱和状态；详解：①刚放入时也可能恰好饱和，“一定不是”错误；②杯底有晶体析出，说明上层溶液一定饱和；③析出晶体使溶液中溶质减少，质量不相等；④析出的是蔗糖晶体，加热蒸发溶剂得到的也是蔗糖晶体。故②④正确。答案为D。", "method": "根据是否有未溶晶体判断饱和状态", "tip": "有未溶固体=该温度下饱和溶液；；溶解度随温度降低而减小的物质，降温会析出晶体；；析出晶体与蒸发结晶得到同种溶质。", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第83题", "kind": "real", "year": "2023"}, {"type": "math", "level": "中等", "stem": "小陈计划在一定时间内完成法律常识题库中的所有练习题。如果每天做50道题，那么最后2天每天要做85道题才能完成，如果每天做55道题，恰好可以提前1天完成，则该题库共有（    ）道题。", "options": ["1215", "1250", "1320", "1375"], "answer": ["C"], "explain": "思路：方程法，设计划x天完成。详解：第一种情况，前面(x-2)天每天50道、最后2天每天85道，总题数=50(x-2)+85×2；第二种情况每天55道、提前1天即做(x-1)天，总题数=55(x-1)。列方程50(x-2)+170=55(x-1)，即50x-100+170=55x-55，50x+70=55x-55，解得x=25天。总题数=55×(25-1)=55×24=1320道。故答案为C（1320）。", "method": "方程法，设计划x天完成。详解：第一种情况，前面(x-2)天每天50道、最后2天每天85道，总题数=50(x-2)+85×2", "tip": "①盈亏类题用“计划天数”作未知数最直接；②注意“最后2天每天多做”与“提前1天”都是相对于同一计划天数，别漏减前面的天数。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 3 题", "kind": "real", "year": "2022"}, {"type": "math", "level": "中等", "stem": "有一个长方形花坛，长为10米，宽为8米。现要在花坛四周安装栅栏，要求4个顶点处各插一根木桩，除顶点处的木桩外，每边还要插若干木桩，且每两根木桩间的距离至少为3米，则最多可以插（    ）根木桩。", "options": ["10", "12", "14", "16"], "answer": ["A"], "explain": "思路：环形（封闭）植树，间隔数=木桩数。详解：要木桩最多则间距取最小3米。长边10÷3≈3.33，取3个间隔（余1米）；宽边8÷3≈2.67，取2个间隔（余2米）。长方形周长方向共2×(3+2)=10个间隔，封闭图形间隔数=棵数，故最多10根木桩。故答案为A（10）。", "method": "环形（封闭）植树，间隔数=木桩数。详解：要木桩最多则间距取最小3米。长边10÷3≈3.33，取3个间隔（余1米）", "tip": "①封闭图形（花坛四周）植树：棵数=间隔数，不要+1；②每边有余数时，商几就是几个间隔，不能四舍五入多栽（会小于3米）；③四边合计=2×(长边间隔+宽边间隔)。", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 7 题", "kind": "real", "year": "2022"}, {"type": "math", "level": "容易", "stem": "小李从山脚开始登顶，匀速走了1小时后到达一个凉亭，并在凉亭休息了半小时。继续走500米后，恰好完成登顶路程的一半。从山顶沿原路匀速返回时，他走了1小时又到了这个凉亭，继续走半小时回到了山脚。则登顶路程为（   ）米。", "options": ["2000", "3000", "3600", "4000"], "answer": ["B"], "explain": "思路：比例行程。详解：山脚到凉亭上山走1小时，凉亭到山脚下山走半小时，同一段路程时间比上山:下山=1:0.5=2:1，路程一定速度与时间成反比，故上山速v:下山速2v=1:2。设上山速v，从凉亭到山顶再返回凉亭的关系：从凉亭继续上山500米到一半处……由题意“走1小时到凉亭、再走半小时到山脚”对应下山路，列关系(v+500)×2=2v×1.5，解得v=1000米/时。全程=上山1小时路程×2+500×2=2×(1000×1+500)=3000米。故答案为B。", "method": "比例行程。详解：山脚到凉亭上山走1小时，凉亭到山脚下山走半小时，同一段路程时间比上山:下山=1:0.5=2:1，路程一定速度与时间成反比，故上山速v:下山速2v=1:2。设上山速v，从凉亭到山顶再返回凉亭的关系：从凉亭继续上山500米到一半处……由题意“走1小时到凉亭、再走半小时到山脚”对应下山路，列关系(v+500)×2=2v×1.5，解得v=1000米/时。全程=上山1小时路程×2+500×2=2×(1000×1+500)=3000米。故答案为B。", "tip": "同一段路上山下山时间比即速度反比；休息时间不计入行程；全程是半程的2倍，先算半程再乘2。", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第 13 题", "kind": "real", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "预判设计是一种能够引导用户、缩短用户行为路径的有效设计手段。它可以根据用户的行为或用户所在的场景，让功能“主动找到”用户，并让用户与之产生自然的交互，为用户提供更好的使用体验，本质就是为用户多想一步，让用户使用起来尽量简单。\n根据上述定义，下列不属于预判设计的是：", "options": ["某购物软件，根据用户输入的搜索关键词，将商品按与关键词的相关性排列", "某翻译软件，用户第一次点击播放，语音速度正常；再次点击，语音速度变慢", "某外卖软件，当用户对店家给出差评，系统自动勾选“将评价设为匿名评价”", "某购物软件，所选商品缺货时，出现“找相似”按钮，点击可看到同款、相似商品"], "answer": ["A"], "explain": "划关键词：①引导用户缩短行为路径；②功能主动找到用户；③为用户多想一步。选非：A购物软件按搜索词列相关商品=配合现有搜索行为，未预判下一步也未缩短路径；B再点变慢预判用户没听清；C差评自动勾匿名预判用户不想暴露身份；D缺货自动出找相似按钮。BCD都满足，A不满足。故A。", "method": "预判设计核心是\"主动替用户想下一步\"，被动配合搜索不是；选非题用找不同法。", "tip": "预判设计核心是\"主动替用户想下一步\"，被动配合搜索不是；选非题用找不同法。", "src": "2023年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 21 题", "kind": "real", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "宇宙：元宇宙", "options": ["闺女：亲闺女", "消息：假消息", "计算：云计算", "化石：活化石"], "answer": ["D"], "explain": "先定一级关系：元宇宙不是真正的宇宙，是从“宇宙”衍生的虚拟科技词；二级辨析：看选项是否“后者不是真正前者，且从前者衍生”。A闺女包含亲闺女，是包含关系；B假消息是一种消息，种属；C云计算是计算的一种，种属；D活化石不是真正的化石，是从“化石”衍生的词，与题干一致。答案为D。", "method": "类比题先看词性结构再定关系；注意“衍生词非真属”这种二级辨析。", "tip": "类比题先看词性结构再定关系；注意“衍生词非真属”这种二级辨析。", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 5 题", "kind": "real", "year": "2023"}, {"type": "logic", "level": "容易", "stem": "某法院对某刑事案件有以下四种说法：①有证据表明赵刚没有作案；②作案者或者是赵刚，或者是王强，或者是李明；③也有证据表明王强没有作案；④电视画面显示，案发时李明在远离案发现场的一个足球赛的观众席上。 下列各项是对四种说法的不同描述，其中正确的一项是：", "options": ["从上述说法中可以推出，只有一个人作案", "上述说法中至少有一个是假的", "从这几种说法中可以推出，表明王强没有作案的证据是假的", "李明肯定不在该足球赛的观众席上"], "answer": ["B"], "explain": "第一步：找出题干矛盾关系。 本题突破口为“三个人都有证据表明没有作案”与“他们至少有一个人作案”之间的矛盾关系。 第二步：判断真假。 由“三个人都有证据表明没有作案”与“他们至少有一个人作案”之间的矛盾关系可知二者必有一假，故上述说法至少有一个是假的，但不能具体判断谁真谁假。 ⇒ 正确答案为B。", "method": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。", "src": "2016年天津选调生选拔考试 综合知识试卷（精选） 第8 题", "kind": "real", "year": "2016"}, {"type": "fig", "imgs": ["data/figs/figq_043_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "图形的边数依次递增。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_044_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "图形的方向依次顺时针旋转。", "trap": ""}]}, {"set": 22, "date": "2026-10-21", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 22 批）", "items": [{"type": "sci", "level": "中等", "id": "kx_000068", "stem": "如图，甲、乙两个相同的容器中盛着不同的液体，当相同的小球漂浮在容器中并保持静止时，容器中液面的高度相同，则下列说法准确的是（ ）。", "options": ["小球在甲容器中受到浮力比在乙容器中的小", "小球在甲容器中受到浮力比在乙容器中的大", "甲容器中液体的密度比乙容器中液体的小", "甲容器中液体的密度比乙容器中液体的大"], "answer": ["C"], "explain": "思路：漂浮条件F浮=G球，两容器小球相同故浮力相等；再由阿基米德原理F浮=ρ液gV排；详解：浮力相等则ρ液甲·V排甲=ρ液乙·V排乙；图中甲中小球排开液体体积更大，故甲液体密度更小。故答案为C。", "method": "漂浮条件F浮=G球，两容器小球相同故浮力相等", "tip": "易错点：误以为液面高的液体密度大；漂浮时浮力恒等于小球重力，与液体密度无关，排开体积大的液体密度反而小。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第80题", "year": "2022"}, {"type": "sci", "level": "中等", "id": "kx_000092", "stem": "在日常生活中，人们总是难以避免与细菌接触，以下有关细菌的说法错误的是：", "options": ["我国甲类传染病中的鼠疫是由细菌引发的", "有的细菌可用于食品生产、废水处理或生物分解", "细菌是微生物也是细胞，可以自行分裂繁殖", "杀灭细菌，只能依靠人体自身免疫力"], "answer": ["D"], "explain": "思路：结合细菌的结构、作用和抑菌杀菌手段判断；详解：A鼠疫由鼠疫杆菌引起正确；B利用乳酸菌、腐生菌等可用于食品和污水处理；C细菌是单细胞微生物，分裂生殖；D杀灭细菌还可用抗生素、消毒剂等，“只能靠免疫力”错误。故答案为D。", "method": "结合细菌的结构、作用和抑菌杀菌手段判断", "tip": "易错点：把免疫力当成唯一杀菌手段；抗生素、消毒、杀菌药剂都能杀灭细菌。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（考生回忆版） 第70题", "year": "2025"}, {"type": "sci", "level": "中等", "id": "kx_000072", "stem": "如图，物体M在恒力F的作用下沿粗糙的斜面匀速向上移动。下列说法不准确的是：", "options": ["恒力F对物体M做正功", "物体M的重力势能逐渐增大", "物体所受的摩擦力与运动方向相反", "斜面对物体M的支持力和M受到的重力是一对平衡力"], "answer": ["D"], "explain": "思路：匀速=合力为零，但各力要按方向分解判断；详解：A力沿运动方向做正功正确；B上升高度增加势能增大正确；C沿粗糙面向上，摩擦力沿斜面向下与运动方向相反正确；D支持力垂直斜面，重力竖直向下，不在同一直线上，不是平衡力。故答案为D。", "method": "匀速=合力为零，但各力要按方向分解判断", "tip": "易错点：把“匀速”当成受力平衡就以为支持力等于重力；支持力垂直斜面、重力竖直向下，二者方向不同，不是一对平衡力。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第68题", "year": "2023"}, {"type": "sci", "level": "中等", "id": "kx_000061", "stem": "农技站为了贮存种子，拟采用以下做法，其中最可行的是", "options": ["将种子浸泡在含水的容器中", "将种子置放在含氧量低于1%的干燥地窖中", "将种子置于15摄氏度左右的低温环境中", "将种子封闭在完全避光的黑暗环境中"], "answer": ["B"], "explain": "思路：种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度；详解：A浸泡在水中会让种子萌发甚至霉烂；C仅15℃远达不到储存要求；D避光并非关键；B干燥地窖既控制水分又把含氧量压到1%以下，呼吸作用被显著抑制，最可行。故答案为B。", "method": "种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度", "tip": "易错点：误选C，以为15℃低温就够了；种子储存的关键是抑制呼吸作用，需同时满足干燥、低氧、低温三条件。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第66题", "year": "2020"}, {"type": "math", "level": "中等", "id": "sl_000127", "stem": "某社区计划组织志愿者为社区内的独居老人提供服务。按已有志愿者的数量，如果每位志愿者服务10位老人，则有5位老人无人提供服务；如果增加2位志愿者，则每位志愿者最多服务8位老人就能为所有老人提供服务。那么该社区最多有（   ）位独居老人。", "options": ["50", "55", "60", "65"], "answer": ["B"], "explain": "思路：代入排除。详解：求最多老人数，从大到小代。D项65：原志愿者(65-5)÷10=6人，加2人变8人，8×8=64<65，不够，排除；C项60：志愿者(60-5)÷10=5.5人，非整数，排除；B项55：志愿者(55-5)÷10=5人，加2人变7人，7×8=56≥55，满足。故答案为B。", "method": "代入排除。详解：求最多老人数，从大到小代。D项65：原志愿者(65-5)÷10=6人，加2人变8人，8×8=64<65，不够，排除", "tip": "余数问题优先代入；人数必须是整数，除不尽的选项直接排除；“最多服务8位”即8×新志愿者数≥老人数。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第 14 题", "year": "2024"}, {"type": "math", "level": "中等", "id": "sl_000044", "stem": "为支持\"一带一路\"建设，某公司派出甲、乙两队工程人员出国参与一个高铁建设项目。如果由甲队单独施工，200天可完成该项目；如果由乙队单独施工，则需要300天。甲、乙两队共同施工60天后，甲队被临时调离，由乙队单独完成剩余任务，则完成该项目共需（    ）天。", "options": ["120", "150", "180", "210"], "answer": ["D"], "explain": "思路：赋值法（工程问题）。赋值工作总量为200和300的最小公倍数600，则甲效率=600÷200=3，乙效率=600÷300=2。甲乙合作60天完成工作量=(3+2)×60=300，剩余工作量=600-300=300。乙单独完成剩余需300÷2=150天。总天数=合作60天+乙单独150天=210天。故答案为D。", "method": "赋值法（工程问题）", "tip": "①工程问题赋值总量为时间最小公倍数；②总天数=合作时间+剩余单独时间，不要漏算合作的60天；③甲调离后乙继续做，不要误以为乙从头开始。", "kind": "real", "src": "2021年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 3 题", "year": "2021"}, {"type": "math", "level": "中等", "id": "sl_000104", "stem": "163，47，22，-19，79，（    ）", "options": ["-256", "-115", "181", "223"], "answer": ["A"], "explain": "思路：递推数列（圈三数）；详解：观察47、22、-19，发现47-22×3=-19，即第一项减第二项的3倍等于第三项；验证：163-47×3=163-141=22，22-(-19)×3=22+57=79，均成立；故所求项=-19-79×3=-19-237=-256。故答案为A。", "method": "递推数列（圈三数）", "tip": "递推数列圈相邻三项凑倍积关系，系数（本题×3）可用最大项反推；负数运算别忘变号。", "kind": "real", "src": "2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版） 第 2 题", "year": "2023"}, {"type": "logic", "level": "中等", "id": "pd_000370", "stem": "红色研学：指以中国革命或社会主义建设时期的历史、事迹和精神为主题，以相关纪念地、标志物等为载体组织开展的旅游活动。\n下列属于红色研学的是（    ）。", "options": ["每到节假日都有很多学生来到渡江胜利纪念馆，了解新中国诞生的历史，学习革命先辈的英勇献身精神，观赏长江美景", "某实验中学的近百名团员在老师带领下来到北大荒开发建设纪念馆，从讲解员的介绍中感受了北大荒建设的艰辛及辉煌成就", "寒假期间，市文化中心推出“培根铸魂颂中华”活动，组织青少年吟诵爱国主义诗词作品，增强对中华文化的自豪感", "清明节前夕，某大学组织学生党员到市郊革命烈士陵园开展义务宣讲活动，为外地游客讲述烈士事迹，受到游客的广泛赞誉"], "answer": ["B"], "explain": "划关键词：①以革命/建设时期历史事迹精神为主题；②以纪念地/标志物为载体；③组织开展的旅游活动。A学生自发，不满足③；B老师带领到北大荒纪念馆，三要件全满足；C在文化中心吟诵诗词，不在纪念地，且非旅游活动；D到烈士陵园是义务宣讲，非旅游。答案为B。", "method": "划关键词：①以革命/建设时期历史事迹精神为主题；②以纪念地/标志物为载体；③组织", "tip": "定义题先划关键要件，选项必须全部满足；“组织开展”“旅游活动”是容易漏的要件。", "kind": "real", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 41 题", "year": "2023"}, {"type": "logic", "level": "中等", "id": "pd_000294", "stem": "每一名战士都是英雄，每一名英雄都值得被纪念，因此每一名战士都值得被纪念。\n下列选项的逻辑结构与题干最相似的是（    ）。", "options": ["艺术家往往是浪漫主义者，而有些浪漫主义者会感情用事，因此艺术家常会感情用事", "所有素食主义者都是人文主义者，而所有和平主义者都是人文主义者，因此素食主义者一定是和平主义者", "所有的科学家都是理性主义者，所有的理性主义者都是天生的哲学家。因此科学家都是天生的哲学家", "利己主义者总是以自身利益最大化作为行事准则，而单纯追求自身利益的最大化必然会损害到他人利益，因此利己主义者总会和他人发生冲突"], "answer": ["C"], "explain": "先抽象题干结构：战士→英雄，英雄→值得被纪念，因此战士→值得被纪念，即a→b，b→c，故a→c（中项b在前提中周延传递）。逐项：A为a→b，有的b→c，故a→c，含“有些”与题干“所有”不符；B为a→b，c→b，故a→c，两项都指向b而非b→c，结构不同；C为科学家→理性主义者，理性主义者→天生哲学家，因此科学家→天生哲学家，即a→b，b→c，故a→c，完全一致，当选；D为a→b，b→c，但结论a→d（损害他人利益≠和他人冲突），概念偷换。", "method": "先抽象题干结构：战士→英雄，英雄→值得被纪念，因此战士→值得被纪念，即a→b，b", "tip": "平行结构题把题干翻译成字母公式（a→b，b→c），再逐项套公式；重点看中项是否传递、量词是“所有”还是“有些”、结论概念是否被偷换。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 29 题", "year": "2022"}, {"type": "logic", "level": "中等", "id": "pd_000103", "stem": "过去人们基于对月岩原子放射性衰变的测量认为，月球诞生在太阳系形成之后约3000万到4000万年之间。一项新的研究基于259台电脑对围绕太阳旋转的原行星盘演化过程的模拟，再现了小型天体在最终形成现有岩态行星之前不断撞击和聚合的过程。该研究人员认为，大约在太阳系诞生之后约9500万年，一颗巨大的小行星撞击地球，形成的碎片最后变成了月球。 以下哪项最能指出前后两种观点的分歧？", "options": ["关于月球形成时间，有两种不同的估算方法，一种基于放射性衰变测量，一种是基于计算机模拟", "关于月球形成过程，有两种不同的理论假说，一种基于月岩自然衰变，一种是原行星盘自然演化", "关于月球形成方式，有两种不同的模型解释，一种基于月球组成成分的测量，一种是小行星撞击", "关于月球与地球的演化，有两种不同的还原方法，一种基于月球现有成分的测量，一种是计算机模拟"], "answer": ["A"], "explain": "第一步：分析题干主要信息。 第一种观点：基于对月岩原子放射性衰变的测量认为，月球诞生在太阳系形成之后约3000万年到4000万年之间； 第二种观点：基于259台电脑对围绕太阳旋转的原行星盘演化过程的模拟，大约在太阳系诞生之后约9500万年，一颗巨大的小行星撞击地球形成的碎片最后变成了月球。 第二步：逐一分析选项。 A项：第一种观点是基于对月岩原子放射性衰变的测量得出结论，第二种观点是基于259台电脑的模拟，得到了不同的月亮形成时间，与选项的描述内容一致，指出前后两种观点最大的分歧，当选； B项：两种观点都是研究月球形成的时间，不是月球的形成过程，而且第一种观点基于的是月岩原子放射性衰变，并不是月岩自然衰变，与题干描述不一致，不能解释分歧，排除； C项：两种观点都是研究月球形成的时间，不是月球的形成方式，而且第一种观点基于的是月岩原子放射性衰变，并不是月球组成成分的测量，与题干描述不一致，不能解释分歧，排除； D项：两种观点都是研究月球形成的时间，不是月球和地球的演化，而且第一种观点基于的是月岩原子放射性衰变，并不是月球现有成分的测量，与题干描述不一致，不能解释分歧，排除。 ⇒ 正确答案为A。", "method": "第一步：分析题干主要信息。 第一种观点：基于对月岩原子放射性衰变的测量认为，月球", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。", "kind": "real", "src": "2016年山东省公务员录用考试《行测》题 第35 题", "year": "2016"}, {"type": "fig", "imgs": ["data/figs/figq_047_1.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。", "options": ["", "", "", ""], "answer": ["A"], "explain": "第一行都是一笔写成的线条，第二行都是两笔写成的线条，第三行都是三笔写成的线条，选择选项中是三笔写成的选项，只要A 是三笔写成的，所以答案选A。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_048_1.png"], "src": "", "cat": "", "fmt": "", "stem": "找出下列图形中不同于其他图形的一项:", "options": ["", "", "", ""], "answer": ["A"], "explain": "A 选项切分之后有四边形，其余都只有三角形", "trap": ""}]}, {"set": 23, "date": "2026-10-21", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 23 批）", "items": [{"type": "sci", "level": "中等", "id": "kx_000082", "stem": "甲酸（HCOOH）具有清洁制氢的巨大潜力，其反应前后分子种类变化的微观示意图如下图所示。则下列说法正确的是：", "options": ["反应后分子个数增多", "该反应类型为化合反应", "反应物和生成物都是有机物", "该反应不遵守能量守恒定律"], "answer": ["A"], "explain": "思路：写出反应方程式HCOOH→H₂↑+CO₂↑；详解：A一个甲酸分子生成一个氢分子和一个二氧化碳分子，分子个数由1变2，增多；B是分解反应不是化合；C生成物H2、CO2属无机物；D一切化学反应都遵守能量守恒。故答案为A。", "method": "写出反应方程式HCOOH→H₂↑+CO₂↑", "tip": "易错点：把它当成化合反应或以为有生成物就是有机物；甲酸分解是一变多，属分解反应。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第80题", "year": "2023"}, {"type": "sci", "level": "中等", "id": "kx_000066", "stem": "对下列生活中的现象或做法解释不合理的是（ ）。", "options": ["物体的热胀冷缩——分子随温度升高而变大", "油锅着火用锅盖盖灭——使可燃物与空气隔绝", "在铁制品表面刷油漆——避免铁制品氧化生锈", "利用真空袋包装食品——破坏需氧菌类的生存环境"], "answer": ["A"], "explain": "思路：用微观和化学原理逐一核对；详解：A热胀冷缩是分子间间隔随温度升高而增大，分子本身体积不变，解释错误；B盖锅盖隔绝氧气灭火正确；C刷油漆隔绝水和氧气防锈正确；D真空缺氧气抑制需氧菌正确。故答案为A。", "method": "用微观和化学原理逐一核对", "tip": "易错点：误以为热胀冷缩是分子本身变大；实际是分子间间隔随温度改变，分子大小不变。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第76题", "year": "2022"}, {"type": "sci", "level": "中等", "id": "kx_000087", "stem": "从北极上空俯视，地球围绕地轴呈逆时针方向自转。如果在北极的地轴正上方有一颗肉眼可见的星星，有一人站在赤道上整晚观察这颗星星。他有可能观察到：\n①这颗星星东升西落\n②这颗星星没有东升西落\n③周围的星星以这颗星星为中心呈逆时针方向转动\n④周围的星星以这颗星星为中心呈顺时针方向转动", "options": ["②③", "①④", "①③", "②④"], "answer": ["A"], "explain": "思路：这颗星位于北天极正上方，在赤道上看它位于正北地平线附近，位置几乎不动；详解：①它不东升西落，②正确；地球自西向东自转，面向北天极看，周围恒星绕北极星逆时针转动，③正确④错误。故②③。答案为A。", "method": "这颗星位于北天极正上方，在赤道上看它位于正北地平线附近，位置几乎不动", "tip": "易错点：以为天上所有星星都东升西落；位于天极的星星（如北极星）高度角不变，不升不落，周围星星绕它旋转。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第85题", "year": "2023"}, {"type": "sci", "level": "中等", "id": "kx_000074", "stem": "小张观察发现，自家房屋的北面在夏天能够被阳光照射，而在冬天，房屋的南面可以被阳光照射。则他家最有可能位于以下城市中的：", "options": ["海口", "武汉", "上海", "北京"], "answer": ["A"], "explain": "思路：北回归线以北全年正午太阳都在南方，房屋南面采光；只有在北回归线以南，太阳直射点移到北面时北面才会被晒到；详解：海口约20°N在北回归线以南，武汉、上海、北京均在北回归线以北。故答案为A。", "method": "北回归线以北全年正午太阳都在南方，房屋南面采光", "tip": "易错点：凭直觉选大城市；关键是“北面夏天有阳光”说明正午太阳位于房屋北侧，即该地在北回归线以南。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第70题", "year": "2023"}, {"type": "math", "level": "中等", "id": "sl_000046", "stem": "小王和小李沿着绿道往返运动，绿道总长度为3公里。小王每小时走2公里；小李每小时跑4公里。如果两人同时从绿道的一端出发，则当两人第7次相遇时，距离出发点（    ）公里。", "options": ["0", "1", "1.5", "2"], "answer": ["D"], "explain": "思路：直线往返相遇问题。同端出发第n次相遇时两人路程和=2nS=2×7×3=42公里。速度和=2+4=6公里/小时，相遇时间t=42÷6=7小时。小王走的路程=2×7=14公里。绿道长3公里，14÷3=4余2，即小王往返了4次（偶数次回到出发点）后又走了2公里，故相遇点距出发点2公里。故答案为D。", "method": "直线往返相遇问题", "tip": "①同端出发相遇路程和=2nS；两端出发才是(2n-1)S；②判断位置：路程除以全程长度，商为偶数回到出发点再走余数，商为奇数在端点后折返；③小李速度快不影响，只", "kind": "real", "src": "2021年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 5 题", "year": "2021"}, {"type": "math", "level": "中等", "id": "sl_000105", "stem": "-2，1，0，5，26，17，124，37，（    ）", "options": ["196", "216", "278", "342"], "answer": ["D"], "explain": "思路：多重数列（交叉看）；详解：奇数项-2、0、26、124，各项加1得-1、1、27、125=(-1)³、1³、3³、5³，底数为连续奇数，下一个为7³=343，故所求项=343-1=342；偶数项1、5、17、37，各项减1得0、4、16、36=0²、2²、4²、6²，验证规律。故答案为D。", "method": "多重数列（交叉看）", "tip": "项数不少于7项优先多重数列交叉看；熟记立方数附近的数（124≈125-1，26≈27-1）是破题关键。", "kind": "real", "src": "2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版） 第 4 题", "year": "2023"}, {"type": "math", "level": "中等", "id": "sl_000145", "stem": "父子两人在百米赛道上匀速跑步，两人从赛道起点同时出发，父亲跑到终点时，儿子距离终点还有40米，若父亲立即折返跑向赛道起点，则两人相遇时，儿子距离终点还有（    ）米。", "options": ["35", "30", "25", "15"], "answer": ["C"], "explain": "思路：比例法（时间相同路程比=速度比）；详解：父到终点跑100米时子跑60米，速度比v父:v子=100:60=5:3；父折返后两人相向而行，相距40米（子距终点40米），相遇时两人共跑40米，按5:3分配，父亲跑40×5/8=25米；即相遇点距终点25米。故答案为C。", "method": "比例法（时间相同路程比=速度比）", "tip": "行程问题先求速度比；相遇问题路程和=总距离，按速度比分配；注意问的是“儿子距离终点”，即折返父亲跑的距离（从终点往回跑）。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（网友回忆版） 第 5 题", "year": "2025"}, {"type": "logic", "level": "中等", "id": "pd_000373", "stem": "野性消费：指消费者在特定情形下，为了表达对相关企业产品的支持而有意忽略产品性能、个人消费能力或需求的情感性购买行为。\n下列属于野性消费的是：", "options": ["陈女士自驾游时，看见一个孩子在路边卖土豆，得知他的父亲遭遇车祸后，毫不犹豫买下全部土豆，并开车把他送回了几公里外的家", "某地发生自然灾害后，某服装企业低调捐赠了数百万元赈灾物资，网友深受感动，涌入其直播间下单，很多人一买就是几十件", "老马包子铺多年来一直向每位进店消费的环卫工赠送两个包子。网友拍到后顶上了热搜，许多顾客纷纷前来购买", "刚工作的小邓喜欢“花明天的钱，圆今天的梦”，昨天手机碎屏后立马用分期付款的方式购买了一款心仪已久的折叠屏手机"], "answer": ["B"], "explain": "划关键词：①为表达对企业产品的支持；②有意忽略性能/消费能力/需求；③情感性购买。A买孩子土豆非企业产品；B网友因企业赈灾感动而涌入直播间下单，一买几十件，符合三要件；C老马包子铺是否为企业不明确，且未忽略需求；D小邓因喜爱购买，非表达支持。答案为B。", "method": "划关键词：①为表达对企业产品的支持；②有意忽略性能/消费能力/需求；③情感性购买", "tip": "定义题要同时满足“情感动因（支持企业）”和“非理性（忽略需求）”；单纯喜爱或同情不算。", "kind": "real", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 44 题", "year": "2023"}, {"type": "logic", "level": "中等", "id": "pd_000450", "stem": "自动投案是指犯罪事实或者犯罪嫌疑人未被司法机关发觉，或者虽被发觉，但犯罪嫌疑人尚未受到讯问、未被采取强制措施时，主动、直接向公安机关、人民检察院或者人民法院投案。\n根据上述定义，下列不属于自动投案的是：", "options": ["甲实施多起电信诈骗，在公安机关进行的一次隐患排查入户走访中，发现甲形迹可疑，经盘问甲主动交代了自己的罪行", "乙致人重伤后潜逃，在公安机关经侦查确认乙为该案的犯罪嫌疑人时，乙正因酒后驾驶被行政拘留，经公安机关讯问后，乙交代了自己的罪行", "丙多次挪用公款，其父母发现异常后，多次规劝其投案自首无效，直至单位发现款项异常开始查账后，丙才到公安机关交代自己的罪行", "丁因入室盗窃被判处有期徒刑，在服刑期间，丁主动向公安机关交代自己系公安机关久未破获的“7·26”走私案的主谋之一"], "answer": ["B"], "explain": "划关键词：①未被发觉，或虽被发觉但尚未受到讯问、未被采取强制措施；②主动直接向司法机关投案。逐项比对：A入户走访盘查、甲尚未被讯问或采取强制措施即主动交代，符合；B乙已被确认为犯罪嫌疑人且处于行政拘留（强制措施）期间、经讯问才交代，不满足①，不属于；C单位刚查账、丙尚未被讯问或采取强制措施即到公安交代，符合；D服刑期间主动交代未被发觉的余罪，符合。本题选非，当选B。", "method": "划关键词：①未被发觉，或虽被发觉但尚未受到讯问、未被采取强制措施；②主动直接向司", "tip": "定义题问“不属于”时找破坏关键要件的选项；“已被采取强制措施/已被讯问后才交代”是自动投案的排除情形。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 18 题", "year": "2025"}, {"type": "logic", "level": "中等", "id": "pd_000281", "stem": "中央预算：年度预算：地方预算", "options": ["历史题材：军事题材：现实题材", "户外广告：文字广告：电视广告", "知识创新：技术创新：管理创新", "人身权利：生命权利：财产权利"], "answer": ["A"], "explain": "先定一级关系：中央预算与地方预算并列，年度预算分别与二者交叉。二级辨析：A历史题材与现实题材并列，军事题材分别与二者交叉，一致，当选；B户外/文字/电视三者互相交叉，无并列；C知识/技术/管理创新三者并列，无交叉；D生命权利属于人身权利（种属），人身权利与财产权利并列，结构不同。故答案为A。", "method": "先定一级关系：中央预算与地方预算并列，年度预算分别与二者交叉。二级辨析：A历史题", "tip": "先看词性结构再定关系，二级辨析区分并列vs交叉vs种属；三词类比找“两个并列+一个交叉”的结构。", "kind": "real", "src": "2021年国家公务员录用考试《行测》题（地市级网友回忆版） 第 32 题", "year": "2021"}, {"type": "fig", "imgs": ["data/figs/figq_049_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "图中每个图形都是由3层图形组成。我们看前三个图，图一（最里面是第一层）第一层放到第三层就是图二，图二第一层放到第三层是图三，所以规律是上一个图形的第一层放到第二层是下一个图形。所以问号处的图形应该是第一层是菱形，第二层是三角形，第三层是梯形。只有C符合，所以答案选C。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_050_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图片应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "图中图形都是由一个正方形黑白阴影，白圆和黑圆组成。从黑白阴影来看，前4个图形阴影位置依次是右下左上，所以下一个图阴影应该在正方形的右面。从黑圆来看，前4个图形黑圆位置依次是左上右下左上右下，所以下一个图黑圆应该在正方形的左上角。从白圆来看，前4个图形白圆位置依次是左下左上右上右下，所以下一个图白圆应该在正方形的左下角。只有B符合，所以答案选B。", "trap": ""}]}, {"set": 24, "date": "2026-10-22", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 24 批）", "items": [{"type": "sci", "level": "中等", "stem": "透过一块纯绿色的玻璃窗观察白墙上写的纯红色大字，最有可能看到：", "options": ["绿墙无字", "绿墙黑字", "绿墙橙字", "黑墙无字"], "answer": ["B"], "explain": "思路：绿色玻璃只让绿光透过，吸收红光等其他色光；详解：白墙反射白光，其中绿光透过玻璃呈绿色墙面；红字只反射红光，红光被绿色玻璃吸收，没有光透过，字看起来就是黑色。故看到绿墙黑字。答案为B。", "method": "思路：绿色玻璃只让绿光透过，吸收红光等其他色光；详解：白墙反射白光，其中绿光透过玻璃呈绿色墙面；红字只反射红光，红光被绿色玻璃吸收，没有光透过，字看起来就是黑色。故看到绿墙黑字。答案为B。", "tip": "有色透明体只透过自身颜色的光；；被吸收的色光看起来变黑；；不透明物体颜色由它反射的色光决定。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第73题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "下图是动物养殖场自动喂水装置的简要示意图。当动物通过饮水口饮水后，水箱内的水位下降，水瓶中的水将自动流入水箱，使水位回到一定的高度。关于这一装置，下列说法正确的是：", "options": ["水瓶最终会处于真空状态", "水瓶内的气压始终等于水箱内的气压", "装置达到平衡时，水瓶内的气压高于大气压", "该装置是利用水瓶、水箱之间的气压差实现的"], "answer": ["D"], "explain": "思路：这是大气压支撑水柱的装置，类似倒置水杯；详解：水位下降瓶口露出时空气进入水瓶，在重力和气压差作用下水补入水箱，正是利用瓶内外气压差；A不会真空；B气压并不始终相等；C平衡时瓶内气压+水柱压=大气压，瓶内气压低于大气压。故答案为D。", "method": "思路：这是大气压支撑水柱的装置，类似倒置水杯；详解：水位下降瓶口露出时空气进入水瓶，在重力和气压差作用下水补入水箱，正是利用瓶内外气压差；A不会真空；B气压并不始终相等；C平衡时瓶内气压+水柱压=大气压，瓶内气压低于大气压。故答案为D。", "tip": "瓶内气压+水柱压强=外界大气压；；水位控制靠空气进入与气压差；；不要把瓶内气压判断成高于外界。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第77题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "小李驾驶卡丁车驶过一个半圆形弯道时，滑离了原定赛道，撞到了安全护栏。为了避免卡丁车转弯时滑离赛道，下列做法最可能有效的是：", "options": ["增加卡丁车的质量", "减少卡丁车的质量", "使用更加粗糙的轮胎", "减小半圆形弯道的半径"], "answer": ["C"], "explain": "思路：转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r；详解：质量m在两边约掉，增减质量无效；减小半径r会让临界速度更低、更易滑；换更粗糙轮胎增大μ，可提高临界速度。故答案为C。", "method": "思路：转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r；详解：质量m在两边约掉，增减质量无效；减小半径r会让临界速度更低、更易滑；换更粗糙轮胎增大μ，可提高临界速度。故答案为C。", "tip": "向心力问题中质量常被约掉，先写公式再判断；；增大摩擦系数、降低车速、增大弯道半径都更安全；；v临=√(μgr)，μ越大r越大越稳。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第69题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "援藏干部小吴发现，夏天在藏区的高山上能看到一条横在半山腰的线，这条线之上冰雪璀璨闪耀，线下则只有裸露岩坡或草丛树林。当地人告诉他，这就是“雪线”。如果气候稳定，雪线每年大致在同一个高度上，如果气候或降雪量发生变化，雪线就会发生变化。则小吴最不可能观察到的现象是", "options": ["气候变暖，降雪量增加，雪线上移", "气候变暖，降雪量减少，雪线上移", "气候变冷，降雪量减少，雪线下移", "气候变冷，降雪量增加，雪线上移"], "answer": ["D"], "explain": "思路：雪线是常年积雪的下界，气温升高消融增强会使雪线上移，气温降低消融减弱会使雪线下移；降雪量增加补给增多会使雪线下移，降雪量减少会使雪线上移；详解：D项气候变冷（消融减弱，雪线应下移）叠加降雪量增加（补给增多，雪线也应下移），两个因素都指向雪线下移，不可能出现雪线上移。故答案为D。", "method": "思路：雪线是常年积雪的下界，气温升高消融增强会使雪线上移，气温降低消融减弱会使雪线下移；降雪量增加补给增多会使雪线下移，降雪量减少会使雪线上移；详解：D项气候变冷（消融减弱，雪线应下移）叠加降雪量增加（补给增多，雪线也应下移），两个因素都指", "tip": "雪线=消融量与补给量平衡的高度，两个反向因素要分开判断；；气候变暖→雪线上移，气候变冷→雪线下移；；降雪增多→雪线下移，降雪减少→雪线上移。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第67题", "year": "2020"}, {"type": "math", "level": "中等", "stem": "92.46，84.42，76.38，68.34，（    ）", "options": ["50.25", "53.26", "55.17", "56.30"], "answer": ["A"], "explain": "思路：机械划分（小数数列）；详解：观察各项92=46×2，84=42×2，76=38×2，68=34×2，规律为整数部分=小数部分×2。验证选项：A 50=25×2满足；B 53≠26×2；C 55≠17×2；D 56≠30×2。故答案为A。", "method": "思路：机械划分（小数数列）；详解：观察各项92=46×2，84=42×2，76=38×2，68=34×2，规律为整数部分=小数部分×2。验证选项：A 50=25×2满足；B 53≠26×2；C 55≠17×2；D 56≠30×2。故答案为A", "tip": "小数数列优先机械划分，先看整数与小数部分的和差倍比；若分开等差无选项，立即转内部关系。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 1 题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "某线上店铺将进货单价为8元的商品按每件10元出售，每天可销售100件。该店铺计划提高售价增加利润，若每件商品售价每提高1元，每天销售量就要减少10件，为保证每天至少获利350元，问该商品售价应为多少？", "options": ["不到13元", "13~15元之间", "15~17元之间", "17元以上"], "answer": ["B"], "explain": "思路：代入法/二次函数。详解：设提价x元，每件利润=(10+x-8)=(2+x)元，销量=(100-10x)件，总利润y=(2+x)(100-10x)。要求y≥350。代入A：x=2（售价12元），y=4×80=320<350，排除；代入B：x=4（售价14元），y=6×60=360>350，满足。解不等式：(2+x)(100-10x)≥350，化简得x²-8x+15≤0，即(x-3)(x-5)≤0，得3≤x≤5，售价=10+x在13~15元之间。故答案为B。", "method": "思路：代入法/二次函数。详解：设提价x元，每件利润=(10+x-8)=(2+x)元，销量=(100-10x)件，总利润y=(2+x)(100-10x)。要求y≥350。代入A：x=2（售价12元），y=4×80=320<350，排除；代入B", "tip": "经济利润最值用二次函数；不等式解集是区间，边界要代入验证；选项为范围时用代入法最快。", "kind": "real", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 8 题", "year": "2024"}, {"type": "math", "level": "中等", "stem": "将甲、乙两种设备各5件全部分配给A、B、C三个车间，要求每个车间分配两种设备至少各1件，A车间分配的设备总数比其他任一车间都多，B车间分配的甲设备多于乙设备，问有多少种不同的分配方式？", "options": ["3", "6", "12", "24"], "answer": ["A"], "explain": "思路：枚举法。详解：设A、B、C各车间甲、乙件数均为正整数，甲共5件、乙共5件；约束为每车间甲乙各≥1、A车间总数多于B和C、B车间甲件数>乙件数。在这些严格约束下逐一枚举整数分配方案，符合全部条件的仅有3组。故答案为A。", "method": "思路：枚举法。详解：设A、B、C各车间甲、乙件数均为正整数，甲共5件、乙共5件；约束为每车间甲乙各≥1、A车间总数多于B和C、B车间甲件数>乙件数。在这些严格约束下逐一枚举整数分配方案，符合全部条件的仅有3组。故答案为A。", "tip": "分配/排列组合题约束多时优先枚举，不要套隔板公式；先把硬约束（每车间≥1、最多方、大小关系）列清再计数。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 4 题", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "某科研机构今年拟举办甲、乙、丙、丁、戊、己、庚、辛8次学术会议，其中第二季度（4—6月）的会议安排需满足以下条件：（1）4月只安排1次会议；（2）丙会议必须安排在5月；（3）甲会议要安排在乙会议之前（不一定在同一月），且甲、乙两次会议安排在连续的月份；（4）丁、戊两次会议安排在同一月；（5）己会议安排在庚会议之后（不一定在同一月）；（6）辛会议安排在戊会议之后（不一定在同一月）。\n如果第二季度只安排2次会议，且甲会议安排在4月，则以下两次会议中，安排在5月的是：", "options": ["甲", "乙", "庚", "丙"], "answer": ["D"], "explain": "先定硬约束：由（2）丙必须安排在5月；由（1）4月只安排1次，且甲已安排在4月，故4月只有甲；第二季度共2次会议，4月占1次，另1次由条件（2）锁定为丙在5月。乙虽按（3）应在甲之后连续月，但受“只安排2次”和丙在5月约束，乙无法排入。故5月安排的是丙。当选D。", "method": "先定硬约束：由（2）丙必须安排在5月；由（1）4月只安排1次，且甲已安排在4月，故4月只有甲；第二季度共2次会议，4月占1次，另1次由条件（2）锁定为丙在5月。乙虽按（3）应在甲之后连续月，但受“只安排2次”和丙在5月约束，乙无法排入。故5", "tip": "材料分析题先把“必须/只能”类硬约束圈出（丙必在5月、4月只1次），再用数量限制（只2次）排除其他可能。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 1 题", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "某研究者选取同一年级的两个班级进行教学实验，第一个班级的学生在听课过程中被鼓励随时提问，而第二个班级的学生没有受到同样的鼓励，结果显示，第一个班级学生的课堂专注度明显高于第二个班级。研究者据此建议在教学过程中学生应随时提问，以提升知识掌握效果。 如果以下选项为真，最能支持研究者建议的是（ ）。", "options": ["学生在课堂上随时主动提问能活跃课堂气氛", "课堂专注度是影响知识掌握效果的重要因素", "这两个班级的学生在实验前的学习成绩相当", "随时提问能帮助学生增强自我认同感和自信"], "answer": ["B"], "explain": "第一步：找出论点和论据。 论点：在教学过程中学生应随时提问，以提升知识掌握效果。 论据：第一个班级学生的课堂专注度明显高于第二个班级。 论据讨论的是 “随时提问的班级课堂专注度更高”，论点说的是“随时提问能提升知识掌握效果”，论点论据话题不一致，优先考虑搭桥，即建立“课堂专注度”和“知识掌握效果”的联系。 第二步：逐一分析选项。 A项：该项指出随时提问能活跃课堂气氛，而论点讨论的是知识掌握效果，话题不一致，无法加强，排除； B项：该项指出课堂专注度是影响知识掌握效果的重要因素，建立了“课堂专注度”和“知识掌握效果”的联系，为搭桥项，可以加强，当选； C项：该项指出两个班级实验前学习成绩相当，但论据讨论的是课堂专注度，话题不一致，无法加强，排除； D项：该项指出随时提问能增强自我认同感和自信，但自我认同感与知识掌握效果的关系不清楚，无法加强，排除。 ⇒ 正确答案为B。", "method": "第一步：找出论点和论据。 论点：在教学过程中学生应随时提问，以提升知识掌握效果。 论据：第一个班级学生的课堂专注度明显高于第二个班级。 论据讨论的是 “随时提问的班级课堂专注度更高”，论点说的是“随时提问能提升知识掌握效果”，论点论据话题不", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（网友回忆版） 第15 题", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "科研人员发现，鸟蛋颜色与温度有极大关联。研究结果显示，在日照强度较低的地方，深色鸟蛋更常见；而在阳光强度更高、更暖和的区域，鸟蛋颜色普遍更浅。研究小组认为，更深颜色的壳意味着可以吸收更多热量，从而在更寒冷的环境中具有生存优势。因为蛋中胚胎需要稳定的环境温度，但其自身却不具备温度调节能力。 以下各项如果为真，最能支持上述结论的是：", "options": ["将不同品种的鸡蛋放置在阳光中，颜色更深的鸡蛋比浅色鸡蛋升温更快，而且其蛋壳表面保持较高温度的时间更长", "大杜鹃将自己生的蛋寄宿在一百多种鸟的巢中，为了避免蛋被鸟巢主人赶跑，它们能够高仿出二十多种色型的鸟蛋", "要孵化出小鸟，适宜的温度十分重要，所以为了保证小鸟能顺利破壳，鸟妈妈只能待在窝里孵蛋，来提高蛋的温度", "蛇、乌龟的蛋大多埋在地下，有隐蔽性，所以是白色的，而鸟蛋暴露在环境中，则需要斑纹和颜色做障眼法迷惑天敌"], "answer": ["A"], "explain": "第一步：找出论点和论据。 论点：更深颜色的壳意味着可以吸收更多热量，从而在更寒冷的环境中具有生存优势。 论据：研究结果显示，在日照强度较低的地方，深色鸟蛋更常见；而在阳光强度更高、更暖和的区域，鸟蛋颜色普遍更浅。蛋中胚胎需要稳定的环境温度，但其自身却不具备温度调节能力。 本题的论点是蛋壳颜色与温度的关系，论据是在日照强度较低的地方深色鸟蛋更多，且蛋的胚胎不具备温度调节的能力，二者话题一致，优先考虑补充论据的方式加强，即举例子或解释原因。 第二步：逐一分析选项。 A项：举出鸡蛋在阳光中的例子，说明颜色更深的蛋壳可以吸收更多热量，举例加强，当选； B项：该项说的是大杜鹃鸟为了避免蛋被鸟巢主人赶跑而高仿出二十多种颜色的鸟蛋，但是没有说明鸟蛋颜色的深浅与温度之间的关系，属于无关项，无法加强，排除； C项：该项说的是为了保证小鸟顺利破壳，鸟妈妈只能待在窝里孵蛋，没有提及鸟蛋的颜色，属于无关项，无法加强，排除； D项：该项说的是鸟蛋需要颜色做障眼法迷惑天敌，但是没有说明鸟蛋颜色的深浅与温度之间的关系，属于无关项，无法加强，排除。 ⇒ 正确答案为A。", "method": "第一步：找出论点和论据。 论点：更深颜色的壳意味着可以吸收更多热量，从而在更寒冷的环境中具有生存优势。 论据：研究结果显示，在日照强度较低的地方，深色鸟蛋更常见；而在阳光强度更高、更暖和的区域，鸟蛋颜色普遍更浅。蛋中胚胎需要稳定的环境温度，", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。", "kind": "real", "src": "2020年陕西省公务员考试《行测》试题（网友回忆版） 第27 题", "year": "2020"}, {"type": "fig", "imgs": ["data/figs/figq_051_1.png", "data/figs/figq_051_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是:", "options": ["", "", "", ""], "answer": ["A"], "explain": "叠加把重复的去掉", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_052_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是？", "options": ["", "", "", ""], "answer": ["D"], "explain": "前3个图，图一加图二是图三，重复的地方不显示，留下不重复的部分，就是图三。后三个图也是一样的道理。图一加图二，重复的地方不显示，留下不重复的部分。图一图二两个阴影部分未重复，都留下来。图一图二六边形和六边形中的两条线都重复了，不显示。最后只剩下两个阴影组成的图形。只有选项D符合，所以答案选D。", "trap": ""}]}, {"set": 25, "date": "2026-10-22", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 25 批）", "items": [{"type": "sci", "level": "中等", "stem": "下列物质与其用途搭配正确的是（ ）。\n①臭氧——用作氧化剂\n②二氧化碳——用作干燥剂\n③氦气——用作燃料\n④液氮——用作制冷剂", "options": ["①④", "②③", "①②", "③④"], "answer": ["A"], "explain": "思路：逐项判断物质性质与用途是否匹配；详解：①臭氧具有强氧化性，可作氧化剂正确；②CO2不能干燥气体；③氦气化学性质稳定、不可燃，不能作燃料；④液氮汽化吸热，可作制冷剂正确。故①④组合。答案为A。", "method": "思路：逐项判断物质性质与用途是否匹配；详解：①臭氧具有强氧化性，可作氧化剂正确；②CO2不能干燥气体；③氦气化学性质稳定、不可燃，不能作燃料；④液氮汽化吸热，可作制冷剂正确。故①④组合。答案为A。", "tip": "干燥剂要选浓硫酸、碱石灰、氯化钙等能吸水的；；氦气、稀有气体稳定不燃，作保护气或填充气；；液氮干冰靠汽化升华吸热做制冷剂。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第70题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "有一种传统的制墨工艺：把冷碟子放在蜡烛火焰的上方，蜡烛燃烧一段时间后，冷碟子底部会有黑色物质生成，黑色物质经过进一步加工可以变成墨，则以下说法有误的是（ ）。", "options": ["所使用的蜡烛由该黑色物质和其他材料混合制成", "该黑色物质具有还原性", "冷碟子会影响蜡烛燃烧过程中氧气的补充，导致蜡烛不完全燃烧", "冷碟子能冷却底部的黑色物质，使其无法燃烧"], "answer": ["A"], "explain": "思路：冷碟压在火焰上方使氧气供应不足，蜡烛不完全燃烧析出炭黑；详解：A错误，蜡烛是石蜡制成，炭黑是燃烧产物不是原料；B炭黑（碳单质）具有还原性；C冷碟隔绝氧气造成不完全燃烧；D冷碟降温使生成的炭黑不能继续燃烧。故答案为A。", "method": "思路：冷碟压在火焰上方使氧气供应不足，蜡烛不完全燃烧析出炭黑；详解：A错误，蜡烛是石蜡制成，炭黑是燃烧产物不是原料；B炭黑（碳单质）具有还原性；C冷碟隔绝氧气造成不完全燃烧；D冷碟降温使生成的炭黑不能继续燃烧。故答案为A。", "tip": "含碳物质不完全燃烧生成炭黑（黑烟）；；碳单质具有可燃性和还原性；；蜡烛主要成分是石蜡烃类。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第65题", "year": "2024"}, {"type": "sci", "level": "中等", "stem": "夏日，小王调制了一杯28℃的蔗糖水，尝了一口后感觉不够甜，又加入了一些蔗糖，搅拌后蔗糖完全溶解。之后他把蔗糖水放入冰箱，一段时间后取出时发现杯子底部有少许晶体析出，则下列说法正确的有：\n①刚放入冰箱的蔗糖溶液一定不是饱和溶液\n②从冰箱中取出的蔗糖溶液一定是饱和溶液\n③放入冰箱前后，蔗糖溶液中溶质的质量相等\n④用加热蒸发溶剂的方法能够得到与析出晶体相同的物质", "options": ["①②", "①④", "②③", "②④"], "answer": ["D"], "explain": "思路：根据是否有未溶晶体判断饱和状态；详解：①刚放入时也可能恰好饱和，“一定不是”错误；②杯底有晶体析出，说明上层溶液一定饱和；③析出晶体使溶液中溶质减少，质量不相等；④析出的是蔗糖晶体，加热蒸发溶剂得到的也是蔗糖晶体。故②④正确。答案为D。", "method": "思路：根据是否有未溶晶体判断饱和状态；详解：①刚放入时也可能恰好饱和，“一定不是”错误；②杯底有晶体析出，说明上层溶液一定饱和；③析出晶体使溶液中溶质减少，质量不相等；④析出的是蔗糖晶体，加热蒸发溶剂得到的也是蔗糖晶体。故②④正确。答案为D", "tip": "有未溶固体=该温度下饱和溶液；；溶解度随温度降低而减小的物质，降温会析出晶体；；析出晶体与蒸发结晶得到同种溶质。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第83题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "下表为一些常见溶液的酸碱度，根据表中的信息，以下说法不恰当的是：", "options": ["草木灰水能改良酸性土壤", "食醋能中和皮蛋中的碱性物质", "肥皂水能中和蚂蚁叮咬皮肤时分泌的蚁酸", "胃酸过多的人适宜多喝苹果汁"], "answer": ["D"], "explain": "思路：酸碱中和，酸过多要补碱；详解：A草木灰碳酸钾呈碱性可中和酸性土壤；B醋酸可中和皮蛋碱性；C肥皂水碱性可中和蚁酸；D苹果汁呈酸性，胃酸过多者多喝会加重，不恰当。故答案为D。", "method": "思路：酸碱中和，酸过多要补碱；详解：A草木灰碳酸钾呈碱性可中和酸性土壤；B醋酸可中和皮蛋碱性；C肥皂水碱性可中和蚁酸；D苹果汁呈酸性，胃酸过多者多喝会加重，不恰当。故答案为D。", "tip": "胃酸过多宜吃碱性食物（苏打、面食）；；草木灰、肥皂水、苏打水均为碱性；；食醋、苹果汁、胃酸均为酸性。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（考生回忆版） 第66题", "year": "2025"}, {"type": "math", "level": "中等", "stem": "某部门7人分两组到甲、乙两市进行调研。已知到甲市人数超过一半，老张和小王均到乙市，问共有多少种不同的分组方式？", "options": ["10", "8", "6", "5"], "answer": ["C"], "explain": "思路：分类讨论加组合。详解：共7人，老张小王都在乙。甲市超一半即4或5人。①甲4乙3：余下5人中再选1人去乙（其余4人去甲），C(5,1)=5种；②甲5乙2：余下5人全去甲，老张小王在乙，仅1种。合计5+1=6种。故答案为C。", "method": "思路：分类讨论加组合。详解：共7人，老张小王都在乙。甲市超一半即4或5人。①甲4乙3：余下5人中再选1人去乙（其余4人去甲），C(5,1)=5种；②甲5乙2：余下5人全去甲，老张小王在乙，仅1种。合计5+1=6种。故答案为C。", "tip": "固定元素先安置（张王在乙），再分配剩余；'超过一半'要枚举上下限，别漏极端情况。", "kind": "real", "src": "2026年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 2 题", "year": "2026"}, {"type": "math", "level": "中等", "stem": "一块梯形场地如下图所示，已知OA=0.6OD，现在需要将这块场地拓展为一块长方形场地，问扩展后场地面积比原来至少增加：", "options": ["20%", "25%", "40%", "50%"], "answer": ["B"], "explain": "思路：赋值加相似三角形。详解：梯形ABCD两腰延长交于O，OA=0.6OD，即上方小三角形与大三角形相似比0.6。设大三角形OCD底边CD=b、高H，则小三角形OAB底边0.6b、高0.6H，梯形高h=H-0.6H=0.4H。梯形面积=(0.6b+b)/2×0.4H=0.32bH。最小长方形EFCD以CD为底、h为高：面积=b×0.4H=0.4bH。增加=(0.4-0.32)/0.32=0.25=25%。故答案为B。", "method": "思路：赋值加相似三角形。详解：梯形ABCD两腰延长交于O，OA=0.6OD，即上方小三角形与大三角形相似比0.6。设大三角形OCD底边CD=b、高H，则小三角形OAB底边0.6b、高0.6H，梯形高h=H-0.6H=0.4H。梯形面积=(0", "tip": "相似图形面积比=边长比平方；'至少增加'=补出最小长方形，缺角越少越好。", "kind": "real", "src": "2026年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 9 题", "year": "2026"}, {"type": "math", "level": "中等", "stem": "某单位计划在一块直角三角形的绿地周边栽种树木，先在3个顶点各栽种1棵，再从顶点开始每隔4米栽种1棵，如果两条直角边（包含顶点）分别栽种4棵和5棵，则该绿地周边一共栽种了（    ）棵树。", "options": ["12", "13", "14", "15"], "answer": ["A"], "explain": "思路：植树问题+勾股定理；详解：直角边1含顶点4棵→段数=3→边长=3×4=12米；直角边2含顶点5棵→段数=4→边长=4×4=16米；斜边=√(12²+16²)=20米；斜边两端是顶点已种树，中间不植，棵数=20÷4-1=4棵；两条直角边共4+5=9棵，但直角顶点被两边重复计算1次，故直角边贡献9-1=8棵，加斜边4棵=12棵。故答案为A。", "method": "思路：植树问题+勾股定理；详解：直角边1含顶点4棵→段数=3→边长=3×4=12米；直角边2含顶点5棵→段数=4→边长=4×4=16米；斜边=√(12²+16²)=20米；斜边两端是顶点已种树，中间不植，棵数=20÷4-1=4棵；两条直角边", "tip": "封闭/半封闭植树：三角形周边种树，三个顶点各算1次后要避免重复；直角边两端植树（含顶点）段数=棵数-1；斜边两端不植树，棵数=总长÷间隔-1；勾股数12-16-20要敏感。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（网友回忆版） 第 7 题", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "所有单纯依靠运气成分获胜的都不能成为电竞游戏，所有虚拟环境中的智力和体力的对抗都是电竞游戏。所以，所有虚拟环境中的智力和体力的对抗都不是无规则的竞技。 上述论证的成立需要补充以下哪项作为前提：", "options": ["所有电竞游戏都是无规则的竞技", "有些虚拟环境中的智力和体力的对抗是单纯依靠运气成分获胜的", "有些无规则的竞技是虚拟环境中的智力和体力的对抗", "所有无规则的竞技都是单纯依靠运气成分获胜的"], "answer": ["D"], "explain": "第一步：找出论点和论据。论点：虚拟环境中的智力和体力的对抗无规则的竞技。论据：单纯依靠运气成分获胜电竞游戏；虚拟环境中的智力和体力的对抗电竞游戏。根据逆否规则可将论据串联为：虚拟环境中的智力和体力的对抗电竞游戏单纯依靠运气成分获胜。本题要想得出“虚拟环境中的智力和体力的对抗无规则的竞技”的结论，需要在“电竞游戏”与“无规则的竞技”之间建立联系，或者在“单纯依靠运气成分获胜”与“无规则的竞技”之间建立联系。第二步：逐一分析选项。A项：翻译为：电竞游戏无规则的竞技，与论据结合可以推出“虚拟环境中的智力和体力的对抗无规则的竞技”，无法推出论点，排除；B项：翻译为：有的虚拟环境中的智力和体力的对抗单纯依靠运气成分获胜，与论据结合无法推出论点，排除；C项：翻译为：有的无规则的竞技虚拟环境中的智力和体力的对抗，通过置换可以推出“有的虚拟环境中的智力和体力的对抗无规则的竞技”，与论点矛盾，排除；D项：翻译为：无规则的竞技单纯依靠运气成分获胜，根据逆否可以得出“单纯依靠运气成分获胜无规则的竞技”，与论据结合可以推出“虚拟环境中的智力和体力的对抗无规则的竞技”，即论点成立，为搭桥项，当选。⇒ 正确答案为D。", "method": "第一步：找出论点和论据。论点：虚拟环境中的智力和体力的对抗无规则的竞技。论据：单纯依靠运气成分获胜电竞游戏；虚拟环境中的智力和体力的对抗电竞游戏。根据逆否规则可将论据串联为：虚拟环境中的智力和体力的对抗电竞游戏单纯依靠运气成分获胜。本题要想", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。", "kind": "real", "src": "2024年黑龙江省公务员录用考试《行测》题（网友回忆版） 第31 题", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "联合国气象组织发布报告说，受厄尔尼诺影响，2016年是有记录以来最热年份，2017年超过2015年成为最热的非厄尔尼诺年。长期气温趋势远比单个年份的气温排名重要，而长期趋势是上升的。虽然某些地区平均气温降低，但全球总体气温是快速上升的。报告据此得出结论，地球气温自2010年以来，呈现出加速上升的趋势。 以下哪项如果为真，最能支持上述结论？", "options": ["2015年、2016年和2017年是有记录以来三个最热年份", "2017年全球平均气温比工业革命前的水平高1.1摄氏度", "有系统记录以来的五个最温暖年份都出现在2010年之后", "联合国气象组织的结论与其他五家主要国际气象机构一致"], "answer": ["C"], "explain": "第一步：找出论点和论据。 论点：地球气温自2010年以来，呈现出加速上升的趋势。 论据：联合国气象组织发布报告说，受厄尔尼诺影响，2016年是有记录以来最热年份，2017年超过2015年成为最热的非厄尔尼诺年。长期气温趋势远比单个年份的气温排名重要，而长期趋势是上升的。虽然某些地区平均气温降低，但全球总体气温是快速上升的。 论点和论据讲的都是地球气温加速上升的事，因此话题一致，可以考虑补充论据进行加强。 第二步：逐一分析选项。 A项：2015年、2016年和2017年是有记录以来三个最热年份，可知15年、16年、17年这三年地球气温比起之前是上升的，说明自2010年以来存在气温不断上升的三年，补充论据可以加强，保留； B项：2017年全球平均气温比工业革命前的水平高，只能说明17年的气温变高了，并不能说明自2010年以来地球气温是否是加速上升的趋势，无法加强，排除； C项：五个最温暖年份都出现在2010年之后，说明自2010年以来存在气温不断上升的五年，可以说明，地球气温自2010年以后存在上升的趋势，补充论据可以加强，保留； D项：与其他气象组织的结论一致，说明论据可靠，可以加强论据，但力度不及A、C两项，排除； 对比A、C两项，其中C项说的是5年情况，比A项的3年情况范围更广，加强力度更强，因此，优选C项。 ⇒ 正确答案为C。", "method": "第一步：找出论点和论据。 论点：地球气温自2010年以来，呈现出加速上升的趋势。 论据：联合国气象组织发布报告说，受厄尔尼诺影响，2016年是有记录以来最热年份，2017年超过2015年成为最热的非厄尔尼诺年。长期气温趋势远比单个年份的气温", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。", "kind": "real", "src": "2018年湖北省选调生招录考试综合知识和行政职业能力测验试卷（网友回忆版） 第15 题", "year": "2018"}, {"type": "logic", "level": "中等", "stem": "架构创新是指组成产品的基本元件不变，但是整体结构布局改变，即将相同元件进行整体结构的重新调整，进而产生新功能的创新。\n根据上述定义，下列属于架构创新的是：", "options": ["陶瓷底板电熨斗与传统不锈钢底板电熨斗相比，其底板的耐磨性更强，具有更高的光滑度，使用起来更顺畅", "某款手机聊天软件增加了拜年红包功能，用户可以在给亲朋好友发送红包时，编辑拜年吉祥语、自定义红包图片，满足个性化需求", "可拆卸手柄锅将原手柄设计成可从锅具上拆卸下来，并提供多个手柄可安装在锅具边缘的任意位置上，满足烹饪需要", "某板材厂改良制作工艺，将原来的轧制工序分成两步进行，同时增加砂光工序，生产出满足市场需要的薄板"], "answer": ["C"], "explain": "划关键词：①基本元件不变；②重新调整相同元件整体结构布局；③产生新功能。逐项：A陶瓷底板vs不锈钢底板基本元件不同；B新增拜年红包功能是新开发不是结构调整；C锅和手柄基本元件不变，手柄可拆可装多个位置=整体结构布局重新调整，产生炒/煮/蒸等新功能，全满足；D轧制工序分两步+增加砂光=制作工艺改变不是产品结构调整。故C。", "method": "划关键词：①基本元件不变；②重新调整相同元件整体结构布局；③产生新功能。逐项：A陶瓷底板vs不锈钢底板基本元件不同；B新增拜年红包功能是新开发不是结构调整；C锅和手柄基本元件不变，手柄可拆可装多个位置=整体结构布局重新调整，产生炒/煮/蒸等", "tip": "架构创新=元件不变只改布局；发明创新=元件变了/全新功能；工艺创新=生产工序变。先划关键要件，选项必须全部满足才算符合。", "kind": "real", "src": "2023年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 17 题", "year": "2023"}, {"type": "fig", "imgs": ["data/figs/figq_053_1.png"], "src": "", "cat": "", "fmt": "", "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "三个图上都有＋号，×号，黑圆，白圆但是位置不相同。先来看＋号的位置，图一到图二＋号顺时针走了3个格，图二到图三顺时针＋号走了4个格，所以图四应该是在图三的基础上顺时针走5个格。再来看×号的位置，图一到图二×顺时针走了1个格，图二到图三×顺时针走了1个格，所以图四应该是在图三的基础上顺时针走1个格。看黑圆的位置，图一到图二顺时针走了6个格，图二到图三顺时针走了5个格，所以图四应该是在图三的基础上顺时针走了4个格。看白圆的位置，图一到图二顺时针走了2个格，图二到图三顺时针走了2个格，所以图四应该是在图三的基础上顺时针走2个格。只有选项A符合，所以选A。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_054_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "黑+白=白黑+黑=黑白+白=黑", "trap": ""}]}, {"set": 26, "date": "2026-10-23", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 26 批）", "items": [{"type": "sci", "level": "中等", "stem": "农技站为了贮存种子，拟采用以下做法，其中最可行的是", "options": ["将种子浸泡在含水的容器中", "将种子置放在含氧量低于1%的干燥地窖中", "将种子置于15摄氏度左右的低温环境中", "将种子封闭在完全避光的黑暗环境中"], "answer": ["B"], "explain": "思路：种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度；详解：A浸泡在水中会让种子萌发甚至霉烂；C仅15℃远达不到储存要求；D避光并非关键；B干燥地窖既控制水分又把含氧量压到1%以下，呼吸作用被显著抑制，最可行。故答案为B。", "method": "思路：种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度；详解：A浸泡在水中会让种子萌发甚至霉烂；C仅15℃远达不到储存要求；D避光并非关键；B干燥地窖既控制水分又把含氧量压到1%以下，呼吸作用被显著抑制，最可行。故答案为B。", "tip": "易错点：误选C，以为15℃低温就够了；种子储存的关键是抑制呼吸作用，需同时满足干燥、低氧、低温三条件。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第66题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "无性繁殖是一种不涉及生殖细胞，不需要经过受精过程，由母体的一部分直接形成新个体的繁殖方式。以下繁殖过程不属于无性繁殖的是：", "options": ["西瓜的花被授粉后结出了果实", "一个草履虫经过细胞分裂变成两个", "水螅母体的体壁上形成与母体相似的芽体", "马铃薯的块茎发芽生长后，形成新的个体"], "answer": ["A"], "explain": "思路：判断关键是否经过受精作用；详解：A西瓜花授粉即精子与卵细胞结合，经过受精，属有性繁殖；B分裂生殖、C出芽生殖、D营养繁殖都没有受精，属无性繁殖。故答案为A。", "method": "思路：判断关键是否经过受精作用；详解：A西瓜花授粉即精子与卵细胞结合，经过受精，属有性繁殖；B分裂生殖、C出芽生殖、D营养繁殖都没有受精，属无性繁殖。故答案为A。", "tip": "易错点：分不清有性与无性；经过两性生殖细胞结合（受精）的就是有性繁殖。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第82题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "有一种传统的制墨工艺：把冷碟子放在蜡烛火焰的上方，蜡烛燃烧一段时间后，冷碟子底部会有黑色物质生成，黑色物质经过进一步加工可以变成墨，则以下说法有误的是（ ）。", "options": ["所使用的蜡烛由该黑色物质和其他材料混合制成", "该黑色物质具有还原性", "冷碟子会影响蜡烛燃烧过程中氧气的补充，导致蜡烛不完全燃烧", "冷碟子能冷却底部的黑色物质，使其无法燃烧"], "answer": ["A"], "explain": "思路：冷碟压在火焰上方使氧气供应不足，蜡烛不完全燃烧析出炭黑；详解：A错误，蜡烛是石蜡制成，炭黑是燃烧产物不是原料；B炭黑（碳单质）具有还原性；C冷碟隔绝氧气造成不完全燃烧；D冷碟降温使生成的炭黑不能继续燃烧。故答案为A。", "method": "思路：冷碟压在火焰上方使氧气供应不足，蜡烛不完全燃烧析出炭黑；详解：A错误，蜡烛是石蜡制成，炭黑是燃烧产物不是原料；B炭黑（碳单质）具有还原性；C冷碟隔绝氧气造成不完全燃烧；D冷碟降温使生成的炭黑不能继续燃烧。故答案为A。", "tip": "易错点：以为黑色烟灰本来就是蜡烛成分；黑色物质是蜡烛不完全燃烧生成的炭黑，不是蜡烛里预先混好的。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第65题", "year": "2024"}, {"type": "sci", "level": "中等", "stem": "水平地面上有甲、乙两块由不同材质构成、质地分布均匀的长方体金属块。已知甲的体积>乙的体积，甲的底面积<乙的底面积，甲的质量>乙的质量。则以下判断一定正确的有： ①甲的高度>乙的高度 ②甲的高度<乙的高度 ③甲的密度>乙的密度 ④甲的密度<乙的密度", "options": ["①", "③", "①③", "②④"], "answer": ["A"], "explain": "思路：长方体V=S·h，密度ρ=m/V；详解：高度h=V/S，甲V更大、S更小，则h甲必大于h乙，①正确②错误；密度ρ=m/V，甲m更大但V也更大，两因素方向相反，密度大小无法确定，③④都不一定成立。故答案为A。", "method": "思路：长方体V=S·h，密度ρ=m/V；详解：高度h=V/S，甲V更大、S更小，则h甲必大于h乙，①正确②错误；密度ρ=m/V，甲m更大但V也更大，两因素方向相反，密度大小无法确定，③④都不一定成立。故答案为A。", "tip": "易错点：把“甲质量大”直接推成“甲密度大”；密度ρ=m/V，质量大且体积也大时无法确定密度大小。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第67题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "父子两人在百米赛道上匀速跑步，两人从赛道起点同时出发，父亲跑到终点时，儿子距离终点还有40米，若父亲立即折返跑向赛道起点，则两人相遇时，儿子距离终点还有（ ）米。", "options": ["35", "30", "25", "15"], "answer": ["C"], "explain": "思路：比例法（时间相同路程比=速度比）；详解：父到终点跑100米时子跑60米，速度比v父:v子=100:60=5:3；父折返后两人相向而行，相距40米（子距终点40米），相遇时两人共跑40米，按5:3分配，父亲跑40×5/8=25米；即相遇点距终点25米。故答案为C。", "method": "思路：比例法（时间相同路程比=速度比）；详解：父到终点跑100米时子跑60米，速度比v父:v子=100:60=5:3；父折返后两人相向而行，相距40米（子距终点40米），相遇时两人共跑40米，按5:3分配，父亲跑40×5/8=25米；即相遇点距终点25米。故答案为C。", "tip": "易错点：容易算成父亲折返后相遇时儿子又跑了多少米，但忽略速度比；记忆要点：父跑100米时子跑60米，速度比父:子=5:3。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（网友回忆版） 第 5 题", "year": "2025"}, {"type": "math", "level": "中等", "stem": "小王经营一家鲜花网店，每位顾客均随机获赠一个装有一支康乃馨、玫瑰花或百合花的盲盒，3种盲盒的成本分别为3元、5元、8元。某日该鲜花网店共有顾客24人，赠送盲盒的总成本为127元，则获赠玫瑰花盲盒的顾客最多有：", "options": ["19人", "20人", "21人", "22人"], "answer": ["B"], "explain": "思路：不定方程+倍数特性；详解：设康乃馨x、玫瑰y、百合z，则x+y+z=24，3x+5y+8z=127。第一式×3减第二式得2y+5z=55。5z和55都是5的倍数，故2y是5的倍数，y为5的倍数。选项中只有20是5的倍数。故答案为B。", "method": "思路：不定方程+倍数特性；详解：设康乃馨x、玫瑰y、百合z，则x+y+z=24，3x+5y+8z=127。第一式×3减第二式得2y+5z=55。5z和55都是5的倍数，故2y是5的倍数，y为5的倍数。选项中只有20是5的倍数。故答案为B。", "tip": "易错点：不列方程直接猜；陷阱是消元后用倍数特性。", "kind": "real", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 10 题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "某科技创新项目有6人投资，共筹资110万元。投资额度有10万元、20万元和30万元三种。已知投资10万元的比投资20万元的多2人，问投资30万元的有多少人？", "options": ["2", "3", "4", "5"], "answer": ["A"], "explain": "思路：方程法。详解：设投资20万的x人，则10万的(x+2)人，30万的y人。人数方程：(x+2)+x+y=6，即2x+y=4；钱数方程：10(x+2)+20x+30y=110，化简得30x+30y=90，即x+y=3。联立两式解得x=1，y=2。故投资30万的有2人。故答案为A。", "method": "思路：方程法。详解：设投资20万的x人，则10万的(x+2)人，30万的y人。人数方程：(x+2)+x+y=6，即2x+y=4；钱数方程：10(x+2)+20x+30y=110，化简得30x+30y=90，即x+y=3。联立两式解得x=1，y=2。故投资30万的有2人。故答案为A。", "tip": "易错点：设元混乱，把投资10万的人数设错；或列方程漏钱数。", "kind": "real", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 3 题", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "在s市国际马拉松赛男子专业组的比赛中，最后5公里跑在第一集团的莫科塔、泽雷亚、斯蒂芬三人中，一个是肯尼亚选手，一个是南非选手，一个是厄立特里亚选手。比赛结束后得知： 1、泽雷亚的成绩比肯尼亚选手的成绩好。 2、厄立特里亚选手的成绩比莫科塔的成绩差。 3、斯蒂芬称赞厄立特里亚选手发挥比自己出色。 根据上述信息，以下 项肯定为真。", "options": ["莫科塔、泽雷亚、斯蒂芬依次为肯尼亚选手、厄立特里亚选手和南非选手", "肯尼亚选手是冠军，南非选手是亚军，厄立特里亚选手是第三名", "莫科塔、泽雷亚、斯蒂芬依次为南非选手、厄立特里亚选手和肯尼亚选手", "南非选手是冠军，肯尼亚选手是亚军，厄立特里亚选手是第三名"], "answer": ["C"], "explain": "第一步：分析题干条件。（1）泽雷亚的成绩比肯尼亚选手的成绩好；（2）厄立特里亚选手的成绩比莫科塔的成绩差；（3）斯蒂芬称赞厄立特里亚选手发挥比自己出色。第二步：根据题干条件进行推理。题干条件中“厄立特里亚”被提及的次数最多，考虑优先从此处开始推理。根据条件（2）（3）可得厄立特里亚选手不是莫科塔、斯蒂芬，只能是泽雷亚。根据条件（1）（2）可得莫科塔>泽雷亚>肯尼亚选手，因此肯尼亚选手只能是斯蒂芬，那么南非选手就是莫科塔。具体情况如下表所示：⇒ 正确答案为C。", "method": "第一步：分析题干条件。（1）泽雷亚的成绩比肯尼亚选手的成绩好；（2）厄立特里亚选手的成绩比莫科塔的成绩差；（3）斯蒂芬称赞厄立特里亚选手发挥比自己出色。第二步：根据题干条件进行推理。题干条件中“厄立特里亚”被提及的次数最多，考虑优先从此处开始推理。根据条件（2）（3）可得厄立特里亚选手不是莫科塔、斯蒂芬，只能是泽雷亚。根据条件（1）（2）可得莫科塔>泽雷亚>肯尼亚选手，因此肯尼亚选手只能是斯蒂芬，那么南非选手就是莫科塔。具体情况如下表所示：⇒ 正确答案为C。", "tip": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "kind": "real", "src": "2016年上海市行政执法类考试《行测》试题（网友回忆版） 第26 题", "year": "2016"}, {"type": "logic", "level": "中等", "stem": "由于人类建设活动的破坏和干扰，生物群体原来连续成片的生活环境被割裂，形成分散的岛状甚至碎片状的生境，生境廊道是指连接破碎化生境并适宜生物生活、移动或扩散的通道，便于实现物种基因、能量、物质的流动。 根据上述定义，下列不属于生境廊道的是：", "options": ["国家公园内，两棵参天古树跨过公路上方枝叶相连，金丝猴借助古树跨越公路。不同区域的金丝猴群可以保持接触", "为了让野生象群在两个自然保护区之间迁移，管理者设计建成了迁移通道，避开村寨，并保证该区域范围内有丰富的水和食物资源", "某地将过去严重污染的河道改造为河滨公园，架设了多座拱桥，美化了环境，方便了交通，还吸引了大量鸟类来此栖息", "为避免青藏铁路隔断藏羚羊迁徙路线，动物学家设计了桥梁下方、隧道上方及路基缓坡3种形式的野生动物通路"], "answer": ["C"], "explain": "划关键词逐项比对：要件①连接破碎化生境②是适宜生物移动扩散的通道③实现基因能量物质流动。A金丝猴借相连古树跨公路、B象群保护区间迁移通道、D藏羚羊铁路野生动物通路都连接了被割裂的生境；C污染河道改河滨公园，只是鸟类栖息地，未体现连接两块破碎生境，不满足①。选C。", "method": "划关键词逐项比对：要件①连接破碎化生境②是适宜生物移动扩散的通道③实现基因能量物质流动。A金丝猴借相连古树跨公路、B象群保护区间迁移通道、D藏羚羊铁路野生动物通路都连接了被割裂的生境；C污染河道改河滨公园，只是鸟类栖息地，未体现连接两块破碎生境，不满足①。选C。", "tip": "易错点：把“河滨公园吸引鸟类栖息”当生境廊道；关键是“连接破碎化生境的通道”，河滨公园只是栖息地未连接破碎生境。", "kind": "real", "src": "2022年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 22 题", "year": "2022"}, {"type": "logic", "level": "中等", "stem": "当前，银行面临着这样一个问题，就是对于那些在贷款后不能及时还贷的客户，银行除了不断通过各种形式催款别无他法。因此许多银行都向不能及时还贷的客户收取滞纳金。但有关调查表明，收取滞纳金后不能及时还贷的客户数量不但未减少，反而增加了。 以下哪项如果为真，最能解释上述调查结果？", "options": ["收取滞纳金后，更多的客户认为即使不及时还贷也不必内疚，只要支付滞纳金就行", "有个别客户对收取滞纳金的行为不满，有时会故意不及时还贷来抗议", "有些客户因为生活压力大，常常不能及时还贷", "收取滞纳金的金额太低，对原本经常不及时还贷的客户没有太大的压力"], "answer": ["A"], "explain": "第一步:找出题干的矛盾之处。 题干的矛盾之处在于银行向不能及时还贷的客户收取滞纳金，但收取滞纳金后不能及时还贷的客户数量不但未减少，反而增加了。 第二步:逐一分析选项。 A项:收取滞纳金后，客户认为不必内疚，所以更多的客户可能不及时还贷，可以解释，当选; B项:个别客户的不满并不能解释为何不能及时还贷的客户数量增加了，不能解释，排除; C项:有些客户不能及时还款，是一个长期性的行为，并不能解释这次收取滞纳金为何使得不能及时还贷的客户数量增加了，不能解释，排除; D项:对原本经常不能还贷的客户的影响，并不能解释为何不能及时还贷的客户数量增加了，不能解释，排除。 ⇒ 正确答案为A。", "method": "第一步:找出题干的矛盾之处。 题干的矛盾之处在于银行向不能及时还贷的客户收取滞纳金，但收取滞纳金后不能及时还贷的客户数量不但未减少，反而增加了。 第二步:逐一分析选项。 A项:收取滞纳金后，客户认为不必内疚，所以更多的客户可能不及时还贷，可以解释，当选; B项:个别客户的不满并不能解释为何不能及时还贷的客户数量增加了，不能解释，排除; C项:有些客户不能及时还款，是一个长期性的行为，并不能解释这次收取滞纳金为何使得不能及时还贷的客户数量增加了，不能解释，排除; D项:对原本经常不能还贷的客户的影响，并不能解释为何不能及时还贷的客户数量增加了，不能解释，排除。 ⇒ 正确答案为A。", "tip": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "kind": "real", "src": "2019年青海省法院、检察院录用考试《行测》题 第28 题", "year": "2019"}, {"type": "fig", "imgs": ["data/figs/figq_055_1.png"], "src": "", "cat": "", "fmt": "", "stem": "找出下列图形中不同于其他图形的一项:", "options": ["", "", ""], "answer": ["A"], "explain": "（题源未附解析，可对照答案自行归纳规律）", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_056_1.png", "data/figs/figq_056_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应当是：", "options": ["", "", ""], "answer": ["A"], "explain": "（题源未附解析，可对照答案自行归纳规律）", "trap": ""}]}, {"set": 27, "date": "2026-10-23", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 27 批）", "items": [{"type": "sci", "level": "中等", "stem": "在日常生活中，人们总是难以避免与细菌接触，以下有关细菌的说法错误的是：", "options": ["我国甲类传染病中的鼠疫是由细菌引发的", "有的细菌可用于食品生产、废水处理或生物分解", "细菌是微生物也是细胞，可以自行分裂繁殖", "杀灭细菌，只能依靠人体自身免疫力"], "answer": ["D"], "explain": "思路：结合细菌的结构、作用和抑菌杀菌手段判断；详解：A鼠疫由鼠疫杆菌引起正确；B利用乳酸菌、腐生菌等可用于食品和污水处理；C细菌是单细胞微生物，分裂生殖；D杀灭细菌还可用抗生素、消毒剂等，“只能靠免疫力”错误。故答案为D。", "method": "思路：结合细菌的结构、作用和抑菌杀菌手段判断；详解：A鼠疫由鼠疫杆菌引起正确；B利用乳酸菌、腐生菌等可用于食品和污水处理；C细菌是单细胞微生物，分裂生殖；D杀灭细菌还可用抗生素、消毒剂等，“只能靠免疫力”错误。故答案为D。", "tip": "易错点：把免疫力当成唯一杀菌手段；抗生素、消毒、杀菌药剂都能杀灭细菌。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（考生回忆版） 第70题", "year": "2025"}, {"type": "sci", "level": "中等", "stem": "小张观察发现，自家房屋的北面在夏天能够被阳光照射，而在冬天，房屋的南面可以被阳光照射。则他家最有可能位于以下城市中的：", "options": ["海口", "武汉", "上海", "北京"], "answer": ["A"], "explain": "思路：北回归线以北全年正午太阳都在南方，房屋南面采光；只有在北回归线以南，太阳直射点移到北面时北面才会被晒到；详解：海口约20°N在北回归线以南，武汉、上海、北京均在北回归线以北。故答案为A。", "method": "思路：北回归线以北全年正午太阳都在南方，房屋南面采光；只有在北回归线以南，太阳直射点移到北面时北面才会被晒到；详解：海口约20°N在北回归线以南，武汉、上海、北京均在北回归线以北。故答案为A。", "tip": "易错点：凭直觉选大城市；关键是“北面夏天有阳光”说明正午太阳位于房屋北侧，即该地在北回归线以南。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第70题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "胰岛素是一种蛋白质，可以用于治疗糖尿病。以下有关胰岛素的说法，正确的是（ ）。", "options": ["胰岛素能够抑制血糖分解", "人体中的胰岛素由肝脏分泌", "一般通过口服胰岛素治疗糖尿病", "血液中的胰岛素浓度过高会导致低血糖"], "answer": ["D"], "explain": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "method": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "tip": "易错点：以为胰岛素口服有效；胰岛素是蛋白质，口服会被消化道分解失效，只能注射；它由胰岛分泌而非肝脏。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "year": "2024"}, {"type": "sci", "level": "中等", "stem": "夏日，小王调制了一杯28℃的蔗糖水，尝了一口后感觉不够甜，又加入了一些蔗糖，搅拌后蔗糖完全溶解。之后他把蔗糖水放入冰箱，一段时间后取出时发现杯子底部有少许晶体析出，则下列说法正确的有： ①刚放入冰箱的蔗糖溶液一定不是饱和溶液 ②从冰箱中取出的蔗糖溶液一定是饱和溶液 ③放入冰箱前后，蔗糖溶液中溶质的质量相等 ④用加热蒸发溶剂的方法能够得到与析出晶体相同的物质", "options": ["①②", "①④", "②③", "②④"], "answer": ["D"], "explain": "思路：根据是否有未溶晶体判断饱和状态；详解：①刚放入时也可能恰好饱和，“一定不是”错误；②杯底有晶体析出，说明上层溶液一定饱和；③析出晶体使溶液中溶质减少，质量不相等；④析出的是蔗糖晶体，加热蒸发溶剂得到的也是蔗糖晶体。故②④正确。答案为D。", "method": "思路：根据是否有未溶晶体判断饱和状态；详解：①刚放入时也可能恰好饱和，“一定不是”错误；②杯底有晶体析出，说明上层溶液一定饱和；③析出晶体使溶液中溶质减少，质量不相等；④析出的是蔗糖晶体，加热蒸发溶剂得到的也是蔗糖晶体。故②④正确。答案为D。", "tip": "易错点：以为刚溶解完就一定不饱和，或以为降温后溶质不变；蔗糖溶解度随温度降低而减小，降温析出晶体后溶液才饱和。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第83题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "档案室需要整理300份档案，要求每天整理的档案数量相同，且规定了完成的期限。如果要提前一天完成，那么每天需要多整理10份档案。则规定的期限为（ ）天。", "options": ["6", "7", "8", "9"], "answer": ["A"], "explain": "思路：代入排除/方程。详解：设规定期限为x天，原每天整理300/x份，提前1天则每天整理300/(x-1)份，列方程 300/(x-1)-300/x=10，化简得x(x-1)=30，解得x=6。验证：原每天50份，提前1天用5天每天60份，正好多10份。故答案为A。", "method": "思路：代入排除/方程。详解：设规定期限为x天，原每天整理300/x份，提前1天则每天整理300/(x-1)份，列方程 300/(x-1)-300/x=10，化简得x(x-1)=30，解得x=6。验证：原每天50份，提前1天用5天每天60份，正好多10份。故答案为A。", "tip": "易错点：把“提前一天”理解成总共只多整理10份；实际是每天多10份，天数减少1天。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第 5 题", "year": "2024"}, {"type": "math", "level": "中等", "stem": "小李开车从甲市到乙市，需要走一段高速公路和一段国道。已知在高速公路上汽车油耗为0.05升/公里，在国道上油耗比在高速公路上多0.03升/公里。小李在高速公路上行驶了200公里，是在国道上行驶路程的4倍，则从甲市到乙市，小李汽车的油耗为（ ）升。", "options": ["15", "14", "12", "10"], "answer": ["B"], "explain": "思路：分路段油耗相加。详解：国道路程=200÷4=50公里；国道油耗=0.05+0.03=0.08升/公里。总油耗=高速200×0.05＋国道50×0.08=10+4=14升。故答案为B（14）。", "method": "思路：分路段油耗相加。详解：国道路程=200÷4=50公里；国道油耗=0.05+0.03=0.08升/公里。总油耗=高速200×0.05＋国道50×0.08=10+4=14升。故答案为B（14）。", "tip": "易错点：求出国道路程=200÷4=50公里后，忘记国道油耗是0.05+0.03=0.08升/公里，直接按0.05算；或把“是国道4倍”的倍数关系弄反。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 2 题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "某家政公司承诺以低于市场价20％的价格为小区业主提供服务。如果有业主向该公司支付了服务费4000元，则与市场价相比优惠了（ ）元。", "options": ["400", "600", "800", "1000"], "answer": ["D"], "explain": "思路：折扣方程。详解：设市场价为x元，低于市场价20%即实付为原价的80%，列方程(1-20%)x=4000，解得x=5000元。优惠金额=5000-4000=1000元。故答案为D。", "method": "思路：折扣方程。详解：设市场价为x元，低于市场价20%即实付为原价的80%，列方程(1-20%)x=4000，解得x=5000元。优惠金额=5000-4000=1000元。故答案为D。", "tip": "易错点：直接拿4000×20%=800当优惠，错把实付价当原价；优惠是原价的20%，不是实付的20%。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第 6 题", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "科研人员发现，鸟蛋颜色与温度有极大关联。研究结果显示，在日照强度较低的地方，深色鸟蛋更常见；而在阳光强度更高、更暖和的区域，鸟蛋颜色普遍更浅。研究小组认为，更深颜色的壳意味着可以吸收更多热量，从而在更寒冷的环境中具有生存优势。因为蛋中胚胎需要稳定的环境温度，但其自身却不具备温度调节能力。 以下各项如果为真，最能支持上述结论的是：", "options": ["将不同品种的鸡蛋放置在阳光中，颜色更深的鸡蛋比浅色鸡蛋升温更快，而且其蛋壳表面保持较高温度的时间更长", "大杜鹃将自己生的蛋寄宿在一百多种鸟的巢中，为了避免蛋被鸟巢主人赶跑，它们能够高仿出二十多种色型的鸟蛋", "要孵化出小鸟，适宜的温度十分重要，所以为了保证小鸟能顺利破壳，鸟妈妈只能待在窝里孵蛋，来提高蛋的温度", "蛇、乌龟的蛋大多埋在地下，有隐蔽性，所以是白色的，而鸟蛋暴露在环境中，则需要斑纹和颜色做障眼法迷惑天敌"], "answer": ["A"], "explain": "第一步：找出论点和论据。 论点：更深颜色的壳意味着可以吸收更多热量，从而在更寒冷的环境中具有生存优势。 论据：研究结果显示，在日照强度较低的地方，深色鸟蛋更常见；而在阳光强度更高、更暖和的区域，鸟蛋颜色普遍更浅。蛋中胚胎需要稳定的环境温度，但其自身却不具备温度调节能力。 本题的论点是蛋壳颜色与温度的关系，论据是在日照强度较低的地方深色鸟蛋更多，且蛋的胚胎不具备温度调节的能力，二者话题一致，优先考虑补充论据的方式加强，即举例子或解释原因。 第二步：逐一分析选项。 A项：举出鸡蛋在阳光中的例子，说明颜色更深的蛋壳可以吸收更多热量，举例加强，当选； B项：该项说的是大杜鹃鸟为了避免蛋被鸟巢主人赶跑而高仿出二十多种颜色的鸟蛋，但是没有说明鸟蛋颜色的深浅与温度之间的关系，属于无关项，无法加强，排除； C项：该项说的是为了保证小鸟顺利破壳，鸟妈妈只能待在窝里孵蛋，没有提及鸟蛋的颜色，属于无关项，无法加强，排除； D项：该项说的是鸟蛋需要颜色做障眼法迷惑天敌，但是没有说明鸟蛋颜色的深浅与温度之间的关系，属于无关项，无法加强，排除。 ⇒ 正确答案为A。", "method": "第一步：找出论点和论据。 论点：更深颜色的壳意味着可以吸收更多热量，从而在更寒冷的环境中具有生存优势。 论据：研究结果显示，在日照强度较低的地方，深色鸟蛋更常见；而在阳光强度更高、更暖和的区域，鸟蛋颜色普遍更浅。蛋中胚胎需要稳定的环境温度，但其自身却不具备温度调节能力。 本题的论点是蛋壳颜色与温度的关系，论据是在日照强度较低的地方深色鸟蛋更多，且蛋的胚胎不具备温度调节的能力，二者话题一致，优先考虑补充论据的方式加强，即举例子或解释原因。 第二步：逐一分析选项。 A项：举出鸡蛋在阳光中的例子，说明颜色更深的蛋壳可以吸收更多热量，举例加强，当选； B项：该项说的是大杜鹃鸟为了避免蛋被鸟巢主人赶跑而高仿出二十多种颜色的鸟蛋，但是没有说明鸟蛋颜色的深浅与温度之间的关系，属于无关项，无法加强，排除； C项：该项说的是为了保证小鸟顺利破壳，鸟妈妈只能待在窝里孵蛋，没有提及鸟蛋的颜色，属于无关项，无法加强，排除； D项：该项说的是鸟蛋需要颜色做障眼法迷惑天敌，但是没有说明鸟蛋颜色的深浅与温度之间的关系，属于无关项，无法加强，排除。 ⇒ 正确答案为A。", "tip": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "kind": "real", "src": "2020年陕西省公务员考试《行测》试题（网友回忆版） 第27 题", "year": "2020"}, {"type": "logic", "level": "中等", "stem": "（ ） 对于 音乐 相当于 真相 对于 （ ）", "options": ["演奏 揭露", "感动 激愤", "浪漫 报纸", "旋律 新闻"], "answer": ["D"], "explain": "代入法：A演奏音乐（动宾），揭露真相（动宾），但词语前后顺序相反；B感动的音乐（偏正），激愤的真相（偏正），顺序相反；C浪漫的音乐（偏正），报纸是真相载体，关系不同；D旋律是音乐的组成部分（组成），新闻包含真相（组成），前后一致。故正确答案为D。", "method": "代入法：A演奏音乐（动宾），揭露真相（动宾），但词语前后顺序相反；B感动的音乐（偏正），激愤的真相（偏正），顺序相反；C浪漫的音乐（偏正），报纸是真相载体，关系不同；D旋律是音乐的组成部分（组成），新闻包含真相（组成），前后一致。故正确答案为D。", "tip": "易错点：A项动宾结构顺序相反；要保证前后两组关系方向一致。", "kind": "real", "src": "2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版） 第 30 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "所有的幼儿园都面临同一个问题：就是对于那些在幼儿园放学之后不能及时来接孩子的家长，幼儿园老师除了等待别无他法，因此许多幼儿园都向晚接孩子的家长收取费用。然而，有调查显示，收取费用后晚接孩子的家长数量并未因此减少，反而增加了。 以下哪项如果为真，最能解释上述调查结果？", "options": ["收费标准太低，对原本经常晚来接孩子的家长没有太大的约束力", "有个别家长对收费行为不满，有时会故意以晚接孩子的行为来抗议", "有些家长因工作忙碌，常常不能及时来接孩子", "收费后，更多的家长认为即使晚来接孩子也不必愧疚，只要付费即可"], "answer": ["D"], "explain": "第一步：找出题干矛盾。 通过收取费用的方式让家长早接孩子，但是收费后晚接孩子的家长数量不减反增。 第二步：逐一分析选项。 A项：收费低对原本晚接孩子的家长无影响，可以解释为什么人数没有减少，但是无法解释为什么人数增加，不能解释题干矛盾，排除； B项：该项说的是个别家长抗议收费而晚来接孩子，但是无法解释清楚为什么晚接孩子的家长数增加了，不能解释题干矛盾，排除； C项：该项解释了家长晚来接孩子的原因，与题干幼儿园收费无关，不能解释题干矛盾，排除； D项：该项说明幼儿园对晚接孩子进行收费后，将这种行为合理化，更多的家长心安理得的晚来接孩子，可以解释为什么晚接孩子的人不减反增，当选。 ⇒ 正确答案为D。", "method": "第一步：找出题干矛盾。 通过收取费用的方式让家长早接孩子，但是收费后晚接孩子的家长数量不减反增。 第二步：逐一分析选项。 A项：收费低对原本晚接孩子的家长无影响，可以解释为什么人数没有减少，但是无法解释为什么人数增加，不能解释题干矛盾，排除； B项：该项说的是个别家长抗议收费而晚来接孩子，但是无法解释清楚为什么晚接孩子的家长数增加了，不能解释题干矛盾，排除； C项：该项解释了家长晚来接孩子的原因，与题干幼儿园收费无关，不能解释题干矛盾，排除； D项：该项说明幼儿园对晚接孩子进行收费后，将这种行为合理化，更多的家长心安理得的晚来接孩子，可以解释为什么晚接孩子的人不减反增，当选。 ⇒ 正确答案为D。", "tip": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "kind": "real", "src": "2019年国家公务员录用考试《行测》题（副省级网友回忆版） 第31 题", "year": "2019"}, {"type": "fig", "imgs": ["data/figs/figq_055_1.png"], "src": "", "cat": "", "fmt": "", "stem": "找出下列图形中不同于其他图形的一项:", "options": ["", "", ""], "answer": ["A"], "explain": "（题源未附解析，可对照答案自行归纳规律）", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_057_1.png"], "src": "", "cat": "", "fmt": "", "stem": "观察图形的变化规律，选出符合规律的一项。", "options": ["", "", ""], "answer": ["A"], "explain": "三图一循环。", "trap": ""}]}, {"set": 28, "date": "2026-10-24", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 28 批）", "items": [{"type": "sci", "level": "中等", "stem": "生物能对外界刺激做出反应。反射是指生物通过神经系统，对外界或内部的各种刺激所发生的有规律的反应。下列生命现象，不属于反射的是：", "options": ["小陈刚坐上过山车心跳就开始加速", "小狗闻到肉的味道后开始流口水", "猎豹发现猎物后停下脚步开始观察环境", "乳酸菌向培养皿中果糖浓度高的区域聚集"], "answer": ["D"], "explain": "思路：反射需要完整的神经系统参与；详解：A人、B狗、C猎豹都有神经系统，其反应属于反射；D乳酸菌是单细胞生物，没有神经系统，向高浓度区域聚集只是应激性（趋化性），不是反射。故答案为D。", "method": "思路：反射需要完整的神经系统参与；详解：A人、B狗、C猎豹都有神经系统，其反应属于反射；D乳酸菌是单细胞生物，没有神经系统，向高浓度区域聚集只是应激性（趋化性），不是反射。故答案为D。", "tip": "易错点：把生物的趋性等同于反射；反射必须经过神经系统，单细胞生物没有神经系统。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第74题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "“庄稼一枝花，全靠肥当家。”以下有关农业种植中肥料使用的说法，错误的是：", "options": ["肥料的主要作用是给农作物提供有机物", "除了根部，肥料也可以通过叶片等部位被农作物吸收", "施肥浓度过高导致“烧根”，是由于农作物根部的细胞在高浓度溶液中失水", "应根据不同农作物和农作物不同生长阶段的实际需要，有针对性地施用肥料"], "answer": ["A"], "explain": "思路：肥料提供的是无机盐而非有机物；详解：A错误，植物有机物来自光合作用；B叶面施肥可吸收；C高浓度土壤溶液使根细胞渗透失水“烧根”正确；D按需施肥正确。故答案为A。", "method": "思路：肥料提供的是无机盐而非有机物；详解：A错误，植物有机物来自光合作用；B叶面施肥可吸收；C高浓度土壤溶液使根细胞渗透失水“烧根”正确；D按需施肥正确。故答案为A。", "tip": "易错点：以为肥料直接给植物提供有机物；植物所需有机物是光合作用自己制造的，肥料主要提供氮磷钾等矿质元素（无机物）。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第78题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "大棚种植是一种被广泛采用的农作物种植方式。以下大棚种植的增产做法，有误的是：", "options": ["在大棚内补充二氧化碳，促进农作物的光合作用", "维持大棚昼夜温度相对稳定，提高农作物的生长速度", "傍晚和夜间在大棚内开灯，增加光照时间和光照强度", "合理密植农作物，增加单位面积内农作物的光照面积"], "answer": ["B"], "explain": "思路：从光合积累与呼吸消耗的角度判断；详解：A补CO2作气肥促光合正确；C延长光照增加光合正确；D合理密植提高光能利用正确；B维持昼夜温差稳定反而让夜间呼吸消耗有机物，不利于增产，做法有误。故答案为B。", "method": "思路：从光合积累与呼吸消耗的角度判断；详解：A补CO2作气肥促光合正确；C延长光照增加光合正确；D合理密植提高光能利用正确；B维持昼夜温差稳定反而让夜间呼吸消耗有机物，不利于增产，做法有误。故答案为B。", "tip": "易错点：以为温度恒定利于生长；增产要增大昼夜温差——白天高温促光合，夜晚低温抑呼吸，减少有机物消耗。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第84题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "食物链主要反映了生产者与消费者之间的联系，下列关系中最能准确表示食物链的是（ ）。", "options": ["草→兔→狐→鹰", "阳光→草→鸡→狼", "虫→鸟→蛇", "草→羊→虎→微生物"], "answer": ["A"], "explain": "思路：食物链起点必须是生产者（绿色植物），终点是最高级消费者，不含非生物部分和分解者；详解：B起点阳光是非生物；C起点虫是消费者不是生产者；D末尾微生物是分解者；A草为生产者，经兔、狐到鹰，完整准确。故答案为A。", "method": "思路：食物链起点必须是生产者（绿色植物），终点是最高级消费者，不含非生物部分和分解者；详解：B起点阳光是非生物；C起点虫是消费者不是生产者；D末尾微生物是分解者；A草为生产者，经兔、狐到鹰，完整准确。故答案为A。", "tip": "易错点：误选B把非生物的阳光写进食物链，或误选D把分解者微生物写进捕食链；食物链只含生产者和消费者，箭头指向捕食者。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第79题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "某单位本科、研究生学历的职工人数之比为7：5。上半年公开招聘本科毕业生若干人后，本科与研究生之比为3：1；下半年通过引才计划引入研究生若干人后，本科与研究生之比为15：8。已知该年度引进的本科生比研究生多10人，则该单位原有本科与研究生学历的职工共（ ）人。", "options": ["12", "24", "36", "48"], "answer": ["B"], "explain": "思路：比例法（抓不变量）。原有本科:研究生=7:5。上半年招本科生后研究生不变，本科:研究生=3:1=15:5（研究生统一为5份），即本科从7份增至15份，增加8份。下半年招研究生后本科不变，本科:研究生=15:8（本科统一为15份），即研究生从5份增至8份，增加3份。引进本科比研究生多8-3=5份，对应10人，故1份=2人。原有总人数=(7+5)×2=24人。故答案为B。", "method": "思路：比例法（抓不变量）。原有本科:研究生=7:5。上半年招本科生后研究生不变，本科:研究生=3:1=15:5（研究生统一为5份），即本科从7份增至15份，增加8份。下半年招研究生后本科不变，本科:研究生=15:8（本科统一为15份），即研究生从5份增至8份，增加3份。引进本科比研究生多8-3=5份，对应10人，故1份=2人。原有总人数=(7+5)×2=24人。故答案为B。", "tip": "易错点：未抓住\"上半年招研究生不变\"\"下半年本科生不变\"这两个不变量；或比例换算时份数不对；记忆要点：比例问题抓不变量统一份数。", "kind": "real", "src": "2021年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 7 题", "year": "2021"}, {"type": "math", "level": "中等", "stem": "李某骑车从甲地出发前往乙地，出发时的速度为15千米/小时，此后均匀加速，骑行25%的路程后速度达到21千米/小时。剩余路段保持此速度骑行，总行程前半段比后半段多用时3分钟。问甲、乙两地之间的距离在以下哪个范围内？", "options": ["不到23千米", "在23~24千米之间", "在24~25千米之间", "超过25千米"], "answer": ["D"], "explain": "思路：分段行程（匀加速+匀速）；详解：设全程4S。前25%（即S）为匀加速，初速15、末速21，平均速度=(15+21)/2=18千米/小时。前半段=2S：其中前S（匀加速，均速18）+后S（匀速21）；后半段=2S（全程匀速21）。时间差：前半段用时S/18+S/21，后半段用时2S/21，差为S/18+S/21-2S/21=S/18-S/21=3分钟=0.05小时。即S(1/18-1/21)=0.05，S×(7-6)/126=0.05，S=6.3千米。全程4S=25.2千米。故答案为D。", "method": "思路：分段行程（匀加速+匀速）；详解：设全程4S。前25%（即S）为匀加速，初速15、末速21，平均速度=(15+21)/2=18千米/小时。前半段=2S：其中前S（匀加速，均速18）+后S（匀速21）；后半段=2S（全程匀速21）。时间差：前半段用时S/18+S/21，后半段用时2S/21，差为S/18+S/21-2S/21=S/18-S/21=3分钟=0.05小时。即S(1/18-1/21)=0.05，S×(7-6)/126=0.05，S=6.3千米。全程4S=25.2千米。故答案为D。", "tip": "易错点：①匀加速段平均速度误算（应用初末速度平均而非用某一端）；②“前半段比后半段多用时3分钟”的分段对应搞错。", "kind": "real", "src": "2022年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 3 题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "小王参加工作时的年龄，和他弟弟现在的年龄相同，小王工作两年后，弟弟也正式参加工作，现在兄弟俩的年龄之和，正好是他们工龄之和的8倍。如果弟弟20岁正式参加工作，则小王比弟弟大（ ）岁。", "options": ["3", "4", "5", "6"], "answer": ["B"], "explain": "思路：方程法；详解：设弟弟现在工龄x年，则弟弟现在年龄=20+x；小王参加工作时年龄=弟弟现在年龄=20+x；小王工作2年后弟弟才参加工作，即小王比弟弟早工作2年，故小王现在工龄=弟弟工龄x+2；小王现在年龄=(20+x)+(2+x)=22+2x；兄弟年龄和=(22+2x)+(20+x)=42+3x；工龄和=(2+x)+x=2+2x；由题意42+3x=8(2+2x)=16+16x，得26=13x，x=2；小王比弟弟大：小王现在年龄(22+4=26)-弟弟现在年龄(20+2=22)=4岁。故答案为B。", "method": "思路：方程法；详解：设弟弟现在工龄x年，则弟弟现在年龄=20+x；小王参加工作时年龄=弟弟现在年龄=20+x；小王工作2年后弟弟才参加工作，即小王比弟弟早工作2年，故小王现在工龄=弟弟工龄x+2；小王现在年龄=(20+x)+(2+x)=22+2x；兄弟年龄和=(22+2x)+(20+x)=42+3x；工龄和=(2+x)+x=2+2x；由题意42+3x=8(2+2x)=16+16x，得26=13x，x=2；小王比弟弟大：小王现在年龄(22+4=26)-弟弟现在年龄(20+2=22)=4岁。故答案为B。", "tip": "易错点：容易混淆“参加工作年龄”“工龄”“现在年龄”三个时间点；记忆要点：弟弟20岁参加工作，小王参加工作时年龄=弟弟现在年龄。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（网友回忆版） 第 11 题", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "沙盒监管是指先要划定一个范围，对在“盒子”里面的企业，采取包容审慎的监管措施，同时杜绝将问题扩散到“盒子”外面，实行容错纠错机制，并由监管部门对运行过程进行全过程监管，以保证测试的安全性并作出最终的评价。 根据上述定义，下列属于沙盒监管的是：", "options": ["某市政府创设“银行业务创新监管互动机制”为金融科技的创新与监管提供制度支持", "某市生态环境局对非法排污的某化工厂处以责令停产整治的行政处罚", "某地金融监管局要求信贷机构强化对小微企业和三农领域等重点对象的信贷支持", "某县市场监管局对肉类食品公司开展专项整治活动以保障人民群众“舌尖上的安全”"], "answer": ["A"], "explain": "划关键词：①划定范围；②对盒内企业包容审慎监管；③杜绝问题外溢；④全过程监管。逐项比对：A项创设“银行业务创新监管互动机制”，划定银行业务范围、包容审慎、全过程监管，符合；B项行政处罚是惩戒，不符合包容审慎；C项只是提信贷要求，非监管机制；D项专项整治是解决问题，非包容测试。当选A。", "method": "划关键词：①划定范围；②对盒内企业包容审慎监管；③杜绝问题外溢；④全过程监管。逐项比对：A项创设“银行业务创新监管互动机制”，划定银行业务范围、包容审慎、全过程监管，符合；B项行政处罚是惩戒，不符合包容审慎；C项只是提信贷要求，非监管机制；D项专项整治是解决问题，非包容测试。当选A。", "tip": "易错点：误选B、D，把行政处罚、专项整治当成“包容审慎监管”，其实它们是惩戒性措施。", "kind": "real", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 12 题", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "某单位的人事、科研、教育、财务、宣传、后勤和工会7个部门各由王、卫和丁3位副主任中的1人分管，已知：（1）教育和财务由同一人分管；（2）宣传和后勤由同一人分管；（3）丁分管的部门比卫多；（4）教育、工会中的一个部门由王分管；（5）工会、后勤中的一个部门由卫分管。 如果王分管的部门多于丁，下列哪项可能为真？", "options": ["人事由卫分管", "科研由卫分管", "教育由丁分管", "后勤由丁分管"], "answer": ["D"], "explain": "先列条件：（1）教育=财务同人；（2）宣传=后勤同人；（3）丁>卫；（4）教育、工会中一个由王；（5）工会、后勤中一个由卫；（6）新增王>丁。突破口：由（3）（6）得王>丁>卫，共7部门，则王4、丁2、卫1；由（1）（2）卫不分管教育财务宣传后勤，再由（5）卫只能分管工会；由（4）工会已由卫分管，故王分管教育和财务。剩余人事、科研、宣传、后勤4个部门，王已占2个（教育财务）还需2个达4个，丁占2个。A人事由卫错（卫只1个是工会）；B科研由卫错；C教育由丁错（教育由王）；D后勤由丁可能（宣传后勤捆绑给丁）。故答案为D。", "method": "先列条件：（1）教育=财务同人；（2）宣传=后勤同人；（3）丁>卫；（4）教育、工会中一个由王；（5）工会、后勤中一个由卫；（6）新增王>丁。突破口：由（3）（6）得王>丁>卫，共7部门，则王4、丁2、卫1；由（1）（2）卫不分管教育财务宣传后勤，再由（5）卫只能分管工会；由（4）工会已由卫分管，故王分管教育和财务。剩余人事、科研、宣传、后勤4个部门，王已占2个（教育财务）还需2个达4个，丁占2个。A人事由卫错（卫只1个是工会）；B科研由卫错；C教育由丁错（教育由王）；D后勤由丁可能（宣传后勤捆绑给丁）。故答案为D。", "tip": "易错点：由（3）丁比卫多和新增（6）王比丁多，未排出王>丁>卫后再定7部门分配数；或忽略（5）工会后勤一个由卫分管。", "kind": "real", "src": "2021年国家公务员录用考试《行测》题（地市级网友回忆版） 第 2 题", "year": "2021"}, {"type": "logic", "level": "中等", "stem": "某街道计划将3名男性干部甲、乙、丙和3名女性干部张、李、王下沉至各个社区开展工作，可供选择的社区有A、B、C、D四个。已知： ①每人只能去一个社区。 ②凡是有男性去的社区就必须有女性去。 ③张去A社区或者B社区，乙去D社区。 如果最终李去了C社区，则下列推论必然正确的是（ ）。", "options": ["丙去了A社区", "张去了B社区", "甲去了C社区", "王去了D社区"], "answer": ["D"], "explain": "划关键条件逐项推理：①每人去一个社区；②有男必有女；③张去A或B，乙去D；④李去C。乙（男）去D，由②D必须有女性。张去A/B，李去C，剩下女性只有王，故王必须去D。故正确答案为D。", "method": "划关键条件逐项推理：①每人去一个社区；②有男必有女；③张去A或B，乙去D；④李去C。乙（男）去D，由②D必须有女性。张去A/B，李去C，剩下女性只有王，故王必须去D。故正确答案为D。", "tip": "易错点：易漏看'有男性去的社区必须有女性去'这一约束，直接排座位；乙去D（男），D必须配女性。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 16 题", "year": "2023"}, {"type": "fig", "imgs": ["data/figs/figq_059_1.png"], "src": "", "cat": "", "fmt": "", "stem": "下列不同于其他的图形是:", "options": ["", "", ""], "answer": ["B"], "explain": "题干中1、2、6是笑脸，4、5是哭脸，由图可知，笑脸眼睛是向右看，哭脸眼睛向左看，图2笑脸眼睛向左看，错误。选B。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_060_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是:", "options": ["", "", "", ""], "answer": ["A"], "explain": "按列，从上往下看，每一列的第一个图形加第二个图形等于第三个图形，相加的规则是有重复的边去掉。", "trap": ""}]}, {"set": 29, "date": "2026-10-24", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 29 批）", "items": [{"type": "sci", "level": "中等", "stem": "在生活中，我们可以用紫色的蝴蝶兰花溶液作为酸碱指示剂，其遇酸性溶液显红色，遇碱性溶液则显黄色。下列说法正确的是（ ）。", "options": ["在盐水中滴入蝴蝶兰花溶液，溶液呈红色", "在纯净水中滴入蝴蝶兰花溶液，溶液呈无色", "在苏打水中滴入蝴蝶兰花溶液，溶液呈黄色", "在酸或碱性溶液滴入蝴蝶兰花溶液后，变色的过程属于物理变化"], "answer": ["C"], "explain": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "method": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "tip": "易错点：误以为中性溶液会让指示剂“无色”，或把指示剂变色当成物理变化；遇酸碱发生的是化学变化。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "一般来说，海水会从密度大的地方向密度小的地方流动，而海水的密度主要受到温度和盐度的影响。则以下判断正确的是（ ）。", "options": ["越热越咸的海水，密度越大", "越冷越咸的海水，密度越大", "越冷越淡的海水，密度越大", "越热越淡的海水，密度越大"], "answer": ["B"], "explain": "思路：ρ随温度降低而增大、随盐度升高而增大；详解：要密度最大，就要温度最低且盐度最高，即“越冷越咸”。故答案为B。", "method": "思路：ρ随温度降低而增大、随盐度升高而增大；详解：要密度最大，就要温度最低且盐度最高，即“越冷越咸”。故答案为B。", "tip": "易错点：只盯盐度或只盯温度，漏了两者叠加；密度与温度、盐度都正相关方向相反：温度越低密度越大，盐度越高密度越大。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第68题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "下表为一些常见溶液的酸碱度，根据表中的信息，以下说法不恰当的是：", "options": ["草木灰水能改良酸性土壤", "食醋能中和皮蛋中的碱性物质", "肥皂水能中和蚂蚁叮咬皮肤时分泌的蚁酸", "胃酸过多的人适宜多喝苹果汁"], "answer": ["D"], "explain": "思路：酸碱中和，酸过多要补碱；详解：A草木灰碳酸钾呈碱性可中和酸性土壤；B醋酸可中和皮蛋碱性；C肥皂水碱性可中和蚁酸；D苹果汁呈酸性，胃酸过多者多喝会加重，不恰当。故答案为D。", "method": "思路：酸碱中和，酸过多要补碱；详解：A草木灰碳酸钾呈碱性可中和酸性土壤；B醋酸可中和皮蛋碱性；C肥皂水碱性可中和蚁酸；D苹果汁呈酸性，胃酸过多者多喝会加重，不恰当。故答案为D。", "tip": "易错点：忽视苹果汁本身呈酸性；胃酸过多应食用碱性食物中和，多喝酸性苹果汁反而加重。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（考生回忆版） 第66题", "year": "2025"}, {"type": "sci", "level": "中等", "stem": "下列关于我国家庭用电的说法正确的是：", "options": ["我国家庭使用的是220V的直流电", "带金属外壳的用电器一般使用两孔插座", "要使用电器之间互不影响，用电器应串联接入电路", "家庭用电的保险丝可以由电阻率大、熔点低的合金制成"], "answer": ["D"], "explain": "思路：家庭用电基本常识逐项判断；详解：A是交流电不是直流；B金属外壳用三孔插座接地防触电；C并联才能互不影响，串联会分压；D保险丝用电阻率大、熔点低的铅锑合金，电流过大时自动熔断。故答案为D。", "method": "思路：家庭用电基本常识逐项判断；详解：A是交流电不是直流；B金属外壳用三孔插座接地防触电；C并联才能互不影响，串联会分压；D保险丝用电阻率大、熔点低的铅锑合金，电流过大时自动熔断。故答案为D。", "tip": "易错点：以为家庭电是直流、或用电器要串联；我国家庭电路是220V交流电，用电器必须并联才能互不影响。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第81题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "某工厂加工出一批正方体奶酪,抽检时质检员从奶酪中切下了一个厚度为2厘米的长方体（如图所示）。如果剩余奶酪的体积为144立方厘米，则奶酪原本的边长为（ ）厘米。", "options": ["4", "6", "8", "10"], "answer": ["B"], "explain": "思路：几何代入法；详解：设原正方体边长x，切下厚2cm的片后剩余部分长=宽=x，高=x-2，剩余体积=x·x·(x-2)=144。代入验证：x=4时4×4×2=32≠144；x=6时6×6×4=144，满足。故答案为B。", "method": "思路：几何代入法；详解：设原正方体边长x，切下厚2cm的片后剩余部分长=宽=x，高=x-2，剩余体积=x·x·(x-2)=144。代入验证：x=4时4×4×2=32≠144；x=6时6×6×4=144，满足。故答案为B。", "tip": "易错点：切下厚度2cm后剩余高是x-2，不是2；容易误列x³-144=2x²。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 8 题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "如图，仓库有一堆管材，每一层的数量都比上一层多1根。搬运工人将管材逐根搬离，搬了99根后发现，管材堆少了3层，且剩余每层的管材数量都减少了3根。如果这堆管材刚好还剩10层，则剩下的管材共有（ ）根。", "options": ["245", "265", "305", "325"], "answer": ["B"], "explain": "思路：等差数列+代入验证。详解：搬99根后剩10层，则原共13层，原总数=中项×13，必为13的倍数。设剩265根，则原总数=265+99=364=13×28，即原数列中项（第7层）为28，原最上层为28-6=22。搬离的3层（最上面22、23、24层）共22+23+24=69根；剩余10层每层减3根共减30根，69+30=99根，与题意吻合。剩余10层最上层原为25、现减为22，共10层公差为1，和=(22+31)×10÷2=265根。故答案为B（265）。", "method": "思路：等差数列+代入验证。详解：搬99根后剩10层，则原共13层，原总数=中项×13，必为13的倍数。设剩265根，则原总数=265+99=364=13×28，即原数列中项（第7层）为28，原最上层为28-6=22。搬离的3层（最上面22、23、24层）共22+23+24=69根；剩余10层每层减3根共减30根，69+30=99根，与题意吻合。剩余10层最上层原为25、现减为22，共10层公差为1，和=(22+31)×10÷2=265根。故答案为B（265）。", "tip": "易错点：列不出“少了3层”与“剩余每层减3根”两个条件的关系，或忽略原总层数=13层这一整除特性。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 11 题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "某单位有甲和乙2个办公室，分别有职工5人和4人。每周从这9名职工中随机抽取1人下沉社区担任志愿者（同一人有可能被连续、重复选中）。问7月前2周的志愿者均来自甲办公室的概率在以下哪个范围内？", "options": ["不到25%", "25%~35%之间", "35%~45%之间", "超过45%"], "answer": ["B"], "explain": "思路：独立事件概率乘法。详解：每周从9人中抽1人，两周总情况=9×9=81种；两周均来自甲办公室=5×5=25种。所求概率=25/81≈30.9%，落在25%~35%之间。故答案为B。", "method": "思路：独立事件概率乘法。详解：每周从9人中抽1人，两周总情况=9×9=81种；两周均来自甲办公室=5×5=25种。所求概率=25/81≈30.9%，落在25%~35%之间。故答案为B。", "tip": "易错点：同一人可重复选中说明是有放回抽样，两周相互独立，不能用C(9,2)组合；甲办公室5人、总9人。", "kind": "real", "src": "2023年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 4 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "匿名投票：实名投票：现场投票", "options": ["早间会议：午间会议：工作会议", "战国文字：象形文字：古代汉字", "金融危机：粮食危机：生态危机", "油料作物：糖料作物：经济作物"], "answer": ["A"], "explain": "一级：匿名与实名投票并列；前两词与现场投票交叉（现场投票可匿名可实名）。逐项：A早间午间会议并列，都与工作会议交叉，一致；B战国文字是古代汉字一种=种属；C三者不同领域危机并列无交叉；D油料糖料作物都是经济作物=种属。故A。", "method": "一级：匿名与实名投票并列；前两词与现场投票交叉（现场投票可匿名可实名）。逐项：A早间午间会议并列，都与工作会议交叉，一致；B战国文字是古代汉字一种=种属；C三者不同领域危机并列无交叉；D油料糖料作物都是经济作物=种属。故A。", "tip": "易错点：前两词并列，都与第三词交叉；D前两词与第三词是种属（油料糖料都是经济作物）。", "kind": "real", "src": "2023年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 30 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "某医生认为，受外伤后不宜食用海鲜。因为海鲜属于“发物”，对人体有刺激性，会导致伤口愈合变慢、伤口复发甚至化脓。 以下哪项如果为真，最能质疑该医生的观点？", "options": ["传统医学对“发物”的定义并不清晰，其作用机制也缺乏实质性证据", "不新鲜或处理不当的海鲜会携带大量致病细菌，食用这种海鲜会使伤口发炎", "一些海鲜中富含长链多不饱和脂肪酸，该物质有助于创伤患者修复神经系统", "伤口愈合时，身体需要消耗更多的蛋白质，海鲜富含优质蛋白质有利于伤口愈合"], "answer": ["D"], "explain": "第一步：找出论点和论据。 论点：受外伤后不宜食用海鲜。 论据：海鲜属于“发物”，对人体有刺激性，会导致伤口愈合变慢、伤口复发甚至化脓。 本题论点说的是受外伤后不宜食用海鲜，论据是对论点的解释说明，二者话题一致，削弱可以考虑削弱论点或削弱论据。 第二步：逐一分析选项。 A项：该项指出传统医学对“发物”的定义并不清晰，其作用机制也缺乏实质性证据，说明无法确定海鲜是否属于“发物”，但未明确指出受外伤是否可以吃海鲜，不明确选项，排除； B项：该项指出食用不新鲜或处理不当的海鲜会使伤口发炎，讨论的是“不新鲜或处理不当的海鲜”对伤口的影响，而论点说的是“海鲜”对伤口的影响，主体不一致，无法削弱，排除； C项：该项指出一些海鲜有助于创伤患者修复神经系统，说明有些海鲜有利于创伤患者的恢复，削弱论点，可以削弱，保留； D项：该项指出海鲜富含优质蛋白质，有利于伤口愈合，说明受外伤后可食用海鲜来促进伤口愈合，削弱论点，可以削弱，保留。 对比C、D两项，C项说“一些”海鲜有助于修复神经系统，但不明确其他海鲜是否对创伤患者有益，而D项直接表明海鲜有利于伤口愈合，且与论证的话题相关度更高，D项的削弱力度更强，当选。 ⇒ 正确答案为D。", "method": "第一步：找出论点和论据。 论点：受外伤后不宜食用海鲜。 论据：海鲜属于“发物”，对人体有刺激性，会导致伤口愈合变慢、伤口复发甚至化脓。 本题论点说的是受外伤后不宜食用海鲜，论据是对论点的解释说明，二者话题一致，削弱可以考虑削弱论点或削弱论据。 第二步：逐一分析选项。 A项：该项指出传统医学对“发物”的定义并不清晰，其作用机制也缺乏实质性证据，说明无法确定海鲜是否属于“发物”，但未明确指出受外伤是否可以吃海鲜，不明确选项，排除； B项：该项指出食用不新鲜或处理不当的海鲜会使伤口发炎，讨论的是“不新鲜或处理不当的海鲜”对伤口的影响，而论点说的是“海鲜”对伤口的影响，主体不一致，无法削弱，排除； C项：该项指出一些海鲜有助于创伤患者修复神经系统，说明有些海鲜有利于创伤患者的恢复，削弱论点，可以削弱，保留； D项：该项指出海鲜富含优质蛋白质，有利于伤口愈合，说明受外伤后可食用海鲜来促进伤口愈合，削弱论点，可以削弱，保留。 对比C、D两项，C项说“一些”海鲜有助于修复神经系统，但不明确其他海鲜是否对创伤患者有益，而D项直接表明海鲜有利于伤口愈合，且与论证的话题相关度更高，D项的削弱力度更强，当选。 ⇒ 正确答案为D。", "tip": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "kind": "real", "src": "2021年度浙江省党政机关选调应届优秀大学毕业生《行测》题（网友回忆版） 第1 题", "year": "2021"}, {"type": "logic", "level": "中等", "stem": "封闭性问题指具有标准答案的问题，这类问题除了标准答案之外的解答，均被认为是错误解答。 根据上述定义，下列属于封闭性问题的是：", "options": ["什么是幸福生活", "宇宙中有外星人吗", "我应该报考哪所大学", "世界上最美丽的城市是哪座"], "answer": ["B"], "explain": "划关键词：有标准答案，其他解答均错误。逐项比对：A项幸福生活因人而异，无标准答案；B项宇宙中是否有外星人，要么有要么没有，有确定答案；C项报哪所大学因人而异；D项最美城市见仁见智。当选B。", "method": "划关键词：有标准答案，其他解答均错误。逐项比对：A项幸福生活因人而异，无标准答案；B项宇宙中是否有外星人，要么有要么没有，有确定答案；C项报哪所大学因人而异；D项最美城市见仁见智。当选B。", "tip": "易错点：误选其他主观题；封闭性问题=有标准答案、除标准答案外都错。", "kind": "real", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 20 题", "year": "2024"}, {"type": "fig", "imgs": ["data/figs/figq_061_1.png"], "src": "", "cat": "", "fmt": "", "stem": "找出下列图形中不同于其他图形的一项:", "options": ["", "", ""], "answer": ["A"], "explain": "除了A，其余图形小球贴的边是相邻的。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_062_1.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性", "options": ["", "", "", ""], "answer": ["C"], "explain": "图中的图形都是一个正方形带有上下左右4个箭头。我们从箭头和正方形入手。第一个图是上面黑箭头，左上角黑三角形。第二个图是左面黑箭头，右上角黑三角形。第三个图是下面黑箭头，右下角黑三角形。第四个图是右面黑箭头，左下角黑三角形。第五个图和第一个图一样，第六个图和第二个图一样。所以前4个图是一个规律，不断重复。问号处的图形应该是规律的第一个图。只有C符合，所以答案选C。", "trap": ""}]}, {"set": 30, "date": "2026-10-25", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 30 批）", "items": [{"type": "sci", "level": "中等", "stem": "下表为一些常见溶液的酸碱度，根据表中的信息，以下说法不恰当的是：", "options": ["草木灰水能改良酸性土壤", "食醋能中和皮蛋中的碱性物质", "肥皂水能中和蚂蚁叮咬皮肤时分泌的蚁酸", "胃酸过多的人适宜多喝苹果汁"], "answer": ["D"], "explain": "思路：酸碱中和，酸过多要补碱；详解：A草木灰碳酸钾呈碱性可中和酸性土壤；B醋酸可中和皮蛋碱性；C肥皂水碱性可中和蚁酸；D苹果汁呈酸性，胃酸过多者多喝会加重，不恰当。故答案为D。", "method": "思路：酸碱中和，酸过多要补碱；详解：A草木灰碳酸钾呈碱性可中和酸性土壤；B醋酸可中和皮蛋碱性；C肥皂水碱性可中和蚁酸；D苹果汁呈酸性，胃酸过多者多喝会加重，不恰当。故答案为D。", "tip": "易错点：忽视苹果汁本身呈酸性；胃酸过多应食用碱性食物中和，多喝酸性苹果汁反而加重。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（考生回忆版） 第66题", "year": "2025"}, {"type": "sci", "level": "中等", "stem": "胰岛素是一种蛋白质，可以用于治疗糖尿病。以下有关胰岛素的说法，正确的是（ ）。", "options": ["胰岛素能够抑制血糖分解", "人体中的胰岛素由肝脏分泌", "一般通过口服胰岛素治疗糖尿病", "血液中的胰岛素浓度过高会导致低血糖"], "answer": ["D"], "explain": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "method": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "tip": "易错点：以为胰岛素口服有效；胰岛素是蛋白质，口服会被消化道分解失效，只能注射；它由胰岛分泌而非肝脏。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "year": "2024"}, {"type": "sci", "level": "中等", "stem": "对下列生活中的现象或做法解释不合理的是（ ）。", "options": ["物体的热胀冷缩——分子随温度升高而变大", "油锅着火用锅盖盖灭——使可燃物与空气隔绝", "在铁制品表面刷油漆——避免铁制品氧化生锈", "利用真空袋包装食品——破坏需氧菌类的生存环境"], "answer": ["A"], "explain": "思路：用微观和化学原理逐一核对；详解：A热胀冷缩是分子间间隔随温度升高而增大，分子本身体积不变，解释错误；B盖锅盖隔绝氧气灭火正确；C刷油漆隔绝水和氧气防锈正确；D真空缺氧气抑制需氧菌正确。故答案为A。", "method": "思路：用微观和化学原理逐一核对；详解：A热胀冷缩是分子间间隔随温度升高而增大，分子本身体积不变，解释错误；B盖锅盖隔绝氧气灭火正确；C刷油漆隔绝水和氧气防锈正确；D真空缺氧气抑制需氧菌正确。故答案为A。", "tip": "易错点：误以为热胀冷缩是分子本身变大；实际是分子间间隔随温度改变，分子大小不变。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第76题", "year": "2022"}, {"type": "sci", "level": "中等", "stem": "在生活中，我们可以用紫色的蝴蝶兰花溶液作为酸碱指示剂，其遇酸性溶液显红色，遇碱性溶液则显黄色。下列说法正确的是（ ）。", "options": ["在盐水中滴入蝴蝶兰花溶液，溶液呈红色", "在纯净水中滴入蝴蝶兰花溶液，溶液呈无色", "在苏打水中滴入蝴蝶兰花溶液，溶液呈黄色", "在酸或碱性溶液滴入蝴蝶兰花溶液后，变色的过程属于物理变化"], "answer": ["C"], "explain": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "method": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "tip": "易错点：误以为中性溶液会让指示剂“无色”，或把指示剂变色当成物理变化；遇酸碱发生的是化学变化。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "year": "2020"}, {"type": "math", "level": "中等", "stem": "县公安局计划举办篮球比赛，6支报名参赛的队伍将平均分为上午组和下午组进行小组赛。其中甲队与乙队来自同部门，不能分在同一组，则分组情况共有（ ）种可能。", "options": ["6", "8", "10", "12"], "answer": ["D"], "explain": "思路：排列组合（正面法/反面法）。正面法：甲乙不能同组，先把甲放一组，从其余4队中选2队与甲同组，C(4,2)=6种，剩下2队自然与乙同组。但甲可在上午组也可在下午组，有2种排列，故总数=6×2=12种。反面法：总分组=C(6,3)÷2=10种（6队平均分两组，除以2消序），甲乙同组：先选1队与甲乙组成一组，C(4,1)=4，再乘2（上/下午组）=8种。所求=10×2-8=12种（总排列含上下午区分应为C(6,3)=20种，减去同组8种=12种）。故答案为D。", "method": "思路：排列组合（正面法/反面法）。正面法：甲乙不能同组，先把甲放一组，从其余4队中选2队与甲同组，C(4,2)=6种，剩下2队自然与乙同组。但甲可在上午组也可在下午组，有2种排列，故总数=6×2=12种。反面法：总分组=C(6,3)÷2=10种（6队平均分两组，除以2消序），甲乙同组：先选1队与甲乙组成一组，C(4,1)=4，再乘2（上/下午组）=8种。所求=10×2-8=12种（总排列含上下午区分应为C(6,3)=20种，减去同组8种=12种）。故答案为D。", "tip": "易错点：忘记甲乙分属上午/下午组有2种排列；或用反面法时漏乘组的排列；记忆要点：正面法——先从其余4队选2队与甲同组，再乘甲乙互换组的2种。", "kind": "real", "src": "2021年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 6 题", "year": "2021"}, {"type": "math", "level": "中等", "stem": "某商品上月售价为进价的1.4倍，销售m件。本月该商品进价下降20%，售价不变，销售利润为上月的1.8倍。那么本月的销量为多少件?", "options": ["1.3m", "1.25m", "1.2m", "1.15m"], "answer": ["C"], "explain": "思路：赋值法；详解：赋上月进价10元，则售价=10×1.4=14元，上月单件利润=14-10=4元，上月总利润=4m；本月进价=10×0.8=8元，售价不变，本月单件利润=14-8=6元；本月总利润=上月的1.8倍=4m×1.8=7.2m；本月销量=7.2m÷6=1.2m件。故答案为C。", "method": "思路：赋值法；详解：赋上月进价10元，则售价=10×1.4=14元，上月单件利润=14-10=4元，上月总利润=4m；本月进价=10×0.8=8元，售价不变，本月单件利润=14-8=6元；本月总利润=上月的1.8倍=4m×1.8=7.2m；本月销量=7.2m÷6=1.2m件。故答案为C。", "tip": "易错点：本月进价下降20%后单件利润算错；售价不变。", "kind": "real", "src": "2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版） 第 7 题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "某高校外国语学院中，会俄语的学生都会英语，其中一半还会法语；会英语的学生中有一半会法语；这三种语言都会的学生有50人，只会其中两种语言的有100人，只会其中一种语言的有150人。问会法语的学生有多少人？", "options": ["100", "200", "50", "150"], "answer": ["B"], "explain": "思路：文氏图分层。会俄语者一半还会法语=三语都会=50人，故会俄语共100人，其中只会俄英双语=50人。只会两种语言共100人，故只会英法双语=100-50=50人。会英语者中一半会法语：会法语的英语者=英法双语50+三语都会50=100人，故会英语共200人，其中只会英语=200-50(英法)-100(俄语人群)=50人。只会一种语言150人=只会英语50+只会法语，故只会法语=100人。会法语=只会法语100+英法双语50+三语都会50=200人。故答案为B。", "method": "思路：文氏图分层。会俄语者一半还会法语=三语都会=50人，故会俄语共100人，其中只会俄英双语=50人。只会两种语言共100人，故只会英法双语=100-50=50人。会英语者中一半会法语：会法语的英语者=英法双语50+三语都会50=100人，故会英语共200人，其中只会英语=200-50(英法)-100(俄语人群)=50人。只会一种语言150人=只会英语50+只会法语，故只会法语=100人。会法语=只会法语100+英法双语50+三语都会50=200人。故答案为B。", "tip": "易错点：“会俄语都会英语”说明俄语集合包含于英语，画圈别画成并列；三种都会的50人=会俄语者的一半。", "kind": "real", "src": "2024年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 6 题", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "一项研究发现，生活贫困能够导致人们的某种基因发生变化，这种基因能够增强负责应对恐慌的大脑区域活动，比如杏仁核的活动增加会导致患上抑郁症的风险增加。同时，较低的社会经济状况与低水平的血清素之间也存在关联，进而增加抑郁症的患病风险。研究员还发现，这种基因变化也会传递给后代。 根据上述研究，可以得知：", "options": ["生活贫困会通过影响生理而对精神健康产生作用", "社会经济地位较高的人群患抑郁症的风险较低", "穷困阶层因基因的变化而使得贫穷和疾病多代延续", "杏仁核活动增强的同时，血清素水平降低"], "answer": ["A"], "explain": "本题为日常结论题。 A项：题干提及“较低的社会经济状况与低水平的血清素之间存在关联，进而增加抑郁症的患病风险”，可以推出生活贫困会通过影响生理而对精神健康产生作用，符合文意，当选； B项：题干只谈及了社会经济较低的人患抑郁症的情况，并未提到社会经济较高的人，无中生有，排除； C项：题干说的是社会经济较低的人的基因变化会传递给后代，而非基因变化导致贫穷和疾病这个结果传递给后代，偷换概念，排除； D项：题干并未提及杏仁核和血清素之间的联系，无中生有，排除。 ⇒ 正确答案为A。", "method": "本题为日常结论题。 A项：题干提及“较低的社会经济状况与低水平的血清素之间存在关联，进而增加抑郁症的患病风险”，可以推出生活贫困会通过影响生理而对精神健康产生作用，符合文意，当选； B项：题干只谈及了社会经济较低的人患抑郁症的情况，并未提到社会经济较高的人，无中生有，排除； C项：题干说的是社会经济较低的人的基因变化会传递给后代，而非基因变化导致贫穷和疾病这个结果传递给后代，偷换概念，排除； D项：题干并未提及杏仁核和血清素之间的联系，无中生有，排除。 ⇒ 正确答案为A。", "tip": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "kind": "real", "src": "2018年北京市公务员录用考试《行测》题（网友回忆版） 第17 题", "year": "2018"}, {"type": "logic", "level": "中等", "stem": "青铜器物：商朝礼器：文化遗产", "options": ["科幻小说：微型小说：文学作品", "中式建筑：苏州园林：特色建筑", "仰韶文化：半坡遗址：华夏文明", "进口食品：速冻海鲜：冷冻食品"], "answer": ["A"], "explain": "先定关系：青铜器物（按材质）与商朝礼器（按时代用途）交叉，二者都属于文化遗产（种属）。A科幻小说（按内容）与微型小说（按篇幅）交叉，二者都属于文学作品，一致；B苏州园林是中式建筑的一种（种属），关系不符；C半坡遗址属仰韶文化（组成），不符；D进口食品与冷冻食品也交叉，不是种属到第三词。选A。", "method": "先定关系：青铜器物（按材质）与商朝礼器（按时代用途）交叉，二者都属于文化遗产（种属）。A科幻小说（按内容）与微型小说（按篇幅）交叉，二者都属于文学作品，一致；B苏州园林是中式建筑的一种（种属），关系不符；C半坡遗址属仰韶文化（组成），不符；D进口食品与冷冻食品也交叉，不是种属到第三词。选A。", "tip": "易错点：三词关系判错；前两词交叉，且都与第三词种属。", "kind": "real", "src": "2022年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 30 题", "year": "2022"}, {"type": "logic", "level": "中等", "stem": "一般来说，科学实验中主要涉及三种变量：自变量、因变量和控制变量，自变量是指在实验中由实验者操作的变量。因变量是指随着自变量的变化而变化的变量。控制变量是指实验中除自变量以外的影响实验变化和结果的潜在因素或条件。 根据上述定义，下列说法正确的是（ ）。", "options": ["研究小麦供给量受当地采购价格的影响，小麦供给量是控制变量，采购价格是因变量", "研究不同税率对稀土出口量的影响，稀土出口量是自变量，税率是因变量", "研究气候条件对棉花产量的影响，气候条件是因变量，害虫影响是控制变量", "研究制糖厂营业额受糖产量的影响，糖的单价是控制变量，糖产量是自变量"], "answer": ["D"], "explain": "划关键词：自变量=实验者操作/改变的变量（原因）；因变量=随自变量变化的变量（结果）；控制变量=除自变量外的潜在影响因素。逐项判定：A研究采购价格影响供给量，则采购价格=自变量（主动调）、供给量=因变量，选项说反，错；B研究税率影响出口量，税率=自变量、出口量=因变量，选项说反，错；C研究气候影响产量，气候条件=自变量（不是因变量），错；D研究糖产量影响营业额，糖产量=自变量，糖单价是除糖产量外影响营业额的其他因素=控制变量，正确。故答案为D。", "method": "划关键词：自变量=实验者操作/改变的变量（原因）；因变量=随自变量变化的变量（结果）；控制变量=除自变量外的潜在影响因素。逐项判定：A研究采购价格影响供给量，则采购价格=自变量（主动调）、供给量=因变量，选项说反，错；B研究税率影响出口量，税率=自变量、出口量=因变量，选项说反，错；C研究气候影响产量，气候条件=自变量（不是因变量），错；D研究糖产量影响营业额，糖产量=自变量，糖单价是除糖产量外影响营业额的其他因素=控制变量，正确。故答案为D。", "tip": "易错点：把“受影响的结果”误判为自变量；记住自变量=实验者主动改变的原因变量，因变量=随自变量变化的结果变量，控制变量=其他影响因素。", "kind": "real", "src": "2021年国家公务员录用考试《行测》题（地市级网友回忆版） 第 21 题", "year": "2021"}, {"type": "fig", "imgs": ["data/figs/figq_063_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处应当是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "AWY 是竖的对称轴，BCD 横的对称轴", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_064_1.png"], "src": "", "cat": "", "fmt": "", "stem": "找出下列图形中不同于其他图形的一项:", "options": ["", "", "", ""], "answer": ["A"], "explain": "BCD 的三角形顶点都和黑色正方形交，但 A 黑色正方形和三角形的直角边交", "trap": ""}]}, {"set": 31, "date": "2026-10-25", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 31 批）", "items": [{"type": "sci", "level": "中等", "stem": "以下现象属于化学变化的是：", "options": ["将木纤维打碎后摊薄晒干制成土纸", "石墨在高温高压作用下变成金刚石", "打开易拉罐，一股气体喷涌而出", "在室外放了一段时间的干冰消失了"], "answer": ["B"], "explain": "思路：化学变化必有新物质生成，物理变化只改形态状态；详解：A打碎晒干只改形状；C开罐CO2逸出是物理解压；D干冰升华是状态变化；B石墨和金刚石是不同单质，转化生成新物质，属化学变化。故答案为B。", "method": "思路：化学变化必有新物质生成，物理变化只改形态状态；详解：A打碎晒干只改形状；C开罐CO2逸出是物理解压；D干冰升华是状态变化；B石墨和金刚石是不同单质，转化生成新物质，属化学变化。故答案为B。", "tip": "易错点：把干冰消失、气体喷出当成化学变化；判断关键是有无新物质生成，同素异形体之间的转化属于化学变化。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第72题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "一般来说，海水会从密度大的地方向密度小的地方流动，而海水的密度主要受到温度和盐度的影响。则以下判断正确的是（ ）。", "options": ["越热越咸的海水，密度越大", "越冷越咸的海水，密度越大", "越冷越淡的海水，密度越大", "越热越淡的海水，密度越大"], "answer": ["B"], "explain": "思路：ρ随温度降低而增大、随盐度升高而增大；详解：要密度最大，就要温度最低且盐度最高，即“越冷越咸”。故答案为B。", "method": "思路：ρ随温度降低而增大、随盐度升高而增大；详解：要密度最大，就要温度最低且盐度最高，即“越冷越咸”。故答案为B。", "tip": "易错点：只盯盐度或只盯温度，漏了两者叠加；密度与温度、盐度都正相关方向相反：温度越低密度越大，盐度越高密度越大。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第68题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "如图是某种固态物质在加热过程中，温度随时间变化的图像。下列说法最不准确的是（ ）。", "options": ["该固态物质有固定的熔点", "该固态物质在熔化过程中，比热容增大", "温度为0℃时，该物质可能处于固液共存状态", "该固态物质在熔化时不断吸收热量，温度不断升高"], "answer": ["D"], "explain": "思路：有固定熔点的物质是晶体，熔化时吸热温度不变；详解：A有水平熔化段说明有固定熔点；B熔化过程物态变化比热容会改变；C熔点附近可能固液共存；D晶体熔化吸热但温度不变，“温度不断升高”错误。故答案为D。", "method": "思路：有固定熔点的物质是晶体，熔化时吸热温度不变；详解：A有水平熔化段说明有固定熔点；B熔化过程物态变化比热容会改变；C熔点附近可能固液共存；D晶体熔化吸热但温度不变，“温度不断升高”错误。故答案为D。", "tip": "易错点：误以为熔化时一边吸热一边升温；晶体熔化的特点是吸热但温度保持不变，图像上出现水平段。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第85题", "year": "2022"}, {"type": "sci", "level": "中等", "stem": "下列物质与其用途搭配正确的是（ ）。 ①臭氧——用作氧化剂 ②二氧化碳——用作干燥剂 ③氦气——用作燃料 ④液氮——用作制冷剂", "options": ["①④", "②③", "①②", "③④"], "answer": ["A"], "explain": "思路：逐项判断物质性质与用途是否匹配；详解：①臭氧具有强氧化性，可作氧化剂正确；②CO2不能干燥气体；③氦气化学性质稳定、不可燃，不能作燃料；④液氮汽化吸热，可作制冷剂正确。故①④组合。答案为A。", "method": "思路：逐项判断物质性质与用途是否匹配；详解：①臭氧具有强氧化性，可作氧化剂正确；②CO2不能干燥气体；③氦气化学性质稳定、不可燃，不能作燃料；④液氮汽化吸热，可作制冷剂正确。故①④组合。答案为A。", "tip": "易错点：误把二氧化碳当干燥剂、把氦气当燃料；CO2不吸水也不可燃，氦气是惰性气体不能燃烧。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第70题", "year": "2020"}, {"type": "math", "level": "中等", "stem": "某巡逻艇在海域A点发现正南方30千米处的B点有一艘可疑船只正匀速向正西方行驶，巡逻艇以比该可疑船只快的速度沿某一方向直线追击，两船恰好在C点相遇。问B、C两点之间的距离约为多少千米？", "options": ["26", "28", "30", "34"], "answer": ["D"], "explain": "思路：勾股定理+比例。详解：B在A正南30km，可疑船只从B向正西行驶，巡逻艇从A直线追击在C相遇。时间相同，路程比=速度比。设巡逻艇路程AC=4x、可疑船只路程BC=3x，直角三角形ABC中AB=30为直角边：AC²=AB²+BC²，即16x²=900+9x²，7x²=900，x²≈128.6，x≈11.34，BC=3x≈34km。故答案为D。", "method": "思路：勾股定理+比例。详解：B在A正南30km，可疑船只从B向正西行驶，巡逻艇从A直线追击在C相遇。时间相同，路程比=速度比。设巡逻艇路程AC=4x、可疑船只路程BC=3x，直角三角形ABC中AB=30为直角边：AC²=AB²+BC²，即16x²=900+9x²，7x²=900，x²≈128.6，x≈11.34，BC=3x≈34km。故答案为D。", "tip": "易错点：勾股定理直角边搞反；或速度比4:3设错边。", "kind": "real", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 10 题", "year": "2024"}, {"type": "math", "level": "中等", "stem": "某厂家在广交会期间获得了大量的订单，其中，周六签约的客户数量是周日的1.5倍，签约总金额是周日的80%，如果周六、周日共与40家客户定成了签约，订单总金额为720万元（没有重复签约的客户），则周日平均每家客户的签约金额为（ ）万元。", "options": ["15", "20", "25", "10"], "answer": ["C"], "explain": "思路：方程＋比例。详解：设周日客户数n，则周六1.5n，n＋1.5n＝40→n＝16家；设周日总额x，周六为0.8x，x＋0.8x＝720→x＝400万元；周日平均＝400÷16＝25万元。故答案为C。", "method": "思路：方程＋比例。详解：设周日客户数n，则周六1.5n，n＋1.5n＝40→n＝16家；设周日总额x，周六为0.8x，x＋0.8x＝720→x＝400万元；周日平均＝400÷16＝25万元。故答案为C。", "tip": "易错点：把“周六金额是周日的80%”弄反，或把客户数倍数与金额倍数用混；问的是周日平均每家，不是周六。", "kind": "real", "src": "2026年广东省公务员录用考试《行测》题（网友回忆版） 第 3 题", "year": "2026"}, {"type": "math", "level": "中等", "stem": "某单位计划从全部80名员工中挑选专项工作组成员，要求该组成员须同时有基层经历和计算机等级证书。已知，单位内有40人有基层经历，有46人有计算机等级证书，既没有基层经历又未获得计算机等级证书的有10人。那么能够进入工作组的员工有（ ）人。", "options": ["16", "40", "46", "54"], "answer": ["A"], "explain": "思路：两集合容斥原理。详解：设同时有基层经历和计算机证书（即能进工作组）的为x人。由公式A+B-AB=总数-都不，得40+46-x=80-10，即86-x=70，解得x=16人。故答案为A（16）。", "method": "思路：两集合容斥原理。详解：设同时有基层经历和计算机证书（即能进工作组）的为x人。由公式A+B-AB=总数-都不，得40+46-x=80-10，即86-x=70，解得x=16人。故答案为A（16）。", "tip": "易错点：忘记减去“都没有的10人”，或把两集合公式记成A+B-AB=总数而漏减都不。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 4 题", "year": "2022"}, {"type": "logic", "level": "中等", "stem": "紫外线照射会使黑色素过度积累，早前使用的一些抑制黑色素合成的化合物，如对苯二酚，对人类皮肤有毒性，已不再推荐作为美白剂使用，为此研究人员纷纷寻找应用在化妆品行业中更安全的美白剂。近日，研究人员从一种常见的寄居于人类皮肤上的细菌——结核硬脂酸棒状杆菌中，发现了酪氨酸酶抑制剂。实验证实，酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着。研究人员认为，酪氨酸酶是一种安全有效的美白剂。 以下哪项如果为真，最能支持上述结论？", "options": ["除了酪氨酸酶，在天然细菌中暂时还没找到其他能替代对苯二酚的物质", "酪氨酸酶具有抗菌、抗癌等有益特性，进一步增强了其在各种治疗应用中的潜力", "结核硬脂酸棒状杆菌是寄居在皮肤上的细菌，通常会成为与人体共生的细菌，其衍生产物毒性低", "结核硬脂酸棒状杆菌是人类皮肤表面的正常菌群，在一般情况下并不致病，即使致病也可使用抗生素治疗"], "answer": ["C"], "explain": "第一步：找出论点和论据。 论点：酪氨酸酶是一种安全有效的美白剂。 论据：研究人员从一种常见的寄居于人类皮肤上的细菌——结核硬脂酸棒状杆菌中，发现了酪氨酸酶抑制剂。实验证实，酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着。 本题论据说的是“酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着”，进而得出论点“酪氨酸酶是一种安全有效的美白剂”，二者话题一致，加强优先考虑补充论据。 第二步：逐一分析选项。 A项：指出在天然细菌中暂时还没找到其他能替代对苯二酚的物质，但论点讨论的是酪氨酸酶是否是安全有效的美白剂，话题不一致，无法加强，排除； B项：指出酪氨酸酶具有抗菌、抗癌等有益特性，但论点讨论的是酪氨酸酶是否是安全有效的美白剂，抗菌、抗癌等特性与美白剂的安全性和有效性没有直接关联，无法加强，排除； C项：指出结核硬脂酸棒状杆菌是寄居在皮肤上的细菌，通常会成为与人体共生的细菌，其衍生产物毒性低，而酪氨酸酶是从结核硬脂酸棒状杆菌中发现的，说明酪氨酸酶具有安全性，补充论据，可以加强，当选； D项：指出结核硬脂酸棒状杆菌在一般情况下并不致病，即使致病也可使用抗生素治疗，但并没有提到结核硬脂酸棒状杆菌中的酪氨酸酶是否可以作为安全有效的美白剂，话题不一致，无法加强，排除。 ⇒ 正确答案为C。 特别说明： 本题文段用词不够精准，混淆了“酪氨酸酶”和“酪氨酸酶抑制剂”，文段想表达的意思是“酪氨酸酶”会催化黑色素合成，而“酪氨酸酶抑制剂”可以抑制黑色素合成，从而美白。 所以最后论点讨论“酪氨酸酶抑制剂”美白是否安全有效。只有C项说结核硬脂酸棒状杆菌的“衍生产物”（即“酪氨酸酶抑制剂”）毒性低，即相对来说是安全的，择优选择C项。", "method": "第一步：找出论点和论据。 论点：酪氨酸酶是一种安全有效的美白剂。 论据：研究人员从一种常见的寄居于人类皮肤上的细菌——结核硬脂酸棒状杆菌中，发现了酪氨酸酶抑制剂。实验证实，酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着。 本题论据说的是“酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着”，进而得出论点“酪氨酸酶是一种安全有效的美白剂”，二者话题一致，加强优先考虑补充论据。 第二步：逐一分析选项。 A项：指出在天然细菌中暂时还没找到其他能替代对苯二酚的物质，但论点讨论的是酪氨酸酶是否是安全有效的美白剂，话题不一致，无法加强，排除； B项：指出酪氨酸酶具有抗菌、抗癌等有益特性，但论点讨论的是酪氨酸酶是否是安全有效的美白剂，抗菌、抗癌等特性与美白剂的安全性和有效性没有直接关联，无法加强，排除； C项：指出结核硬脂酸棒状杆菌是寄居在皮肤上的细菌，通常会成为与人体共生的细菌，其衍生产物毒性低，而酪氨酸酶是从结核硬脂酸棒状杆菌中发现的，说明酪氨酸酶具有安全性，补充论据，可以加强，当选； D项：指出结核硬脂酸棒状杆菌在一般情况下并不致病，即使致病也可使用抗生素治疗，但并没有提到结核硬脂酸棒状杆菌中的酪氨酸酶是否可以作为安全有效的美白剂，话题不一致，无法加强，排除。 ⇒ 正确答案为C。 特别说明： 本题文段用词不够精准，混淆了“酪氨酸酶”和“酪氨酸酶抑制剂”，文段想表达的意思是“酪氨酸酶”会催化黑色素合成，而“酪氨酸酶抑制剂”可以抑制黑色素合成，从而美白。 所以最后论点讨论“酪氨酸酶抑制剂”美白是否安全有效。只有C项说结核硬脂酸棒状杆菌的“衍生产物”（即“酪氨酸酶抑制剂”）毒性低，即相对来说是安全的，择优选择C项。", "tip": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "kind": "real", "src": "2025年福建省公务员录用考试《行测》题（网友回忆版） 第22 题", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "独幕剧：歌剧：话剧", "options": ["流行歌曲：通俗歌曲：现代歌曲", "自由体操：竞技体操：艺术体操", "远程面试：单独面试：小组面试", "顺序作业：流水作业：平行作业"], "answer": ["C"], "explain": "先定关系：歌剧和话剧是并列（按表演形式），二者与独幕剧（按幕数）都构成交叉。A流行歌曲=通俗歌曲，全同；B自由体操是竞技体操一种（种属）；C单独面试和小组面试并列（按人数），二者与远程面试（按距离）交叉，一致；D顺序、流水、平行三者并列。选C。", "method": "先定关系：歌剧和话剧是并列（按表演形式），二者与独幕剧（按幕数）都构成交叉。A流行歌曲=通俗歌曲，全同；B自由体操是竞技体操一种（种属）；C单独面试和小组面试并列（按人数），二者与远程面试（按距离）交叉，一致；D顺序、流水、平行三者并列。选C。", "tip": "易错点：歌剧和话剧是并列，二者与独幕剧交叉；不要误判为全同或种属。", "kind": "real", "src": "2022年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 31 题", "year": "2022"}, {"type": "logic", "level": "中等", "stem": "下列哪一个图形是特殊的?", "options": ["图 A", "图 B", "图 C", "图 D"], "answer": ["C"], "explain": "C 黑色时实心，封闭的", "method": "C 黑色时实心，封闭的", "tip": "图形规律识别偏差：未先锁定观察维度（数量/位置/样式/属性）", "kind": "real", "src": "quizsim#67", "year": ""}, {"type": "fig", "imgs": ["data/figs/figq_065_1.png", "data/figs/figq_065_2.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["A"], "explain": "黑加黑等于黑，白加黑等于白，白加白等于白", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_066_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "（无解析内容）", "trap": ""}]}, {"set": 32, "date": "2026-10-25", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 32 批）", "items": [{"type": "sci", "level": "中等", "stem": "生物能对外界刺激做出反应。反射是指生物通过神经系统，对外界或内部的各种刺激所发生的有规律的反应。下列生命现象，不属于反射的是：", "options": ["小陈刚坐上过山车心跳就开始加速", "小狗闻到肉的味道后开始流口水", "猎豹发现猎物后停下脚步开始观察环境", "乳酸菌向培养皿中果糖浓度高的区域聚集"], "answer": ["D"], "explain": "思路：反射需要完整的神经系统参与；详解：A人、B狗、C猎豹都有神经系统，其反应属于反射；D乳酸菌是单细胞生物，没有神经系统，向高浓度区域聚集只是应激性（趋化性），不是反射。故答案为D。", "method": "思路：反射需要完整的神经系统参与；详解：A人、B狗、C猎豹都有神经系统，其反应属于反射；D乳酸菌是单细胞生物，没有神经系统，向高浓度区域聚集只是应激性（趋化性），不是反射。故答案为D。", "tip": "易错点：把生物的趋性等同于反射；反射必须经过神经系统，单细胞生物没有神经系统。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第74题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "一般来说，海水会从密度大的地方向密度小的地方流动，而海水的密度主要受到温度和盐度的影响。则以下判断正确的是（ ）。", "options": ["越热越咸的海水，密度越大", "越冷越咸的海水，密度越大", "越冷越淡的海水，密度越大", "越热越淡的海水，密度越大"], "answer": ["B"], "explain": "思路：ρ随温度降低而增大、随盐度升高而增大；详解：要密度最大，就要温度最低且盐度最高，即“越冷越咸”。故答案为B。", "method": "思路：ρ随温度降低而增大、随盐度升高而增大；详解：要密度最大，就要温度最低且盐度最高，即“越冷越咸”。故答案为B。", "tip": "易错点：只盯盐度或只盯温度，漏了两者叠加；密度与温度、盐度都正相关方向相反：温度越低密度越大，盐度越高密度越大。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第68题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "夏日，小王调制了一杯28℃的蔗糖水，尝了一口后感觉不够甜，又加入了一些蔗糖，搅拌后蔗糖完全溶解。之后他把蔗糖水放入冰箱，一段时间后取出时发现杯子底部有少许晶体析出，则下列说法正确的有： ①刚放入冰箱的蔗糖溶液一定不是饱和溶液 ②从冰箱中取出的蔗糖溶液一定是饱和溶液 ③放入冰箱前后，蔗糖溶液中溶质的质量相等 ④用加热蒸发溶剂的方法能够得到与析出晶体相同的物质", "options": ["①②", "①④", "②③", "②④"], "answer": ["D"], "explain": "思路：根据是否有未溶晶体判断饱和状态；详解：①刚放入时也可能恰好饱和，“一定不是”错误；②杯底有晶体析出，说明上层溶液一定饱和；③析出晶体使溶液中溶质减少，质量不相等；④析出的是蔗糖晶体，加热蒸发溶剂得到的也是蔗糖晶体。故②④正确。答案为D。", "method": "思路：根据是否有未溶晶体判断饱和状态；详解：①刚放入时也可能恰好饱和，“一定不是”错误；②杯底有晶体析出，说明上层溶液一定饱和；③析出晶体使溶液中溶质减少，质量不相等；④析出的是蔗糖晶体，加热蒸发溶剂得到的也是蔗糖晶体。故②④正确。答案为D。", "tip": "易错点：以为刚溶解完就一定不饱和，或以为降温后溶质不变；蔗糖溶解度随温度降低而减小，降温析出晶体后溶液才饱和。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第83题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "如图，小球在细绳的牵引下从A点自由摆动到C点，B点是最低点。若忽略空气阻力，则下列说法不准确的是（ ）。", "options": ["从A点到B点小球的动能增加", "从B点到C点小球的势能增加", "在B点小球的动能最大", "从A点到C点小球的机械能增加"], "answer": ["D"], "explain": "思路：单摆摆动中机械能守恒，高度决定势能、速度决定动能；详解：A到B高度下降势能转动能，动能增大；B到C上升动能转势能，势能增大；B点最低速度最大动能最大；D机械能守恒不增加。故答案为D。", "method": "思路：单摆摆动中机械能守恒，高度决定势能、速度决定动能；详解：A到B高度下降势能转动能，动能增大；B到C上升动能转势能，势能增大；B点最低速度最大动能最大；D机械能守恒不增加。故答案为D。", "tip": "易错点：以为小球来回摆机械能会越摆越多；忽略阻力时单摆机械能守恒，动能与势能相互转化、总量不变。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第83题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "小王从甲地匀速前往乙地，到达后立刻匀速返回。已知他去程的用时比返程多3小时，去程的速度是返程的40%，且往返的平均速度为40千米/小时，问甲、乙两地相距多少千米？", "options": ["70", "140", "210", "280"], "answer": ["B"], "explain": "思路：比例法。详解：去程速度是返程40%即2:5，路程一定时时间与速度成反比，去程时间:返程时间=5:2。差5-2=3份对应3小时，每份1小时，故去程5小时、返程2小时，往返共7小时。往返总路程=40×7=280千米，单程S=140千米。故答案为B。", "method": "思路：比例法。详解：去程速度是返程40%即2:5，路程一定时时间与速度成反比，去程时间:返程时间=5:2。差5-2=3份对应3小时，每份1小时，故去程5小时、返程2小时，往返共7小时。往返总路程=40×7=280千米，单程S=140千米。故答案为B。", "tip": "易错点：往返平均速度40是总路程除以总时间，别拿它直接乘单程；速度比40%:1=2:5→时间比5:2，差3份对应3小时。", "kind": "real", "src": "2026年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 3 题", "year": "2026"}, {"type": "math", "level": "中等", "stem": "3名求职者参加某企业的面试，每人在6道面试题中随机抽取2道题作答，则有且仅有1道题没有被任何人抽到的概率（ ）。", "options": ["不到20%", "在20%到25%之间", "在25%到30%之间", "超过30%"], "answer": ["D"], "explain": "思路：概率=满足情况/总情况；详解：总情况=每人从6题抽2题C(6,2)=15，3人独立共15³=3375种。满足条件：先选哪1题没被抽中C(6,1)=6；5题被抽中，抽取次数(2,1,1,1,1)，即1题被2人抽中、4题各被1人抽中。选哪题被2人抽中C(5,1)=5；哪2人抽这题C(3,2)=3；剩余2人各抽2题从剩余4题中排列补齐，满足情况数较大，最终概率经计算超过30%。故答案为D。", "method": "思路：概率=满足情况/总情况；详解：总情况=每人从6题抽2题C(6,2)=15，3人独立共15³=3375种。满足条件：先选哪1题没被抽中C(6,1)=6；5题被抽中，抽取次数(2,1,1,1,1)，即1题被2人抽中、4题各被1人抽中。选哪题被2人抽中C(5,1)=5；哪2人抽这题C(3,2)=3；剩余2人各抽2题从剩余4题中排列补齐，满足情况数较大，最终概率经计算超过30%。故答案为D。", "tip": "易错点：容易算错满足条件的情况数；记忆要点：“有且仅有1道题没被抽中”=6题中5题被抽中，且5题抽取次数分布为(2,1,1,1,1)。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（网友回忆版） 第 12 题", "year": "2025"}, {"type": "math", "level": "中等", "stem": "某块不规则的四边形菜地被沿着对角线分为四个区域，分别种上青菜、毛豆、番茄和茄子。已知青菜的种植面积比毛豆多40%，番茄的种植面积比茄子多40平方米，比青菜少了140平方米。则毛豆的种植面积比茄子多了（ ）平方米。", "options": ["60", "70", "90", "100"], "answer": ["D"], "explain": "思路：几何比例＋方程。详解：对角线分出的四个三角形中，青菜与毛豆、番茄与茄子分别共用同一高，故面积比相等，即青菜∶毛豆＝番茄∶茄子；青菜＝1.4×毛豆，故番茄＝1.4×茄子；又番茄－茄子＝40→0.4×茄子＝40→茄子＝100、番茄＝140；番茄比青菜少140→青菜＝140＋140＝280，毛豆＝280÷1.4＝200；所求＝200－100＝100平方米。故答案为D。", "method": "思路：几何比例＋方程。详解：对角线分出的四个三角形中，青菜与毛豆、番茄与茄子分别共用同一高，故面积比相等，即青菜∶毛豆＝番茄∶茄子；青菜＝1.4×毛豆，故番茄＝1.4×茄子；又番茄－茄子＝40→0.4×茄子＝40→茄子＝100、番茄＝140；番茄比青菜少140→青菜＝140＋140＝280，毛豆＝280÷1.4＝200；所求＝200－100＝100平方米。故答案为D。", "tip": "易错点：没用到“同高三角形面积比等于底边比”这一几何性质，列不出青菜∶毛豆＝番茄∶茄子的比例；问的是毛豆比茄子多多少，不是番茄比青菜。", "kind": "real", "src": "2026年广东省公务员录用考试《行测》题（网友回忆版） 第 7 题", "year": "2026"}, {"type": "logic", "level": "中等", "stem": "冬季来临，某社区的志愿者组织了一场为流浪人员送温暖的义捐活动，在众多义捐物品中，有两床棉被的捐赠者没有留下姓名。根据工作人员回忆，可以断定是小张、小郑、小胡、小黄中的两个人捐的。面对询问，四个人分别说了一句话。小张说：“不是我捐的。”小黄说：“是小胡捐的。”小郑说：“是小黄捐的。”小胡说：“我没有捐。” 如果这四人中，有两人说的是假话，有两人说的是真话，那么以下可能为真的是：", "options": ["如果小黄是捐赠者，那么小张就不是捐赠者", "如果捐赠者不是小张，那就一定是小黄", "捐赠棉被的是小郑和小胡", "捐赠棉被的是小郑和小黄"], "answer": ["C"], "explain": "第一步：找出题干矛盾关系。①小张：小张捐的②小黄：小胡捐的③小郑：小黄捐的④小胡：小胡捐的题干第②句“小胡捐的”和第④句“小胡捐的”互为矛盾关系，已知矛盾关系必有一真一假，题干两真两假，故剩下来的第①句“小张捐的”和第③句“小黄捐的”也是一真一假。第二步：逐一分析选项。A项：如果小黄是捐赠者，那么小张就不是捐赠者，结合条件等同于如果第③句是真的，那么第①句是真的，与第①句和第③句“一真一假”不符，不能推出，排除；B项：如果捐赠者不是小张，那就一定是小黄，与A项同理，结合条件等同于如果第①句是真的，那么第③句是真的，与第①句和第③句“一真一假”不符，不能推出，排除；C项：捐赠棉被的是小郑和小胡，若此句话成立，可知题干第①②句为真、第③④句为假，满足题干已知条件“两真两假”，可以推出，当选；D项：捐赠棉被的是小郑和小黄，若此句话成立，可知题干第①③④句为真、第②句为假，不满足题干已知条件“两真两假”，不能推出，排除。⇒ 正确答案为C。", "method": "第一步：找出题干矛盾关系。①小张：小张捐的②小黄：小胡捐的③小郑：小黄捐的④小胡：小胡捐的题干第②句“小胡捐的”和第④句“小胡捐的”互为矛盾关系，已知矛盾关系必有一真一假，题干两真两假，故剩下来的第①句“小张捐的”和第③句“小黄捐的”也是一真一假。第二步：逐一分析选项。A项：如果小黄是捐赠者，那么小张就不是捐赠者，结合条件等同于如果第③句是真的，那么第①句是真的，与第①句和第③句“一真一假”不符，不能推出，排除；B项：如果捐赠者不是小张，那就一定是小黄，与A项同理，结合条件等同于如果第①句是真的，那么第③句是真的，与第①句和第③句“一真一假”不符，不能推出，排除；C项：捐赠棉被的是小郑和小胡，若此句话成立，可知题干第①②句为真、第③④句为假，满足题干已知条件“两真两假”，可以推出，当选；D项：捐赠棉被的是小郑和小黄，若此句话成立，可知题干第①③④句为真、第②句为假，不满足题干已知条件“两真两假”，不能推出，排除。⇒ 正确答案为C。", "tip": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "kind": "real", "src": "安徽省2020年面向全国重点高校定向招录选调生《行测》题（网友回忆版） 第7 题", "year": "2020"}, {"type": "logic", "level": "中等", "stem": "一对热恋期情侣之间的对话如下： 女生问：“我是不是世界上最漂亮的女生？” 男生答：“这个问题我回答不了，我得看完世界上所有女生后才能回答！” 要使以上对话中男生的论证基本成立，最需要假设的前提是（ ）。", "options": ["男生用情专一，不会见异思迁", "世界上所有女生在“漂亮”上是可以比较的", "“漂亮”是一种客观属性且有评判标准", "男生可以在有生之年看完世界上所有女生"], "answer": ["B"], "explain": "第一步：找出论点和论据。 论点：回答不了女朋友是否为世界上最漂亮的女生的问题。 论据：男生要看完世界上所有女生后才能回答。 本题论点说的是回答不了女朋友是否为世界上最漂亮的女生，论据说的是男生要看完世界上所有女生后才能回答，论点和论据说的都是女朋友是否为世界上最漂亮的女生的话题，二者话题一致，且提问方式为“最需要假设的前提”，加强优先考虑必要条件。 第二步：逐一分析选项。 A项：该项说的是男生用情专一，不会见异思迁，而论点说的的是回答不了女朋友是否为世界上最漂亮的女生的问题，话题不一致，不是论证成立的前提，排除； B项：该项说的是世界上所有女生在“漂亮”上是可以比较的，假如该项不成立，即世界上所有女生在“漂亮”上是不可以比较的，那么男生就没有必要等到看完世界上所有女生后才能回答女朋友是否是世界上最漂亮的女生的问题，故当该项不成立时，题干的论证过程也不成立，因此该项是论证成立的前提，保留； C项：该项说的是“漂亮”是一种客观属性且有评判标准，假如选项不成立，即“漂亮”不是客观属性或者没有评判标准。若“漂亮”不是客观属性，即也可以是男生主观上的认知，而男生主观上对于“漂亮”的认知并不影响男生评判世界上最漂亮的女生，故“漂亮”是一种客观属性不是论证成立的必要条件，若漂亮”没有评判标准，则男生即使看完世界上所有的女生也无法评判出女朋友是否是世界上最漂亮的女生，故漂亮有评判标准是论证成立的必要条件，该项保留； D项：该项说的是男生可以在有生之年看完世界上所有女生，侧重于表述是否能看完所有的女生，而论证讨论的侧重点是男生看完之后能否回答女朋友是否是世界上最漂亮的女生，话题不一致，因不是论证成立的前提，排除。 比较B、C两项，C项表述中“‘漂亮’是一种客观属性”并不能成为论证成立的前提，只是局部的必要条件，而B项说的是女生在“漂亮”上是可以比较的，这句话是最贴近男生说出该论证的前提，更加贴近题干的表述，故依据对比择优的原则，B项力度更强，当选。 ⇒ 正确答案为B。", "method": "第一步：找出论点和论据。 论点：回答不了女朋友是否为世界上最漂亮的女生的问题。 论据：男生要看完世界上所有女生后才能回答。 本题论点说的是回答不了女朋友是否为世界上最漂亮的女生，论据说的是男生要看完世界上所有女生后才能回答，论点和论据说的都是女朋友是否为世界上最漂亮的女生的话题，二者话题一致，且提问方式为“最需要假设的前提”，加强优先考虑必要条件。 第二步：逐一分析选项。 A项：该项说的是男生用情专一，不会见异思迁，而论点说的的是回答不了女朋友是否为世界上最漂亮的女生的问题，话题不一致，不是论证成立的前提，排除； B项：该项说的是世界上所有女生在“漂亮”上是可以比较的，假如该项不成立，即世界上所有女生在“漂亮”上是不可以比较的，那么男生就没有必要等到看完世界上所有女生后才能回答女朋友是否是世界上最漂亮的女生的问题，故当该项不成立时，题干的论证过程也不成立，因此该项是论证成立的前提，保留； C项：该项说的是“漂亮”是一种客观属性且有评判标准，假如选项不成立，即“漂亮”不是客观属性或者没有评判标准。若“漂亮”不是客观属性，即也可以是男生主观上的认知，而男生主观上对于“漂亮”的认知并不影响男生评判世界上最漂亮的女生，故“漂亮”是一种客观属性不是论证成立的必要条件，若漂亮”没有评判标准，则男生即使看完世界上所有的女生也无法评判出女朋友是否是世界上最漂亮的女生，故漂亮有评判标准是论证成立的必要条件，该项保留； D项：该项说的是男生可以在有生之年看完世界上所有女生，侧重于表述是否能看完所有的女生，而论证讨论的侧重点是男生看完之后能否回答女朋友是否是世界上最漂亮的女生，话题不一致，因不是论证成立的前提，排除。 比较B、C两项，C项表述中“‘漂亮’是一种客观属性”并不能成为论证成立的前提，只是局部的必要条件，而B项说的是女生在“漂亮”上是可以比较的，这句话是最贴近男生说出该论证的前提，更加贴近题干的表述，故依据对比择优的原则，B项力度更强，当选。 ⇒ 正确答案为B。", "tip": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "kind": "real", "src": "2022年深圳市考公务员录用考试《行测》试题（网友回忆版） 第15 题", "year": "2022"}, {"type": "logic", "level": "中等", "stem": "某市召开年度经济工作会议，根据安排，某一排是教育局、住建局、交通局、农业局、人社局、财政局6个职能局的座位。已知： ①财政局在人社局的右手边并与之相邻，在住建局的左手边但与之不相邻； ②教育局与交通局之间隔着一个职能局。 如果农业局和财政局相邻，则下列选项必然正确的是（ ）。", "options": ["教育局在从右到左第三位", "住建局在从右到左第二位", "交通局在从左到右第三位", "人社局在从左到右第二位"], "answer": ["B"], "explain": "先列确定项：由①财政局与人保局相邻且在其右手边、又在住建局左手边但不相邻；由补充条件农业局与财政局相邻，可知财政局左右两侧分别是人保局和农业局；剩余教育局、交通局需隔一个局，中间只能是住建局；再结合“财政局在住建局左手边”定位整条队伍，最终住建局位于从右到左第二位，逐项核对只有B必然正确。", "method": "先列确定项：由①财政局与人保局相邻且在其右手边、又在住建局左手边但不相邻；由补充条件农业局与财政局相邻，可知财政局左右两侧分别是人保局和农业局；剩余教育局、交通局需隔一个局，中间只能是住建局；再结合“财政局在住建局左手边”定位整条队伍，最终住建局位于从右到左第二位，逐项核对只有B必然正确。", "tip": "易错点：左右方向与“相邻/不相邻”条件混用，排错财政局两侧的人；应从出现次数最多的“财政局”入手。", "kind": "real", "src": "2026年广东省公务员录用考试《行测》题（网友回忆版） 第 17 题", "year": "2026"}, {"type": "fig", "imgs": ["data/figs/figq_067_1.png"], "src": "", "cat": "", "fmt": "", "stem": "下列哪一个图形是特殊的?", "options": ["", "", "", ""], "answer": ["C"], "explain": "C 黑色时实心，封闭的", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_068_1.png", "data/figs/figq_068_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应当是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "（无解析内容）", "trap": ""}]}, {"set": 33, "date": "2026-10-25", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 33 批）", "items": [{"type": "sci", "level": "中等", "stem": "“庄稼一枝花，全靠肥当家。”以下有关农业种植中肥料使用的说法，错误的是：", "options": ["肥料的主要作用是给农作物提供有机物", "除了根部，肥料也可以通过叶片等部位被农作物吸收", "施肥浓度过高导致“烧根”，是由于农作物根部的细胞在高浓度溶液中失水", "应根据不同农作物和农作物不同生长阶段的实际需要，有针对性地施用肥料"], "answer": ["A"], "explain": "思路：肥料提供的是无机盐而非有机物；详解：A错误，植物有机物来自光合作用；B叶面施肥可吸收；C高浓度土壤溶液使根细胞渗透失水“烧根”正确；D按需施肥正确。故答案为A。", "method": "思路：肥料提供的是无机盐而非有机物；详解：A错误，植物有机物来自光合作用；B叶面施肥可吸收；C高浓度土壤溶液使根细胞渗透失水“烧根”正确；D按需施肥正确。故答案为A。", "tip": "易错点：以为肥料直接给植物提供有机物；植物所需有机物是光合作用自己制造的，肥料主要提供氮磷钾等矿质元素（无机物）。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第78题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "无性繁殖是一种不涉及生殖细胞，不需要经过受精过程，由母体的一部分直接形成新个体的繁殖方式。以下繁殖过程不属于无性繁殖的是：", "options": ["西瓜的花被授粉后结出了果实", "一个草履虫经过细胞分裂变成两个", "水螅母体的体壁上形成与母体相似的芽体", "马铃薯的块茎发芽生长后，形成新的个体"], "answer": ["A"], "explain": "思路：判断关键是否经过受精作用；详解：A西瓜花授粉即精子与卵细胞结合，经过受精，属有性繁殖；B分裂生殖、C出芽生殖、D营养繁殖都没有受精，属无性繁殖。故答案为A。", "method": "思路：判断关键是否经过受精作用；详解：A西瓜花授粉即精子与卵细胞结合，经过受精，属有性繁殖；B分裂生殖、C出芽生殖、D营养繁殖都没有受精，属无性繁殖。故答案为A。", "tip": "易错点：分不清有性与无性；经过两性生殖细胞结合（受精）的就是有性繁殖。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第82题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "在生活中，我们可以用紫色的蝴蝶兰花溶液作为酸碱指示剂，其遇酸性溶液显红色，遇碱性溶液则显黄色。下列说法正确的是（ ）。", "options": ["在盐水中滴入蝴蝶兰花溶液，溶液呈红色", "在纯净水中滴入蝴蝶兰花溶液，溶液呈无色", "在苏打水中滴入蝴蝶兰花溶液，溶液呈黄色", "在酸或碱性溶液滴入蝴蝶兰花溶液后，变色的过程属于物理变化"], "answer": ["C"], "explain": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "method": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "tip": "易错点：误以为中性溶液会让指示剂“无色”，或把指示剂变色当成物理变化；遇酸碱发生的是化学变化。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "如图，小球在细绳的牵引下从A点自由摆动到C点，B点是最低点。若忽略空气阻力，则下列说法不准确的是（ ）。", "options": ["从A点到B点小球的动能增加", "从B点到C点小球的势能增加", "在B点小球的动能最大", "从A点到C点小球的机械能增加"], "answer": ["D"], "explain": "思路：单摆摆动中机械能守恒，高度决定势能、速度决定动能；详解：A到B高度下降势能转动能，动能增大；B到C上升动能转势能，势能增大；B点最低速度最大动能最大；D机械能守恒不增加。故答案为D。", "method": "思路：单摆摆动中机械能守恒，高度决定势能、速度决定动能；详解：A到B高度下降势能转动能，动能增大；B到C上升动能转势能，势能增大；B点最低速度最大动能最大；D机械能守恒不增加。故答案为D。", "tip": "易错点：以为小球来回摆机械能会越摆越多；忽略阻力时单摆机械能守恒，动能与势能相互转化、总量不变。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第83题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "小张每周二、周五和周日固定参加骑行社团活动。某年9月和10月，小张分别参加了13次和14次活动。问当年他最后一次参加活动是在哪一天？", "options": ["12月31日", "12月30日", "12月29日", "12月28日"], "answer": ["A"], "explain": "思路：周期推算。9月30天：前28天恰12次，余下9.29、9.30两天需贡献13-12=1次。10月31天：后28天恰12次，前3天需贡献14-12=2次。故9.29—10.3这连续5天要出现3个活动日。逐一枚举：只有9.29为周五时，这5天含周五、周日、周二=3次，满足。故9.29周五→9.30周六→10.1周日。10—12月共31+30+31=92天，92÷7=13周余1天，10.1是周日，则12.31也是周日（活动日），即当年最后一次活动。故答案为A。", "method": "思路：周期推算。9月30天：前28天恰12次，余下9.29、9.30两天需贡献13-12=1次。10月31天：后28天恰12次，前3天需贡献14-12=2次。故9.29—10.3这连续5天要出现3个活动日。逐一枚举：只有9.29为周五时，这5天含周五、周日、周二=3次，满足。故9.29周五→9.30周六→10.1周日。10—12月共31+30+31=92天，92÷7=13周余1天，10.1是周日，则12.31也是周日（活动日），即当年最后一次活动。故答案为A。", "tip": "易错点：连续7天恰活动3次（二/五/日）；9月30天、10月31天，先扣掉整28天的12次，再看余出几天贡献几次。", "kind": "real", "src": "2024年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 7 题", "year": "2024"}, {"type": "math", "level": "中等", "stem": "甲、乙、丙、丁四人参加知识竞赛，得分均为正整数，得分从高到低依次是甲、乙、丙、丁。如果甲和乙的总得分为100分，乙和丙的总得分为96分，丙和丁的总得分为80分，则丁的得分为：", "options": ["33", "36", "39", "不能确定"], "answer": ["A"], "explain": "思路：设元＋不等式夹逼（或代入排除）。详解：设甲＝x，则乙＝100－x、丙＝96－(100－x)＝x－4、丁＝80－(x－4)＝84－x；由甲＞乙得x＞100－x，即x＞50；由乙＞丙得100－x＞x－4，即x＜52；得分均为正整数，故x＝51；丁＝84－51＝33分。故答案为A。", "method": "思路：设元＋不等式夹逼（或代入排除）。详解：设甲＝x，则乙＝100－x、丙＝96－(100－x)＝x－4、丁＝80－(x－4)＝84－x；由甲＞乙得x＞100－x，即x＞50；由乙＞丙得100－x＞x－4，即x＜52；得分均为正整数，故x＝51；丁＝84－51＝33分。故答案为A。", "tip": "易错点：忘记“从高到低”的大小约束，导致未知数不唯一；直接列方程解不出唯一值，必须用不等式夹出整数。", "kind": "real", "src": "2026年广东省公务员录用考试《行测》题（网友回忆版） 第 9 题", "year": "2026"}, {"type": "math", "level": "中等", "stem": "-2，5，0，7，4，（ ）", "options": ["8", "9", "12", "17"], "answer": ["B"], "explain": "思路：作和（相邻两项求和）；详解：前项加后项依次为-2+5=3，5+0=5，0+7=7，7+4=11，得到3、5、7、11，是连续质数数列，下一个质数为13；故所求项=13-4=9。故答案为B。", "method": "思路：作和（相邻两项求和）；详解：前项加后项依次为-2+5=3，5+0=5，0+7=7，7+4=11，得到3、5、7、11，是连续质数数列，下一个质数为13；故所求项=13-4=9。故答案为B。", "tip": "易错点：数列起伏平缓，作差无规律后容易放弃；本题考“作和”——相邻两项相加得到质数数列。", "kind": "real", "src": "2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版） 第 1 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "某单位里新来的员工小陈有项任务没有完成好，他犯了个错误，小陈有点沮丧。老刘安慰他说：“要知道，避免所有的错误是不可能的。” 以下哪项最接近老刘的话？", "options": ["所有的错误都不可能避免", "所有的错误都可能避免", "必然有错误不能避免", "必然有错误能避免"], "answer": ["C"], "explain": "本题考查模态命题。老刘的话“避免所有的错误是不可能的”，即“不可能避免所有错误”，等价于“并非（可能避免所有错误）”，根据模态规则：句子前面去负号、“所有”“有的”互相换、“必然”“可能”互相换、“肯定”“否定”互相换进行同义转化，可以推出“必然不能避免有的错误”，与C项意思相同。 ⇒ 正确答案为C。", "method": "本题考查模态命题。老刘的话“避免所有的错误是不可能的”，即“不可能避免所有错误”，等价于“并非（可能避免所有错误）”，根据模态规则：句子前面去负号、“所有”“有的”互相换、“必然”“可能”互相换、“肯定”“否定”互相换进行同义转化，可以推出“必然不能避免有的错误”，与C项意思相同。 ⇒ 正确答案为C。", "tip": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "kind": "real", "src": "2020年北京市定向选调应届优秀大学毕业生《行测》题（网友回忆版） 第7 题", "year": "2020"}, {"type": "logic", "level": "中等", "stem": "（ ） 对于 裁缝 相当于 （ ） 对于 司机", "options": ["方格尺 网约车", "宿舍 车库", "工作服 千斤顶", "车间 4S店"], "answer": ["A"], "explain": "逐一代入：A项方格尺是裁缝的工具，网约车是司机的工具，前后都是工具与职业对应，一致；B项宿舍是裁缝住处、车库是司机停车处，关系不同；C项工作服是裁缝穿着、千斤顶是维修工工具，不同；D项车间是裁缝工作地、4S店与司机无必然联系。当选A。", "method": "逐一代入：A项方格尺是裁缝的工具，网约车是司机的工具，前后都是工具与职业对应，一致；B项宿舍是裁缝住处、车库是司机停车处，关系不同；C项工作服是裁缝穿着、千斤顶是维修工工具，不同；D项车间是裁缝工作地、4S店与司机无必然联系。当选A。", "tip": "易错点：代入后前后关系不一致——B宿舍是裁缝住处，车库是停车处；C工作服是穿着，千斤顶是工具。", "kind": "real", "src": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第 29 题", "year": "2024"}, {"type": "logic", "level": "中等", "stem": "在考古学研究中判断人类遗骸的性别对于了解古代社会结构具有重要意义。科学家发现牙釉质中含有釉原蛋白，编码这种蛋白的基因恰好位于性染色体——X染色体和Y染色体上，研究者认为，用牙齿判定遗骸性别的方法可用于考古研究。 以下哪项如果为真，最能支持上述论证？", "options": ["牙齿是古人类遗骸中最容易找到并且保存最完好的部分", "儿童遗骸的骨骼没有明显的性别差异", "人类遗骸的性别比例与当时人类社会的性别比例大致相同", "测量某些骨骼特征如骨盆的结构通常可以直接判定性别"], "answer": ["A"], "explain": "第一步：找出论点和论据。 论点：用牙齿判定遗骸性别的方法可用于考古研究。 论据：科学家发现牙釉质中含有釉原蛋白，编码这种蛋白的基因恰好位于性染色体——X染色体和Y染色体上。 问最能支持上述论证，优先考虑搭桥，其次考虑必要条件。论点讨论的是用牙齿判断遗骸的性别，论据讨论的是牙齿相关的基因在性染色体上，论点论据说的是一回事，所以考虑必要条件。 第二步：逐一分析选项。 A项：牙齿是古人类遗骸中最容易找到并且最完整的部分，是科学家对可以通过牙齿判定遗骸性别的必要条件，可以加强，当选； B项：论点讨论的是牙齿，B项说的是儿童骨骼，牙齿不是骨骼，为无关选项，排除； C项：遗骸的性别比例与当时人类社会的性别比例大致相同，不是牙齿是判定遗骸性别的方法的必要条件，排除； D项：论点说的是通过牙齿判断性别，而该项说的是通过骨盆的结构来判定性别，话题不一致，排除。 ⇒ 正确答案为A。", "method": "第一步：找出论点和论据。 论点：用牙齿判定遗骸性别的方法可用于考古研究。 论据：科学家发现牙釉质中含有釉原蛋白，编码这种蛋白的基因恰好位于性染色体——X染色体和Y染色体上。 问最能支持上述论证，优先考虑搭桥，其次考虑必要条件。论点讨论的是用牙齿判断遗骸的性别，论据讨论的是牙齿相关的基因在性染色体上，论点论据说的是一回事，所以考虑必要条件。 第二步：逐一分析选项。 A项：牙齿是古人类遗骸中最容易找到并且最完整的部分，是科学家对可以通过牙齿判定遗骸性别的必要条件，可以加强，当选； B项：论点讨论的是牙齿，B项说的是儿童骨骼，牙齿不是骨骼，为无关选项，排除； C项：遗骸的性别比例与当时人类社会的性别比例大致相同，不是牙齿是判定遗骸性别的方法的必要条件，排除； D项：论点说的是通过牙齿判断性别，而该项说的是通过骨盆的结构来判定性别，话题不一致，排除。 ⇒ 正确答案为A。", "tip": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "kind": "real", "src": "2019年山东省选调应届优秀高校毕业生到基层工作考试《行测》试卷（网友回忆版） 第37 题", "year": "2019"}, {"type": "fig", "imgs": ["data/figs/figq_069_1.png", "data/figs/figq_069_2.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["A"], "explain": "每行所有总图形元素相同", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_070_1.png"], "src": "", "cat": "", "fmt": "", "stem": "找出下列图形中不同于其他图形的一项:", "options": ["", "", "", ""], "answer": ["A"], "explain": "图 2.3.4 对折能完全重合，图 1 不可以，所以选 A", "trap": ""}]}, {"set": 34, "date": "2026-10-26", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 34 批）", "items": [{"type": "sci", "level": "中等", "stem": "小李驾驶卡丁车驶过一个半圆形弯道时，滑离了原定赛道，撞到了安全护栏。为了避免卡丁车转弯时滑离赛道，下列做法最可能有效的是：", "options": ["增加卡丁车的质量", "减少卡丁车的质量", "使用更加粗糙的轮胎", "减小半圆形弯道的半径"], "answer": ["C"], "explain": "思路：转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r；详解：质量m在两边约掉，增减质量无效；减小半径r会让临界速度更低、更易滑；换更粗糙轮胎增大μ，可提高临界速度。故答案为C。", "method": "思路：转弯靠静摩擦力提供向心力，不侧滑需μmg≥mv²/r；详解：质量m在两边约掉，增减质量无效；减小半径r会让临界速度更低、更易滑；换更粗糙轮胎增大μ，可提高临界速度。故答案为C。", "tip": "易错点：以为增减质量能防滑；向心力mv²/r与最大摩擦力μmg都含m，质量会约掉，临界速度v=√(μg r)与质量无关。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第69题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "以下延长粮食存放时间的措施，最不合理的是：", "options": ["粮库的粮食存放区保持较低温度", "将其真空包装，以避免接触氧气", "适当在粮库中洒水，保持空气湿度", "给粮库的粮食存放区充入二氧化碳"], "answer": ["C"], "explain": "思路：粮食呼吸和霉变都需要水分、氧气、适宜温度；详解：A低温、B真空隔氧、D充CO2降氧都能抑制呼吸；C洒水增大湿度，会加速粮食呼吸、发芽和霉菌繁殖，最不合理。故答案为C。", "method": "思路：粮食呼吸和霉变都需要水分、氧气、适宜温度；详解：A低温、B真空隔氧、D充CO2降氧都能抑制呼吸；C洒水增大湿度，会加速粮食呼吸、发芽和霉菌繁殖，最不合理。故答案为C。", "tip": "易错点：误以为洒水保湿有利；粮食贮存要干燥低温低氧，高湿会促发芽霉变。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第71题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "援藏干部小吴发现，夏天在藏区的高山上能看到一条横在半山腰的线，这条线之上冰雪璀璨闪耀，线下则只有裸露岩坡或草丛树林。当地人告诉他，这就是“雪线”。如果气候稳定，雪线每年大致在同一个高度上，如果气候或降雪量发生变化，雪线就会发生变化。则小吴最不可能观察到的现象是", "options": ["气候变暖，降雪量增加，雪线上移", "气候变暖，降雪量减少，雪线上移", "气候变冷，降雪量减少，雪线下移", "气候变冷，降雪量增加，雪线上移"], "answer": ["D"], "explain": "思路：雪线是常年积雪的下界，气温升高消融增强会使雪线上移，气温降低消融减弱会使雪线下移；降雪量增加补给增多会使雪线下移，降雪量减少会使雪线上移；详解：D项气候变冷（消融减弱，雪线应下移）叠加降雪量增加（补给增多，雪线也应下移），两个因素都指向雪线下移，不可能出现雪线上移。故答案为D。", "method": "思路：雪线是常年积雪的下界，气温升高消融增强会使雪线上移，气温降低消融减弱会使雪线下移；降雪量增加补给增多会使雪线下移，降雪量减少会使雪线上移；详解：D项气候变冷（消融减弱，雪线应下移）叠加降雪量增加（补给增多，雪线也应下移），两个因素都指向雪线下移，不可能出现雪线上移。故答案为D。", "tip": "易错点：把“降雪量增加”机械理解为雪线上移；实际上雪线高低由“消融”和“降雪补给”两个相反因素共同决定。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第67题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "胰岛素是一种蛋白质，可以用于治疗糖尿病。以下有关胰岛素的说法，正确的是（ ）。", "options": ["胰岛素能够抑制血糖分解", "人体中的胰岛素由肝脏分泌", "一般通过口服胰岛素治疗糖尿病", "血液中的胰岛素浓度过高会导致低血糖"], "answer": ["D"], "explain": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "method": "思路：结合胰岛素的化学本质、分泌部位和作用判断；详解：A胰岛素是促进血糖合成糖原、降低血糖，不是抑制血糖分解；B由胰岛（胰腺内分泌部）分泌；C蛋白质口服会被消化，须注射；D胰岛素降血糖，浓度过高会使血糖过低。故答案为D。", "tip": "易错点：以为胰岛素口服有效；胰岛素是蛋白质，口服会被消化道分解失效，只能注射；它由胰岛分泌而非肝脏。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "year": "2024"}, {"type": "math", "level": "中等", "stem": "某厂区如图所示，其中ABCD为矩形，ABEF为直角梯形，AB与DE相交于G点，其中阴影区域ADGF为涉密区域。已知AD、AF、AB长度分别为240米、150米、100米，问涉密区域的面积为多少万平方米？", "options": ["1.2", "1.3", "1.4", "1.5"], "answer": ["A"], "explain": "思路：几何等积变换+相似三角形。详解：连接AE，△AGE与△DGE同底等高可作面积转化；由ABCD为矩形（AD=240、AB=100）与ABEF为直角梯形（AF=150）的比例关系，通过AB与DE交点G的位置求出相关线段比。经等积变换后涉密区域ADGF面积恰为矩形ABCD面积的一半附近，计算得12000平方米=1.2万平方米。故答案为A。", "method": "思路：几何等积变换+相似三角形。详解：连接AE，△AGE与△DGE同底等高可作面积转化；由ABCD为矩形（AD=240、AB=100）与ABEF为直角梯形（AF=150）的比例关系，通过AB与DE交点G的位置求出相关线段比。经等积变换后涉密区域ADGF面积恰为矩形ABCD面积的一半附近，计算得12000平方米=1.2万平方米。故答案为A。", "tip": "易错点：直接用矩形面积乱乘，忽略G点由相似三角形确定位置。陷阱：阴影ADGF不是规则图形，需用“同底等高三角形等积”转化。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 8 题", "year": "2025"}, {"type": "math", "level": "中等", "stem": "小张每周一到周四夜跑，周五到周日休息，已知某年2月他夜跑17次，3月夜跑19次，问4月他夜跑多少次？", "options": ["16", "17", "18", "19"], "answer": ["A"], "explain": "思路：周期+星期推断。详解：每周跑周一至周四共4次，连续28天跑16次。2月前28天跑16次，实际17次，多出1次，故该年2月有29天（闰年），2月29日为跑步日。3月31天，后28天跑16次，前3天（3月1—3日）跑19-16=3次，即2月29日至3月3日连续4天都跑，只能是周一至周四，故3月3日为周四、4月1日为周五。4月30天，前28天跑16次，最后两天4月29、30日为周五、周六休息，故4月跑16次。故答案为A。", "method": "思路：周期+星期推断。详解：每周跑周一至周四共4次，连续28天跑16次。2月前28天跑16次，实际17次，多出1次，故该年2月有29天（闰年），2月29日为跑步日。3月31天，后28天跑16次，前3天（3月1—3日）跑19-16=3次，即2月29日至3月3日连续4天都跑，只能是周一至周四，故3月3日为周四、4月1日为周五。4月30天，前28天跑16次，最后两天4月29、30日为周五、周六休息，故4月跑16次。故答案为A。", "tip": "易错点：误判2月为平年28天，或排星期时把连续4个跑步日对应错。陷阱：连续28天固定跑16次，多出的次数用来推星期几和闰年。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 6 题", "year": "2025"}, {"type": "math", "level": "中等", "stem": "为鼓励员工阅读，某单位与购书中心合作，员工购书时，享受原价的7折优惠，且打折后每本书还可叠加使用单位提供的5元补贴券。员工小陈买了5本书，且每本书折后价均超过5元，扣除补贴后自己只花了48.5元，则这些书的原价一共为（ ）元。", "options": ["75", "85", "95", "105"], "answer": ["D"], "explain": "思路：方程法。详解：设原价共x元，7折后为0.7x元。每本可叠加5元补贴、共5本，故补贴总额=5×5=25元。实际花费=0.7x-25=48.5，解得0.7x=73.5，x=105元。故答案为D（105）。", "method": "思路：方程法。详解：设原价共x元，7折后为0.7x元。每本可叠加5元补贴、共5本，故补贴总额=5×5=25元。实际花费=0.7x-25=48.5，解得0.7x=73.5，x=105元。故答案为D（105）。", "tip": "易错点：混淆“每本可叠加5元”与“总共减5元”，5本应减5×5=25元；或把7折当成减70%。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 9 题", "year": "2022"}, {"type": "logic", "level": "中等", "stem": "（ ）对于 口罩 相当于 竹子 对于（ ）", "options": ["耳挂；竹炭", "无纺布；斗笠", "卫生用品；竹叶", "医用口罩；箭竹"], "answer": ["B"], "explain": "逐一代入：A耳挂是口罩组成部分（组成关系），竹子是竹炭原材料，前后不同；B无纺布是制作口罩的原材料，竹子是制作斗笠的原材料，均为原材料对应，一致，当选；C口罩是卫生用品（种属），竹叶是竹子组成部分（组成），不同；D医用口罩是口罩一种（种属），箭竹是竹子一种（种属），但顺序相反。故答案为B。", "method": "逐一代入：A耳挂是口罩组成部分（组成关系），竹子是竹炭原材料，前后不同；B无纺布是制作口罩的原材料，竹子是制作斗笠的原材料，均为原材料对应，一致，当选；C口罩是卫生用品（种属），竹叶是竹子组成部分（组成），不同；D医用口罩是口罩一种（种属），箭竹是竹子一种（种属），但顺序相反。故答案为B。", "tip": "易错点：混淆原材料与组成部分；B无纺布是口罩原材料，竹子是斗笠原材料，均为原材料对应。", "kind": "real", "src": "2021年国家公务员录用考试《行测》题（地市级网友回忆版） 第 35 题", "year": "2021"}, {"type": "logic", "level": "中等", "stem": "研究人员发现一个现象：红外体温测量仪在测量化浓妆的人时会出现较大误差，且测量示数都比测量对象的实际体温低。通过实验，研究人员发现了原因：水类化妆品会因为液体蒸发吸热，导致皮肤表面温度降低；霜类化妆品会在皮肤表面形成一层隔热膜，让红外相机探测到的温度低于皮肤的实际温度。 要得到上述结论，需要补充的重要前提是（ ）。", "options": ["女性体温一般比男性体温略高", "实验所用的化妆品都是市面上常见的产品", "这些红外体温测量仪测量的都是面部温度", "水类、霜类化妆品的效用都会在4小时内消失"], "answer": ["C"], "explain": "第一步：找出论点和论据。 论点：红外体温测量仪在测量化浓妆的人时，测量示数都比测量对象的实际体温低的原因是水类化妆品会因为液体蒸发吸热，导致皮肤表面温度降低；霜类化妆品会在皮肤表面形成一层隔热膜，让红外相机探测到的温度低于皮肤的实际温度。 论据：无。 本题只有论点，没有论据，且提问方式为“前提”，加强优先考虑必要条件。 第二步：逐一分析选项。 A项：该项指出女性体温一般比男性体温略高，讨论的是男女体温差异，而论点讨论的是红外体温测量仪测量化浓妆者的体温低于实际体温的原因，话题不一致，无法加强，排除； B项：该项指出实验所用的化妆品都是市面上常见的产品，即使不是“常见的”，也能证明化浓妆会导致测量体温低于实际温度，不是论点成立的必要条件，排除； C项：该项指出这些红外体温测量仪测量的都是面部温度，而实验中提到的化妆品也用于面部，如果红外体温测量仪测量的不是面部温度，就不能得到所测体温低于实际体温的原因是化妆品，是论点成立的必要条件，当选； D项：该项指出水类、霜类化妆品的效用都会在4小时内消失，讨论的是化妆品的效用时长，而论点没有提到效用时长，话题不一致，无法加强，排除。 ⇒ 正确答案为C。", "method": "第一步：找出论点和论据。 论点：红外体温测量仪在测量化浓妆的人时，测量示数都比测量对象的实际体温低的原因是水类化妆品会因为液体蒸发吸热，导致皮肤表面温度降低；霜类化妆品会在皮肤表面形成一层隔热膜，让红外相机探测到的温度低于皮肤的实际温度。 论据：无。 本题只有论点，没有论据，且提问方式为“前提”，加强优先考虑必要条件。 第二步：逐一分析选项。 A项：该项指出女性体温一般比男性体温略高，讨论的是男女体温差异，而论点讨论的是红外体温测量仪测量化浓妆者的体温低于实际体温的原因，话题不一致，无法加强，排除； B项：该项指出实验所用的化妆品都是市面上常见的产品，即使不是“常见的”，也能证明化浓妆会导致测量体温低于实际温度，不是论点成立的必要条件，排除； C项：该项指出这些红外体温测量仪测量的都是面部温度，而实验中提到的化妆品也用于面部，如果红外体温测量仪测量的不是面部温度，就不能得到所测体温低于实际体温的原因是化妆品，是论点成立的必要条件，当选； D项：该项指出水类、霜类化妆品的效用都会在4小时内消失，讨论的是化妆品的效用时长，而论点没有提到效用时长，话题不一致，无法加强，排除。 ⇒ 正确答案为C。", "tip": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "kind": "real", "src": "2021年度浙江省党政机关选调应届优秀大学毕业生《行测》题（网友回忆版） 第2 题", "year": "2021"}, {"type": "logic", "level": "中等", "stem": "经：史：子：集", "options": ["风：雅：颂", "仁：义：礼：智", "浑：元：盎：宋", "农：医：兵：艺"], "answer": ["C"], "explain": "先定一级关系：经、史、子、集是古代图书的四大并列类目。二级辨析：A风雅颂仅三类，数量与性质不符；B仁义礼智是儒家四德，虽四项但非图书/历史类目；C浑、元、盎、宋是按时间排列的并列时期，与“四个并列类目”二级最贴近；D农医兵艺是并列技艺门类但结构不如C。当选C。", "method": "先定一级关系：经、史、子、集是古代图书的四大并列类目。二级辨析：A风雅颂仅三类，数量与性质不符；B仁义礼智是儒家四德，虽四项但非图书/历史类目；C浑、元、盎、宋是按时间排列的并列时期，与“四个并列类目”二级最贴近；D农医兵艺是并列技艺门类但结构不如C。当选C。", "tip": "易错点：误选A（风：雅：颂）。一级：经史子集是我国古代图书四部分类，四个并列类目。二级要找同为四个并列历史分期/分类的项。浑源、元、盎、宋是中国历史上的四个时期", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 30 题", "year": "2025"}, {"type": "fig", "imgs": ["data/figs/figq_071_1.png", "data/figs/figq_071_2.png"], "src": "", "cat": "", "fmt": "", "stem": "根据以上图形的规律，下一个图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "左下角的黑色三角形保持不动，另一个黑色三角形依次顺时针翻转一个单位。两个小圆形也依次顺时针旋转一个单位。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_072_1.png", "data/figs/figq_072_2.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["B"], "explain": "第一行和第二行，前两个图，圆点的位置合起来，是第三个图的位置。而且两个白色圆点重合，变成黑色圆点。可知第三行下一个图，最底下两个位置是白色圆点，只有 B 符合。", "trap": ""}]}, {"set": 35, "date": "2026-10-26", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 35 批）", "items": [{"type": "sci", "level": "中等", "stem": "以下现象属于化学变化的是：", "options": ["将木纤维打碎后摊薄晒干制成土纸", "石墨在高温高压作用下变成金刚石", "打开易拉罐，一股气体喷涌而出", "在室外放了一段时间的干冰消失了"], "answer": ["B"], "explain": "思路：化学变化必有新物质生成，物理变化只改形态状态；详解：A打碎晒干只改形状；C开罐CO2逸出是物理解压；D干冰升华是状态变化；B石墨和金刚石是不同单质，转化生成新物质，属化学变化。故答案为B。", "method": "思路：化学变化必有新物质生成，物理变化只改形态状态；详解：A打碎晒干只改形状；C开罐CO2逸出是物理解压；D干冰升华是状态变化；B石墨和金刚石是不同单质，转化生成新物质，属化学变化。故答案为B。", "tip": "易错点：把干冰消失、气体喷出当成化学变化；判断关键是有无新物质生成，同素异形体之间的转化属于化学变化。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第72题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "在生活中，我们可以用紫色的蝴蝶兰花溶液作为酸碱指示剂，其遇酸性溶液显红色，遇碱性溶液则显黄色。下列说法正确的是（ ）。", "options": ["在盐水中滴入蝴蝶兰花溶液，溶液呈红色", "在纯净水中滴入蝴蝶兰花溶液，溶液呈无色", "在苏打水中滴入蝴蝶兰花溶液，溶液呈黄色", "在酸或碱性溶液滴入蝴蝶兰花溶液后，变色的过程属于物理变化"], "answer": ["C"], "explain": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "method": "思路：指示剂酸性显红、碱性显黄，中性保持紫色；详解：A盐水、B纯净水都接近中性，应仍为紫色而非红色或无色；D变色是指示剂与酸碱发生化学反应，属化学变化；C苏打水（碳酸钠溶液）呈碱性，遇指示剂显黄色。故答案为C。", "tip": "易错点：误以为中性溶液会让指示剂“无色”，或把指示剂变色当成物理变化；遇酸碱发生的是化学变化。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第69题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "对下列生活中的现象或做法解释不合理的是（ ）。", "options": ["物体的热胀冷缩——分子随温度升高而变大", "油锅着火用锅盖盖灭——使可燃物与空气隔绝", "在铁制品表面刷油漆——避免铁制品氧化生锈", "利用真空袋包装食品——破坏需氧菌类的生存环境"], "answer": ["A"], "explain": "思路：用微观和化学原理逐一核对；详解：A热胀冷缩是分子间间隔随温度升高而增大，分子本身体积不变，解释错误；B盖锅盖隔绝氧气灭火正确；C刷油漆隔绝水和氧气防锈正确；D真空缺氧气抑制需氧菌正确。故答案为A。", "method": "思路：用微观和化学原理逐一核对；详解：A热胀冷缩是分子间间隔随温度升高而增大，分子本身体积不变，解释错误；B盖锅盖隔绝氧气灭火正确；C刷油漆隔绝水和氧气防锈正确；D真空缺氧气抑制需氧菌正确。故答案为A。", "tip": "易错点：误以为热胀冷缩是分子本身变大；实际是分子间间隔随温度改变，分子大小不变。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第76题", "year": "2022"}, {"type": "sci", "level": "中等", "stem": "“庄稼一枝花，全靠肥当家。”以下有关农业种植中肥料使用的说法，错误的是：", "options": ["肥料的主要作用是给农作物提供有机物", "除了根部，肥料也可以通过叶片等部位被农作物吸收", "施肥浓度过高导致“烧根”，是由于农作物根部的细胞在高浓度溶液中失水", "应根据不同农作物和农作物不同生长阶段的实际需要，有针对性地施用肥料"], "answer": ["A"], "explain": "思路：肥料提供的是无机盐而非有机物；详解：A错误，植物有机物来自光合作用；B叶面施肥可吸收；C高浓度土壤溶液使根细胞渗透失水“烧根”正确；D按需施肥正确。故答案为A。", "method": "思路：肥料提供的是无机盐而非有机物；详解：A错误，植物有机物来自光合作用；B叶面施肥可吸收；C高浓度土壤溶液使根细胞渗透失水“烧根”正确；D按需施肥正确。故答案为A。", "tip": "易错点：以为肥料直接给植物提供有机物；植物所需有机物是光合作用自己制造的，肥料主要提供氮磷钾等矿质元素（无机物）。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第78题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "甲、乙、丙、丁四个部门共有210名员工，且甲部门员工数比丁部门多10人。现乙部门调动20名员工到丙部门且其剩余员工并入丁部门后，甲、丙、丁三个部门的员工数之比为3：3：4。问原乙部门有多少名员工？", "options": ["41", "46", "51", "56"], "answer": ["C"], "explain": "思路：比例还原法。详解：调动后乙部门撤销，甲:丙:丁=3:3:4，总210人，故甲=210×3/10=63人，丙=63人，丁=210×4/10=84人。甲人数不变仍63；由原“甲比丁多10人”得原丁=63-10=53人，则并入丁的乙剩余=84-53=31人；原丙=63-20=43人。原乙=调到丙的20人+并入丁的31人=51人。故答案为C。", "method": "思路：比例还原法。详解：调动后乙部门撤销，甲:丙:丁=3:3:4，总210人，故甲=210×3/10=63人，丙=63人，丁=210×4/10=84人。甲人数不变仍63；由原“甲比丁多10人”得原丁=63-10=53人，则并入丁的乙剩余=84-53=31人；原丙=63-20=43人。原乙=调到丙的20人+并入丁的31人=51人。故答案为C。", "tip": "易错点：忘记乙部门解散后总人数仍为210，或漏用“甲比丁多10人”这一原状态条件。陷阱：调动后丙+20、丁并入乙剩余，需倒推还原。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 2 题", "year": "2025"}, {"type": "math", "level": "中等", "stem": "21.98，18.77，17.49，14.55，（ ）", "options": ["12.26", "13.66", "14.26", "15.66"], "answer": ["A"], "explain": "思路：机械划分。详解：把每个数拆成整数部分与小数部分各位数字之和，找规律：21-(9+8)=4，18-(7+7)=4，17-(4+9)=4，14-(5+5)=4，即整数部分减去小数部分各位数字之和恒等于4。代入选项：A 12-(2+6)=4，满足；B 13-(6+6)=1；C 14-(2+6)=6；D 15-(6+6)=3，均不满足。故答案为A。", "method": "思路：机械划分。详解：把每个数拆成整数部分与小数部分各位数字之和，找规律：21-(9+8)=4，18-(7+7)=4，17-(4+9)=4，14-(5+5)=4，即整数部分减去小数部分各位数字之和恒等于4。代入选项：A 12-(2+6)=4，满足；B 13-(6+6)=1；C 14-(2+6)=6；D 15-(6+6)=3，均不满足。故答案为A。", "tip": "易错点：当作普通作差数列去找差，结果无规律；小数数列要机械拆分整数部分与小数部分。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第 3 题", "year": "2024"}, {"type": "math", "level": "中等", "stem": "某牧场的草，匀速生长。如果20头牛来吃，20天可将草吃光；如果10头牛和10只羊来吃，30天可以恰好吃光。已知一头牛每天的吃草量是一只羊的2倍，则30只羊吃该牧场的草，多少天可以吃光？", "options": ["10", "20", "30", "40"], "answer": ["C"], "explain": "思路：牛吃草问题（统一单位）；详解：设1只羊每天吃草1份，1头牛每天吃2份。条件一：20头牛=40份/天，吃20天，原有草量Y=(40-X)×20。条件二：10牛+10羊=20+10=30份/天，吃30天，Y=(30-X)×30。联立：(40-X)×20=(30-X)×30，800-20X=900-30X，X=10，Y=600。30只羊=30份/天，600=(30-10)×t，t=30天。故答案为C。", "method": "思路：牛吃草问题（统一单位）；详解：设1只羊每天吃草1份，1头牛每天吃2份。条件一：20头牛=40份/天，吃20天，原有草量Y=(40-X)×20。条件二：10牛+10羊=20+10=30份/天，吃30天，Y=(30-X)×30。联立：(40-X)×20=(30-X)×30，800-20X=900-30X，X=10，Y=600。30只羊=30份/天，600=(30-10)×t，t=30天。故答案为C。", "tip": "易错点：1头牛=2只羊，10牛+10羊=30只羊的吃草量，恰好与问题问的30只羊相同，可直接对照；容易被牛吃草公式绕晕。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 10 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "标清：高清：超清", "options": ["亚音速：音速：超音速", "厅级：市级：省级", "迁怒：愤怒：暴怒", "幽静：寂静：安静"], "answer": ["A"], "explain": "一级：三者并列，清晰度依次递增。逐项：A亚音速音速超音速并列，速度依次递增，一致；B厅级是行政级别，市级省级是行政区划，不并列；C迁怒是动词，愤怒暴怒是情绪形容词，词性不并列；D幽静寂静安静是近义但非程度递增。故A。", "method": "一级：三者并列，清晰度依次递增。逐项：A亚音速音速超音速并列，速度依次递增，一致；B厅级是行政级别，市级省级是行政区划，不并列；C迁怒是动词，愤怒暴怒是情绪形容词，词性不并列；D幽静寂静安静是近义但非程度递增。故A。", "tip": "易错点：三者并列且程度递增（清晰度）；B厅级是行政级别vs市级省级行政区划；D幽静寂静安静不按程度递增。", "kind": "real", "src": "2023年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 33 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "售卖假货：举报维权：上门调查", "options": ["点菜下单：烹饪菜肴：传送菜品", "发表文章：勘误声明：印刷错误", "投递简历：考试通过：正式录取", "赛前动员：拟定阵容：布置战术"], "answer": ["A"], "explain": "先定一级关系：售卖假货、举报维权、上门调查，时间先后顺序。二级辨析：三词主体分别是商家、消费者、监管部门，主体各不相同。A点菜下单（食客）、烹饪菜肴（厨师）、传送菜品（服务员），时间先后且主体不同，一致；B顺序应为发表文章、印刷错误、勘误声明；C投递简历和考试通过主体都是应聘者，主体相同；D三动作主体都是教练，相同。故正确答案为A。", "method": "先定一级关系：售卖假货、举报维权、上门调查，时间先后顺序。二级辨析：三词主体分别是商家、消费者、监管部门，主体各不相同。A点菜下单（食客）、烹饪菜肴（厨师）、传送菜品（服务员），时间先后且主体不同，一致；B顺序应为发表文章、印刷错误、勘误声明；C投递简历和考试通过主体都是应聘者，主体相同；D三动作主体都是教练，相同。故正确答案为A。", "tip": "易错点：只看时间先后，忽略“三动作主体不同”这一二级辨析。", "kind": "real", "src": "2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版） 第 28 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "某机构对在广州有创业、就业、实习等经历的港澳青年进行调查，结果显示，有留穗发展意愿的港澳青年比例占七成以上；九成港澳青年通过实习了解和认识广州；有超过一半的港澳青年非常看好粤港澳大湾区的发展前景。因此，来广州实习有助于港澳青年获得对粤港澳大湾区的认同感。 要使上述推论成立，可以补充的前提是（ ）。", "options": ["熟悉广州有助于港澳青年更好地适应在广州工作和生活", "港澳青年的留穗发展意愿是其对粤港澳大湾区具有认同感的重要表现", "通过实习，港澳青年对粤港澳大湾区发展前景更有信心", "超过一半的在穗实习港澳青年参与了这项调查"], "answer": ["B"], "explain": "第一步：找出论点和论据。 论点：来广州实习有助于港澳青年获得对粤港澳大湾区的认同感。 论据：有留穗发展意愿的港澳青年比例占七成以上；九成港澳青年通过实习了解和认识广州；有超过一半的港澳青年非常看好粤港澳大湾区的发展前景。 本题论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，论据讨论的是在广州实习的港澳青年中有七成以上有留穗发展意愿、有超过一半看好粤港澳大湾区的发展前景，论点论据话题不一致，加强优先考虑搭桥。找到论据与论点中不同的关键词为“留穗发展意愿”或“看好粤港澳大湾区的发展前景”与“对粤港澳大湾区的认同感”，需要在二者之间进行搭桥。 第二步：逐一分析选项。 A项：论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，而该项讨论的是熟悉广州能让港澳青年更好地适应在广州工作和生活，适应工作和生活与能否获得认同感无必然联系，因此该项不是论点成立的前提，排除； B项：该项讨论的是港澳青年的留穗发展意愿是其对粤港澳大湾区具有认同感的重要表现，指出了“留穗发展意愿”与“对粤港澳大湾区的认同感”之间的联系，搭桥项，保留； C项：论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，而该项讨论的是通过实习能让港澳青年对粤港澳大湾区发展前景更有信心，但更有信心不等同于会产生认同感，话题不一致，无法加强，排除； D项：论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，而该项讨论的是超过一半的在穗实习港澳青年参与了这项调查，说明论据的调查结果相对准确的，加强论据，保留。 比较B、D两项，D项是加强论据，力度没有B项搭桥强，故排除D项，B项当选。 ⇒ 正确答案为B。", "method": "第一步：找出论点和论据。 论点：来广州实习有助于港澳青年获得对粤港澳大湾区的认同感。 论据：有留穗发展意愿的港澳青年比例占七成以上；九成港澳青年通过实习了解和认识广州；有超过一半的港澳青年非常看好粤港澳大湾区的发展前景。 本题论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，论据讨论的是在广州实习的港澳青年中有七成以上有留穗发展意愿、有超过一半看好粤港澳大湾区的发展前景，论点论据话题不一致，加强优先考虑搭桥。找到论据与论点中不同的关键词为“留穗发展意愿”或“看好粤港澳大湾区的发展前景”与“对粤港澳大湾区的认同感”，需要在二者之间进行搭桥。 第二步：逐一分析选项。 A项：论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，而该项讨论的是熟悉广州能让港澳青年更好地适应在广州工作和生活，适应工作和生活与能否获得认同感无必然联系，因此该项不是论点成立的前提，排除； B项：该项讨论的是港澳青年的留穗发展意愿是其对粤港澳大湾区具有认同感的重要表现，指出了“留穗发展意愿”与“对粤港澳大湾区的认同感”之间的联系，搭桥项，保留； C项：论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，而该项讨论的是通过实习能让港澳青年对粤港澳大湾区发展前景更有信心，但更有信心不等同于会产生认同感，话题不一致，无法加强，排除； D项：论点讨论的是来广州实习有助于港澳青年获得对粤港澳大湾区的认同感，而该项讨论的是超过一半的在穗实习港澳青年参与了这项调查，说明论据的调查结果相对准确的，加强论据，保留。 比较B、D两项，D项是加强论据，力度没有B项搭桥强，故排除D项，B项当选。 ⇒ 正确答案为B。", "tip": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第18 题", "year": "2022"}, {"type": "fig", "imgs": ["data/figs/figq_073_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "图形的形状依次变化。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_074_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "图形的边数依次递增。", "trap": ""}]}, {"set": 36, "date": "2026-10-26", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 36 批）", "items": [{"type": "sci", "level": "中等", "stem": "下列关于我国家庭用电的说法正确的是：", "options": ["我国家庭使用的是220V的直流电", "带金属外壳的用电器一般使用两孔插座", "要使用电器之间互不影响，用电器应串联接入电路", "家庭用电的保险丝可以由电阻率大、熔点低的合金制成"], "answer": ["D"], "explain": "思路：家庭用电基本常识逐项判断；详解：A是交流电不是直流；B金属外壳用三孔插座接地防触电；C并联才能互不影响，串联会分压；D保险丝用电阻率大、熔点低的铅锑合金，电流过大时自动熔断。故答案为D。", "method": "思路：家庭用电基本常识逐项判断；详解：A是交流电不是直流；B金属外壳用三孔插座接地防触电；C并联才能互不影响，串联会分压；D保险丝用电阻率大、熔点低的铅锑合金，电流过大时自动熔断。故答案为D。", "tip": "易错点：以为家庭电是直流、或用电器要串联；我国家庭电路是220V交流电，用电器必须并联才能互不影响。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第81题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "如图是某种固态物质在加热过程中，温度随时间变化的图像。下列说法最不准确的是（ ）。", "options": ["该固态物质有固定的熔点", "该固态物质在熔化过程中，比热容增大", "温度为0℃时，该物质可能处于固液共存状态", "该固态物质在熔化时不断吸收热量，温度不断升高"], "answer": ["D"], "explain": "思路：有固定熔点的物质是晶体，熔化时吸热温度不变；详解：A有水平熔化段说明有固定熔点；B熔化过程物态变化比热容会改变；C熔点附近可能固液共存；D晶体熔化吸热但温度不变，“温度不断升高”错误。故答案为D。", "method": "思路：有固定熔点的物质是晶体，熔化时吸热温度不变；详解：A有水平熔化段说明有固定熔点；B熔化过程物态变化比热容会改变；C熔点附近可能固液共存；D晶体熔化吸热但温度不变，“温度不断升高”错误。故答案为D。", "tip": "易错点：误以为熔化时一边吸热一边升温；晶体熔化的特点是吸热但温度保持不变，图像上出现水平段。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第85题", "year": "2022"}, {"type": "sci", "level": "中等", "stem": "以下现象属于化学变化的是：", "options": ["将木纤维打碎后摊薄晒干制成土纸", "石墨在高温高压作用下变成金刚石", "打开易拉罐，一股气体喷涌而出", "在室外放了一段时间的干冰消失了"], "answer": ["B"], "explain": "思路：化学变化必有新物质生成，物理变化只改形态状态；详解：A打碎晒干只改形状；C开罐CO2逸出是物理解压；D干冰升华是状态变化；B石墨和金刚石是不同单质，转化生成新物质，属化学变化。故答案为B。", "method": "思路：化学变化必有新物质生成，物理变化只改形态状态；详解：A打碎晒干只改形状；C开罐CO2逸出是物理解压；D干冰升华是状态变化；B石墨和金刚石是不同单质，转化生成新物质，属化学变化。故答案为B。", "tip": "易错点：把干冰消失、气体喷出当成化学变化；判断关键是有无新物质生成，同素异形体之间的转化属于化学变化。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第72题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "在日常生活中，人们总是难以避免与细菌接触，以下有关细菌的说法错误的是：", "options": ["我国甲类传染病中的鼠疫是由细菌引发的", "有的细菌可用于食品生产、废水处理或生物分解", "细菌是微生物也是细胞，可以自行分裂繁殖", "杀灭细菌，只能依靠人体自身免疫力"], "answer": ["D"], "explain": "思路：结合细菌的结构、作用和抑菌杀菌手段判断；详解：A鼠疫由鼠疫杆菌引起正确；B利用乳酸菌、腐生菌等可用于食品和污水处理；C细菌是单细胞微生物，分裂生殖；D杀灭细菌还可用抗生素、消毒剂等，“只能靠免疫力”错误。故答案为D。", "method": "思路：结合细菌的结构、作用和抑菌杀菌手段判断；详解：A鼠疫由鼠疫杆菌引起正确；B利用乳酸菌、腐生菌等可用于食品和污水处理；C细菌是单细胞微生物，分裂生殖；D杀灭细菌还可用抗生素、消毒剂等，“只能靠免疫力”错误。故答案为D。", "tip": "易错点：把免疫力当成唯一杀菌手段；抗生素、消毒、杀菌药剂都能杀灭细菌。", "kind": "real", "src": "2025年广东省公务员录用考试《行测》题（考生回忆版） 第70题", "year": "2025"}, {"type": "math", "level": "中等", "stem": "有4批原材料存放在同一个仓库，工厂每次会从仓库中运出一整批原材料进行加工，加工完成后才能从仓库提取下一批原材料。已知一批原材料在仓库内每存放满1小时需要支付100元的费用，且工厂加工这4批原材料需要的时间分别为4、6、7、8小时，则工厂为这些原材料支付的仓库存放费用至少为（ ）元。", "options": ["2800", "3100", "3300", "3500"], "answer": ["B"], "explain": "思路：贪心排序（短作业优先）。详解：加工时间固定，要省存放费就让加工快的先做，使后续批次等待最短；按4、6、7、8排序，总等待＝4×3＋6×2＋7×1＝12＋12＋7＝31小时；费用＝31×100＝3100元。故答案为B。", "method": "思路：贪心排序（短作业优先）。详解：加工时间固定，要省存放费就让加工快的先做，使后续批次等待最短；按4、6、7、8排序，总等待＝4×3＋6×2＋7×1＝12＋12＋7＝31小时；费用＝31×100＝3100元。故答案为B。", "tip": "易错点：按任意顺序加工导致等待时间变长，或没意识到“等待时间＝后面每批都在仓库多待的时间”；问最少费用，要让短作业优先。", "kind": "real", "src": "2026年广东省公务员录用考试《行测》题（网友回忆版） 第 10 题", "year": "2026"}, {"type": "math", "level": "中等", "stem": "甲地在丙地正西17千米，乙地在丙地正北8千米。张从甲地、李从乙地同时出发，分别向正东和正南方向匀速行走。两人速度均为整数千米/小时，且1小时后两人的直线距离为13千米，又经过3小时后两人均经过了丙地且直线距离为5千米。已知李的速度是张的60%，则张经过丙地的时间比李：", "options": ["早不到10分钟", "早10分钟以上", "晚不到10分钟", "晚10分钟以上"], "answer": ["D"], "explain": "思路：勾股定理+比例；详解：张从甲（丙正西17km）向东走，李从乙（丙正北8km）向南走。设张速5m、李速3m。4小时后（1+3）：张过丙地，距丙地=5m×4-17；李过丙地，距丙地=3m×4-8。此时两人在丙地以东、以南，直线距离=√[(4×5m-17)²+(4×3m-8)²]=5（题给）。试m=1：张距丙=20-17=3，李距丙=12-8=4，√(9+16)=5，符合。故张速5、李速3。张到丙地时间=17/5=3.4小时=3时24分；李到丙地时间=8/3=2时40分。张比李晚3:24-2:40=44分钟。故答案为D。", "method": "思路：勾股定理+比例；详解：张从甲（丙正西17km）向东走，李从乙（丙正北8km）向南走。设张速5m、李速3m。4小时后（1+3）：张过丙地，距丙地=5m×4-17；李过丙地，距丙地=3m×4-8。此时两人在丙地以东、以南，直线距离=√[(4×5m-17)²+(4×3m-8)²]=5（题给）。试m=1：张距丙=20-17=3，李距丙=12-8=4，√(9+16)=5，符合。故张速5、李速3。张到丙地时间=17/5=3.4小时=3时24分；李到丙地时间=8/3=2时40分。张比李晚3:24-2:40=44分钟。故答案为D。", "tip": "易错点：①速度比60%=3:5，设成5m和3m；②不会用勾股定理列距离方程；③“经过丙地”的时间=到丙地的距离÷速度。", "kind": "real", "src": "2022年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 7 题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "某考试有30人参加，每人得分都是0~100之间的整数且互不相同。已知得分不低于90的人平均分为93.8分，小姜得了92分，问他的成绩排名最低可能是第几名？", "options": ["4", "5", "7", "8"], "answer": ["A"], "explain": "思路：最值构造加代入。详解：不低于90分共n人，分数为90-100间互不相同整数，n≤11。总分=93.8n须整数→n为5的倍数，n=5或10。n=10时前10名最低总分90+91+...+99=945>938，排除。故n=5，前五名总分=93.8×5=469分。问最低名次：若92排第5名，则其余4人至少93+94+95+96，五人总分≥92+93+94+95+96=470>469，不可能；故92进不了第5名。验证第4名：3人在其上（≥93,94,95）、1人在其下（≤91），最低总分=93+94+95+92+91=465≤469，余4分可在互不相同前提下调整，成立。故最低第4名。答案为A。", "method": "思路：最值构造加代入。详解：不低于90分共n人，分数为90-100间互不相同整数，n≤11。总分=93.8n须整数→n为5的倍数，n=5或10。n=10时前10名最低总分90+91+...+99=945>938，排除。故n=5，前五名总分=93.8×5=469分。问最低名次：若92排第5名，则其余4人至少93+94+95+96，五人总分≥92+93+94+95+96=470>469，不可能；故92进不了第5名。验证第4名：3人在其上（≥93,94,95）、1人在其下（≤91），最低总分=93+94+95+92+91=465≤469，余4分可在互不相同前提下调整，成立。故最低第4名。答案为A。", "tip": "易错点：平均分93.8n必须是整数，93.8=469/5，故n是5的倍数只能5或10；n=10时前10名最低总分945>938矛盾，只能n=5。", "kind": "real", "src": "2026年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 8 题", "year": "2026"}, {"type": "logic", "level": "中等", "stem": "白天：夜晚：夏夜", "options": ["红色：黑色：漆黑", "中国：外国：欧洲国家", "高山：大海：南海", "草原：森林：原始森林"], "answer": ["B"], "explain": "先定一级关系：白天和夜晚非此即彼，矛盾并列；夏夜属于夜晚，种属。二级辨析：A红色和黑色之外还有其他颜色，反对关系；B中国和外国非此即彼（一个国家不是中国就是外国），矛盾，欧洲国家属于外国，一致；C高山和大海之外还有平原等，反对；D草原和森林之外还有荒漠，反对。故正确答案为B。", "method": "先定一级关系：白天和夜晚非此即彼，矛盾并列；夏夜属于夜晚，种属。二级辨析：A红色和黑色之外还有其他颜色，反对关系；B中国和外国非此即彼（一个国家不是中国就是外国），矛盾，欧洲国家属于外国，一致；C高山和大海之外还有平原等，反对；D草原和森林之外还有荒漠，反对。故正确答案为B。", "tip": "易错点：把矛盾关系当成反对关系；白天和夜晚是非此即彼的矛盾关系。", "kind": "real", "src": "2023年浙江省公务员录用考试《行测》题（A类）（网友回忆版） 第 26 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "优秀的企业家既要有杰出的领导能力，也必须积极承担相应的社会责任。因此，能运用出色的领导力引领企业发展却不愿承担任何社会责任的人，一定不是优秀的企业家。 以下选项的逻辑结构与题干最为相似的是（ ）。", "options": ["真正的“美丽”不仅体现在外表上，还体现在心灵上。因此，心灵美丽的人外表也一定出众", "设计要源于现实生活才能发挥意义而成为真正伟大的设计。因此，脱离生活的设计是不切实际的，更是毫无现实意义的", "优秀的学习成绩和良好的道德品质在评奖评优中缺一不可。因此，即使有优秀的学习成绩，要想评奖评优，良好的道德品质仍然不可或缺", "流量明星一定程度带动了经济发展，也带来了一些新的社会问题。因此，片面强调流量明星带来的经济效益，忽视其后来的社会问题并不可取"], "answer": ["C"], "explain": "题干：优秀企业家→领导能力且承担责任（A→B且C），因此：有领导力但不愿担责任→不是优秀企业家（B且非C→非A），即否定其中一个必要条件推出否定整体。C：评奖评优→好成绩且好品德（A→B且C），因此：有好成绩但无好品德→不能评优（B且非C→非A），结构一致。A是C→B方向反了。故正确答案为C。", "method": "题干：优秀企业家→领导能力且承担责任（A→B且C），因此：有领导力但不愿担责任→不是优秀企业家（B且非C→非A），即否定其中一个必要条件推出否定整体。C：评奖评优→好成绩且好品德（A→B且C），因此：有好成绩但无好品德→不能评优（B且非C→非A），结构一致。A是C→B方向反了。故正确答案为C。", "tip": "易错点：易误选A，因为都讲两个必要条件；但A后半句是心灵→外表，方向反了。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第 32 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "夜盲症：维生素A：胡萝卜", "options": ["水肿：维生素B1：酵母", "脚气：维生素C：青椒", "佝偻病：维生素E：葵花籽", "坏血病：维生素D：动物肝脏"], "answer": ["A"], "explain": "先定一级关系：夜盲症对应缺乏维生素A，胡萝卜富含维生素A。二级辨析：A水肿与维生素B1缺乏相关，酵母富含维生素B1，对应正确；B脚气（脚气病）应对应维生素B1而非维C，错；C佝偻病应对应维生素D而非维E，错；D坏血病应对应维生素C而非维D，错。当选A。", "method": "先定一级关系：夜盲症对应缺乏维生素A，胡萝卜富含维生素A。二级辨析：A水肿与维生素B1缺乏相关，酵母富含维生素B1，对应正确；B脚气（脚气病）应对应维生素B1而非维C，错；C佝偻病应对应维生素D而非维E，错；D坏血病应对应维生素C而非维D，错。当选A。", "tip": "易错点：把病症—维生素—食物的对应记错。二级辨析：夜盲症缺维生素A、胡萝卜富含维A；水肿与缺维生素B1相关、酵母富含维B1。B/C/D把维生素与病症张冠李戴。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 28 题", "year": "2025"}, {"type": "fig", "imgs": ["data/figs/figq_075_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "图形的方向依次顺时针旋转。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_076_1.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["A"], "explain": "前面很多类似的题了，总结一下。横着看，找出重叠的部分。", "trap": ""}]}, {"set": 37, "date": "2026-10-26", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 37 批）", "items": [{"type": "sci", "level": "中等", "stem": "农技站为了贮存种子，拟采用以下做法，其中最可行的是", "options": ["将种子浸泡在含水的容器中", "将种子置放在含氧量低于1%的干燥地窖中", "将种子置于15摄氏度左右的低温环境中", "将种子封闭在完全避光的黑暗环境中"], "answer": ["B"], "explain": "思路：种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度；详解：A浸泡在水中会让种子萌发甚至霉烂；C仅15℃远达不到储存要求；D避光并非关键；B干燥地窖既控制水分又把含氧量压到1%以下，呼吸作用被显著抑制，最可行。故答案为B。", "method": "思路：种子通过呼吸作用消耗有机物，贮存要尽量降低呼吸强度；详解：A浸泡在水中会让种子萌发甚至霉烂；C仅15℃远达不到储存要求；D避光并非关键；B干燥地窖既控制水分又把含氧量压到1%以下，呼吸作用被显著抑制，最可行。故答案为B。", "tip": "易错点：误选C，以为15℃低温就够了；种子储存的关键是抑制呼吸作用，需同时满足干燥、低氧、低温三条件。", "kind": "real", "src": "2020年广东省公务员录用考试《行测》题（网友回忆版） 第66题", "year": "2020"}, {"type": "sci", "level": "中等", "stem": "甲酸（HCOOH）具有清洁制氢的巨大潜力，其反应前后分子种类变化的微观示意图如下图所示。则下列说法正确的是：", "options": ["反应后分子个数增多", "该反应类型为化合反应", "反应物和生成物都是有机物", "该反应不遵守能量守恒定律"], "answer": ["A"], "explain": "思路：写出反应方程式HCOOH→H₂↑+CO₂↑；详解：A一个甲酸分子生成一个氢分子和一个二氧化碳分子，分子个数由1变2，增多；B是分解反应不是化合；C生成物H2、CO2属无机物；D一切化学反应都遵守能量守恒。故答案为A。", "method": "思路：写出反应方程式HCOOH→H₂↑+CO₂↑；详解：A一个甲酸分子生成一个氢分子和一个二氧化碳分子，分子个数由1变2，增多；B是分解反应不是化合；C生成物H2、CO2属无机物；D一切化学反应都遵守能量守恒。故答案为A。", "tip": "易错点：把它当成化合反应或以为有生成物就是有机物；甲酸分解是一变多，属分解反应。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第80题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "下图是动物养殖场自动喂水装置的简要示意图。当动物通过饮水口饮水后，水箱内的水位下降，水瓶中的水将自动流入水箱，使水位回到一定的高度。关于这一装置，下列说法正确的是：", "options": ["水瓶最终会处于真空状态", "水瓶内的气压始终等于水箱内的气压", "装置达到平衡时，水瓶内的气压高于大气压", "该装置是利用水瓶、水箱之间的气压差实现的"], "answer": ["D"], "explain": "思路：这是大气压支撑水柱的装置，类似倒置水杯；详解：水位下降瓶口露出时空气进入水瓶，在重力和气压差作用下水补入水箱，正是利用瓶内外气压差；A不会真空；B气压并不始终相等；C平衡时瓶内气压+水柱压=大气压，瓶内气压低于大气压。故答案为D。", "method": "思路：这是大气压支撑水柱的装置，类似倒置水杯；详解：水位下降瓶口露出时空气进入水瓶，在重力和气压差作用下水补入水箱，正是利用瓶内外气压差；A不会真空；B气压并不始终相等；C平衡时瓶内气压+水柱压=大气压，瓶内气压低于大气压。故答案为D。", "tip": "易错点：以为瓶内气压高于大气压；平衡时瓶内气压加水柱压强等于外界大气压，瓶内气压其实低于大气压。", "kind": "real", "src": "2023年广东省公务员录用考试《行测》题（乡镇卷）（网友回忆版） 第77题", "year": "2023"}, {"type": "sci", "level": "中等", "stem": "食物链主要反映了生产者与消费者之间的联系，下列关系中最能准确表示食物链的是（ ）。", "options": ["草→兔→狐→鹰", "阳光→草→鸡→狼", "虫→鸟→蛇", "草→羊→虎→微生物"], "answer": ["A"], "explain": "思路：食物链起点必须是生产者（绿色植物），终点是最高级消费者，不含非生物部分和分解者；详解：B起点阳光是非生物；C起点虫是消费者不是生产者；D末尾微生物是分解者；A草为生产者，经兔、狐到鹰，完整准确。故答案为A。", "method": "思路：食物链起点必须是生产者（绿色植物），终点是最高级消费者，不含非生物部分和分解者；详解：B起点阳光是非生物；C起点虫是消费者不是生产者；D末尾微生物是分解者；A草为生产者，经兔、狐到鹰，完整准确。故答案为A。", "tip": "易错点：误选B把非生物的阳光写进食物链，或误选D把分解者微生物写进捕食链；食物链只含生产者和消费者，箭头指向捕食者。", "kind": "real", "src": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第79题", "year": "2022"}, {"type": "math", "level": "中等", "stem": "在下表中，小方格中的字母均为整数。若各行之和、各列之和、各对角线之和均相等，则a的值为：", "options": ["17", "18", "19", "20"], "answer": ["D"], "explain": "思路：幻方问题列等式；详解：第一列和=a+3+11+x，主对角线和=a+17+5+2，相等得x=10。第二行和=3+17+b+11，第三列和=8+b+5+z，相等得z=18。第四行和=10+14+18+2=44，故幻和为44。第一列和=a+3+11+10=44，解得a=20。故答案为D。", "method": "思路：幻方问题列等式；详解：第一列和=a+3+11+x，主对角线和=a+17+5+2，相等得x=10。第二行和=3+17+b+11，第三列和=8+b+5+z，相等得z=18。第四行和=10+14+18+2=44，故幻和为44。第一列和=a+3+11+10=44，解得a=20。故答案为D。", "tip": "易错点：不先列等式求未知格；陷阱是用第一列=主对角线求出x。", "kind": "real", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 19 题", "year": "2023"}, {"type": "math", "level": "中等", "stem": "甲、乙和丙3个单位共有100多名职工，其中甲单位的职工人数占总数的24%，乙单位的职工比丙单位多50%。问丙单位的职工比甲单位多多少人？", "options": ["4", "8", "12", "16"], "answer": ["B"], "explain": "思路：倍数特性。详解：甲占24%=6/25，总人数必为25的倍数；乙丙共76%=19/25。乙比丙多50%→乙:丙=1.5:1=3:2，故丙=2/5×乙丙和。乙丙和=总人数×19/25，需为5的倍数，故总人数须为25×5=125的倍数。100多名中只有125人。甲=125×24%=30人；乙丙共95人，丙=95×2/5=38人。丙-甲=38-30=8人。故答案为B。", "method": "思路：倍数特性。详解：甲占24%=6/25，总人数必为25的倍数；乙丙共76%=19/25。乙比丙多50%→乙:丙=1.5:1=3:2，故丙=2/5×乙丙和。乙丙和=总人数×19/25，需为5的倍数，故总人数须为25×5=125的倍数。100多名中只有125人。甲=125×24%=30人；乙丙共95人，丙=95×2/5=38人。丙-甲=38-30=8人。故答案为B。", "tip": "易错点：甲占24%→乙丙共76%，乙比丙多50%即乙:丙=3:2，要找同时满足两个比例的整数总人数；'100多名'即100到200之间。", "kind": "real", "src": "2026年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 5 题", "year": "2026"}, {"type": "math", "level": "中等", "stem": "某单位65名职工中，拥有甲、乙、丙三项认证中至少一项的职工正好占80%，没有甲认证的职工与有乙认证的职工人数一样多，仅有丙认证的职工有3人，三项认证都有的职工有6人，问有多少人仅拥有甲、乙两项认证？", "options": ["10", "13", "16", "19"], "answer": ["A"], "explain": "思路：三集合容斥（韦恩图）。详解：至少一项认证占80%=52人，故三项都没有的=65-52=13人。设仅乙=z、仅乙丙=y、仅甲乙=x。没有甲认证的人=仅乙z+仅乙丙y+仅丙3+都没有13=z+y+16；有乙认证的人=仅乙z+仅乙丙y+仅甲乙x+三项都有6=z+y+x+6。两式相等：z+y+16=z+y+x+6，消去公共项得x=10。故仅甲乙两项认证的有10人，答案为A。", "method": "思路：三集合容斥（韦恩图）。详解：至少一项认证占80%=52人，故三项都没有的=65-52=13人。设仅乙=z、仅乙丙=y、仅甲乙=x。没有甲认证的人=仅乙z+仅乙丙y+仅丙3+都没有13=z+y+16；有乙认证的人=仅乙z+仅乙丙y+仅甲乙x+三项都有6=z+y+x+6。两式相等：z+y+16=z+y+x+6，消去公共项得x=10。故仅甲乙两项认证的有10人，答案为A。", "tip": "易错点：画韦恩图时漏算“都没有认证”的13人，或把“没有甲认证”与“有乙认证”的组成写错。陷阱：两式相等时公共项可消去，不必求出具体人数。", "kind": "real", "src": "2025年国家公务员录用考试《行测》题（行政执法卷网友回忆版） 第 9 题", "year": "2025"}, {"type": "logic", "level": "中等", "stem": "挑战：应战", "options": ["报考：录取", "观察：评估", "抚养：扶养", "超速：限速"], "answer": ["A"], "explain": "先定一级关系：动作先后顺序，且发出动作的主体不同；二级辨析：A先报考再录取，主体不同（考生/学校）；B先观察再评估，主体相同；C抚养与扶养无明显先后；D限速是为预防超速，不是先后。答案为A。", "method": "先定一级关系：动作先后顺序，且发出动作的主体不同；二级辨析：A先报考再录取，主体不同（考生/学校）；B先观察再评估，主体相同；C抚养与扶养无明显先后；D限速是为预防超速，不是先后。答案为A。", "tip": "易错点：只看先后顺序忽略主体是否相同；题干先挑战再应战，主体不同。", "kind": "real", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 6 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "智慧城乡建设：指在城乡建设过程中，以大数据、物联网等数字化技术为基础，通过多领域数据的互联互通，提高政府治理效能及宜居度的举措。 下列属于智慧城乡建设的是（ ）。", "options": ["某县小商品市场利用物联网技术，强化产品质量溯源体系建设，所有商品实现了“带证上网、带码上线、带标上市”，交易额大幅提高", "某现代农业园采用多项“5G+农业”技术，通过上百个监测点实时监测作物生长情况，把各区域的温度、湿度等数据传输到控制中心，根据数据进行种苗选育、水肥管控", "某公司针对城区道路上下班高峰期的拥堵问题，研发出了一套新的智能信控系统，有望实现从“车看灯”到“灯看车”的转变", "某地依托城市洪涝数值模拟模型发布了市区积水地图，能直观展示低洼路段、下穿立交等区域的风险点位分布以及相应的避险提示。从此以后，市民雨天出行再也没有出现过安全问题"], "answer": ["D"], "explain": "划关键词：①数字化技术为基础；②提高政府治理效能及宜居度。A小商品市场行为，非政府治理；B农业园监测作物，非政府治理；C某公司研发，非政府治理；D依托洪涝数值模拟模型发积水地图，方便市民出行，提高政府治理效能和宜居度，符合。答案为D。", "method": "划关键词：①数字化技术为基础；②提高政府治理效能及宜居度。A小商品市场行为，非政府治理；B农业园监测作物，非政府治理；C某公司研发，非政府治理；D依托洪涝数值模拟模型发积水地图，方便市民出行，提高政府治理效能和宜居度，符合。答案为D。", "tip": "易错点：漏看“提高政府治理效能及宜居度”这一目的；A市场、B农业园、C公司行为都不涉及政府治理。", "kind": "real", "src": "2023年江苏省公务员录用考试《行测》题（A类）（网友回忆版） 第 43 题", "year": "2023"}, {"type": "logic", "level": "中等", "stem": "水火是无情的，人不是水火，所以人不是无情的。 下列选项所犯的逻辑错误与题干最相似的是（ ）。", "options": ["所有羊都是白色的，羊毛是白色的，所以羊毛是羊", "蛋糕都是圆的，蛋糕里面添加了鸡蛋，所以鸡蛋也是圆的", "水星是星球，水星上没有人类；地球是星球，所以地球上也没有人类", "所有不遵守规则的司机都会被处罚，司机小陈一直遵守规则，所以他不会被处罚"], "answer": ["D"], "explain": "先定一级关系：题干结构为“水火→无情，人不是水火（否前），所以人不是无情（否后）”，即否定前件推出否定后件。再做二级辨析：A肯后推肯前，结构不同；B添加鸡蛋无法形式化，结构不同；C错误类比（同类事物类推）；D“不遵守规则→被处罚，小陈遵守规则（否前），所以不被处罚（否后）“，同为否前推否后。故正确答案为D。", "method": "先定一级关系：题干结构为“水火→无情，人不是水火（否前），所以人不是无情（否后）”，即否定前件推出否定后件。再做二级辨析：A肯后推肯前，结构不同；B添加鸡蛋无法形式化，结构不同；C错误类比（同类事物类推）；D“不遵守规则→被处罚，小陈遵守规则（否前），所以不被处罚（否后）“，同为否前推否后。故正确答案为D。", "tip": "易错点：被表面内容相似带偏，没抓住“否前推否后”这一结构；平行结构题比的是推理形式不是内容。", "kind": "real", "src": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第 12 题", "year": "2024"}, {"type": "fig", "imgs": ["data/figs/figq_075_1.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "图形的方向依次顺时针旋转。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_076_1.png"], "src": "", "cat": "", "fmt": "", "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["A"], "explain": "前面很多类似的题了，总结一下。横着看，找出重叠的部分。", "trap": ""}]}];
